\subsection{Three-dimensional volume alignment}  

In the 3D reconstruction process, in contrast to the 2D classification process, it is assumed that the templates exhibit an algebraic structure governed by $\s{SO}(3)$ rotations of the underlying volume. This raises the question: under what conditions does the maximum-likelihood estimator, as defined in \eqref{eqn:maximumOfLogLikelihoodCryoET}, converge to the template volume used in the particle-picking procedure based on template matching? Similar to the 2D classification case discussed in the previous section, the conditions include an asymptotic number of extracted particles, an asymptotic threshold, and an additional assumption regarding the $\s{SO}(3)$ samples, as outlined in Assumption \ref{assump:1}.

\begin{thm}
\label{thm:3DvolumeVsTemplateVolume}
%(3D templates resembling for an asymptotic number of particles, and asymptotic threshold.) 
Assume the input templates to Algorithm \ref{alg:particlePickerTemplateMatching} are of the form $\ppp{x_\ell}_{\ell=0}^{L-1} = \ppp{R_\ell \cdot V_{\s{template}}}_{\ell=0}^{L-1}$, where $V_{\s{template}}$ is the input 3D template volume, and $\ppp{R_\ell}_{\ell=0}^{L-1} \in \s{SO}(3)$. Assume that
that $R_{\ell_1} \cdot V_{\s{template}} \neq R_{\ell_2} \cdot V_{\s{template}}$ for every $\ell_1 \neq \ell_2$.
Let $\hat{V}$ be the maximum-likelihood 3D volume estimator, as defined in \eqref{eqn:maximumOfLogLikelihoodCryoET}. Let $T$ be the threshold of the template matching algorithm as specified in Algorithm \ref{alg:particlePickerTemplateMatching}. Then, under Assumption \ref{assump:1}, 
    \begin{align}
        \lim_{T\to\infty}\lim_{N\to\infty} \frac{\hat{V}}{T} = R \cdot V_{\s{template}} \label{eqn:nonVanishingEstimator3D},
    \end{align}
for some $R \in \s{SO}(3)$, where the convergence is in probability. 
\end{thm}

\subsection{The impact of the number of observations and signal dimension}  \label{sec:app_sampleComplexity}
In the previous sections, we analyzed the asymptotic behavior of the convergence of 2D classes in cryo-EM and the reconstructed 3D structure in cryo-ET relative to the underlying 3D template. This analysis was carried out under the asymptotic regimes of an infinite number of extracted particles ($M \to \infty$) and an infinite threshold ($T \to \infty$). We now shift focus to the convergence rates of maximum-likelihood estimators (MLEs), specifically examining how these rates depend on the signal dimension and the number of samples.

\paragraph{Sample complexity for estimating the mean of a Gaussian distribution.}
We begin with the sample complexity for estimating the mean of a $d$-dimensional multivariate Gaussian distribution. Consider i.i.d.\ observations $X_i \sim \mathcal{N}(\mu, \Sigma = \sigma^2 I_{d \times d})$ in $\mathbb{R}^d$, and let $\hat{\mu}_{\mathrm{ML}}$ denote the MLE of $\mu$ based on $M$ samples $\{X_i\}_{i=0}^{M-1}$. By the asymptotic efficiency of MLEs~\cite{newey1994large}, as $n \to \infty$,
\begin{align}
    \sqrt{M} \left(\hat{\mu}_{\mathrm{ML}} - \mu\right) \xrightarrow[]{\mathcal{D}} \mathcal{N}(0, \mathcal{I}^{-1}), \label{eqn:efficencyFisherInformation}
\end{align}
where $\mathcal{I}$ is the Fisher information matrix. In our case, since $\Sigma = \sigma^2 I_{d \times d}$, the limiting distribution becomes
\begin{align}
    \sqrt{M} \left(\hat{\mu}_{\mathrm{ML}} - \mu\right) \xrightarrow[]{\mathcal{D}} \mathcal{N}(0, \sigma^2 I_{d \times d}).
\end{align}
Thus, for sufficiently large $n$, the mean squared error (MSE) between $\hat{\mu}_{\mathrm{ML}}$ and $\mu$ scales as
\begin{align}
    \|\hat{\mu}_{\mathrm{ML}} - \mu\|^2 \propto \frac{d \sigma^2}{M}.
\end{align}

\paragraph{Sample complexity for estimating the means in a Gaussian mixture model (GMM).}
Now consider a GMM with $L$ components, where each component has mean $\mu_\ell$ and covariance matrix $\Sigma_\ell = \sigma^2 I_{d \times d}$. Let $\{\hat{\mu}_\ell\}_{\ell = 0}^{L-1}$ be the MLEs of the component means. As in the single-Gaussian case, the efficiency result of~\eqref{eqn:efficencyFisherInformation} applies, but the convergence behavior is more intricate due to the latent structure.

In the general case, without assumptions on the separation between components, the MSE satisfies the following pessimistic bound~\cite{moitra2010settling}:
\begin{align}
    \sum_{\ell = 0}^{L-1} \|\hat{\mu}_\ell - \mu_\ell\|^2 = \mathcal{O}\left(\frac{\sigma^{O(L)}}{M}\right).
\end{align}
However, if the component means are well-separated, specifically, if $\|\mu_{\ell_1} - \mu_{\ell_2}\| \gg d \sigma^2$ for all $\ell_1 \neq \ell_2$, then the MSE improves significantly, scaling as~\cite{dasgupta1999learning}
\begin{align}
    \sum_{\ell = 0}^{L-1} \|\hat{\mu}_\ell - \mu_\ell\|^2 \propto Ld \frac{\sigma^2}{M}. \label{eqn:app_C_12}
\end{align}


\paragraph{Sample complexity for the convergence of the particle-picking mixture to templates.}
The distribution of extracted particles, defined in~\eqref{eqn:componentOfMixtureModelParticlePicker}, does not follow a standard GMM but rather a \emph{truncated Gaussian mixture}, due to the selection bias induced by the particle-picking mechanism. For such non-Gaussian models, consistency and asymptotic efficiency of MLEs can still hold under suitable regularity conditions~\cite{vandervaart1998}.

In particular, we state the following known result for  truncated Gaussian distributions.%, the following result is well known~\cite{durrett2019probability}:
\begin{lem}[\cite{durrett2019probability}] \label{lem:C4}
Let $X \sim \mathcal{N}(0, \sigma^2)$. Then, for any threshold $T \in \mathbb{R}$,
\begin{align}
    \mathbb{E}[X \mid X \geq T] = \sigma \cdot \frac{\varphi(T/\sigma)}{Q(T/\sigma)}, \label{eqn:app_C13}
\end{align}
where $\varphi(z) = \frac{1}{\sqrt{2\pi}} e^{-z^2/2}$ is the standard normal density function,
$Q(z) = \int_z^\infty \varphi(t) \, dt = 1 - \Phi(z)$ is the standard Gaussian upper tail probability, and $\Phi$ is the CDF of the standard normal distribution.
In addition, the variance of $X$ conditioned on $X \geq T$ is given by:
\begin{align}
    \operatorname{Var}(X \mid X \geq T) = \sigma^2 \left(1 + \frac{T}{\sigma} \cdot \frac{\varphi(T/\sigma)}{Q(T/\sigma)} - \left(\frac{\varphi(T/\sigma)}{Q(T/\sigma)}\right)^2\right). \label{eqn:app_C14}
\end{align}
Asymptotically, as $T \to \infty$, we have, \footnote{Here, the symbol $f(t) \sim g(t)$ denotes asymptotic equivalence, i.e., $\lim_{t \to \infty} \frac{f(t)}{g(t)} = 1.$}
\begin{align}
    \mathbb{E}[X \mid X \geq T] &\sim T + \frac{\sigma^2}{T}, \\
    \operatorname{Var}(X \mid X \geq T) &\sim \sigma^2 \left(1 - \frac{\sigma^2}{T^2}\right).
\end{align}
\end{lem}

In our setting, the random variable $X$ corresponds to the projection of the noisy observation onto the direction of the template, and Lemma~\ref{lem:C4} characterizes the distribution of this projection after truncation by the particle-picking threshold (see Lemmas~\ref{lemma:2} and~\ref{lemma:3} for further details).
We thus define the effective variance of each truncated component by
\begin{align}
    \sigma_T^2 = \sigma^2 \p{1 - \frac{\sigma^2}{T^2}}. \label{eqn:app_C17}
\end{align}

In the regime where the threshold $T \to \infty$, the extracted particle mixture becomes well-separated, assuming the templates are separated, since the the mean of each component concentrates near $m_\ell^{(T)}\approx T \cdot x_\ell$, and the variance tends toward $\sigma_T^2 \approx \sigma^2$.
Thus, they satisfy the conditions under which the rate in~\eqref{eqn:app_C_12} applies. 

Let $M$ denote the number of extracted particles selected by the thresholding mechanism. Then, the MSE of the estimated means from the extracted mixture satisfies:\begin{align}
    \sum_{\ell = 0}^{L-1} \|\hat{\mu}_\ell - m_\ell^{(T)}\|^2 \propto \frac{L d \sigma_T^2}{M}, \label{eqn:app_C_18}
\end{align}
where $\sigma_T^2$ is defined in \eqref{eqn:app_C17}, as $M,T \to \infty$.
This scaling indicates that a smaller signal dimension $d$ or a larger number of observations $M$ leads to faster convergence of the estimated means to the true ones. In the context of cryo-EM or cryo-ET particle picking, this implies that smaller particle sizes and a greater number of extracted particles amplify the bias toward the underlying templates.
%accelerate the approach to asymptotic behavior, thereby amplifying the bias toward the underlying templates.

\section{Proofs} \label{sec:proofs}
\subsection{Proof of Proposition \ref{thm:prop1}}

Let $\ppp{y_i}_{i=0}^{N-1} \stackrel{\text{i.i.d.}}{\sim} \mathcal{N}(\textbf{0}_d, \sigma^2 I_{d \times d})$, be the input observations to Algorithm \ref{alg:particlePickerTemplateMatching}, and $\mathcal{A} = \ppp{z_i}_{i=0}^{M-1}$ be the output set of the extracted particles of Algorithm \ref{alg:particlePickerTemplateMatching}, and recall the definitions of  $\mathcal{A}_\ell^{(T)}$ \eqref{eq:mu_l_def}, and $m_\ell^{(T)}$ \eqref{eq:calA_ell}. In addition, recall the definition of $\mathcal{V}_\ell^{(T)} \subset \mathbb{R}^d$ \eqref{eqn:VlDef}, 
which defines the subset of $\mathbb{R}^d$, where the inner-product between the particles and the $\ell$-th template $x_\ell$ exceed the threshold $T$. 

Let $\mathcal{P}: \mathbb{R}^d \to \mathbb{R}$ denote the $d$-dimensional Gaussian density function:
\begin{align}
    \mathcal{P}\p{y} \triangleq \mathcal{N}\p{y; \mu = 0, \Sigma = \sigma^2 I_{d \times d}} = \frac{1}{\p{2\pi \sigma^2}^{d/2}} \exp \ppp{-\frac{\norm{y}^2}{2\sigma^2}}. \label{eqn:g_N_def}
\end{align}
The input to Algorithm \ref{alg:particlePickerTemplateMatching} follows the distribution $\mathcal{P}$ (by the assumption on the distribution of the input observations $\ppp{y_i}_{i=0}^{N-1} \sim \mathcal{N} \p{\textbf{0}_d, \Sigma = \sigma^2 I_{d \times d}}$), while the output follows the mixture model defined in \eqref{eqn:mixtureModelParticlePicker} and \eqref{eqn:componentOfMixtureModelParticlePicker}. In particular, the extracted particles in the set $\mathcal{A}_\ell^{(T)}$ follows the distribution $g_\ell \p{z}$, as defined in \eqref{eqn:componentOfMixtureModelParticlePicker}, i.e., $g_\ell \p{z} = C_T \cdot \mathcal{P} \p{z} \mathbbm{1}_{\langle z, x_\ell \rangle \geq T}$, where $C_T$ is a normalization factor.

By the Strong Law of Large Numbers (SLLN), for $N \to \infty$, we have
\begin{align}
     m_\ell^{(T)} & = \frac{1}{|{\mathcal{A}_\ell^{(T)}}|} \sum_{\langle z_i, x_\ell \rangle \geq T} z_i 
     \nonumber \\ & = \frac{\frac{1}{N}\sum_{\langle y_i, x_\ell \rangle \geq T} y_i}{|{\mathcal{A}_\ell^{(T)}}|/N} \xrightarrow[]{\s{a.s.}} \frac{\mathbb{E}\pp{y_1 \mathbbm{1}{\ppp{y_1 \in \mathcal{V}_\ell^{(T)}}}}}{\mathbb{P}\pp{y_1 \in \mathcal{V}_\ell^{(T)}}}. \label{eqn:SLLNsingleMixtureMean1}
\end{align}
The numerator term at the  right-hand-side of \eqref{eqn:SLLNsingleMixtureMean1} is simply the expected value of all vectors which their inner product with the template $x_\ell$ is greater than the threshold $T$. In addition, the denominator term $\mathbb{P}\pp{y_1 \in \mathcal{V}_\ell^{(T)}} = \int_{y \in \mathcal{V}_\ell^{(T)}} \mathcal{P} \p{y} dy  > 0$; thus, the right-hand-side of \eqref{eqn:SLLNsingleMixtureMean1} is well-defined for every $T < \infty$. By the definition of $g_\ell$ \eqref{eqn:componentOfMixtureModelParticlePicker}, and following \eqref{eqn:SLLNsingleMixtureMean1}, we have,
\begin{align}
     m_\ell^{(T)} &  \xrightarrow[]{\s{a.s.}} \frac{\mathbb{E}\pp{y_1 \mathbbm{1}{\ppp{y_1 \in \mathcal{V}_\ell^{(T)}}}}}{\mathbb{P}\pp{y_1 \in \mathcal{V}_\ell^{(T)}}}
     = \frac{\int_{y \in \mathcal{V}_\ell^{(T)}} y \cdot \mathcal{P} \p{y}  dy}{\int_{y \in \mathcal{V}_\ell^{(T)}} \mathcal{P} \p{y} dy} \nonumber
     \\ & = C_T \int_{\mathbb{R}^d} y \cdot \mathcal{P} \p{y} \mathbbm{1}_{\langle y, x_\ell \rangle \geq T} \ dy 
     \triangleq  \int_{\mathbb{R}^d} z \cdot g_\ell \p{z} dz  = \mathbb{E}_{g_\ell} \pp{z}. 
\label{eqn:SLLNsingleMixtureMean}
\end{align}
where $C_T \triangleq {1/\mathbb{P}\pp{y_1 \in \mathcal{V}_\ell^{(T)}}}$. 

\paragraph{Part (1).} First, we prove that $m_\ell^{(T)} \xrightarrow[]{\s{a.s.}} \alpha_\ell \cdot x_\ell$, in the limit as $N \to \infty$, where $\alpha_\ell$ is a constant. This condition can be equivalently expressed algebraically: for any vector $u \in \mathbb{R}^d$ orthogonal to $x_\ell$ (i.e., $\langle u, x_\ell \rangle = 0$), the mean $m_\ell^{(T)}$ must also be orthogonal to $u$ (i.e., $\langle u, m_\ell^{(T)} \rangle = 0$).
Consequently, proving this is equivalent to showing that for every $u \in \mathbb{R}^d$ orthogonal to the template $x_\ell$ ($\langle u, x_\ell \rangle = 0$), the mean $m_\ell^{(T)}$ satisfies the condition:
\begin{align}
    \langle m_\ell^{(T)}, u \rangle = \frac{1}{|\mathcal{A}_\ell^{(T)}|} \sum_{\langle z_i, x_\ell \rangle \geq T} \langle z_i, u \rangle \xrightarrow[]{\s{a.s.}} 0, \label{eqn:orthogonalIsZero}
\end{align}
where $\mathcal{A}_\ell^{(T)}$ is the set of indices for which $\langle z_i, x_\ell \rangle \geq T$.


To prove the right-hand-side of \eqref{eqn:orthogonalIsZero}, we substitute \eqref{eqn:SLLNsingleMixtureMean} into the left-hand-side of \eqref{eqn:orthogonalIsZero}, and use the linearity of the inner-product to obtain,
\begin{align}
    \langle m_\ell^{(T)}, u \rangle \xrightarrow[]{\s{a.s.}}  C_T \int_{\mathbb{R}^d} \langle z, u \rangle \mathcal{P} \p{z} \mathbbm{1}_{\langle z, x_\ell \rangle \geq T} \ dz. \label{eqn:innerProductBetweenMeanAndU}
\end{align}
We prove in Lemma \ref{lemma:1}, stated below and proved in Section \ref{sec:proofLemma1}, that the right-hand size of \eqref{eqn:innerProductBetweenMeanAndU} is 0 from symmetry properties, which proves that $m_\ell^{(T)} \xrightarrow[]{\s{a.s.}} \alpha_\ell \cdot x_\ell$. 
\begin{lem} \label{lemma:1}
Let $\mathcal{P} \p{z}$ be the $d$-dimensional multivariate Gaussian distribution defined in \eqref{eqn:g_N_def}. Assume $u \in \mathbb{R}^d$, satisfying $\langle u, x_\ell \rangle = 0$. Then, for every $T$,
\begin{align}
    \int_{\mathbb{R}^d} \langle z, u \rangle \mathcal{P} \p{z} \mathbbm{1}_{\langle z, x_\ell \rangle \geq T} \ dz = 0.
\end{align}
\end{lem}

In Lemma \ref{lemma:2}, stated below, and proved in Section \ref{sec:proofLemma2}, we prove that $\alpha_\ell \geq T$, and that $\alpha_\ell$ is independent of $\ell$, i.e., $\alpha_{\ell_1} = \alpha_{\ell_2}$, for every $\ell_1, \ell_2 \in \pp{L}$, which completes the proof of the first part of the proposition.

\begin{lem} \label{lemma:2}
Recall the definition of $m_{\ell}^{(T)}$ in \eqref{eq:mu_l_def}. For every $\ell_1, \ell_2 \in \pp{L}$, the following holds as $N \to \infty$,
\begin{align}
    \alpha_{\ell_1} = \norm{\langle m_{\ell_1}^{(T)}, x_{\ell_1} \rangle} = \norm{\langle m_{\ell_2}^{(T)}, x_{\ell_2} \rangle} = \alpha_{\ell_2} \geq T.
\end{align}
\end{lem}


\paragraph{Part (2).} In this part, we prove that asymptotically in $T$, the factor $\alpha$ grows linearly with $T$, attaining the lower bound from the previous part. To prove this result, we use Lemma \ref{lemma:3}, which is stated below and proved in Section \ref{sec:proofLemma3}. 

\begin{lem} \label{lemma:3}
Let $\mathbb{E}_{g_\ell} \pp{z} = \int_{\mathbb{R}^d} z \cdot g_\ell \p{z} dz$, and  let $C_T$ be the normalization factor of $g_\ell$, for every $T \in \mathbb{R}^+$. Then, for $T \to \infty$, 
\begin{align}
     \lim_{T \to \infty} \norm{\frac{\mathbb{E}_{g_\ell}\pp{z}}{T} } = \lim_{T \to \infty} \norm{\frac{1}{T} \int_{\mathbb{R}^d} C_T \cdot y \cdot \mathcal{P} \p{y} \mathbbm{1}_{\langle y, x_\ell \rangle \geq T} \ dy} = 1.
\end{align}
\end{lem}
Then, combining Lemma \ref{lemma:1}, Lemma \ref{lemma:2}, and Lemma \ref{lemma:3}, and the fact that $\|x_\ell\| = 1$, for every $\ell \in \pp{L}$, results 
\begin{align}
    \lim_{N,T \to \infty} \norm{\frac{\alpha_\ell^{(T)}}{T}} = \lim_{N,T \to \infty} \norm{\frac{m_\ell^{(T)}}{T}} \overset{\mathrm{a.s.}}{=}  \lim_{T \to \infty} \norm{\frac{\mathbb{E}_{g_\ell}\pp{z}}{T} } = 1.
\end{align}
where the first almost sure convergence follows from \eqref{eqn:SLLNsingleMixtureMean}, and the second convergence follows by applying Lemma \ref{lemma:3}, which completes the proof of the second part of the proposition.

\subsubsection{Proof of Lemma \ref{lemma:1}} \label{sec:proofLemma1}
Fix $u \in \mathbb{R}^d$, such that $\langle u, x_\ell \rangle = 0$. First, we show that for every $v \in \mathcal{V}_\ell^{(T)}$, there is a unique corresponding $v' \in \mathcal{V}_\ell^{(T)}$ such that $\langle u, v \rangle = - \langle u,v' \rangle$, and $\mathcal{P}\p{v} = \mathcal{P}\p{v'}$.
Every $v \in \mathbb{R}^d$ can be decomposed uniquely by $v = \gamma_v u + w$, where $w \in \mathbb{R}^d$ orthogonal to $u$, $\langle u, w \rangle = 0$.  
Define $v' = -\gamma_v u + w$. Clearly, the map $v \to v'$ is unique, and due to the orthogonality between $u$ and $w$, we have, $\langle u, v \rangle = \gamma_v$, and $\langle u, v' \rangle = -\gamma_v$; thus, $\langle u, v \rangle = - \langle u,v' \rangle$. In addition, $v \in \mathcal{V}_\ell^{(T)}$ if and only if $v' \in \mathcal{V}_\ell^{(T)}$, since,
\begin{align}
    v \in \mathcal{V}_\ell^{(T)}  & \Longleftrightarrow   \langle v, x_\ell \rangle \geq T \Longleftrightarrow \langle \gamma_v u + w, x_\ell \rangle \geq T  
    \nonumber \\ & \Longleftrightarrow \langle w, x_\ell \rangle \geq T \label{eqn:iffBelongToVell}
    \\ &  \Longleftrightarrow \langle -\gamma_v u + w, x_\ell \rangle \geq T \Longleftrightarrow \langle v', x_\ell \rangle \geq T \Longleftrightarrow  v' \in \mathcal{V}_\ell^{(T)}, \nonumber
\end{align}
where the transition in \eqref{eqn:iffBelongToVell} follows from the orthogonality between $u$ and $x_\ell$.

Next, we show that $\mathcal{P}\p{v} = \mathcal{P}\p{v'}$. We note that $\mathcal{P}$ \eqref{eqn:g_N_def} is an isotropic function that depends solely on the norm of $z$. Thus, we prove below that $\norm{v} = \norm{v'}$, which would prove that $\mathcal{P} \p{v} = \mathcal{P} \p{v'}$: \begin{align}
    \norm{v}^2 = \norm{\gamma_v u + w}^2 = \gamma_v^2\norm{u}^2 + \norm{w}^2 = \norm{-\gamma_v u + w}^2 = \norm{v'}^2,
\end{align}
where in the second equality we have used the orthogonality between $u$ and $w$. Therefore, $\norm{v} = \norm{v'}$, which shows that $\mathcal{P} \p{v} = \mathcal{P} \p{v'}$.

Next, note that the right-hand-side of \eqref{eqn:SLLNsingleMixtureMean} can be rewritten as follows,
\begin{align}
    \int_{\mathbb{R}^d} \langle z, u \rangle \mathcal{P} \p{z} & \mathbbm{1}_{\langle z, x_\ell \rangle \geq T} \ dz  = \int_{z \in \mathcal{V}_\ell^{(T)}} \langle z, u \rangle \mathcal{P} \p{z} \ dz \nonumber
    \\ & = \int_{z \in \mathcal{V}_\ell^{(T)}: \langle z, u \rangle > 0} \langle z, u \rangle \mathcal{P} \p{z} \ dz + \int_{z \in \mathcal{V}_\ell^{(T)}: \langle z, u \rangle < 0} \langle z, u \rangle \mathcal{P} \p{z} \ dz. \label{eqn:Appx_C13}
\end{align}
Thus, since for every $v \in \mathcal{V}_\ell^{(T)}$ there is a unique corresponding $v' \in \mathcal{V}_\ell^{(T)}$ such that ${\langle{v, u_i\rangle}} = -{\langle{v', u_i\rangle}}$ and $\mathcal{P}\p{v} = \mathcal{P}\p{v'}$, it is clear that the r.h.s. of \eqref{eqn:Appx_C13} is zero, which completes the proof.

\subsubsection{Proof of Lemma \ref{lemma:2}} \label{sec:proofLemma2}
First, we show that for every $\ell_1, \ell_2 \in \pp{L}$, $\langle x_{\ell_1}, {m_{\ell_1}^{(T)}} \rangle = \langle x_{\ell_2}, {m_{\ell_2}^{(T)}} \rangle$, which proves that $\alpha$ is independent of $\ell$. As the templates $\ppp{x_\ell}_{\ell=0}^{L-1}$ are normalized, there is a orthonormal matrix $O_{\ell_1, \ell_2}$, such that $O_{\ell_1, \ell_2} x_{\ell_1} = x_{\ell_2}$. Then, following from the right-hand-side of \eqref{eqn:SLLNsingleMixtureMean}, we have,
\begin{align}
    \langle x_{\ell_1}, {m_{\ell_1}^{(T)}} \rangle & = 
    \int_{\mathbb{R}^d} \langle z, x_{\ell_1} \rangle \mathcal{P} \p{z} \mathbbm{1}_{\langle z, x_{\ell_1} \rangle \geq T} \ dz \label{eqn:app_C19}
    \\ & = \int_{\mathbb{R}^d} \langle z, O_{\ell_2, \ell_1} x_{\ell_2} \rangle \mathcal{P} \p{z} \mathbbm{1}_{\langle z, O_{\ell_2, \ell_1} x_{\ell_2} \rangle \geq T} \ dz \label{eqn:app_C20}
    \\ & = \int_{\mathbb{R}^d} \langle O_{\ell_2, \ell_1} z, O_{\ell_2, \ell_1} x_{\ell_2} \rangle \mathcal{P} \p{O_{\ell_2, \ell_1} z} \mathbbm{1}_{\langle O_{\ell_2, \ell_1} z, O_{\ell_2, \ell_1} x_{\ell_2} \rangle \geq T} \ dz \label{eqn:app_C21}
    \\ & = \int_{\mathbb{R}^d} \langle z, x_{\ell_2} \rangle \mathcal{P} \p{O_{\ell_2, \ell_1} z} \mathbbm{1}_{\langle z, x_{\ell_2} \rangle \geq T} \ dz \label{eqn:app_C22}
    \\ & = \int_{\mathbb{R}^d} \langle z, x_{\ell_2} \rangle \mathcal{P} \p{z} \mathbbm{1}_{\langle z, x_{\ell_2} \rangle \geq T} \ dz \label{eqn:app_C23}
    \\ & = \langle x_{\ell_2}, {m_{\ell_2}^{(T)}} \rangle, \label{eqn:app_C24}
\end{align}
where \eqref{eqn:app_C19} follows from the dentition of $m_\ell^{(T)}$; \eqref{eqn:app_C20} follows from the orthonormal operator definition of $O_{\ell_2, \ell_1}$; \eqref{eqn:app_C21} follows from substitution of variables $z \to O_{\ell_2, O_{\ell_1}} \cdot z$; \eqref{eqn:app_C22} follows from the property of orthonormal operator $O$, which satisfies, $\langle O \cdot a, O \cdot b \rangle = \langle a, b \rangle$ for every $a,b \in \mathbb{R}^d$; \eqref{eqn:app_C23} follows from the isotropic property of $\mathcal{P} \p{z} = \mathcal{P} \p{O \cdot z}$, that is for every orthonormal operator $O$ and for every $z \in \mathbb{R}^d$, $\norm{O \cdot z} = \norm{z}$; and \eqref{eqn:app_C24} follows from the dentition of $m_\ell^{(T)}$. 

Next, we show that $\alpha_\ell \geq T$. As the templates $\ppp{x_\ell}_{\ell=0}^{L-1}$ are normalized, $\|{x_\ell\| } = 1$, for every $\ell \in \pp{L}$, then,
\begin{align}
    \alpha_\ell = \|{\langle m_\ell^{(T)}, x_\ell \rangle}\| = \|{m_\ell^{(T)}}\|.
\end{align}
Then, following the definition of $m_\ell^{(T)}$ \eqref{eq:mu_l_def} and the SLLN \eqref{eqn:SLLNsingleMixtureMean}, we have,
\begin{align}
    \alpha_\ell = \norm{\langle m_\ell^{(T)}, x_\ell \rangle} 
    & = \norm{\frac{1}{|\mathcal{A}_\ell^{(T)}|} \sum_{z_i \in \mathcal{A}_\ell} \langle z_i, x_\ell \rangle}  \nonumber
     \\ & \xrightarrow[]{\s{a.s.}} \norm{C_T\int_{\mathbb{R}^d} \langle z, x_\ell \rangle \mathcal{P} \p{z} \mathbbm{1}_{\langle z, x_\ell \rangle \geq T} \ dz} \label{eqn:app_D20}
\end{align}
Similar to Lemma~\ref{lemma:1}, for every $z \in \mathbb{R}^d$, we can decompose it into $z = \beta_z x_\ell + \gamma_z w_z$, where $\langle w_z, x_\ell  \rangle = 0$, and $\beta_z \geq T$, by the definition of the domain of the integral. Thus, we can decompose the integral in \eqref{eqn:app_D20} as follows:
\begin{align}
    \int_{\mathbb{R}^d} \langle z, x_\ell \rangle \mathcal{P} \p{z} \mathbbm{1}_{\langle z, x_\ell \rangle \geq T} \ dz & = \int_{\mathbb{R}^d} \langle \beta_z x_\ell, x_\ell \rangle \mathcal{P} \p{z} \mathbbm{1}_{\langle z, x_\ell \rangle \geq T} \ dz \nonumber
    \\ &  \quad + \int_{\mathbb{R}^d} \langle \gamma_z w_z, x_\ell \rangle \mathcal{P} \p{z} \mathbbm{1}_{\langle z, x_\ell \rangle \geq T} \ dz \label{eqn:app_D21}
\end{align}

By Lemma~\ref{lemma:1}, there exists $z' = \beta_z x_\ell - \gamma_z w_z$, such that $\norm{z'} = \norm{z}$, and $\langle z', x_\ell \rangle \geq T$. Thus, as $\mathcal{P}$ is isotropic, that is, $\mathcal{P}(z) = \mathcal{P}(z')$ for $\norm{z} = \norm{z'}$, the last term in \eqref{eqn:app_D21} vanishes:
\begin{align}
    \int_{\mathbb{R}^d} \langle \gamma_z w_z, x_\ell \rangle \mathcal{P} \p{z} \mathbbm{1}_{\langle z, x_\ell \rangle \geq T} \ dz = 0. \label{eqn:app_D22}
\end{align}
Substituting \eqref{eqn:app_D22} into \eqref{eqn:app_D21} results,
\begin{align}
    \int_{\mathbb{R}^d} \langle z, x_\ell \rangle \mathcal{P} \p{z} \mathbbm{1}_{\langle z, x_\ell \rangle \geq T} \ dz & = \int_{\mathbb{R}^d} \langle \beta_z x_\ell, x_\ell \rangle \mathcal{P} \p{z} \mathbbm{1}_{\langle z, x_\ell \rangle \geq T} \ dz \nonumber
     \\ & = \int_{\mathbb{R}^d} \beta_z \|x_\ell\|^2 \mathcal{P} \p{z} \mathbbm{1}_{\langle z, x_\ell \rangle \geq T} \ dz \nonumber
     \\ & = \int_{\mathbb{R}^d} \beta_z  \mathcal{P} \p{z} \mathbbm{1}_{\langle z, x_\ell \rangle \geq T} \ dz,
     \label{eqn:app_D23}
\end{align}
where we have used $\|x_\ell\| = 1$. As $\beta_z \geq T$ for every $z \in \mathcal{V}_\ell^{(T)}$, we have,
\begin{align}
    C_T \int_{\mathbb{R}^d} \beta_z  \mathcal{P} \p{z} \mathbbm{1}_{\langle z, x_\ell \rangle \geq T} \ dz \geq T. \label{eqn:app_D24_1}
\end{align}
Substituting \eqref{eqn:app_D24_1} into \eqref{eqn:app_D20} results,
\begin{align}
    \alpha_\ell \xrightarrow[]{\s{a.s.}} \norm{C_T\int_{\mathbb{R}^d} \langle z, x_\ell \rangle \mathcal{P} \p{z} \mathbbm{1}_{\langle z, x_\ell \rangle \geq T} \ dz} \geq T, \label{eqn:app_D24_2}
\end{align}
which completes the proof of the lemma.

\subsubsection{Proof of Lemma \ref{lemma:3}} \label{sec:proofLemma3}
Assume without loss of generality that $x_\ell = e_1$, the first standard basis vector. This can always be arranged by rotating coordinates, due to the isotropy of the Gaussian distribution (see Lemma \ref{lemma:2}).
Let $z = (z_1, z_2, \dots, z_d) \sim \mathcal{N}(0, \sigma^2 I_{d \times d})$. Then, $z_1 \sim \mathcal{N}(0, \sigma^2)$, independent of $z_2, \dots, z_d$.

The distribution $g_\ell(z)$, defined in \eqref{eqn:componentOfMixtureModelParticlePicker}, can be represented by
\begin{align}
    g_\ell(z) = \frac{1}{\mathbb{P}(z_1 \geq T)} \cdot \mathcal{P}(z) \cdot \mathbbm{1}_{\{z_1 \geq T\}},
\end{align}
where $\mathcal{P}(z) = \frac{1}{(2\pi \sigma^2)^{d/2}} \exp\left( -\frac{\|z\|^2}{2\sigma^2} \right)$ is the isotropic Gaussian density with mean 0 and covariance $\sigma^2 I_{d \times d}$.
Thus, the expectation becomes:
\begin{align}
    \mathbb{E}_{g_\ell}[z] = \frac{1}{\mathbb{P}(z_1 \geq T)} \int_{z_1 \geq T} z \cdot \mathcal{P}(z) \, dz. \label{eqn:app_D24}
\end{align}

Because the Gaussian is symmetric and the truncation is only in the \( z_1 \) direction, the only nonzero component of the expectation is in the \( e_1 \) direction. That is,
\begin{align}
    \mathbb{E}_{g_\ell}[z] = \mathbb{E}_{g_\ell}[z_1] \cdot e_1,
\end{align}
and thus we have,
\begin{align}
    \left\| \frac{\mathbb{E}_{g_\ell}[z]}{T} \right\| = \frac{\mathbb{E}_{g_\ell}[z_1]}{T}. \label{eqn:app_D26}
\end{align}

Our aim is to compute the right-hand-side of \eqref{eqn:app_D26} for $T \to \infty$,
\begin{align}
    \lim_{T \to \infty} \frac{1}{T} \cdot \frac{1}{\mathbb{P}(z_1 \geq T)} \int_T^\infty z_1 \cdot \frac{1}{\sqrt{2\pi \sigma^2}} \exp\left(-\frac{z_1^2}{2\sigma^2} \right) \, dz_1. \label{eqn:app_D27}
\end{align}
Let us define the one-dimensional Gaussian probability density function:
\begin{align}
    \varphi_\sigma(z) = \frac{1}{\sqrt{2\pi \sigma^2}} e^{-z^2 / (2\sigma^2)}, \label{eqn:app_D28}
\end{align}
and the upper right tail:
\begin{align}
    Q_\sigma(T) = \int_T^\infty \varphi_\sigma(z) \, dz. \label{eqn:app_D29}
\end{align}
Then, substituting \eqref{eqn:app_D28} and \eqref{eqn:app_D29} into \eqref{eqn:app_D24} results,
\begin{align}
    \mathbb{E}_{g_\ell}[z_1] = \frac{1}{Q_\sigma(T)} \int_T^\infty z_1 \varphi_\sigma(z_1) \, dz_1. \label{eqn:app_D30}
\end{align}

This expression corresponds to the conditional mean of a Gaussian random variable truncated from below.  For $X \sim \mathcal{N}(0, \sigma^2)$ it is known that \cite{durrett2019probability}
\begin{align}
    \mathbb{E}[X \mid X \geq T] = \sigma \cdot \frac{\varphi(T/\sigma)}{Q(T/\sigma)}, \label{eqn:app_D31}
\end{align}
where $\varphi$ is the standard normal density and $Q$ is the standard upper tail probability.

Using the following known asymptotic relation \cite{durrett2019probability}, 
\begin{align}
    \frac{\varphi(t)}{Q(t)} \sim t + \frac{1}{t}, \quad \text{as } t \to \infty. \label{eqn:app_D32}
\end{align}
and by \eqref{eqn:app_D31}, we have,
\begin{align}
    \mathbb{E}[X \mid X \geq T] =  \sigma \cdot \frac{\varphi(T/\sigma)}{Q(T/\sigma)}\sim T + \frac{\sigma^2}{T},
\end{align}
as $T \to \infty$. Therefore,
\begin{align}
    \frac{\mathbb{E}_{g_\ell}[z_1]}{T} = \frac{\mathbb{E}[X \mid X \geq T]}{T} \sim \frac{T + \sigma^2/T}{T} = 1 + \frac{\sigma^2}{T^2}. \label{eqn:app_D33}
\end{align}
Hence, combining \eqref{eqn:app_D26},  \eqref{eqn:app_D27}, and \eqref{eqn:app_D33} results,
\begin{align}
    \lim_{T \to \infty} \left\| \frac{\mathbb{E}_{g_\ell}[z]}{T} \right\| = \lim_{T \to \infty} \frac{\mathbb{E}_{g_\ell}[z_1]}{T} = 1,
\end{align}
completing the proof of the lemma.

\subsection{Proof of Theorem \ref{thm:classesCentersVersusTemplates}}
Recall the definitions of the \textit{postulated} GMM model, given in \eqref{eqn:GMMmodel}, and the \textit{actual} statistics of the extracted particles, given in \eqref{eqn:mixtureModelParticlePicker}. 
Their respective probability density functions are $f,g: \mathbb{R}^d \to \mathbb{R}$, each consists of $L$ components, and are defined by,
\begin{align}
    f\p{z; \ppp{\mu_\ell}_{\ell \in \pp{L}}} = \sum_{\ell=0}^{L-1} w_\ell f_{\ell}(z) = \sum_{\ell=0}^{L-1} w_\ell \cdot \mathcal{N}\p{z; \mu_\ell, \Sigma_\ell = \sigma_{\s{GMM}}^2 I_{d \times d}}, \label{eqn:GMMmodelExcplicit}
\end{align}
and,
\begin{align}
    g\p{z; \ppp{m_\ell}_{\ell \in \pp{L}}} = \sum_{\ell=0}^{L-1} \pi_\ell g_{\ell}(z) = C_T \sum_{\ell=0}^{L-1} \pi_\ell  \cdot \exp\p{-\frac{\norm{z}_2^2}{2\sigma^2}} \mathbbm{1}_{\langle z, x_\ell \rangle \geq T}, \label{eqn:trueMixtureStatistics}
\end{align}
where $g_\ell$ is defined by \eqref{eqn:componentOfMixtureModelParticlePicker}, $\ppp{m_\ell}_{\ell=0}^{L-1}$ are the means of the mixture component distributions $\ppp{g_\ell}_{\ell=0}^{L-1}$, and $\ppp{\mu_\ell}_{\ell=0}^{L-1}$ are the means of the Gaussian mixture component distributions $\ppp{f_\ell}_{\ell=0}^{L-1}$. By definition,
\begin{align}
    m_\ell = \mathbb{E}_{g_\ell}\pp{z} = \int_{\mathbb{R}^d} z \cdot g_\ell \p{z} \ dz.
\end{align}
Note that $f, g \in C^0(\mathbb{R}^d)$ are continuous almost everywhere.

The output of Algorithm \ref{alg:particlePickerTemplateMatching} is the set $\mathcal{A} = \ppp{z_i}_{i=0}^{M-1} \in \mathbb{R}^d$, which follows the distribution $g$. However, the maximum-likelihood estimators of the centers $\ppp{\hat{\mu}_\ell}_{\ell=0}^{L-1}$ are given with respect to the likelihood function of the postulated model $f$:
\begin{align}
    \ppp{\hat{\mu}_\ell}_{\ell=0}^{L-1} & = \argmax_{\ppp{\mu_\ell}_{\ell=0}^{L-1}} \prod_{i=0}^{M-1} f \p{z_i ; \ppp{\mu_\ell}_{\ell=0}^{L-1}}. \label{eqn:maximumLiklehoodTerm}
\end{align}

The next lemma relates the maximum-likelihood estimators given in \eqref{eqn:maximumLiklehoodTerm} to the true statistics of the extracted particles, $g$. The lemma is proved in Section \ref{sec:proofLemma4}.

\begin{lem} \label{lemma:4}
Let $\ppp{\hat{\mu}_\ell}_{\ell=0}^{L-1}$ be the maximum-likelihood estimators given by \eqref{eqn:maximumLiklehoodTerm}, based on the postulated GMM model with probability density function $f$, given in \eqref{eqn:GMMmodelExcplicit}. Let $g$ represent the actual statistics of the extracted particles, given by \eqref{eqn:trueMixtureStatistics}. Then, as $N \to \infty$,
\begin{align}
    \nonumber \ppp{\hat{\mu}_\ell}_{\ell=0}^{L-1}  & \xrightarrow[]{\s{a.s.}} \argmin_{\ppp{\mu_\ell}_{\ell=0}^{L-1}} \int dz \ g \p{z ; \ppp{m_\ell}_{\ell=0}^{L-1}} \log \frac{g \p{z ; \ppp{m_\ell}_{\ell=0}^{L-1}}}{{f \p{z ; \ppp{\mu_\ell}_{\ell=0}^{L-1}}}} \\ & = \argmin_{\ppp{\mu_\ell}_{\ell=0}^{L-1}} D_{\s{KL}} \p{g || f \p{\ppp{\mu_\ell}_{\ell=0}^{L-1}}}, \textbf{\label{eqn:KLdiv}}
\end{align}
where $D_{\s{KL}}$ is the Kullback–Leibler divergence.
\end{lem}

In other words, the maximum-likelihood estimator of the means $\ppp{\hat{\mu_\ell}}_{\ell \in \pp{L}}$, given by \eqref{eqn:maximumLiklehoodTerm}, converges to the estimators that minimize the Kullback–Leibler (KL) divergence between the expected GMM statistics $f$, and the true probability distribution $g$, from which the extracted particles were generated. Thus, the maximum-likelihood estimator provides the closest distribution (within the constraints of the GMM model, dependent on $\ppp{\hat{\mu_\ell}}_{\ell \in \pp{L}}$) to the true distribution $g$.

We substitute the expression of $f,g$ following from \eqref{eqn:GMMmodelExcplicit}, and \eqref{eqn:trueMixtureStatistics} into \eqref{eqn:KLdiv}, and obtain,
\begin{align}
    \ppp{\hat{\mu}_\ell}_{\ell=0}^{L-1} & \xrightarrow[]{\s{a.s.}} \argmax_{\ppp{\mu_\ell}_{\ell=0}^{L-1}} \int dz \ g \p{z ; \ppp{m_\ell}_{\ell=0}^{L-1}} \log{f \p{z \mid \ppp{\mu_\ell}_{\ell=0}^{L-1}}} \nonumber
    \\ & = \argmax_{\ppp{\mu_k}_{k=0}^{L-1}} \int dz \sum_{\ell=0}^{L-1} \ \pi_\ell g_\ell \p{z} \log\pp{ \sum_{k=0}^{L-1} w_k f_k \p{z; \mu_k}} 
\nonumber    \\ & = \argmax_{\ppp{\mu_k}_{k=0}^{L-1}} \sum_{\ell=0}^{L-1} \pi_\ell \int dz \  g_\ell \p{z} \log\pp{ \sum_{k=0}^{L-1} w_k f_k \p{z; \mu_k}}. \label{eqn:MLestimatoesExplicitFormMM}
\end{align}

We define the expression within the $\argmax$ term in \eqref{eqn:MLestimatoesExplicitFormMM} by:
\begin{align}
    \mathcal{H} \p{\{ \mu_\ell\}_{\ell =0}^{L-1}} \triangleq \sum_{\ell=0}^{L-1} \pi_\ell \int dz \  g_\ell \p{z} \log\pp{ \sum_{k=0}^{L-1} w_k f_k \p{z; \mu_k}}. \label{eqn:mathcalH}
\end{align}
The next lemma shows that as $T \to \infty$ the means $\ppp{\mu_k}_{k \in \pp{L}}$ that maximize $\mathcal{H}$ converge to the means $\ppp{m_\ell}_{\ell \in \pp{L}}$ of the true probability distribution $g$. The lemma is proved in Section \ref{sec:proofLemma5}.

\begin{lem} \label{lemma:5}
Let $\mathcal{H}$ denote the function defined in \eqref{eqn:mathcalH}. Then, as $T \to \infty$, the $\ppp{\mu_k}_{k \in \pp{L}}$ that maximize $\mathcal{H}$ are given by,
\begin{align}
    \lim_{T \to \infty} \pp{\argmax_{\ppp{\mu_\ell}_{\ell=0}^{L-1}}  \ \p{\frac{\mathcal{H} \p{\{ \mu_\ell\}_{\ell =0}^{L-1}}}{T}} } = \ppp{x_\ell}_{\ell=0}^{L-1}.
\end{align}
\end{lem}
The global maximum is unique, up to a permutation between the centers of the likelihood function, i.e., there exists a permutation function $\pi: \pp{L} \to \pp{L}$, such that for every $0 \leq \ell \leq L-1$,
\begin{align}
    \lim_{T \to \infty} \frac{\hat{\mu}_{\pi \p{\ell}}}{m_\ell} = 1.
\end{align}
Combining \eqref{eqn:maximumLiklehoodTerm}, Lemma \ref{lemma:4}, \eqref{eqn:mathcalH}, and Lemma \ref{lemma:5} completes the proof.

\subsubsection{Proof of Lemma \ref{lemma:4}}
\label{sec:proofLemma4}
Rearranging \eqref{eqn:maximumLiklehoodTerm} results,
\begin{align}
    \ppp{\hat{\mu}_\ell}_{\ell=0}^{L-1} & = \argmax_{\ppp{\mu_\ell}_{\ell=0}^{L-1}} \prod_{i=0}^{M-1} f \p{z_i \mid \ppp{\mu_\ell}_{\ell=0}^{L-1}}  \nonumber\\ & = \argmax_{\ppp{\mu_\ell}_{\ell=0}^{L-1}} \sum_{i=0}^{M-1} \log {f \p{z_i \mid \ppp{\mu_\ell}_{\ell=0}^{L-1}}} \nonumber \\ & = \argmax_{\ppp{\mu_\ell}_{\ell=0}^{L-1}} \frac{1}{M} \sum_{i=0}^{M-1} \log {f \p{z_i \mid \ppp{\mu_\ell}_{\ell=0}^{L-1}}} - \frac{1}{M} \sum_{i=0}^{M-1} \log {g \p{z_i ; \ppp{m_\ell}_{\ell=0}^{L-1}}} \\ & = \argmax_{\ppp{\mu_\ell}_{\ell=0}^{L-1}} \frac{1}{M} \sum_{i=0}^{M-1} \log \frac{{f \p{z_i \mid \ppp{\mu_\ell}_{\ell=0}^{L-1}}}}{{g \p{z_i ; \ppp{m_\ell}_{\ell=0}^{L-1}}}} \nonumber\\ & \xrightarrow[]{\s{a.s.}} \argmin_{\ppp{\mu_\ell}_{\ell=0}^{L-1}} \int dz \ g \p{z ; \ppp{m_\ell}_{\ell=0}^{L-1}} \log \frac{g \p{z ; \ppp{m_\ell}_{\ell=0}^{L-1}}}{{f \p{z \mid \ppp{\mu_\ell}_{\ell=0}^{L-1}}}} \nonumber\\ & = \argmin_{\ppp{\mu_\ell}_{\ell=0}^{L-1}} D_{\s{KL}} \p{g || f \p{\ppp{\mu_\ell}_{\ell=0}^{L-1}}}, \nonumber
\end{align}
where the last transition follows from the strong law of large number (SLLN), and $D_\s{KL}$ represents the Kullback-Leibler divergence \cite{kullback1951information}.



\subsubsection{Proof of Lemma \ref{lemma:5}}
\label{sec:proofLemma5}
To obtain the maximum argument of \eqref{eqn:mathcalH}, we derive it with respect to each one of the means $\ppp{\mu_\ell}_{\ell=0}^{L-1}$. Recall the definition of $g_\ell$ in \eqref{eqn:componentOfMixtureModelParticlePicker} and of the GMM distribution $f$ in \eqref{eqn:GMMmodelExcplicit}. Then,
\begin{align}
    \frac{\partial}{\partial \mu_k}\mathcal{H} & = \frac{1}{\sigma_{\s{GMM}}^2}
    \sum_{\ell=0}^{L-1} \pi_{\ell} \int dz \  g_{\ell} \p{z} \frac{w_k f_k\p{z;\mu_k} } {\sum_{r=0}^{L-1} w_r f_r \p{z;\mu_r}} \p{z-\mu_{k}} 
    \\ & = \frac{C_T}{\sigma_{\s{GMM}}^2} \sum_{\ell=0}^{L-1} \pi_{\ell} \int dz \  \exp \p{-\frac{\norm{z}^2}{2}} \mathbbm{1}_{\langle z, x_{\ell} \rangle \geq T}  \frac{w_k f_k\p{z;\mu_k} } {\sum_{r=0}^{L-1} w_r f_r \p{z;\mu_r}} \p{z-\mu_{k}} 
\end{align}
To obtain the maximum of $\mathcal{H}$, the following condition is necessary:
\begin{align}
    \frac{\partial}{\partial \mu_k}\mathcal{H} & = \sum_{\ell=0}^{L-1} \pi_{\ell} \int dz \  g_{\ell} \p{z} \frac{w_k f_k\p{z;\mu_k} } {\sum_{r=0}^{L-1} w_r f_r \p{z;\mu_r}} \p{z-\mu_{k}} = 0, \label{eqn:AppC17}
\end{align}
for every $k \in \pp{L}$.

Our aim is to find sufficient conditions such that $\ppp{\hat{\mu_\ell}}_{\ell \in \pp{L}} = \{m_\ell^{(T)}\}_{\ell \in \pp{L}}$, i.e., that the maximum-likelihood estimators $\ppp{\hat{\mu_\ell}}_{\ell=0}^{L-1}$ would converge to the means of the true distribution of the particles $\ppp{g_\ell}_{\ell=0}^{L-1}$. Thus, the following should hold by substituting $\ppp{\mu_\ell}_{\ell=0}^{L-1} = \{m_\ell^{(T)}\}_{\ell \in \pp{L}}$ into \eqref{eqn:AppC17}:
\begin{align}
    \sum_{\ell=0}^{L-1} \pi_{\ell} \int dz \  g_{\ell} \p{z} \frac{w_k f_k\p{z;m_k^{(T)}} } {\sum_{r=0}^{L-1} w_r f_r \p{z;m_r^{(T)}}} \p{z-m_{k}^{(T)}} = 0, \label{eqn:AppC18}
\end{align}
where \eqref{eqn:AppC18} must hold for every $k \in \pp{L}$. For notation simplicity, we remove the $T$ transcript in $m_k^{(T)}$. 

We rearrange the terms related to the distribution $f$ in \eqref{eqn:AppC18}, following the definition of the GMM $f$ from \eqref{eqn:GMMmodelExcplicit}:
\begin{align}
    \frac{w_k f_k\p{z;m_k} } {\sum_{r=0}^{L-1} w_r f_r \p{z;m_r}} 
    & = \frac{w_k \exp \p{-\frac{\norm{z-m_k}^2}{2\sigma_{\s{GMM}}^2}} } {\sum_{r=0}^{L-1} w_r \exp \p{-\frac{\norm{z-m_r}^2}{2\sigma_{\s{GMM}}^2}}} 
    \nonumber \\ & = \frac{w_k \exp \p{-\frac{\norm{m_k}^2 - 2\langle z, m_k \rangle}{2\sigma_{\s{GMM}}^2}} } {\sum_{r=0}^{L-1} w_r \exp \p{-\frac{\norm{m_r}^2 - 2\langle z, m_r \rangle}{2\sigma_{\s{GMM}}^2}}} 
    \\ & = \frac{w_k \exp\ppp{\langle z, m_k \rangle / \sigma_{\s{GMM}}^2}}{\sum_{r=0}^{L-1} w_r \exp \ppp{\langle z, m_r \rangle /\sigma_{\s{GMM}}^2}} \nonumber \\ & = \frac{w_k \exp\ppp{\langle z, \alpha x_k \rangle /\sigma_{\s{GMM}}^2}}{\sum_{r=0}^{L-1} w_r \exp \ppp{\langle z, \alpha x_r \rangle /\sigma_{\s{GMM}}^2}}, \nonumber
\end{align}
where the last two steps followed from Proposition \ref{thm:prop1}, i.e., $\norm{m_\ell} = \norm{m_k} = \alpha$, for every $k,\ell \in \pp{L}$. 
Recall that $\alpha \geq T$. Thus, for $T\to \infty$, we have for $\ppp{w_\ell}_{\ell \in \pp{L}} > 0$ \cite{balanov2024confirmation},
\begin{align}
    \lim_{T \to \infty} \frac{w_k \exp\ppp{\alpha \langle z, x_k \rangle /\sigma_{\s{GMM}}^2}}{\sum_{r=0}^{L-1} w_r \exp \ppp{\alpha \langle z,  x_r \rangle /\sigma_{\s{GMM}}^2}} 
    = \mathbbm{1} \ppp {\langle z, x_k \rangle = \max_{r \in \pp{L}} {\langle z, x_r \rangle}}. \label{eqn:appx_C56}
\end{align}
%In other words, as $T \to \infty$, the left-hand-side of \eqref{eqn:appx_C56} converge to the $\argmax$ expression. 

Recall the definition of $\mathcal{V}_\ell^{(T)} \subset \mathbb{R}^d$ \eqref{eqn:VlDef}. The result in \eqref{eqn:appx_C56} implies that the components are well-separated, i.e., that $\mathcal{V}_{\ell_1}^{(T)}$ and $\mathcal{V}_{\ell_2}^{(T)}$ are disjoint sets as $T \to \infty$.
Taking the limit $T \to \infty$ of each term of the summation in \eqref{eqn:AppC18} results,
\begin{align}
    \lim_{T \to \infty} & \ \frac{1}{T}\int dz  \  g_{\ell} \p{z} \frac{w_k f_k\p{z;m_k} } {\sum_{r=0}^{L-1} w_r f_r \p{z;m_r}} \p{z-m_{k}} \nonumber
    \\ & = \lim_{T \to \infty} \ \frac{C_T }{T} \int_{z \in \mathcal{V}_\ell^{(T)}} dz \ \exp \p{-\frac{\norm{z}^2}{2\sigma^2}} \frac{w_k f_k\p{z;m_k} } {\sum_{r=0}^{L-1} w_r f_r \p{z;m_r}} \p{z-m_{k}} \nonumber
    \\ & = \lim_{T \to \infty}  \ \frac{C_T }{T} \int_{z \in \mathcal{V}_\ell^{(T)}} dz \ \exp \p{-\frac{\norm{z}^2}{2\sigma^2}} \frac{w_k f_k\p{z;m_k} } {\sum_{r=0}^{L-1} w_r f_r \p{z;m_r}} z -  
     \nonumber \\ & \quad \quad - \lim_{T \to \infty} \ \frac{C_T }{T} \int_{z \in \mathcal{V}_\ell^{(T)}} dz \ \exp \p{-\frac{\norm{z}^2}{2\sigma^2}} \frac{w_k f_k\p{z;m_k} } {\sum_{r=0}^{L-1} w_r f_r \p{z;m_r}} m_k \label{eqn:appx_C59}
\end{align}
Following from part (2) in Proposition \ref{thm:prop1}, \eqref{eqn:appx_C56}, and by applying the dominated convergence theorem, which allows to interchange the sequence between the limits and the integral, we have,
\begin{align}
    \lim_{T \to \infty} \ \frac{C_T}{T} \int_{z \in \mathcal{V}_\ell^{(T)}}  \ z \ \exp \p{-\frac{\norm{z}^2}{2\sigma^2}} \frac{w_k f_k\p{z;m_k} } {\sum_{\ell=0}^{L-1} w_\ell f_\ell \p{z;m_\ell}} \ dz = \delta_{k \ell} x_\ell. \label{eqn:app_C61}
\end{align}
In addition, following from \eqref{eqn:appx_C56}, we have,
\begin{align}
    \lim_{T \to \infty} \ C_T \int_{z \in \mathcal{V}_\ell^{(T)}}  \ \exp \p{-\frac{\norm{z}^2}{2\sigma^2}} \frac{w_k f_k\p{z;m_k} } {\sum_{\ell=0}^{L-1} w_\ell f_\ell \p{z;m_\ell}} \ dz = \delta_{k \ell}. \label{eqn:app_C62}
\end{align}
Substituting \eqref{eqn:app_C61}, and \eqref{eqn:app_C62} into \eqref{eqn:appx_C59} leads to,
\begin{align}
    \lim_{T \to \infty} & \ \frac{1}{T}\int dz  \  g_{\ell} \p{z} \frac{w_k f_k\p{z;m_k} } {\sum_{r=0}^{L-1} w_r f_r \p{z;m_r}} \p{z-m_{k}} \nonumber
    \\ & = \delta_{k \ell}x_\ell - \delta_{k \ell} \lim_{T \to \infty} \frac{m_\ell^{(T)}}{T}. \label{eqn:appx_C68}
\end{align}
From part (2) of Proposition \ref{thm:prop1},
\begin{align}
    \lim_{T \to \infty} \frac{m_\ell^{(T)}}{T} = x_\ell. \label{eqn:appx_C69}
\end{align}
Substituting \eqref{eqn:appx_C69} into \eqref{eqn:appx_C68} leads to \eqref{eqn:AppC18}. Thus, as $T \to \infty$, the means which maximizes  $\mathcal{H}$ are the means $\ppp{m_\ell}_{\ell \in \pp{L}}$ of the true components $g$, completing the proof of the lemma.

\subsection{Proof of Theorem \ref{thm:3DvolumeVsTemplateVolume}}
Let $x_\ell = R_\ell \cdot V_{\s{template}}$ 
denote the input templates used in Algorithm~\ref{alg:particlePickerTemplateMatching}.
By Assumption~\ref{assump:1}, the $\mathrm{SO}(3)$ samples used for generating these templates during the particle-picking stage, denoted by 
$\{ R_\ell \}_{\ell \in \{0, \dots, L-1\}}$, 
is the same as the samples used during the 3D reconstruction step. That is, the samples in \eqref{eqn:actualETstatistics} and \eqref{eqn:assumedLikeEst3DcryoET} are identical $\{ R_\ell \}_{\ell \in \{0, \dots, L-1\}} = \{ R_n \}_n$.
Recall the assumed probability density function used during 3D reconstruction, defined in \eqref{eqn:distributionCryoETfor3DalignDisc}: 
\begin{align}
    \bar{f}_{\text{ET}}(z; V) &= \frac{1}{(2\pi \sigma_V^2)^{d/2}} \sum_{R_\ell \in \mathrm{SO}(3)} w(R_\ell) \cdot \exp\left( -\frac{\| z - (R_\ell \cdot V) \|^2}{2\sigma_V^2} \right) \notag \\
    &= \sum_{\ell=0}^{L-1} w(R_\ell) \cdot \bar{f}_\ell(z; R_\ell \cdot V), \label{eqn:distributionCryoETfor3DalignDisc2}
\end{align}
where we define
\begin{align}
    \bar{f}_\ell(z; R_\ell \cdot V) \triangleq \frac{1}{(2\pi \sigma_V^2)^{d/2}} \exp\left( -\frac{\| z - R_\ell \cdot V \|_F^2}{2\sigma_V^2} \right). \label{eqn:app_D72}
\end{align}

In contrast, the actual distribution of the particles extracted by the template-matching particle picker is given in \eqref{eqn:actualETstatistics}:
\begin{align}
    g_{\text{picker}}(z) &\triangleq C_T \sum_{\ell=0}^{L-1} \pi(R_\ell) \cdot \exp\left( -\frac{\|z\|^2}{2\sigma^2} \right) \mathbbm{1}_{\langle z, R_\ell \cdot V_{\s{template}} \rangle \geq T} \notag \\
    &= \sum_{\ell=0}^{L-1} \pi(R_\ell) \cdot g_\ell(z), \label{eqn:actualETstatistics2}
\end{align}
where
\begin{align}
    g_\ell(z) \triangleq C_T \cdot \exp\left( -\frac{\|z\|_F^2}{2\sigma^2} \right) \mathbbm{1}_{\langle z, x_\ell \rangle \geq T}. \label{eqn:app_D74}
\end{align}

The maximum likelihood estimator $\hat{V}$ is defined by
\begin{align}
    \hat{V} = \arg\max_V \bar{\mathcal{L}}_{\text{assumed}}(V; \mathcal{A}), \label{eqn:app_D73}
\end{align}
where the objective $\bar{\mathcal{L}}_{\text{assumed}}$ is specified in \eqref{eqn:assumedLikeEst3DcryoET}.
Following the logic of Lemma~\ref{lemma:4} and Equation~\eqref{eqn:mathcalH}, we define the function
\begin{align}
    \mathcal{H}(V) \triangleq \sum_{\ell=0}^{L-1} \pi(R_\ell) \int dz \, g_\ell(z) \log\left( \sum_{k=0}^{L-1} w(R_k) \cdot \bar{f}_k(z; R_k \cdot V) \right). \label{eqn:mathcalH2}
\end{align}
Maximizing $\mathcal{H}$ yields the maximum likelihood estimator:
\begin{align}
    \hat{V} = \argmax_V \mathcal{H}(V). \label{eqn:maximumOfLogLikelihoodCryoET2}
\end{align}

We now state the following lemma, whose proof is given below.
\begin{lem}
\label{lemma:6}
    Let $\mathcal{H}(V)$ be defined as in \eqref{eqn:mathcalH2}. Then, in the limit as $T \to \infty$, the maximizer of $\mathcal{H}(V)/T$ converges to the template (up to a global rotation $R \in \s{SO}(3)$):
    \begin{align}
        \lim_{T \to \infty} \left\{ \argmax_V \left( \frac{\mathcal{H}(V)}{T} \right) \right\} = R \cdot V_{\s{template}}.
    \end{align}
\end{lem}
Combining Equation~\eqref{eqn:maximumOfLogLikelihoodCryoET2} with Lemma~\ref{lemma:6} completes the proof.
%It is left to prove Lemma \ref{lemma:6}.

\begin{proof}[Proof of Lemma~\ref{lemma:6}]
Recall the objective function $\mathcal{H}(V)$ defined in \eqref{eqn:mathcalH2}:
\begin{align}
    \mathcal{H}(V) = \sum_{\ell=0}^{L-1} \pi(R_\ell) \int dz \, g_\ell(z) \log\left( \sum_{k=0}^{L-1} w(R_k) \cdot \bar{f}_k(z; R_k \cdot V) \right),
\end{align}
where $g_\ell(z) = C_T \cdot \exp\left( -\frac{\|z\|_F^2}{2\sigma^2} \right) \mathbbm{1}_{\langle z, x_\ell \rangle \geq T}$ and $\bar{f}_k(z; R_k \cdot V)$ is the Gaussian density centered at $R_k \cdot V$ with variance $\sigma_V^2$.
As $T \to \infty$, the support of $g_\ell(z)$ becomes increasingly concentrated on the set of $z$ such that $\langle z, x_\ell \rangle \geq T$. Since the Gaussian term $\exp\left( -\frac{\|z\|^2}{2\sigma^2} \right)$ suppresses contributions from large-$\|z\|$ regions, the dominant contribution to the integral arises from values of $z$ that are nearly colinear with $x_\ell$, and of moderate norm. Specifically, $g_\ell(z)$ concentrates around the direction of $x_\ell = R_\ell \cdot V_{\mathrm{template}}$ with increasing magnitude.

In the limit $T \to \infty$, the distribution $g_\ell(z)$ converges (in the weak sense) to a point mass supported at $x_\ell$. That is,
\begin{align}
    g_\ell(z) \xrightarrow[T \to \infty]{} \delta(z - x_\ell),
\end{align}
up to normalization. Thus, the integral becomes
\begin{align}
    \int dz \, g_\ell(z) \log\left( \sum_{k=0}^{L-1} w(R_k) \cdot \bar{f}_k(z; R_k \cdot V) \right) \xrightarrow[T \to \infty]{} \log\left( \sum_{k=0}^{L-1} w(R_k) \cdot \bar{f}_k(x_\ell; R_k \cdot V) \right).
\end{align}

Plugging this into the expression for $\mathcal{H}(V)$, we find that:
\begin{align}
    \frac{\mathcal{H}(V)}{T} \xrightarrow[T \to \infty]{} \sum_{\ell=0}^{L-1} \pi(R_\ell) \log\left( \sum_{k=0}^{L-1} w(R_k) \cdot \bar{f}_k(x_\ell; R_k \cdot V) \right).
\end{align}

Now observe that for each $\ell$, the function $\bar{f}_k(x_\ell; R_k \cdot V)$ is maximized when $R_k \cdot V = x_\ell = R_\ell \cdot V_{\mathrm{template}}$, due to the form of the Gaussian kernel centered at $R_k \cdot V$. Therefore, the log-sum is maximized globally when $V = R \cdot V_{\mathrm{template}}$, for some rotation $R \in \s{SO}(3)$, since this makes $R_k \cdot V$ match $x_k$ exactly for all $k$ (up to a global rotation).
Hence,
\begin{align}
    \lim_{T \to \infty} \left\{ \arg\max_V \left( \frac{\mathcal{H}(V)}{T} \right) \right\} = R \cdot V_{\mathrm{template}},
\end{align}
for $R \in \s{SO}(3)$.
\end{proof}
