	%% Mathematical methods
	\subsection{Mathematical models}

	%% Scalar model
	\subsubsection{Temporal population density model}

	First, we consider a scalar model that characterises a changing population density. Denoting the population density $u(t)$, the dynamics are given by a generalised logistic equation \cite{Tsoularis.2002,Sarapata.2014},
	%
		\begin{equation}\label{ode}
			\dv{u}{t} = r u f\!\left(\hat{u}\right),\qquad u(0) = u_0,
		\end{equation}
	%
    where we denote $\hat{u} = u / K$ where $K$ is the carrying capacity. The \textit{crowding function}, $f(\hat{u}) \ge 0$ satisfies $f(0) = 1$, $f(1) = 0$, and $f'(\hat{u}) < \infty$ for $0 \leq \hat{u} \leq 1$. Following this choice, we can interpret $r$ as the low-density per-capita growth rate 
	%
		\begin{equation*}
			r = \lim_{u \rightarrow 0} \dfrac{1}{u} \dv{u}{t},
		\end{equation*}
	%
	and $K = \lim_{t \rightarrow \infty} u(t)$ as the maximum density the population can support.

	We make the standard assumption that observations from the population density model, denoted $u^\text{obs}(t)$, are subject to independent additive Gaussian noise with standard deviation $\sigma$ \cite{Pawitan.2001} such that
	%
		\begin{equation*}
			u^\text{obs}(t) = u(t) + \sigma \varepsilon,
		\end{equation*}
	% 
	where $\varepsilon \sim \mathcal{N}(0,1)$ is a standard normal random variable. Similar results are expected when considering other forms of noise \cite{Murphy.2024}.

	For general $f(\cdot)$, we solve the resultant ordinary differential equation (ODE) numerically using the \texttt{DifferentialEquations} package in Julia \cite{Rackauckas.2017}. In the case that $f(\cdot)$ is piecewise linear (for example, where $f(\cdot)$ is described by a discretised Gaussian process), we exploit the analytical solution to \cref{ode} (supplementary material). 

	%% Spatial model
	\subsubsection{Spatio-temporal population density model}

	We also consider an experiment with spatial structure, such that cell growth is captured by the generalised logistic equation and cell motility is captured through diffusion \cite{Maini.2004}. The spatio-temporal model is given by the partial differential equation	
	%
		\begin{equation}\label{pde}
			\pdv{u}{t} = D\,\hat{\mathcal{D}}(t) \pdv[2]{u}{x} + ru\, f\left(\hat{u}\right),	
		\end{equation}
	%
	subject to Neumann boundary conditions on the finite domain $x \in [0,L]$. Setting $f(\hat{u}) = 1 - \hat{u}$ and $\mathcal{D}(t) = 1$ recovers the well-known Fisher-Kolmogorov equation. We assume that $\hat{\mathcal{D}}(t) > 0$ and that $\hat{\mathcal{D}}(t_\mathrm{max}) = 1$ such that the model parameter $D$ corresponds to the diffusivity at the temporal end point, $t_\mathrm{max}$. 

	We consider two initial conditions:
	\begin{itemize}
		\item \textit{A scratch.} Representative of a scratch assay, cells are removed from the central region of an otherwise uniform monolayer. The initial condition is given parametrically by  
		%
			\begin{equation*}
				u(x,0) = \left\{\begin{array}{ll}
					0 	& \alpha_1 L < x < \alpha_2 L,\\
					u_0 & \text{otherwise.}
				\end{array}\right.
			\end{equation*}
		%
		The scratch location is characterised by $(\alpha_{1},\alpha_{2})$ and is assumed to be known (i.e., determined by the experimental geometry), but the initial monolayer density $u_0$ is treated as an unknown parameter.

		When working with the scratch initial condition, we assume that only the overall cell density, given by
		%
			\begin{equation}\label{overall_density}
				U(t) = \dfrac{1}{L}\int_0^L u(x,t) \  \dd x,
			\end{equation}
		%
		is reported, and is subject to additive Gaussian noise with standard deviation $\sigma_1$ such that
		%
			\begin{equation*}
				U^\text{obs}(t) = U(t) + \sigma_1 \varepsilon.	
			\end{equation*}
		%


		\item \textit{A step.} Representative of a moving tissue front, the initial condition is given by
		%
			\begin{equation}\label{stepic}
				u(x,0) = \left\{\begin{array}{ll}
					u_0 	& x < 0.1L,\\
					0   & x \ge 0.1 L.
				\end{array}\right.
			\end{equation}
		%
		When working with the step initial condition, we assume that two summary statistics are reported: the overall cell density (\cref{overall_density}), subject to additive Gaussian noise with standard deviation $\sigma_1$; and the front location, given by
		%
			\begin{equation*}
				F(t) = \{\min x : u(x,t) < 10^{-4}\}.
			\end{equation*}		
		%
		The front location is also subject to additive Gaussian noise, with standard deviation $\sigma_2$ such that
		%
			\begin{equation*}
				F^\text{obs}(t) = F(t) + \sigma_2 \varepsilon.	
			\end{equation*}
		%

	\end{itemize}

	For both initial conditions, we solve the time-dependent partial differential equation numerically using a central-finite-difference scheme over a uniformly spaced grid. The temporal integration is performed using the \texttt{DifferentialEquations} package in Julia \cite{Rackauckas.2017}. 

	%% Statistical methods
	\subsection{Statistical methods}

	%% Inference
	\subsubsection{Bayesian inference approach}

	We take a standard Bayesian approach to parameter inference, assuming first that knowledge about model parameters is initially encoded in a \textit{prior} distribution, denoted $p(\bm\theta)$. We take $\bm\theta = [\varphi_1,\dots,\varphi_n,h_1,\dots,h_m]^\intercal$, to incorporate both non-negative model parameters $\varphi_i$ (i.e., $r$, $K$, $u_0$, $\beta$, $\sigma_i$), and parameters $\mathbf{h} = [h_1,\dots,h_n]$ that parameterise a piecewise linear function $h(x)$ such that $h(x_i) = h_i$. We place independent uniform priors on the logarithm of each model parameter, $\varphi_{i}$, to cover several orders of magnitude. We construct an appropriate prior on $\mathbf{h}$ by discretising an appropriate Gaussian process prior on the function $h(x)$ (see \cref{GPmethods}).

	Knowledge of the parameters $\bm\theta$ is then updated using the likelihood, $\mathcal{L}$, to form the posterior distribution
	%
		\begin{equation*}
			p(\bm\theta | \mathcal{D}) \propto \mathcal{L}(\mathcal{D} | \bm\theta) p(\bm\theta).	
		\end{equation*}
	%
	Here, $\mathcal{D}$ denotes the data: for example, $\mathcal{D} = \{t_{i},u^\text{obs}_{i}\}$ where $t_{i}$ denotes the time and $u^\text{obs}_{i}$ the value of observation $i$. In this case, the likelihood is given by
	%
		\begin{equation*}
			\mathcal{L}(\mathcal{D}|\bm\theta) = \prod_{i=1}^I\phi(u^\text{obs}_{i};u(t_i),\sigma^2),
		\end{equation*}
	%
	where $I$ denotes the total number of observations, and $\phi(\cdot;\mu,\sigma^2)$ denotes the probability density function for the Gaussian distribution $\mathcal{N}(\mu,\sigma^2)$. The likelihood in cases where overall cell density and cell front measurements are made (i.e., denoted by $U_{n,i}$ and $F_{n,i}$) is constructed similarly. 

	We draw samples from the posterior distribution using an adaptive scaling within an adaptive Metropolis Markov chain Monte Carlo (MCMC) scheme implemented in the \texttt{AdaptiveMCMC} Julia package \cite{Vihola.2020}. Convergence of the MCMC algorithm is supported by ensuring that $\hat{R} < 1.05$ \cite{Vehtari.2021}. To visualise model fit, we use the \textit{maximum a posteriori} (MAP) estimate, corresponding to the posterior sample with the highest posterior density. As we are primarily interested in assessing the identifiability of model parameters, all chains are initiated (where possible) using the true parameter values. In cases where the crowding function $f(\hat{u})$ is unknown even in the synthetic case, chains are initiated with the discretised logistic function $f(\hat{u}) = 1 - \hat{u}$. 

		%% Gaussian processes
		\subsubsection{Gaussian process prior for unknown functions}\label{GPmethods}

		A distribution of a Gaussian process is, essentially, a distribution over continuous functions, and in general is characterised such that every pair of random variables associated with function points (for example, $h(x_i)$ and $h(x_j)$) are jointly Gaussian \cite{Rasmussen.2005}. The mean of $h(x_i)$ is typically assumed to be a smooth, continuous function of $x_i$, while a \textit{kernel} describes the covariance of pairs $(h(x_i),h(x_j))$ and, in effect, determines how smooth the space of functions is. We relax the requirement that the joint distributions are unbounded Gaussian to develop priors for the non-negative crowding function $f(\hat{u})$, denoted $\mathcal{GP}_1$ and the time-dependent diffusivity $\hat{\mathcal{D}}(t)$, denoted $\mathcal{GP}_2$. 

		%% FIGURE 2
		\begin{figure}[!t]
			\centering
			\includegraphics{fig2}
			\caption[Figure 2]{Samples from Gaussian process priors for unknown functions $f(\hat{u})$ and $\hat{\mathcal{D}}(t)$. We apply a Gaussian process with (a) marginal truncated normal distributions and (b) marginal uniform distributions. In both cases, we show five samples from the prior (yellow), the prior mean (grey solid) and the 95\% probability interval (grey). In (a), we also show the crowding function used to generate synthetic data in \cref{fig1}, $f(\hat{u}) = 1 - \hat{u}^2$ (black dashed).}
			\label{fig2}
		\end{figure}

		\begin{itemize}[listparindent=\parindent]

		%% f(u)
		\item \textit{Crowding function.} We assume that 
			%
				\begin{equation*}
					f(\hat{u}_i) \sim \mathcal{N}_{(0,\infty)}(\mu(\hat{u}_i), k(\hat{u}_i,\hat{u}_i))
				\end{equation*}
			%
			where $\mathcal{N}_{(0,\infty)}$ denotes a truncated Gaussian distribution. We define the covariance structure in terms of the untruncated crowding function in which $\mathrm{cov}(\hat{u}_i,\hat{u}_j) = k(\hat{u}_i,\hat{u}_i)$. We choose
			%
				\begin{equation*}
					\mu(\hat{u}_i) = 1 - \hat{u}_i,
				\end{equation*}
			%
			such that the average (non-truncated) crowding function is logistic. We base the kernel on the canonical squared exponential covariance kernel \cite{Rasmussen.2005}, modified such that $\mathrm{var}(f(\hat{u}_i)) = 0$ for $\hat{u}_i \in \{0,1\}$. We have that
			%
				\begin{equation*}
					k(\hat{u}_i,\hat{u}_j) = 2^4 \eta^2 \exp\left(-\dfrac{(\hat{u}_i - \hat{u}_j)^2}{2\rho^2}\right) \hat{u}_i\hat{u}_j(1 - \hat{u}_i)(1 - \hat{u}_j),
				\end{equation*}
			%
			corresponding to a maximal covariance at $k(0.5,0.5) = \eta^2$. For demonstrative purposes, we set $\eta = 0.2$ and $\rho = 0.5$, although these choices can be inferred or constructed from \textit{a priori} knowledge about the crowding function through, for example, past experimentation \cite{Browning.2019a}.

			In practice, we work with a discretised piecewise-linear crowding function, such that $[f_1,\cdots,f_m]$ are inferred ($f_0 = 1$ and $f_{m+1} = 0$, by definition) where $f(\hat{u}_i) = f_i$ and $\hat{u}_i = i / (m + 1)$. In \cref{fig2}a, we compare discretised realisations of $f(\hat{u}) \sim \mathcal{GP}_1$ to the crowding function $f(\hat{u}) = 1 - \hat{u}^2$ used to generate synthetic data in \cref{fig1}, and to the prior. We take $m = 10$, which is sufficient given the prior (through the choice of scale parameter $\rho$) on the smoothness of $f(\hat{u})$ (\cref{fig2}). 

		%% D(t)
		\item \textit{Time-dependent diffusivity.} We begin by constructing an autonomous Gaussian process for $g(t)$, such that
			%
				\begin{equation*}
					g(t_i) \sim \mathrm{Uniform}(0,1).
				\end{equation*}
			%
			We then construct a Gaussian process for $\hat{\mathcal{D}}(t)$ as the conditional distribution
			%
				\begin{equation*}
					\hat{\mathcal{D}}(t) = 2g(t)\, | \, 2g(t_\mathrm{max}) = 1,	
				\end{equation*}
			%
			which ensures that $\hat{\mathcal{D}}(t_\mathrm{max}) = 1$, and that $\hat{\mathcal{D}}(t) \in (0,2)$.

			We construct a Gaussian process with uniform marginals by employing a Gaussian copula \cite{Nelsen.2006}. Define the Gaussian process $h(t)$ with marginals $h(t_i) \sim \mathcal{N}(0,1)$ and a standard squared-exponential kernel \cite{Rasmussen.2005}
			%
				\begin{equation*}
					\mathrm{cov}(h(t_i),h(t_j)) = \mathrm{exp}\left(-\dfrac{(t_1 - t_2)^2}{2\rho^2}\right).
				\end{equation*}
			%

			The Gaussian process $g(t)$ is then defined through the transformation
			%
				\begin{equation*}
					g(t) = \phi^{-1}(h(t)),
				\end{equation*}
			%
			where $\phi^{-1}(\cdot)$ is the quantile function (i.e., inverse distribution function) for the standard normal distribution. 

			In practice, we again work with a discretised piecewise-linear crowding function, such that $[g_0,\cdots,g_n]$ are inferred ($g_{n+1} = 0.5$, by definition) where $g(t_i) = g_i$ and $t_i = t_\mathrm{max} i / (n + 1)$. In \cref{fig2}b, we compare realisations of $\hat{\mathcal{D}}(t) \sim \mathcal{GP}_2$ to the prior, for smoothness parameter $\rho = 2$. We take $n = 19$, which is sufficient given the prior (through the choice of $\rho$) on the smoothness of $\hat{\mathcal{D}}(t)$. 



		\end{itemize}

