\section{Analytical solution to the population growth model}

Here, we construct the analytical solution to the non-dimensional generalised logistic equation
%
	\begin{equation}
		\dv{\hat{u}}{t} = \hat{u} g(\hat{u}),\qquad \hat{u}(0) = \hat{u}_0.
	\end{equation}
%
in the case that $g(\hat{u})$ is piecewise linear on $\hat{u} \in (\hat{u}_0,1)$ such that $g(\hat{u}_i) = g_i > 0$ at a set of discrete ordered points $\hat{u}_0 < \hat{u}_1 < \cdots < 1$, and that $g(1) = 0$. We therefore have that
%
	\begin{equation}
		g(\hat{u}) = a_i \hat{u} + b_i, \qquad \hat{u}_i \le \hat{u} < \hat{u}_{i+1},
	\end{equation}
%
with
%
	\begin{equation}
		a_i = \dfrac{g_{i+1} - g_i}{\hat{u}_{i+1} - \hat{u}_i}, \qquad b_i = g_i - a_i \hat{u}_i.
	\end{equation}
%

Consider that, for $t \in [\tau_i, \tau_{i+1}]$,
%
	\begin{align*}
		\dv{\hat{u}}{t} &= a_i \hat{u}^2 + b_i \hat{u}, \qquad \hat{u}(\tau_i) = \hat{u}_i.
	\end{align*}
%
Integrating the separable equation yields
%
	\begin{equation}\label{si_integrated}
		b_i(t - \tau_i) = \log\left(a_i + \dfrac{b_i}{\hat{u}_i}\right)-\log\left(a_i + \dfrac{b_i}{\hat{u}(t)}\right).
	\end{equation}
%

We can now recursively solve for $\tau_{i}$ by defining $\tau_i$ such that $\hat{u}(\tau_i) = \hat{u}_i$ is true for all $t$. This definition is unique by our previous assertion that $g(\hat{u})$ is strictly positive for $\hat{u}_{1} \leq \hat{u} < 1$. Therefore,
%
	\begin{align*}
		\tau_{i+1} &= \tau_i + \dfrac{1}{b_i}\left[\log\left(a_i + \dfrac{b_i}{\hat{u}_i}\right)-\log\left(a_i + \dfrac{b_i}{\hat{u}_{i+1}}\right)\right],
	\end{align*}
%
with $\tau_0 = 0$. Inverting \cref{si_integrated} and simplifying yields
%
	\begin{equation}
		\hat{u}(t) = \dfrac{b_i}{\mathrm{e}^{-b_i (t - \tau_i)}\left(a_i + \dfrac{b_i}{\hat{u}_i}\right) - a_i}
	\end{equation}
%
which applies for $t \in [\tau_i, \tau_{i+1}]$.


