\subsection{Notation}

\begin{itemize}
\item We will write $\zz_+$ for the set of nonnegative integers, and $\N$ for the nonzero elements of $\zz_+$.
    \item $\mathbb{M}_n(\mathbb{C})$ will denote the $\C$-algebra of $n\times n$-matrices with coefficients in $\mathbb{C}$, and $\mathcal{K}$ will stand for the $\C$-algebra of compact operators on a separable, infinite-dimensional Hilbert space.
    \item We will write cp and cpc for completely positive and completely positive contractive, respectively. Moreover, ucp will stand for unital and completely positive.
    \item Given a $\C$-algebra $A$, we will write $\End(A)$ for the set of endomorphisms of $A$ and $\Aut(A)$ for the automorphism group of $A$, that is, $\End(A)=\{^*\text{-homomorphisms}\ A\to A\}$ and $\Aut(A)=\{^*\text{-isomorphisms}\ A\to A\}$.
    \item Given a $\C$-algebra $A$ and a free ultrafilter $\omega$ on $\mathbb{N}$, we will write $A_\omega$ for the $\C$-algebra obtained as a quotient of the bounded sequences of $A$ by the null sequences along the ultrafilter $\omega$.
    \item By a `trace' we will always mean a tracial state. For a unital $\C$-algebra $A$, we will denote the set of traces on $A$ by $T(A)$, and the set of extremal traces by $\partial_e T(A)$, both sets equipped with the weak$^*$-topology.
\end{itemize}


\subsection{Nuclear dimension and decomposition rank}

Before defining the notion of finite nuclear dimension for $\C$-algebras, we need to recall the definition of order zero maps. A cp map $\phi: A\to B$ between $\C$-algebras is said to be
\emph{order zero} if, for every $a,b \in A_+$ with $ab=0$, one has $\phi(a)\phi(b)=0$. The general theory for these maps was developed in \cite{WinterZachOrderZero}. 

\begin{defn}[{\cite{KirchbergWinterDecompRank,WinterZachNucDim}}]\label{defn: NucDim}
Let $A$ be a $\C$-algebra and $d$ be a nonnegative integer.
It is said that $A$ has \emph{nuclear dimension at most $d$}, and denoted by $\dimnuc(A)\leq d$, if for any finite set $\cF\subseteq A$ and any $\eps>0$, there exists a finite-dimensional $\C$-algebra $F=F^{(0)}\oplus \ldots \oplus F^{(d)}$  and  maps $\psi\colon A\to F$ and $\varphi\colon F\to A$ such that 

\begin{enumerate}
    \item $\|\varphi\circ\psi(a)-a\|\leq \eps$ for all $a\in \cF$,
    \item $\psi$ is cpc,
    \item if we denote by $\varphi^{(i)}$ the restriction of $\varphi$ to $F^{(i)}$, then $\varphi^{(i)}$ is a cpc order zero map for all $i=0,\ldots, d$.
\end{enumerate}
In this case, we call $(F,\psi,\varphi)$ a \emph{$(d,\cF,\eps)$-decomposable system} for $A$.
If additionally $\varphi$ is contractive, then we call $(F,\psi,\varphi)$ a \emph{contractive $(d,\cF,\eps)$-decomposable system} for $A$. It is said that $A$ has \emph{decomposition rank at most $d$} (written $\dr(A)\leq d$) if, for every $\cF$ and $\eps$, there exists a contractive $(d,\cF,\eps)$-decomposable system for $A$.
The $\C$-algebra $A$ has nuclear dimension (respectively, decomposition rank) equal to $d$ if $d$ is the minimum number for which $\dimnuc(A)\leq d$ (respectively, $\dr(A)\leq d$). If there is no such $d$, then by definition $\dimnuc(A)=\infty$ (respectively, $\dr(A)=\infty$).
\end{defn}

Furthermore, these approximations properties for $\C$-algebras are often related to external approximation properties for traces, such as amenability and quasidiagonality. We will only define the notion of quasidiagonality for a trace. Note that the definition we choose (\cite[Definition 7.2]{BBSTW19}) is formally different than Brown's in \cite{Brown06}, but in fact equivalent as observed in the discussion after \cite[Definition 7.2]{BBSTW19}

\begin{defn}[{\cite[Definition 7.2]{BBSTW19}}]\label{defn: AmenQDTraces}
Let $A$ be a $\C$-algebra.
%\item  A trace $\tau\colon A\rightarrow\mathbb{C}$ is called \emph{amenable} if for any finite set $\cF\subseteq A$ and any $\eps>0$, there is an integer $k\geq 1$ and a ucp map $\varphi\colon A\rightarrow \mathbb{M}_{k}(\mathbb{C})$ such that $$\|\varphi(ab)-\varphi(a)\varphi(b)\|_2 \leq\eps$$ and $|\tr_{k}(\varphi(a))-\tau(a)|\leq\eps$ for all $a,b\in \cF$, where $\|x\|_2=\tr_{k}(x^*x)^{1/2}$ and $\tr_{k}$ is the unique normalised trace on $\mathbb{M}_{k}(\mathbb{C})$.
A trace $\tau\colon A\to\mathbb{C}$ is \emph{quasidiagonal} if for any finite set $\cF\subseteq A$ and any $\eps>0$, there is a finite-dimensional $\C$-algebra $F$ with a trace $\tau_F$ and a cpc map $\varphi\colon A\rightarrow F$ such that $$\|\varphi(ab)-\varphi(a)\varphi(b)\|\leq\eps$$ and $|\tau_F(\varphi(a))-\tau(a)|\leq\eps$ for any $a,b\in \cF$.   
\end{defn}






\section{Noncommutative topological entropy} \label{sect: NoncommutativeEntropy}

Let us first recall the definition of the Brown--Voiculescu entropy, as introduced in \cite{Voiculescu95} for unital nuclear $\C$-algebras, and refined in \cite{Brown99} to cover exact $\C$-algebras.


\begin{defn}[{\cite[Definition 4.1]{Voiculescu95}}]\label{defn: BrownVoiculescuEntropy}
Let $A$ be a nuclear $\C$-algebra and let $\alpha\colon A\to A$ be an endomorphism of $A$.
For any finite set $\cF\subseteq A$ and any $\eps>0$, we say that $(F,\psi,\varphi)$ is an \emph{$(\cF,\eps)$-completely positive system} for $A$ if $F$ is finite dimensional, $\psi\colon A\to F$ and $\varphi\colon F\to A$ are cpc, and $\|\varphi(\psi(a))-a\|\leq\eps$ for any $a\in \cF$. We then consider the \emph{$(\cF,\eps)$-completely positive rank} to be \[\rcp(\cF,\eps)=\inf\{\rk(F)\mid (F,\psi,\varphi) \ \text{is $(\cF,\eps)$-completely positive}\},\] where the \emph{rank} of a finite-dimensional $\C$-algebra is defined to be the dimension of a maximal abelian subalgebra.
We now further define the quantities
\begin{align*}
&\h(\alpha,\cF,\eps)=\limsup\limits_{n\to\infty}\frac{1}{n}\log \rcp(\cF\cup\alpha(\cF)\cup\ldots\cup\alpha^{n-1}(\cF),\eps),\\
&\h(\alpha,\cF)=\sup\limits_{\eps>0}\h(\alpha,\cF,\eps), \\
&\h(\alpha)=\sup\limits_{\cF}\h(\alpha,\cF),\ \text{with $\cF$ ranging over all finite subsets of $A$.}
\end{align*} 
The definition for exact $\C$-algebras is the same, except that the completely positive systems are required to approximate a faithful representation $A\to\mathcal{B}(H)$ rather than the identity map $A\to A$. By convention, $\h(\alpha)=\infty$ if $A$ is not exact.
\end{defn}

If the $\C$-algebras in question have finite nuclear dimension (or finite decomposition rank), we consider the following notions of coloured entropy.


\begin{defn}\label{defn: NucDimAndDrEntropy}
Let $A$ be a $\C$-algebra with nuclear dimension equal to $d$ and let $\alpha\colon A\to A$ be an endomorphism of $A$.
For any finite set $\cF\subseteq A$ and any $\eps>0$, we define the \emph{$(d,\cF,\eps)$-decomposable rank} by \[r_{\nuc}(d,\cF,\eps)=\inf\{\rk(F)\mid (F,\psi,\varphi)\ \text{is $(d,\cF,\eps)$-decomposable}\}.\] 
Moreover, we define the \emph{contractive $(d,\cF,\eps)$-decomposable rank} by \[r_{\dr}(d,\cF,\eps)=\inf\{\rk(F)\mid (F,\psi,\varphi)\ \text{is contractive $(d,\cF,\eps)$-decomposable}\}.\]
We now further define the quantities
\begin{align*}
&\h_\nuc(\alpha,\cF,\eps)=\limsup\limits_{n\to\infty}\frac{1}{n}\log r_\nuc(d,\cF\cup\alpha(\cF)\cup\ldots\cup\alpha^{n-1}(\cF),\eps),\\
&\h_\nuc(\alpha,\cF)=\sup\limits_{\eps>0}\h_\nuc(\alpha,\cF,\eps), \\
&\h_\nuc(\alpha)=\sup\limits_{\cF}\h_\nuc(\alpha,\cF),\ \text{with $\cF$ ranging over all finite subsets of $A$.}
\end{align*}We will often call the last quantity the \emph{coloured entropy}. If $A$ does not have finite nuclear dimension, then $\h_\nuc(\alpha)=\infty$ by convention. 
Using the contractive decomposable rank instead, we can likewise define $\h_\dr(\alpha,\cF,\eps)$, $\h_\dr(\alpha,\cF)$, and $\h_\dr(\alpha)$. Similarly, we will often refer to the last quantity as the \emph{contractive coloured entropy}, and $\h_\dr(\alpha)=\infty$ if $A$ does not have finite decomposition rank.
\end{defn}

\begin{prop}\label{prop: IneqBrownVoicEntr}
Let $A$ be a unital, exact $\C$-algebra and let $\alpha\colon A\to A$ be an endomorphism of $A$. Then $\h(\alpha)\leq \h_\nuc(\alpha)\leq \h_\dr(\alpha)$.  
\end{prop}

\begin{proof}
The fact that $\h_\nuc(\alpha)\leq \h_\dr(\alpha)$ follows from the definition, so it remains to show that $\h(\alpha)\leq \h_\nuc(\alpha)$. 
If $\dim_{\nuc}(A)=\infty$, then $\h_\nuc(\alpha)=\infty$, so the inequality holds. 
Therefore, we can assume that $\dim_\nuc(A)=d$ for some $d\in \mathbb{Z}_+$.

We will now follow the standard proof that a $\C$-algebra with finite nuclear dimension is nuclear.
Let $\cF$ be a finite subset of $A$, $n\in\mathbb{N}$, $0<\eps<1$, and $\delta>0$ such that if $|1-t|\leq\delta$, then $|1-t^{-1/2}|<\frac{\eps}{4(d+1)}.$ We can assume that all elements of $\cF$ are contractions and $1\in\cF$.
Let $(F,\psi,\varphi)$ be a $(d,\cF\cup\alpha(\cF)\cup\ldots\cup\alpha^{n-1}(\cF),\min\{\delta, \frac{\eps}{4},\frac{1}{2}\})$-decomposable system for $A$. In particular, this implies that $\|\varphi(\psi(1))-1\|\leq\delta$, so $\varphi(\psi(1))$ is invertible if $\delta$ is small enough. Moreover, by choice of $\delta$, the continuous functional calculus implies that \[\|1-\varphi(\psi(1))^{-1/2}\|<\frac{\eps}{4(d+1)}.\]Using \cite[Lemma 2.2.5]{BrownOzawa08}, we can now choose a ucp map $\psi_0\colon A\to F$ such that \[\psi(a)=\psi(1)^{1/2}\psi_0(a)\psi(1)^{1/2}, \ a\in A.\]Then, we let $\varphi_0\colon F\to A$ given by \[\varphi_0(x)=\varphi(\psi(1))^{-1/2}\varphi\left(\psi(1)^{1/2}x\psi(1)^{1/2}\right)\varphi(\psi(1))^{-1/2}.\]As in the proof of \cite[Proposition 1.5.4]{Castillejos16}, the maps $\psi_0$ and $\varphi_0$ are ucp and their composition approximates the identity map on $\cF\cup\alpha(\cF)\cup\ldots\cup\alpha^{n-1}(\cF)$ up to $\eps$. Since this procedure did not change the finite-dimensional $\C$-algebra $F$, it follows that \[\h(\alpha,\cF,\eps)\leq\h_\nuc(\alpha,\cF,\min\{\delta, \frac{\eps}{4},\frac{1}{2}\})\leq \h_\nuc(\alpha).\]Since $\cF$ and $\eps$ were arbitrary, this implies that $\h(\alpha)\leq\h_\nuc(\alpha)$.
\end{proof}

Next, we show that in the approximately finite-dimensional setting, both the coloured and the contractive coloured entropies coincide with the \emph{topological approximation entropy} $\ha$ introduced in \cite{Voiculescu95}. The definition of this version of noncommutative entropy is similar to Definition~\ref{defn: BrownVoiculescuEntropy}, except that the finite-dimensional $\C$-algebras appearing in the infimum do not come from completely positive approximation systems. Instead, bearing in mind that the ambient $\C$-algebra $A$ is AF, we take the infimum of the ranks of finite-dimensional $\C$-subalgebras $F$ of $A$ that $\eps$-contain the given finite set $\cF$ (that is, for every $a\in\cF$ there exists $b\in F$ such that $\|a-b\|<\eps$). The rest of the definition is unchanged.

\begin{prop} \label{prop: AFEntropy}
Let $A$ be a separable, unital AF-algebra, and let $\alpha$ be an endomorphism of $A$. Then $\h_{\dr}(\alpha) = \h_{\nuc}(\alpha) = \ha(\alpha)$.
\end{prop}

\begin{proof}
Fix $\eps>0$, a finite set $\cF\subseteq A$, and $n\in\mathbb{N}$. Suppose that $F$ is a finite-dimensional subalgebra of $A$ that $\eps$-contains $\cF\cup\alpha(\cF)\cup\ldots\cup\alpha^{n-1}(\cF)$ (in the sense described above). As in the proof of \cite[Proposition 4.5]{Voiculescu95}, we then get an $(\cF\cup\alpha(\cF)\cup\ldots\cup\alpha^{n-1}(\cF),2\eps)$-completely positive system $(F,\psi,\varphi)$, where $\psi\colon A \to F$ is an Arveson extension of $\id\colon F \to F$ and $\varphi$ is the inclusion map $F \to A$. Since $\varphi$ is a $^*$-homomorphism, so in particular is order zero and contractive, it follows that $\h_\dr(\alpha)\le\ha(\alpha)$. For the reverse inequality, we recall the proof that $\dr(A)=0$ (or equally, $\dimnuc(A)=0$) implies that $A$ is an AF-algebra. The argument can be traced back to \cite[Theorem 3.4]{Winter03}, and as observed there, for unital $A$ amounts to the observation that an approximately unital cpc order zero map $\varphi\colon F \to A$ can be perturbed to a $^*$-homomorphism $\varphi'\colon F\to A$. It follows that $\ha(\alpha)\le\h_\nuc(\alpha)\le\h_\dr(\alpha)$.
\end{proof}

Using Proposition~\ref{prop: AFEntropy}, we can compute the coloured and the contractive coloured entropies for an important class of examples, the noncommutative Bernoulli shifts.

\begin{prop} \label{prop: Shift}
Let $A=B^{\otimes\zz}$ for a given UHF-algebra $B$, and let $\alpha\colon A \to A$ be the tensor shift automorphism induced by the map $i\mapsto i+1$ on the index set $\zz$. Then either $B\cong\mathbb{M}_k(\mathbb{C})$ for some $k\in\N$, in which case $\h_\dr(\alpha) = \h_\nuc(\alpha) = \h(\alpha) = \log k$, or $B$ is infinite dimensional and $\h_\dr(\alpha) = \h_\nuc(\alpha) = \h(\alpha) = \infty$.
\end{prop}

\begin{proof}
For infinite-dimensional $B$, $\alpha$ restricts to the shift on subalgebras of the form $\mathbb{M}_k(\mathbb{C})^{\otimes\zz}$ for arbitrarily large $k$. The second assertion therefore follows from the first by monotonicity of $\h$ (see \cite[Proposition 2.1]{Brown99} and also Proposition~\ref{prop: Hereditary} below) and Proposition~\ref{prop: IneqBrownVoicEntr}. So let us assume that $B=\mathbb{M}_k(\mathbb{C})$. By \cite[Propositions 2.6 and 4.7]{Voiculescu95}, $\ha(\alpha)=\h(\alpha)=\log k$. By Proposition~\ref{prop: AFEntropy}, we then have $\h_\dr(\alpha)=\h_\nuc(\alpha)=\log k$ as well.
\end{proof}

The \emph{canonical endomorphism} of the Cuntz algebra $\cO_k=\C(s_1,\dots,s_k)$, $2\le k<\infty$, is the map $\theta_k\colon \cO_k \to \cO_k$ defined by $\theta_k(a) = \sum_{i=1}^k s_ias_i^*$. It leaves invariant the canonical UHF subalgebra $\mathbb{M}_k(\mathbb{C})^{\otimes\N}\subseteq\cO_k$, on which it acts as the one-sided Bernoulli shift $a\mapsto1\otimes a$. This observation forms part of the proof of \cite[Theorem 4.6]{Choda99}, which computes $\h(\theta_k)=\log k$. Appealing to the alternative proof provided by \cite{BocaGoldstein00}, we discover that $\h_\nuc(\theta_k)=\log k$ as well.

\begin{prop} \label{prop: CuntzEndo}
If $\theta_k\colon \cO_k \to \cO_k$ is the canonical endomorphism described above, then $\h_\dr(\theta_k)=\infty$ and $\h_\nuc(\theta_k)=\log k$.
\end{prop}

\begin{proof}
The equality $\h_\dr(\theta_k)=\infty$ holds because the purely infinite $\C$-algebra $\cO_k$ has infinite decomposition rank. We turn to $\h_\nuc$. In conjunction with Choda's theorem \cite[Theorem 4.6]{Choda99}, Proposition~\ref{prop: IneqBrownVoicEntr} gives that $\h_\nuc(\theta_k)\ge \h(\theta_k)=\log k$. The reverse inequality can be extracted from the proof of  \cite[Proposition 3]{BocaGoldstein00}. Given $\eps>0$, a finite set $\cF\subseteq \cO_k$ (which can be assumed to consist of monomials in the generators $s_1,\dots,s_k$), this proposition provides a sequence $(F_n,\psi_n,\varphi_n)$ of $(\cF\cup\theta_k(\cF)\cup\ldots\cup\theta_k^{n-1}(\cF),\eps)$-completely positive systems such that $\limsup_{n\to\infty}\frac{1}{n}\log \rk(F_n) = \log k$. The starting point in the construction of these systems is an $(\cF,\eps)$-system $(F_0,\psi_0,\varphi_0)$ obtained from nuclearity of $\cO_k$. Since $\dimnuc(\cO_k)=1$, we can assume that $(F_0,\psi_0,\varphi_0)$ is in fact $(1,\cF,\eps)$-decomposable. For each $n$, $\varphi_n$ and $\psi_n$ are defined in terms of an isomorphism $\rho_m \colon \cO_k \to \mathbb{M}_{k^m}(\mathbb{C}) \otimes \cO_k$, where $m=n+n_0$ for a suitable $n_0$ depending on $\cF$. Specifically, we have $F_n=\mathbb{M}_{k^m}(\mathbb{C}) \otimes F_0$, $\psi_n=(\id\otimes\psi_0)\circ\rho_m$ and $\varphi_n=\rho_m^{-1}\circ(\id\otimes\varphi_0)$, so $\varphi_n$ is $1$-decomposable since $\varphi_0$ is. It follows that $\h_\nuc(\theta_k)\le \log k$ and hence that $\h_\nuc(\theta_k)=\log k$.
\end{proof}

\begin{rmk} \label{rmk: CuntzKrieger}
The results of \cite{BocaGoldstein00} apply more generally to the canonical `endomorphisms' $\theta_A$ (which are actually unital completely positive self-maps) of Cuntz--Krieger algebras $\cO_A$ associated to irreducible, non-permutation matrices $A$ taking values in $\{0,1\}$. In this setting, the map $\rho_m \colon \cO_A \to \mathbb{M}_{w(m)}\otimes\cO_A$ used in the proof of Proposition~\ref{prop: CuntzEndo} (wherein $w(m)=k^m$) is in general not an isomorphism. To define $\psi_n$, the map $\rho_m^{-1} \colon \rho_m(\cO_A) \to \cO_A \subseteq \mathcal{B}(H)$ must first be extended to a completely positive map $\mathbb{M}_{w(m)}\otimes\cO_A \to \mathcal{B}(H)$. Because this extension need not be order zero, it is unclear whether we can obtain a decomposable system in this way. We leave open the problem of determining whether $\h_\nuc(\theta_A)$ is equal to the logarithm of the spectral radius of the matrix $A$.

On the other hand, by the same reasoning used in the proof of Proposition~\ref{prop: CuntzEndo}, the entropy bound for polynomial endomorphisms of Cuntz algebras established in \cite[Theorem 2.2]{SkalskiZacharias08} carries over to $\h_\nuc$. More precisely, if $u$ is a unitary in the canonical copy of $M_{k^m}$ in $\cO_k$ and $\rho_u\colon \cO_k\to\cO_k$ is the associated endomorphism defined by $s_i\mapsto us_i$, $i=1,\dots,k$, then $\h_\nuc(\rho_u)\le(m-1)\log k$. Moreover, $\h_\nuc(\alpha)$ agrees with $\h(\alpha)$ for all of the concrete endomorphisms $\alpha$ of $\cO_2$ considered in \cite{SkalskiZacharias08}.
\end{rmk}

\section{Permanence properties} \label{sect: Permanence}

In this section, we will record some permanence properties for the (contractive) coloured entropy. Most of the arguments are essentially following the standard proofs for the Brown--Voiculescu entropy (see \cite[Section 2]{Brown99}). We will start with a form of monotonicity for the coloured entropies. Since neither nuclear dimension nor decomposition rank is inherited by $\C$-subalgebras, we will restrict ourselves to hereditary $\C$-subalgebras.

\begin{prop}\label{prop: Hereditary}
Let $A$ be a $\C$-algebra, $\alpha$ be an endomorphism of $A$, and $B\subseteq A$ be a full hereditary $\C$-subalgebra of $A$ which is invariant under $\alpha$. Then \[\h_\nuc(\alpha|_B)\leq \h_\nuc(\alpha) \ \text{and} \ \h_\dr(\alpha|_B)\leq \h_\dr(\alpha). \] 
\end{prop}

\begin{proof}
If $\dim_\nuc(A)=\infty$, then $\h_\nuc(\alpha)=\infty$, so there is nothing to prove. Therefore, we will assume that $A$ has finite nuclear dimension, say $d$. We will now follow the proof that $B$ has nuclear dimension at most $d$ provided in \cite[Proposition 2.5]{WinterZachNucDim}. Note that since $B$ is a full hereditary $\C$-subalgebra of $A$, we know that $\dim_\nuc(B)=\dim_\nuc(A)$ (\cite[Corollary 2.8(ii)]{WinterZachNucDim}). Thus, the estimates provided by the proof of \cite[Proposition 2.5]{WinterZachNucDim} can indeed be used to compute $\h_\nuc(\alpha|_B)$.

Let $\cF\subseteq B$ be a finite set of positive contractions, $\eps>0$, and $n\in\mathbb{N}$. As in \cite[Proposition 2.5]{WinterZachNucDim}, let $h_0,h_1$ be positive contractions in $B$ such that $h_0h_1=h_1$ and $h_1b=b$ for any $b\in\cF$. Set \[\cG=\cF\cup\{h_0,h_1\},\ \eta=\min\left\{\frac{\eps^8}{13(d+1)},\frac{1}{2^{16}}\right\},\] and let $(F,\psi,\varphi)$ be a $(d, \cG\cup\alpha(\cG)\cup\ldots\cup\alpha^{n-1}(\cG),\eta)$-decomposable system for $A$. One then defines a projection $p\in F$ as in the proof of \cite[Proposition 2.5]{WinterZachNucDim} and builds a decomposable system $(\hat{F},\hat{\psi},\hat{\varphi})$ for $B$, where $\hat{F}=pFp$. Note that the proof of \cite[Proposition 2.5]{WinterZachNucDim} shows that a $(d,\cG,\eta)$-decomposable system for $A$ yields a $(d,\cF,\eps)$-decomposable system for $B$. Then for any $1\leq k\leq n-1$, as $\alpha^k(h_1)\alpha^k(h_0)=\alpha^k(h_0h_1)=\alpha^k(h_1)$ and $\alpha^k(h_1)\alpha^k(b)=\alpha^k(h_1b)=\alpha^k(b)$ for any $b\in\cF$, a $(d,\alpha^k(\cG),\eta)$-decomposable system for $A$ gives a $(d,\alpha^k(\cF),\eps)$-decomposable system for $B$. Therefore, the system $(\hat{F},\hat{\psi},\hat{\varphi})$ is a $(d,\cF\cup\alpha(\cF)\cup\ldots\cup\alpha^{n-1}(\cF),\eps)$-decomposable system for $B$. Since $\mathrm{rank}(\hat{F})\leq\mathrm{rank}(F)$, we have shown that
\begin{equation}\label{eq:Hered1}
\h_\nuc(\alpha|_B,\cF,\eps)\leq\h_\nuc(\alpha,\cG,\eta)\leq \h_\nuc(\alpha).
\end{equation}
But $\cF$ and $\eps$ were arbitary, so \eqref{eq:Hered1} yields that $\h_\nuc(\alpha|_B)\leq\h_\nuc(\alpha)$. Further assuming that $A$ has finite decomposition rank, using the proof of \cite[Proposition 3.8]{KirchbergWinterDecompRank} instead, one can show in the same fashion that $\h_\dr(\alpha|_B)\leq \h_\dr(\alpha)$.
\end{proof}

%\bj{Does Lemma~\ref{lemma: TechLemBrown} give inequalities for endomorphisms?}
%\rn{Don't think so. Brown's proof really has cpc maps everywhere (as he uses Arveson's extension at some point); this will not play well with the order zero structure. Maybe I am missing something.}
%\bj{Probably you are right. This means we do not get the Kolmogorov--Sinai result for endomorphisms, not obviously anyway. I will think about it, or else just remove Proposition~\ref{prop: KolmogorovSinai}. I wanted to refer to it in the proof of Proposition~\ref{prop: CuntzEndo} but I think it may be overkill for that.}

\begin{lemma}[cf.{\cite[Lemma 2.4]{Brown99}}]\label{lemma: TechLemBrown}
Let $A$ be a $\C$-algebra with nuclear dimension equal to $d$, $\alpha$ be an automorphism of $A$, $\cF\subseteq A$ finite, and $\eps>0$. Then \[r_\nuc(d,\alpha(\cF),\eps)= r_\nuc(d,\cF,\eps).\]Moreover, if $A$ has decomposition rank equal to $d$, then the same equality holds by replacing $r_\nuc$ with $r_\dr$.
\end{lemma}

\begin{proof}
Let $(F,\psi,\varphi)$ be a $(d,\cF,\eps)$-decomposable system for $A$. Considering the system $(F,\psi\circ\alpha^{-1},\alpha\circ\varphi)$, we get a $(d,\alpha(\cF),\eps)$-decomposable system for $A$, so \[r_\nuc(d,\alpha(\cF),\eps)\leq r_\nuc(d,\cF,\eps).\]Conversely, if we start with a $(d,\alpha(\cF),\eps)$-decomposable system for $A$, say $(F,\psi,\varphi)$, then $(F, \psi\circ\alpha,\alpha^{-1}\circ\varphi)$ is a $(d,\cF,\eps)$-decomposable system for $A$. This shows that \[r_\nuc(d,\alpha(\cF),\eps)\geq r_\nuc(d,\cF,\eps),\]so the conclusion follows. Further assuming that $\dr(A)=d$, exactly the same argument shows that $r_\dr(d,\alpha(\cF),\eps)=r_\dr(d,\cF,\eps)$.
\end{proof}

Using Lemma~\ref{lemma: TechLemBrown}, we can extract the behaviour of the (contractive) coloured entropy under taking powers.


\begin{prop}\label{prop: EntropyPower}
Let $A$ be a $\C$-algebra and $\alpha$ be an automorphism of $A$. Then \[\h_\nuc(\alpha^k)=|k|\h_\nuc(\alpha) \ \text{and} \ \h_\dr(\alpha^k)=|k|\h_\dr(\alpha), \ k\in\mathbb{Z}.\]
\end{prop}

\begin{proof}
If $\dim_\nuc(A)=\infty$, then $\h_\nuc(\alpha)=\infty$, so there is nothing to prove. Therefore, we will assume that $A$ has finite nuclear dimension, say $d$. We will first show that $\h_\nuc(\alpha)=\h_\nuc(\alpha^{-1})$. Let $\cF\subseteq A$ be finite, $\eps>0$, and $n\in\mathbb{N}$. Then, by Lemma \ref{lemma: TechLemBrown} we get that
\begin{align*}
r_\nuc\left(d,\bigcup_{j=0}^{n-1}\alpha^j(\cF),\eps\right)&=r_\nuc\left(d, \alpha^{-n+1}\left(\bigcup_{j=0}^{n-1}\alpha^j(\cF)\right),\eps\right)\\&=r_\nuc\left(d,\bigcup_{j=0}^{n-1}\alpha^{-j}(\cF),\eps\right),
\end{align*}
which yields that $\h_\nuc(\alpha)=\h_\nuc(\alpha^{-1})$. Therefore, it suffices to check that $\h_\nuc(\alpha^k)=k \h_\nuc(\alpha)$ for $k\geq 0$. Since the equality holds trivially for $k=0$, we shall assume $k\geq 1$. Then the same argument as in \cite[Proposition 1.3]{Voiculescu95} gives the result. Finally, exactly the same proof shows that $\h_\dr(\alpha^k)=|k|\h_\dr(\alpha)$ for any $k\in\mathbb{Z}$.
\end{proof}

Another consequence of Lemma~\ref{lemma: TechLemBrown} is a Kolmogorov--Sinai description of the (contractive) coloured entropy in terms of a generating system of finite subsets (cf.\ \cite[Proposition 3.4]{Voiculescu95} and \cite[Proposition 2.6]{Brown99}).

\begin{prop} \label{prop: KolmogorovSinai}
Let $A$ be a $\C$-algebra and $\alpha$ be an automorphism of $A$. Suppose that there is a net $(\cF_\lambda)_{\lambda\in\Lambda}$ of finite subsets of $A$ (partially ordered by inclusion) such that $\bigcup_{\lambda\in\Lambda,n\in\zz}\alpha^n(\cF_\lambda)$ is dense in $A$. Then
\[
\h_\nuc(\alpha) =\sup_{\lambda\in\Lambda}\h_\nuc(\alpha,\cF_\lambda) \ \text{and} \ \h_\dr(\alpha) =\sup_{\lambda\in\Lambda}\h_\dr(\alpha,\cF_\lambda).
\]
\end{prop}

\begin{proof}
The proof is the same as that of \cite[Proposition 2.6]{Brown99}, just using Lemma~\ref{lemma: TechLemBrown} instead of \cite[Proposition 2.4]{Brown99}.
\end{proof}

Similarly to the Brown--Voiculescu entropy, the notions of entropy introduced in Definition \ref{defn: NucDimAndDrEntropy} are well behaved with respect to taking direct sums and conjugacies. However, since in general the nuclear dimension of an inductive limit can only be bounded above by the dimensions of the building blocks, we cannot obtain general bounds for the coloured entropy of an inductive limit automorphism (but see Remark~\ref{rmk: DiffDefEntropy}). For similar reasons, we cannot provide bounds for the coloured entropy of tensor products. However, we can show the coloured entropy is stable under tensoring with the compact operators.


\begin{prop}\label{prop: TensorProd}
Let $A$ be a $\C$-algebra and $\alpha$ be an endomorphism of $A$. Then\[\h_\nuc(\alpha\otimes\id_\mathcal{K})=\h_\nuc(\alpha) \ \text{and} \ \h_\dr(\alpha\otimes\id_\mathcal{K})=\h_\dr(\alpha).\]
\end{prop}

\begin{proof}
If $\dim_\nuc(A)=\infty$, then $\h_\nuc(\alpha)=\h_\nuc(\alpha\otimes\id_\mathcal{K})=\infty$, so there is nothing to prove. Therefore, we will assume that $A$ has finite nuclear dimension, say $d$. First note that by \cite[Corollary 2.8(i)]{WinterZachNucDim}, $\dim_\nuc(A\otimes\mathcal{K})=\dim_\nuc(A)=d$. Then, Proposition \ref{prop: Hereditary} shows that \[\h_\nuc(\alpha)\leq\h_\nuc(\alpha\otimes\id_\mathcal{K}).\]

For the reverse inequality, let $\cF\subseteq A$ and $\cG\subseteq \mathcal{K}$ be finite collections of contractions, $\eps>0$, and $n\in\mathbb{N}$. Then let $(F,\psi,\varphi)$ be a $(d,\cF\cup\alpha(\cF)\cup\ldots\cup\alpha^{n-1}(\cF),\eps/2)$-decomposable system for $A$ and $(G,\gamma,\eta)$ be a $(0,\cG,\eps/2)$-decomposable system for $\mathcal{K}$. Using that the tensor of two order zero maps is order zero (\cite[Corollary 4.3]{WinterZachOrderZero}), it follows that $(F\otimes G,\psi\otimes\gamma,\varphi\otimes\eta)$ is a $(d,(\cF\otimes\cG)\cup(\alpha\otimes\id_\mathcal{K})(\cF\otimes\cG)\cup\ldots\cup(\alpha\otimes\id_\mathcal{K})^{n-1}(\cF\otimes\cG),\eps)$-decomposable system for $A\otimes\mathcal{K}$. Thus, we have shown that \[\h_\nuc(\alpha\otimes\id_\mathcal{K},\cF\otimes\cG,\eps)\leq \h_\nuc(\alpha,\cF,\eps/2)+\h_\nuc(\id_\mathcal{K},\cG,\eps/2)\leq \h_\nuc(\alpha),\]where the last inequality follows since $\h_\nuc(\id_\mathcal{K},\cG,\eps/2)=0$. Since finite sets of the form $\cF\otimes\cG$ span a dense set in $A\otimes\mathcal{K}$, it suffices to take the supremum over such sets (in a similar fashion to Proposition~\ref{prop: KolmogorovSinai}) to conclude that $\h_\nuc(\alpha\otimes\id_\mathcal{K})\leq\h_\nuc(\alpha)$. Clearly the same argument also shows that $\h_\dr(\alpha)=\h_\dr(\alpha\otimes\id_\mathcal{K})$. 
\end{proof}

\begin{prop}\label{prop: DirectSums}
Let $A$ be a $\C$-algebra and $\alpha_1,\alpha_2$ be endomorphisms of $A$. Then\[\h_\nuc(\alpha_1\oplus\alpha_2)=\max\{\h_\nuc(\alpha_1),\h_\nuc(\alpha_2)\}\] and \[\h_\dr(\alpha_1\oplus\alpha_2)=\max\{\h_\dr(\alpha_1),\h_\dr(\alpha_2)\}.\]
\end{prop}

\begin{proof}
If $\dim_\nuc(A)=\infty$, then $\h_\nuc(\alpha_1)=\h_\nuc(\alpha_1\oplus\alpha_2)=\infty$, so there is nothing to prove. Therefore, we will assume that $A$ has finite nuclear dimension, say $d$. Then $A\oplus A$ has nuclear dimension equal to $d$ by \cite[Proposition 2.3(i)]{WinterZachNucDim}. We will first show that \[\h_\nuc(\alpha_1)\leq\h_\nuc(\alpha_1\oplus\alpha_2).\]Let $\cF\subseteq A$ be finite, $\cF_0=\cF\oplus 0\subseteq A\oplus A$, $\eps>0$, and $n\in\mathbb{N}$. We then let $(F,\psi_0,\varphi_0)$ be a $(d,\cF_0\cup(\alpha_1\oplus\alpha_2)(\cF_0)\cup\ldots\cup(\alpha_1\oplus\alpha_2)^{n-1}(\cF_0),\eps)$-decomposable system for $A\oplus A$. To obtain a decomposable system for $A$, we let $\psi=\psi_0\circ\iota_1\colon A\to F$, where $\iota_1\colon A\to A\oplus A$ is the first-factor embedding, and $\varphi=\pi_1\circ\varphi_0$, where $\pi_1\colon A\oplus A\to A$ is the projection onto the first copy of $A$. Then, it is immediate to see that $(F,\psi,\varphi)$ is a $(d,\cF\cup\alpha_1(\cF)\cup\ldots\cup\alpha_1^{n-1}(\cF),\eps)$-decomposable system for $A$. Hence, \[\h_\nuc(\alpha_1,\cF,\eps)\leq \h_\nuc(\alpha_1\oplus\alpha_2, \cF\oplus 0,\eps)\leq\h_\nuc(\alpha_1\oplus\alpha_2).\] Since $\cF$ and $\eps$ were arbitrary, we get that $\h_\nuc(\alpha_1)\leq\h_\nuc(\alpha_1\oplus\alpha_2)$, and by symmetry, this shows that \[\h_\nuc(\alpha_1\oplus\alpha_2)\geq\max\{\h_\nuc(\alpha_1),\h_\nuc(\alpha_2)\}.\]

Conversely, let $\cF_1\oplus\cF_2\subseteq A\oplus A$ be finite, $\eps>0$, and $n\in\mathbb{N}$. Then, for each $i=1,2$, let $(F_i,\psi_i,\varphi_i)$ be a $(d,\cF_i\cup\alpha_i(\cF_i)\cup\ldots\cup\alpha_i^{n-1}(\cF_i),\eps)$-decomposable system for $A$. Since $(F_1\oplus F_2,\psi_1\oplus\psi_2,\varphi_1\oplus\varphi_2)$ is a $(d,(\cF_1\oplus\cF_2)\cup\ldots\cup(\alpha_1\oplus\alpha_2)^{n-1}(\cF_1\oplus\cF_2),\eps)$-decomposable system for $A\oplus A$, it follows that 
\[
r_\nuc\left(d,\bigcup_{j=0}^{n-1}(\alpha_1\oplus\alpha_2)^{j}(\cF_1\oplus\cF_2),\eps\right) \leq 2 \max_{i=1,2}r_\nuc\left(d,\bigcup_{j=0}^{n-1}\alpha_i^{j}(\cF_i),\eps\right).
\]Therefore, \[\h_\nuc(\alpha_1\oplus\alpha_2,\cF_1\oplus\cF_2,\eps)\leq \max_{i=1,2}\h_\nuc(\alpha_i,\cF_i,\eps)\leq\max_{i=1,2}\h_\nuc(\alpha_i).\]Since $\cF_1\oplus\cF_2$ and $\eps$ were arbitrary, we get that \[\h_\nuc(\alpha_1\oplus\alpha_2)\leq\max\{\h_\nuc(\alpha_1),\h_\nuc(\alpha_2)\}.\] The same argument shows that $\h_\dr(\alpha_1\oplus\alpha_2)=\max\{\h_\dr(\alpha_1),\h_\dr(\alpha_2)\}$.
\end{proof}

In the spirit of \cite[Proposition 2.8]{Brown99}, the notions of entropy from Definition \ref{defn: NucDimAndDrEntropy} are invariant under conjugacy.

\begin{prop}\label{prop: Conjugacy}
Let $A$ be a $\C$-algebra and $\alpha,\sigma$ be automorphisms of $A$. Then \[\h_\nuc(\sigma\circ\alpha\circ\sigma^{-1})=\h_\nuc(\alpha) \ \text{and} \ \h_\dr(\sigma\circ\alpha\circ\sigma^{-1})=\h_\dr(\alpha).\]
\end{prop}

\begin{proof}
If $\dim_\nuc(A)=\infty$, then $\h_\nuc(\alpha)=\h_\nuc(\sigma\circ\alpha\circ\sigma^{-1})=\infty$, so there is nothing to prove. Therefore, we will assume that $A$ has finite nuclear dimension, say $d$. Let $\cF\subseteq A$ be finite, $\eps>0$, and $n\in\mathbb{N}$. Then, by Lemma \ref{lemma: TechLemBrown}, we get that
%\begin{align*}
%&r_\nuc(d, \cF\cup(\sigma\circ\alpha\circ\sigma^{-1})(\cF)\cup\ldots\cup (\sigma\circ\alpha\circ\sigma^{-1})^{n-1}(\cF),\eps)\\ &= r_\nuc(d, \cF\cup(\sigma\circ\alpha\circ\sigma^{-1})(\cF)\cup\ldots\cup (\sigma\circ\alpha^{n-1}\circ\sigma^{-1})(\cF),\eps)\\ &= r_\nuc(d, \sigma^{-1}(\cF)\cup(\alpha\circ\sigma^{-1})(\cF)\cup\ldots\cup (\alpha^{n-1}\circ\sigma^{-1})(\cF),\eps).
%\end{align*}
%\bj{What do you think about typesetting like this, which I did for Proposition~\ref{prop: EntropyPower} just to address the overfull hbox. If you would prefer not to for notational consistency, that would be fine too.}
%\rn{It looks better, so I am happy to change. Maybe we can do this in the previous proposition too.}
\begin{align*}
r_\nuc\left(d,\bigcup_{j=0}^{n-1}(\sigma\circ\alpha\circ\sigma^{-1})^j(\cF),\eps\right)&=r_\nuc\left(d,\bigcup_{j=0}^{n-1}\sigma\circ\alpha^j\circ\sigma^{-1}(\cF),\eps\right)\\&=r_\nuc\left(d,\bigcup_{j=0}^{n-1}\alpha^j(\sigma^{-1}(\cF)),\eps\right).
\end{align*}
This implies that \[\h_\nuc(\sigma\circ\alpha\circ\sigma^{-1},\cF,\eps)=\h_\nuc(\alpha,\sigma^{-1}(\cF),\eps)\leq\h_\nuc(\alpha).\]Since $\cF$ and $\eps$ were arbitrary, we get that $\h_\nuc(\sigma\circ\alpha\circ\sigma^{-1})\leq \h_\nuc(\alpha)$. Conversely, if we let $\gamma=\sigma\circ\alpha\circ\sigma^{-1}$, then the proof above shows that\[\h_\nuc(\gamma)\geq\h_\nuc(\sigma^{-1}\circ\gamma\circ\sigma)=\h_\nuc(\alpha),\] so the conclusion follows. Clearly the same argument also shows that $\h_\dr(\sigma\circ\alpha\circ\sigma^{-1})=\h_\dr(\alpha)$. 
\end{proof}


\section{The commutative case} \label{sect: Commutative}

In this section, we will prove that the notions of coloured entropy we introduced, coincide with the usual topological entropy in the commutative setting. This is known to be the case for the Brown--Voiculescu entropy, as shown in \cite[Proposition 4.8]{Voiculescu95} when $X$ is a compact metric space and extended in \cite[Proposition 3.1]{KerrLi05} to the case of a general compact Hausdorff space. To prove a corresponding result for the coloured and the contractive coloured entropies, we first introduce a new variant of topological entropy.

Recall that a \emph{refinement} of an open cover $\cU$ of a topological space $X$ is an open cover $\cV$ such that every $V\in\cV$ is contained in some $U\in\cU$. The \emph{least common refinement} of open covers $\cU$ and $\cV$ is the set $\cU\vee\cV$ of nonempty intersections $U\cap V$ of elements $U\in\cU$, $V\in\cV$. Given $n\in\N$, we say that an open cover $\cU$ is \emph{$n$-coloured} if there are subsets $\cU_0,\dots,\cU_{n-1}$ of $\cU$ such that each $\cU_i$ is a collection of pairwise disjoint sets, and $\cU=\bigcup_{i=0}^{n-1}\cU_i$.


