We now let $\cU$ be an open cover of $X$ and $n\in\mathbb{N}$. Applying the result above to the open cover $\cU_0^{n-1}$ yields that \[N_c(\cU_0^{n-1})\leq (d+1)N(\cU_0^{n-1}),\] where $N(\cdot)$ denotes the minimal cardinality of a subcover. Therefore,
\begin{align*}
\lim_{n\to\infty}\frac{1}{n}\log N_c(\cU_0^{n-1}) &\leq \lim_{n\to\infty}\frac{1}{n}(\log (d+1)+\log N(\cU_0^{n-1}))\\
&=\lim_{n\to\infty}\frac{1}{n}\log N(\cU_0^{n-1}).
\end{align*}
By definition of the topological entropy $h_\tp(T)$ of $T$ and its coloured variant $h_{\tp,c}(T)$, this shows that $h_{\tp,c}(T)\leq h_\tp(T)$.
\end{proof}

Combining Lemma~\ref{lemma: UpperBddComm1} and Lemma~\ref{lemma: UpperBddComm2}, we can prove that the (contractive) coloured entropy coincides with the topological entropy in the commutative case.



\begin{theorem}\label{thm: CommCase}
Let $X$ be a nonempty compact metric space with finite covering dimension and $T$ be a homeomorphism of $X$. 
If we denote the induced automorphism of $C(X)$ by $\alpha_T$, then \[h_\tp(T)=\h(\alpha_T)=\h_\nuc(\alpha_T)=\h_\dr(\alpha_T)=h_{\tp,c}(T).\]    
\end{theorem}

\begin{proof}
Combining \cite[Proposition 4.8]{Voiculescu95}, Proposition~\ref{prop: IneqBrownVoicEntr}, Lemma~\ref{lemma: UpperBddComm1}, and Lemma~\ref{lemma: UpperBddComm2} in this order, we obtain the sequence of inequalities
\[h_\tp(T)=\h(\alpha_T)\leq\h_\nuc(\alpha_T)\leq\h_\dr(\alpha_T)\leq h_{\tp,c}(T)\leq h_\tp(T).\]Hence, we have equality everywhere and the conclusion follows.
\end{proof}

\section{A variational type principle for coloured entropy}\label{sect: VarPr}

In this section, we will study the contractive coloured entropy in the setting of simple classifiable $\C$-algebras. The main objective is obtaining a characterisation of the contractive coloured entropy in terms of a suitable notion of entropy for traces. This characterisation aims to shed light on the problem of obtaining a variational principle for noncommutative topological entropy. 

Recall that the \emph{variational principle} states that if $T$ is a homeomorphism of a compact Hausdorff space $X$, then $h_\tp(T)=\sup_{\mu}h_\mu(T),$ where the supremum is taken over $T$-invariant Borel probability measures $\mu$ of $X$ (see for example \cite[Section 6.3, Theorem 3.10]{Petersen83}). In the noncommutative case, Voiculescu showed in \cite[Proposition 4.6]{Voiculescu95} that for an automorphism $\alpha$ of a $\C$-algebra $A$, one has that $\h(\alpha)\geq\sup_\sigma h_\sigma(\alpha)$, where the supremum is taken over $\alpha$-invariant states $\sigma$. To consider this problem in the context of the contractive coloured entropy, we will introduce a new notion of entropy for \emph{quasidiagonal traces} (see Definition~\ref{defn: AmenQDTraces}).

\begin{defn}\label{defn: TraceEntropy}
Let $A$ be a $\C$-algebra, $\alpha$ be an endomorphism of $A$, and $\tau$ be a quasidiagonal trace on $A$. For any finite set $\cF\subseteq A$ and any $\eps>0$, we say $(F,\tau_F,\varphi)$ is an \emph{$(\cF,\eps)$-quasidiagonal system} for $\tau$ if $F$ is finite dimensional with a trace $\tau_F$, and $\varphi\colon A\to F$ is a cpc map such that \[\|\varphi(ab)-\varphi(a)\varphi(b)\|\leq \eps\]and \[|\tau(a)-\tau_F(\varphi(a))|\leq\eps\] for any $a,b\in\cF$. We then consider the \emph{$(\cF,\eps)$-quasidiagonal rank} of $\tau$ to be \[\rqd_\tau(\cF,\eps)=\inf\{\mathrm{rank}(F)\mid (F,\tau_F,\varphi) \ \text{is $(\cF,\eps)$-quasidiagonal} \ \text{for} \ \tau_F\in T(F)\}.\] 
We now further define the quantities
\begin{align*}
&\hqd_\tau(\alpha,\cF,\eps)=\limsup\limits_{n\to\infty}\frac{1}{n}\log \rqd_\tau(\cF\cup\alpha(\cF)\cup\ldots\cup\alpha^{n-1}(\cF),\eps),\\
&\hqd_\tau(\alpha,\cF)=\sup\limits_{\eps>0}\hqd_\tau(\alpha,\cF,\eps), \\
&\hqd_\tau(\alpha)=\sup\limits_{\cF}\hqd_\tau(\alpha,\cF),\ \text{with $\cF$ ranging over all finite subsets of $A$.}
\end{align*}We will often refer to $\hqd_\tau(\alpha)$ as the \emph{quasidiagonal entropy of $\alpha$ with respect to $\tau$}. 
\end{defn}

\begin{rmk}\label{rmk: AmenRankTau}
If $\tau$ is an amenable trace, one can define a similar notion of an amenable entropy of $\alpha$ with respect to $\tau$ simply by considering cpc maps which approximately commute in $2$-norm rather than in norm.  
\end{rmk}

