\noindent\textbf{Notation}: We have adopted the following notational conventions. First, $^VW\equiv VWV^{-1}$ for any pair of unitary operators $V$ and $W$. Moreover, $U^A_g$ is denoted by $g$ and $\Om^I_{g,h}$ by $(g,h)$ whenever they appear within a left superscript. For instance,
\begin{align}
    ^gW&\equiv U^A_gW(U^A_g)^{-1},\\^{g\cdot h}W&\equiv U^A_gU^A_hW(U^A_gU^A_h)^{-1},\\\hp{}^{(g,h)}W&\equiv\Om^I_{g,h}W(\Om^I_{g,h})^{-1},\\\hp{}^{^g(h,k)}W&\equiv U^A_g\Om^I_{h,k}(U^A_g)^{-1}W\big(U^A_g\Om^I_{h,k}(U^A_g)^{-1}\big)^{-1}.
\end{align}

\noindent\textbf{Remark:} It is possible to choose operator restrictions such that the output 4-cocycle $\omega$ is automatically ``normalized", \textit{i.e.} $\omega(g,h,k,l)=1$ when any member of the 4-tuple $g,h,k,l$ is the identity element. To ensure that $\omega$ is normalized, one must choose $U^A_1$ to be the identity operator, $\Om^I_{g,h}$ to be the identity operator whenever $g=1$ or $h=1$, and $\Ga^a_{g,h,k}$ to be the identity operator when any of $g,h,k$ is the identity.

\subsection{Definition of the index}
\label{sec:explicit}

We now give a detailed exposition of the procedure following the list of steps in the overview above.
\begin{enumerate}[leftmargin=*]
    \item To begin, we choose a disk $A$ and an interval $I=[a,b]\subset\partial A$. The radius of $A$, and the length of $I$, are assumed to be much larger than $R$, where $R$ is the maximal range of the symmetry operators $\{U_g\}$.

    \item Next, we choose a restriction $U^A_g$ of each symmetry operator $U_g$ to the disk $A$.

    \item The restricted symmetries obey the group multiplication law \textit{up to} composition by a 1D QCA supported near $\partial A$. In particular, for each pair $g,h,\in G$, define the 1D QCA
    \begin{equation}
        \Om_{g,h}\equiv U^A_g U^A_h\left(U^A_{gh}\right)^{-1}.
    \end{equation}
    For every triple $g,h,k\in G$, the $\Om$ operators obey a constraint which we refer to as the ``non-abelian 2-cocycle condition" \cite{brown1982cohomology,Muger,ElseNayak}:
    \begin{equation}
        \label{eq:NA2cocycle}
        \Om_{g,h}\Om_{gh,k}=\hp{}^g\Om_{h,k}\Om_{g,hk}.
    \end{equation}
    This constraint is derived by using associativity of the restricted symmetries: on one hand,
    \begin{align}
         (U^A_g U^A_h)U^A_k&=\Om_{g,h} U^A_{gh} U^A_k=\Om_{g,h}\Om_{gh,k} U^A_{ghk}.
    \end{align}
    On the other hand,
    \begin{align}
        U^A_g(U^A_hU^A_k)&=U^A_g\Om_{h,k}U^A_{hk}=\hp{}^g\Om_{h,k}\Om_{g,hk}U^A_{ghk}.
    \end{align}
    Comparing the final expressions, we obtain (\ref{eq:NA2cocycle}). The function $\nu:G\times G\to\mathbb{Q}_+$ is defined as follows:
    \begin{equation}
        \nu(g,h)\equiv\text{Ind}(\Om_{g,h})
    \end{equation}
    where $\text{Ind}(W)$ denotes the GNVW index of a 1D QCA $W$.\footnote{Our convention is that a GNVW index $\nu>1$ corresponds to net operator flow in the counterclockwise direction, whereas $\nu<1$ corresponds to net operator flow in the clockwise direction.} It is straightforward to verify that $\nu$ satisfies the 2-cocycle condition (\ref{eq:2cocycle}), by evaluating the index of both sides of (\ref{eq:NA2cocycle}).

    \item We now introduce an ancillary 1D qudit chain living along $\partial A$. The purpose of adding ancillas is to define modified $\Om_{g,h}$ operators, denoted by $\Om'_{g,h}$, which have trivial GNVW index but still satisfy the non-abelian 2-cocycle condition:
    \begin{equation}
        \label{eq:NA2cocycletilde}
        \Om'_{g,h}\Om'_{gh,k}=\hp{}^g\Om'_{h,k}\Om'_{g,hk}.
    \end{equation}
    To do so, the 1D chain must be composed of qudits of various dimensions. In particular, let us write $\nu(g,h)=m(g,h)/n(g,h)$ where $m(g,h)$ and $n(g,h)$ are relatively prime positive integers. Then let $\{p_1,\ldots,p_k\}$ be the set of all prime numbers appearing in the prime decomposition of $m(g,h)$ or $n(g,h)$ for any pair $g,h\in G$. Finally, define the Hilbert space 
    \begin{equation}
        \mathcal{H}_{\partial A}=\bigotimes_{r=1}^k\mathcal{H}_r\quad\text{where}\quad\mathcal{H}_r=\bigotimes_{i\in\mathbb{Z}_L}\mathbb{C}^{p_r}.
    \end{equation}
    Here, $\mathbb{Z}_L$ denotes a chain of $L$ sites living along $\partial A$. Upon adding these ancillas, the total Hilbert space becomes $\mathcal{H}'=\mathcal{H}\otimes\mathcal{H}_{\partial A}$. We now define a canonical operator $T_\nu$ on $\mathcal{H}_{\partial A}$ such that $\text{Ind}(T_\nu)=\nu$ for any GNVW index $\nu$ that can be expressed in terms of the prime factors $\{p_1,\ldots,p_k\}$. To do so, we first express $\nu=m/n$ in terms of the prime decomposition of the relatively prime positive integers $m$ and $n$:
    \begin{equation}
        m=p_{1}^{i_1}\cdots p_{k}^{i_k}\quad\text{and} \quad n=p_{1}^{j_1}\cdots p_{k}^{j_k}
    \end{equation}
    where $i_1,\ldots,i_k,j_1,\ldots,j_k\in\mathbb{Z}_{\geq 0}$. Then define
    \begin{equation}
        T_\nu=t_{p_1}^{i_1}\cdots t_{p_k}^{i_k}\left(t_{p_1}^{j_1}\cdots t_{p_k}^{j_k}\right)^{-1},
    \end{equation}
    where $t_r$ denotes a uniform translation of the qudits in $\mathcal{H}_r$ in the counterclockwise direction. Crucially, these operators satisfy the condition
    \begin{equation}
        T_\nu T_{\nu'}=T_{\nu\cdot\nu'}.\label{eq:Tcondition}
    \end{equation}
    For each pair $g,h\in G$, we define the following operator on $\mathcal{H}_{\partial A}$:
    \begin{equation}
        T_{g,h}\equiv T_{\nu(g,h)}^{-1}.
    \end{equation}
    By definition $\text{Ind}(T_{g,h})=\nu(g,h)^{-1}$. By virtue of (\ref{eq:Tcondition}) and the 2-cocycle condition (\ref{eq:2cocycle}) on $\nu:G\times G\to\mathbb{Q}_+$, it follows that
    \begin{equation}
        T_{g,h}T_{gh,k}=T_{h,k}T_{g,hk}.\label{eq:2cocycleT}
    \end{equation}
    Finally, we define the operator $\Om'_{g,h}$ on $\mathcal{H}'$ for each pair $g,h\in G$:
    \begin{equation}
        \Om'_{g,h}\equiv\Om_{g,h}\otimes T_{g,h}.
    \end{equation}
    Clearly, $\text{Ind}(\Om'_{g,h})=1$, hence $\Om'_{g,h}$ is a 1D FDQC along $\partial A$. Moreover, the non-abelian 2-cocycle condition (\ref{eq:NA2cocycletilde}) follows from (\ref{eq:NA2cocycle}) and (\ref{eq:2cocycleT}).

    \item Next, we choose a restriction $\Om^I_{g,h}$ of each $\Om'_{g,h}$ to the vicinity of the interval $I=[a,b]\subset\partial M$.

    \item For each triple $g,h,k\in G$, the $\Om^I$ operators obey the non-abelian 2-cocycle condition \textit{up to} composition by a unitary operator $\Ga_{g,h,k}$ supported near $\partial I=\{a,b\}$:
    \begin{equation}\label{eq:Gamma_def}
        \Gamma_{g,h,k}\equiv\Om^I_{g,h}\Om^I_{gh,k}\left(\hp{}^g\Om^I_{h,k}\Om^I_{g,hk}\right)^{-1}.
    \end{equation}
    For every 4-tuple $g,h,k,k\in G$, the $\Ga$ operators obey a constraint we refer to as the ``non-abelian 3-cocycle condition":
    \begin{equation}
        \Ga_{g,h,k}\cdot\hp{}^{^g(h,k)}\Ga_{g,hk,l}\cdot\hp{}^g\Ga_{h,k,l}=\hp{}
        ^{(g,h)}\Ga_{gh,k,l}\cdot\hp{}\Delta_{g,h,(k,l)}\cdot\hp{}^{^{g\cdot h}(k,l)}\Ga_{g,h,kl},\label{eq:NA3cocycle}
    \end{equation}
    where we have introduced the operator\footnote{We give $\Delta_{g,h,(k,l)}$ its subscript because of the operators that appear in its definition.}
    \begin{equation}
        \Delta_{g,h,(k,l)}\equiv\hp{}^{(g,h)\cdot gh}\Om^I_{k,l}\left(\hp{}^{g\cdot h}\Om^I_{k,l}\right)^{-1}.
        \label{eq:Delta}
    \end{equation}
    To derive this constraint, we evaluate $\Om^I_{g,h}\Om^I_{gh,k}\Om^I_{ghk,l}$ in two different ways. On one hand,
    \begin{align}
        \Om^I_{g,h}\Om^I_{gh,k}\Om^I_{ghk,l}&=\Ga_{g,h,k}\cdot\hp{}^g\Om^I_{h,k}\Om^I_{g,hk}\Om^I_{ghk,l}\\
        &=\Ga_{g,h,k}\cdot\hp{}^{^g(h,k)}\Gamma_{g,hk,l}\cdot\hp{}^g(\Om^I_{h,k}\Om^I_{hk,l})\Om^I_{g,hkl}\\
        &=\Ga_{g,h,k}\cdot\hp{}^{^g(h,k)}\Ga_{g,hk,l}\cdot\hp{}^g\Ga_{h,k,l}\cdot\hp{}^{g\cdot h}\Om^I_{k,l}\cdot\hp{}^g\Om^I_{h,kl}\Om^I_{g,hkl}.\label{eq:3cocycle1}
    \end{align}
    On the other hand,
    \begin{align}
        \Om^I_{g,h}\Om^I_{gh,k}\Om^I_{ghk,l}&=\hp{}^{(g,h)}\Ga_{gh,k,l}\cdot\hp{}^{(g,h)\cdot gh}\Om^I_{k,l}\Om^I_{g,h}\Om^I_{gh,kl}\\
        &=\hp{}^{(g,h)}\Ga_{gh,k,l}\cdot\Delta_{g,h,(k,l)}\cdot\hp{}^{g\cdot h}\Om^I_{k,l}\Om^I_{g,h}\Om^I_{gh,kl}\\
        &=\hp{}^{(g,h)}\Ga_{gh,k,l}\cdot\Delta_{g,h,(k,l)}\cdot\hp{}^{^{g\cdot h}(k,l)}\Ga_{g,h,kl}\cdot\hp{}^{g\cdot h}\Om^I_{k,l}\cdot\hp{}^g\Om^I_{h,kl}\Om^I_{g,hkl}.
        \label{eq:3cocycle2}
    \end{align}
    Comparing (\ref{eq:3cocycle1}) and (\ref{eq:3cocycle2}), we obtain (\ref{eq:NA3cocycle}).

    \item Next, we choose a restriction $\Ga^a_{g,h,k}$ of $\Ga_{g,h,k}$ to the vicinity of point $a$. Clearly, this choice is unique up to multiplication by a $U(1)$ phase.

    \item We then define an operator $\Delta^a_{g,h,(k,l)}$, which is a restriction of $\Delta_{g,h,(k,l)}$ to the vicinity of point $a$. Unlike $\Ga^a_{g,h,k}$, the overall phase of $\Delta^a_{g,h,(k,l)}$ is not arbitrarily chosen; we may define it canonically. To do so, we first choose an arbitrary point $c$ in the interior of $I$, and define the intervals $L=[a,c]$ and $R=[c,b]$. Then, we arbitrarily decompose the operator $\Om^I_{k,l}$ as a product of two 1D FDQCs, one supported in the vicinity of $L$ and one supported in the vicinity of $R$. That is, $\Om^I_{k,l}=\Om^L_{k,l}\Om^R_{k,l}$.
    We then define
    \begin{align}\label{eq:Delta_a_def}
        \Delta^a_{g,h,(k,l)}&\equiv\hp{}^{(g,h)\cdot gh}\Om^L_{k,l}\hp{}\left(\hp{}^{g\cdot h}\Om^L_{k,l}\right)^{-1}.
    \end{align}
    Clearly this definition is independent of the choice of intervals $L$ and $R$, and the choice of operators $\Om^L_{g,h}$ and $\Om^R_{g,h}$.\footnote{We note that $\Delta^a_{g,h,(k,l)}$ can also be expressed using the ``commutator pairing" introduced in \cite{Kapustin}. In particular, let $d$ be a point to the left of $a$, and define the interval $J=[d,a]$. The commutator pairing between a 1D FDQC $A$ supported near $J$ and a 1D FDQC $B$ supported near $L=[a,c]$ is defined as the unitary $\eta(A,B)=ABA^{-1}B^{-1}$, which is supported near point $a$. Choose a restriction $\Om^K_{g,h}$ of $\Om_{g,h}$ to $K=J\cup L=[d,c]$ which coincides with $\Om^L_{g,h}$ near point $c$, and let $\Om^J_{g,h}=\Om^K_{g,h}(\Om^L_{g,h})^{-1}$. Then, via a simple calculation, we find that $\Delta^a_{g,h,(k,l)}=\eta(A,B)^{-1}$ where $A=\Om^J_{g,h}$ and $B=\hp{}^{(g,h)\cdot gh}\Om^L_{k,l}$.}

    \item Since the $\Gamma$ and $\Delta$ operators satisfy the non-abelian 3-cocycle condition (\ref{eq:3cocycle}), the corresponding $\Ga^a$ and $\Delta^a$ operators must obey an analogous constraint, up to a $U(1)$ phase. The function $\omega:G\times G\times G\times G\to U(1)$ is defined in terms of this phase. Specifically,
    \begin{equation}
        \omega(g,h,k,l)\equiv\Ga^a_{g,h,k}\cdot\hp{}^{^g(h,k)}\Ga^a_{g,hk,l}\cdot\hp{}^g\Ga^a_{h,k,l}\left(\hp{}^{(g,h)}\Ga^a_{gh,k,l}\cdot\hp{}\Delta^a_{g,h,(k,l)}\cdot\hp{}^{^{g\cdot h}(k,l)}\Ga^a_{g,h,kl}\right)^{-1}.
        \label{eq:omega}
    \end{equation}
    In Appendix~\ref{app:cocycle}, we demonstrate that $\omega$ is a 4-cocycle, \textit{i.e.} it satisfies the 4-cocycle condition (\ref{eq:4cocycle}).
\end{enumerate}

We have thus arrived at a formula for the anomaly 4-cocycle $\omega$, in terms of the operators $U_g^A$, $\Om^I_{g,h}$, $\Ga^a_{g,h,k}$, and $\Delta^a_{g,h,(k,l)}$. While this is a concrete expression, it may appear somewhat arcane. To illuminate its structure, in Section~\ref{diagrams} we provide a graphical representation of the formula and its derivation.

\subsection{Ambiguity of the output cocycles}
\label{sec:ambiguity}

Thus far, we have explained how to define a $\mathbb{Q}_+$-valued 2-cocycle $\nu$, and a $U(1)$-valued 4-cocycle $\omega$, via a series of concrete steps. However, there are arbitrary choices made at various points in this procedure, which all affect the cocycles that are obtained. We now explain why different choices always lead to cocycles belonging to the same cohomology classes in $H^2(G,\mathbb{Q}_+)$ and $H^4(G,U(1))$, respectively. We will also see why our procedure can produce \textit{any} pair of representative cocycles in their respective equivalence classes.
Thus, the invariants we compute are precisely elements of $H^2(G,\mathbb{Q}_+)$ and $H^4(G,U(1))$.

We will work backward, starting from the end of the procedure and working toward the start. The last choice made is the choice of restriction of $\Ga_{g,h,k}$ to the vicinity of point $a$, which has an inherent phase ambiguity. That is, instead of $\Ga^a_{g,h,k}$, we are free to instead choose $\rho(g,h,k)\Ga^a_{g,h,k}$ for an arbitrary $U(1)$ phase $\rho(g,h,k)$. Given this choice, instead of $\omega(g,h,k,l)$, we would obtain the 4-cocycle
\begin{equation}
    \tilde\omega(g,h,k,l)=\omega(g,h,kl)\frac{\rho(g,h,k)\rho(g,hk,l)\rho(h,k,l)}{\rho(gh,k,l)\rho(g,h,kl)}.
\end{equation}
We find that $\tilde\omega$ differs from $\omega$ by the 4-coboundary $d\rho$. Thus, different choices of $\Ga^a_{g,h,k}$ give rise to equivalent 4-cocycles.\footnote{We note that there is crucially no such ambiguity in the restriction $\Delta^a_{g,h,(k,l)}$ of $\Delta_{g,h,(k,l)}$, which is canonically defined, including its overall phase.}
Furthermore, since $\rho$ may be any 3-cochain, $\tilde{\omega}$ may be any 4-cocycle which is equivalent to $\omega$.

Continuing to work backward, there is a choice of restriction $\Om^I_{g,h}$ of $\Om'_{g,h}$. We show in Appendix~\ref{appendix:ambiguity1} that the freedom in this choice does not contribute any additional ambiguity to $\omega$ beyond the 4-coboundary ambiguity arising from the restriction of $\Ga_{g,h,k}$. Thus, different choices of $\Om^I_{g,h}$ give rise to equivalent 4-cocycles.


Next, consider the choice of symmetry restriction $U^A_g$. Instead of $U^A_g$, we could instead choose $\tilde U^A_g=\Sig_gU^A_g$ where $\Sig_g$ is an arbitrary 1D QCA acting along $\partial A$. Given this choice, instead of $\nu(g,h)$ we would obtain the 2-cocycle
\begin{equation}
    \tilde\nu(g,h)=\nu(g,h)\frac{\mu(g)\mu(h)}{\mu(gh)}
\end{equation}
where $\mu(g)=\text{Ind}(\Sig_g)$. We find that $\tilde\nu$ differs from $\nu$ by the 2-coboundary $d\mu$. Thus, different choices of symmetry restriction give rise to equivalent 2-cocycles. Similarly to before, since $\mu$ may be any 1-cochain, $\tilde\nu$ may be any $2$-cocycle which is equivalent to $\nu$. We show in Appendix~\ref{appendix:ambiguity2} that different choices of symmetry restriction also give rise to equivalent 4-cocycles.

Finally, we consider the choice of disk $A$ and interval $I\in\partial A$. Clearly, small deformations of these regions can be absorbed into the choice of restrictions $U_g^A$ and $\Om^I_{g,h}$. The cohomology classes of the output cocycles are thus invariant under such small deformations, and it follows that they are also invariant under large deformations. We conclude that our procedure yields well-defined cohomology classes $[\nu]\in H^2(G,\mathbb{Q}_+)$ and $[\omega]\in H^4(G,U(1))$. Clearly, these indices are additive under stacking of $G$-symmetric systems.

\section{Obstruction to a trivially gapped Hamiltonian}
\label{sec:obstruction}

In the previous section, we have defined a pair of indices, $[\nu]\in H^2(G,\mathbb{Q}_+)$ and $[\omega]\in H^4(G,U(1))$, for any $G$-symmetry acting by FDQCs on a 2D lattice system. Here, we justify the interpretation of $[\omega]$ as a label for the anomaly of the symmetry. That is, we show---under certain physically reasonable assumptions---that a $G$-symmetry with nontrivial $[\omega]$ does not admit a $G$-symmetric invertible state. Thus, there cannot exist a symmetric gapped Hamiltonian with a unique invertible ground state.

Our first assumption is that the defining procedure for the index $[\omega]$ can be appropriately modified to the setting of QCAs and FDQCs ``with tails". More precisely, a QCA with tails refers to a unitary that preserves locality of operators up to corrections that decay exponentially with distance. Similarly, a FDQC with tails refers to a circuit whose gates are supported on a finite number of sites, up to exponentially decaying corrections.\footnote{We note that a FDQC with tails is equivalent to a locally generated unitary, \textit{i.e.} finite time evolution by a time-dependent local Hamiltonian.} In 1D, the GNVW index is well-defined in the setting of QCAs with tails, and the $\mathbb{Q}_+$ classification of 1D QCAs modulo FDQCs is unaffected by allowing for tails \cite{Ranard}. Thus, we anticipate that  the procedure can be modified to allow for non-strict locality of all of the operators used to define $[\nu]$ and $[\omega]$.\footnote{This would require a suitable notion of ``restriction" of a QCA with tails.} We emphasize that there are subtleties involving finite size effects arising from the lack of strict locality; we do not attempt a rigorous treatment here. Henceforth, the terms QCA and FDQC will refer to operators with tails.

Bearing these subtleties in mind, we may now outline the argument. Recall that a state $\ket{\psi}$ is \textit{invertible} if there exists a state $\ket{\phi}$ living in an ancillary Hilbert space, and a FDQC $V$ such that $V(\ket{\psi}\otimes\ket{\phi})$ is a product state \cite{Kitaev1,Kitaev2}. Further recall that a state $\ket{\psi}$ is \textit{short-range entangled} (SRE) if there exists a FDQC $W$ such that $W\ket{\psi}$ is a product state \cite{LRE}.\footnote{The standard definition of SRE states allows for tensoring with a product state in an ancillary Hilbert space. We will omit this possibility for simplicity; this does not affect the validity of Theorem~\ref{thm}.}
Note that in general, short-range entanglement is a strictly stronger condition than invertibility.\footnote{We note that Kitaev uses an alternative definition of SRE that includes invertible states in the class of SRE states. Here, we use the stated definition.} However, in 1D bosonic systems it is believed that all invertible states are also SRE \cite{LRE}.\footnote{In 1D fermionic systems there are invertible states that are not SRE, such as the Kitaev chain \cite{KitaevWire}.} For our purpose we will assume this to be the case:
\begin{assumption}
    \label{assumption1}
    Every 1D invertible state is SRE.
\end{assumption}

Under this assumption, we demonstrate the following proposition:
\begin{thm}\label{thm}
    Suppose $\{U_g\}$ is a $G$-symmetry acting by FDQCs on a 2D lattice system, and there exists a $G$-symmetric invertible state $\ket{\psi}$. Then, $\{U_g\}$ has trivial anomaly index $[\omega]\in H^4(G,U(1))$.
\end{thm}
\begin{proof}
    The proof follows from the three lemmas below. First, consider the case where $\ket{\psi}$ is not only invertible, but is also SRE.

    To begin, consider a restriction $U^A_g$ of $U_g$ to the disk $A$. By Lemma~\ref{lemma1}, there exists a FDQC $\Sigma_g$ supported near $\partial A$ such that $\Sigma_gU^A_g\ket{\psi}=\ket{\psi}$, for each $g\in G$. Let us redefine $U^A_g\to \Sigma_gU^A_g$, such that after the redefinition, $U^A_g\ket{\psi}=\ket{\psi}$. Since $\Om_{g,h}=U^A_gU^A_h(U^A_{gh})^{-1}$, it follows that $\Om_{g,h}\ket{\psi}=\ket{\psi}$.

    Next, we define the expanded Hilbert space $\mathcal{H}'=\mathcal{H}\otimes\mathcal{H}_{\partial A}$ and the operator $\Om'_{g,h}=\Om_{g,h}\otimes T_{g,h}$ as in step 4 of our anomaly computation procedure. Moreover, we define a state $\ket{\psi'}=\ket{\psi}\otimes\ket{\psi_{\partial A}}$ where $\ket{\psi_{\partial A}}$ is the 1D translation invariant product state from step 4. Since $\ket{\psi_{\partial A}}$ is translation invariant, it follows that $T_{g,h}\ket{\psi_{\partial A}}=\ket{\psi_{\partial A}}$, and hence $\Om'_{g,h}\ket{\psi'}=\ket{\psi'}$. We now consider a restriction $\Om^I_{g,h}$ of $\Om'_{g,h}$ to the interval $I=[a,b]\in\partial A$. By Lemma~\ref{lemma2}, there exists a FDQC $\La_{g,h}$ supported near points $a$ and $b$ such that $\La_{g,h}\Om^I_{g,h}\ket{\psi'}=\ket{\psi'}$, for each pair $g,h\in G$. Let us redefine $\Om^I_{g,h}\to\La_{g,h}\Om^I_{g,h}$, such that $\Om^I_{g,h}\ket{\psi'}=\ket{\psi'}$. By definitions (\ref{eq:Gamma_def}) and (\ref{eq:Delta}), it follows that $\Ga_{g,h,k}\ket{\psi'}=\Delta_{g,h,(k,l)}\ket{\psi'}=\ket{\psi'}$.

    Since $\Om^I_{g,h}\ket{\psi'}=\ket{\psi'}$, it follows by Lemma~\ref{lemma2} that there exists a decomposition $\Om^I_{g,h}=\Om^L_{g,h}\Om^R_{g,h}$, where $\Om^L_{g,h}$ ($\Om^R_{g,h}$) is supported near the interval $L$ ($R$), such that $\Om^L_{g,h}\ket{\psi'}=\ket{\psi'}$. By definition (\ref{eq:Delta_a_def}), it follows that $\Delta^a_{g,h,(k,l)}\ket{\psi'}=\ket{\psi'}$.

    By Lemma~\ref{lemma3}, there exists a restriction $\Ga^a_{g,h,k}$ of $\Ga_{g,h,k}$ to the vicinity of $a$, such that $\Ga^a_{g,h,k}\ket{\psi'}=\ket{\psi'}$. Altogether, by definition (\ref{eq:omega}), it follows that $\omega(g,h,k,l)\ket{\psi'}=\ket{\psi'}$. Hence $\omega(g,h,k,l)=1$, and the anomaly index $[\omega]$ is trivial.

    Thus far, we have shown that the proposition holds whenever $\ket{\psi}$ is SRE. We now claim that the general case, in which $\ket{\psi}$ is merely invertible, immediately follows. To see this, consider the SRE state $\ket{\psi}_\text{SRE}=\ket{\psi}\otimes\ket{\phi}$ which is guaranteed to exist by invertibility of $\ket{\psi}$. Clearly $\ket{\psi}_\text{SRE}$ is symmetric under the $G$-symmetry $\{U_g\otimes\mathbbm{1}\}$. Therefore, $\{U_g\otimes\mathbbm{1}\}$ has trivial anomaly index, hence $\{U_g\}$ must also have trivial anomaly index.
\end{proof}

