\section{Review: Group cohomology}
\label{app:cohomology}

In this appendix, we briefly review the definitions of the cohomology groups $H^2(G,\mathbb{Q}_+)$, $H^3(G,U(1))$, and $H^4(G,U(1))$.

\subsection{$H^2(G,\mathbb{Q}_+)$}

A $\mathbb{Q}_+$-valued \textit{2-cocycle} is a function $\nu:G\times G\to\mathbb{Q}_+$ that satisfies the \textit{2-cocycle condition}
\begin{equation}
    \nu(g,h)\nu(gh,k)=\nu(h,k)\nu(g,hk)\label{eq:2cocycle}
\end{equation}
for any triple of group elements $g,h,k\in G$. The set of 2-cocycles is subject to the following equivalence relation: $\nu\sim\nu'$ if there exists a function $\mu:G\to\mathbb{Q}_+$ such that 
\begin{equation}
    \nu'(g,h)=\nu(g,h)\frac{\mu(g)\mu(h)}{\mu(gh)}.\label{eq:2coboundary}
\end{equation}
The cohomology group $H^2(G,\mathbb{Q}_+)$ is defined as the set of equivalence classes $[\nu]$ of 2-cocycles, with the composition law $[\nu]+[\nu']=[\nu\cdot\nu']$. The ratio to the right of $\nu(g,h)$ in (\ref{eq:2coboundary}) is referred to as the \textit{2-coboundary} $d\mu$.

\subsection{$H^3(G,U(1))$}

A $U(1)$-valued \textit{3-cocycle} is a function $\alpha:G\times G\times G\to U(1)$ that satisfies the \textit{3-cocycle condition}
\begin{equation}
    \alpha(g,h,k)\alpha(g,hk,l)\alpha(h,k,l)=\alpha(gh,k,l)\alpha(g,h,kl)\label{eq:3cocycle}
\end{equation}
for any 4-tuple of group elements $g,h,k,l\in G$. The set of 3-cocycles is subject to the following equivalence relation: $\alpha\sim\alpha'$ if there exists a function $\beta:G\times G\to U(1)$ such that
\begin{equation}
    \alpha'(g,h,k)=\alpha(g,h,k)\frac{\beta(g,h)\beta(gh,k)}{\beta(h,k)\beta(g,hk)}.\label{eq:3coboundary}
\end{equation}
The cohomology group $H^3(G,U(1))$ is defined as the set of equivalence classes $[\alpha]$ of 3-cocycles, with the composition law $[\alpha]+[\alpha']=[\alpha\cdot\alpha']$. The ratio to the right of $\alpha(g,h,k)$ in (\ref{eq:3coboundary}) is referred to as the \textit{3-coboundary} $d\beta$.

\subsection{$H^4(G,U(1))$}

A $U(1)$-valued \textit{4-cocycle} is a function $\omega:G\times G\times G\times G\to U(1)$ that satisfies the \textit{4-cocycle condition}
\begin{equation}
    \omega(h,k,l,m)\omega(g,hk,l,m)\omega(g,h,k,lm)=\omega(gh,k,l,m)\omega(g,h,kl,m)\omega(g,h,k,l)\label{eq:4cocycle}
\end{equation}
for any 5-tuple of group elements $g,h,k,l,m\in G$. The set of 4-cocycles is subject to the following equivalence relation: $\omega\sim\omega'$ if there exists a function $\rho:G\times G\times G\to U(1)$ such that
\begin{equation}
    \omega'(g,h,k,l)=\omega(g,h,k,l)\frac{\rho(g,h,k)\rho(g,hk,l)\rho(h,k,l)}{\rho(gh,k,l)\rho(g,h,kl)}.\label{eq:4coboundary}
\end{equation}
The cohomology group $H^4(G,U(1))$ is defined as the set of equivalence classes $[\omega]$ of 4-cocycles, with the composition law $[\omega]+[\omega']=[\omega\cdot\omega']$. The ratio to the right of $\omega(g,h,k,l)$ in (\ref{eq:4coboundary}) is referred to as the \textit{4-coboundary} $d\rho$.

\section{Review: Else-Nayak index}

In this appendix, we review the Else-Nayak \cite{ElseNayak} procedure for computing the anomaly of a unitary symmetry of a 1D spin chain. The input to the procedure is a collection $\{U_g\}$ of FDQCs satisfying the group law $U_gU_h\propto U_{gh}$, and the output is a 3-cocycle $\alpha:G\times G\times G\to U(1)$. The procedure consists of the following steps:

\begin{enumerate}[leftmargin=*]
    \item Choose a finite interval $I=[a,b]$, which is much longer than the range of the symmetry.

    \item Choose a restriction $U_g^I$ of each symmetry operator $U_g$ to the interval $I$.

    \item The restricted symmetry operators obey the group multiplication law up to composition by a 0D FDQC supported near points $a$ and $b$. In particular, for each pair $g,h\in G$, define the unitary
    \begin{equation}
        \Om_{g,h}\equiv U^I_gU^I_h\left(U^I_{gh}\right)^{-1}.
    \end{equation}
    These operators obey the ``non-abelian 2-cocycle condition" for all $g,h,k\in G$:
    \begin{equation}
        \Om_{g,h}\Om_{gh,k}=\hp{}^g\Om_{h,k}\Om_{g,hk},\label{eq:ElseNayak2cocycle}
    \end{equation}
    where $^gW$ is a shorthand for $U_g^IW(U^I_g)^{-1}$. This constraint is derived from associativity of the restricted symmetries: on one hand,
    \begin{align}
         (U^I_gU^I_h)U^I_k&=\Om_{g,h} U^I_{gh} U^I_k=\Om_{g,h}\Om_{gh,k} U^I_{ghk}.\label{eq:ghk1}
    \end{align}
    On the other hand,
    \begin{align}
        U^I_g(U^I_hU^I_k)&=U^I_g\Om_{h,k}U^I_{hk}=\hp{}^g\Om_{h,k}\Om_{g,hk}U^I_{ghk}.\label{eq:ghk2}
    \end{align}
    Comparing (\ref{eq:ghk1}) with (\ref{eq:ghk2}) begets (\ref{eq:ElseNayak2cocycle}).

    \item Choose a restriction $\Om^a_{g,h}$ of $\Om_{g,h}$ to the vicinity of point $a$. This choice is unique up to multiplication by a $U(1)$ phase.

    \item Since the $\Om$ operators satisfy the non-abelian 2-cocycle condition (\ref{eq:ElseNayak2cocycle}), the corresponding $\Om^a$ operators must obey an analogous constraint, up to a $U(1)$ phase. The function $\alpha:G\times G\times G\to U(1)$ is defined in terms of this phase. Specifically,
    \begin{equation}
    \alpha(g,h,k)=\Om^a_{g,h}\Om^a_{gh,k}\left(\hp{}^g\Om^a_{h,k}\Om^a_{g,hk}\right)^{-1},
    \end{equation}
    It was shown in \cite{ElseNayak} that $\alpha$ defined in this manner automatically obeys the 3-cocycle condition (\ref{eq:3cocycle}).
\end{enumerate}

Importantly, the restriction of $\Om_{g,h}$ to $\Om^a_{g,h}$ has an inherent phase ambiguity: we could instead restrict to $\tilde\Om^a_{g,h}=\beta(g,h)\Om^a_{g,h}$ for an arbitrary function $\beta:G\times G\to U(1)$. Given this choice, instead of $\alpha(g,h,k)$, we would obtain the 3-cocycle
\begin{equation}
    \tilde\alpha(g,h,k)=\alpha(g,h,k)\frac{\beta(g,h)\beta(gh,k)}{\beta(h,k)\beta(g,hk)}.
\end{equation}
Since $\tilde\alpha$ differs from $\alpha$ by the 3-coboundary $d\beta$, the two cocycles are equivalent. Moreover, since $\beta$ may be any 2-cochain, $\tilde\alpha$ may be any 3-cocycle equivalent to $\alpha$. It was further shown in \cite{ElseNayak} that different choices of symmetry restriction always yield equivalent 3-cocycles. Therefore, the procedure gives a well-defined cohomology class $[\alpha]\in H^3(G,U(1))$.

\section{Proof of the 4-cocycle condition}
\label{app:cocycle}

In this appendix, we prove that the function $\omega:G\times G\times G\times G\to U(1)$ defined in (\ref{eq:omega}) satisfies the 4-cocycle condition (\ref{eq:4cocycle}). For convenience we will adopt the following notation:
\begin{align}
    \bar\Om_{g,h}&\equiv\Om^I_{g,h},\\
    \bar\Ga_{g,h,k}&\equiv\Ga^a_{g,h,k},\\
    \bar\Delta_{g,h,(k,l)}&\equiv\Delta^a_{g,h,(k,l)}.
\end{align}

To prove (\ref{eq:4cocycle}), we will make use of a pair of equalities, (\ref{eq:equality1}) and (\ref{eq:equality2}). First,
\begin{equation}
    \bar\Delta_{g,h,(k,l)}\cdot\hp{}^{^{g\cdot h}(k,l)}\bar\Delta_{g,h,(kl,m)}\cdot\hp{}^{g\cdot h}\bar{\Ga}_{k,l,m}=\hp{}^{(g,h)\cdot gh}\bar{\Ga}_{k,l,m}\cdot\hp{}\bar\Delta_{g,h,^k(l,m)}\cdot\hp{}^{^{g\cdot h\cdot k}(l,m)}\bar\Delta_{g,h,(k,lm)}\label{eq:equality1}
\end{equation}
where
\begin{equation}
    \bar\Delta_{g,h,\hp{}^k(l,m)}\equiv\hp{}^{(g,h)\cdot gh\cdot k}\Om^L_{l,m}\left(\hp{}^{g\cdot h\cdot k}\Om^L_{l,m}\right)^{-1}.
\end{equation}
To demonstrate (\ref{eq:equality1}), let us first define the operator $\Ga^c_{g,h,k}$ with support near point $c$, via the following equation:
\begin{equation}
    \Ga^a_{g,h,k}\Ga^c_{g,h,k}=\Om^L_{g,h}\Om^L_{gh,k}\big(\hp{}^g\Om^L_{h,k}\Om^L_{g,hk}\big)^{-1}.
\end{equation}
Then observe that
\begin{align}
    &\bar\Delta_{g,h,(k,l)}\cdot\hp{}^{^{g\cdot h}(k,l)}\bar\Delta_{g,h,(kl,m)}\cdot\hp{}^{g\cdot h}\bar{\Ga}_{k,l,m}\\&\hspace{10pt}=\hp{}^{(g,h)\cdot gh}\big(\Om^L_{k,l}\Om^L_{kl,m}\big)\cdot\hp{}^{g\cdot h}\big(\Om^L_{k,l}\Om^L_{kl,m}\big)^{-1}\cdot\hp{}^{g\cdot h}\bar{\Ga}_{k,l,m},\label{eq:eq11}
\end{align}
whereas
\begin{align}
    &\hp{}^{(g,h)\cdot gh}\bar{\Ga}_{k,l,m}\cdot\hp{}\bar\Delta_{g,h,^k(l,m)}\cdot\hp{}^{^{g\cdot h\cdot k}(l,m)}\bar\Delta_{g,h,(k,lm)}\\&\hspace{10pt}=\hp{}^{(g,h)\cdot gh}\big(\bar\Ga_{k,l,m}\cdot\hp{}^k\Om^L_{l,m}\Om^L_{k,lm}\big)\cdot\hp{}^{g\cdot h}\big(\hp{}^k\Om^L_{l,m}\Om^L_{k,lm}\big)^{-1}\\&\hspace{10pt}=\hp{}^{(g,h)\cdot gh}\big(\Ga^a_{k,l,m}\Ga^c_{k,l,m}\cdot\hp{}^k\Om^L_{l,m}\Om^L_{k,lm}\big)\cdot\hp{}^{g\cdot h}\big(\Ga^c_{k,l,m}\cdot\hp{}^k\Om^L_{l,m}\Om^L_{k,lm}\big)^{-1}\\&\hspace{10pt}=\hp{}^{(g,h)\cdot gh}\big(\Om^L_{k,l}\Om^L_{kl,m}\big)\cdot\hp{}^{g\cdot h}\big(\Om^L_{k,l}\Om^L_{kl,m}\big)^{-1}\cdot\hp{}^{g\cdot h}\bar{\Ga}_{k,l,m}.\label{eq:eq12}
\end{align}
Comparing (\ref{eq:eq11}) with (\ref{eq:eq12}), we obtain (\ref{eq:equality1}). The second equality is as follows:
\begin{equation}
    \bar{\Ga}_{g,h,k}\cdot\hp{}^{^g(h,k)}\bar\Delta_{g,hk,(l,m)}\cdot\hp{}^g\bar\Delta_{h,k,(l,m)}=\hp{}^{(g,h)}\bar\Delta_{gh,k,(l,m)}\cdot\hp{}\bar\Delta_{g,h,^k(l,m)}\cdot\hp{}^{^{g\cdot h\cdot k}(l,m)}\bar{\Ga}_{g,h,k}.\label{eq:equality2}
\end{equation}
To derive this equality, observe that
\begin{align}
    &\bar{\Ga}_{g,h,k}\cdot\hp{}^{^g(h,k)}\bar\Delta_{g,hk,(l,m)}\cdot\hp{}^g\bar\Delta_{h,k,(l,m)}\\
    &\hspace{10pt}=\bar{\Ga}_{g,h,k}\cdot\hp{}^{^g(h,k)\cdot(g,hk)\cdot ghk}{\Om}^L_{l,m}\cdot\hp{}(^{g\cdot h\cdot k}{\Om}^L_{l,m})^{-1}\\
    &\hspace{10pt}=\hp{}^{\Ga_{g,h,k}\cdot\hp{}^g(h,k)\cdot(g,hk)\cdot ghk}{\Om}^L_{l,m}\cdot\bar{\Ga}_{g,h,k}\cdot\hp{}(^{g\cdot h\cdot k}{\Om}^L_{l,m})^{-1}\\
    &\hspace{10pt}=\hp{}^{(g,h)\cdot(gh,k)\cdot ghk}{\Om}^L_{l,m}\cdot\bar{\Ga}_{g,h,k}\cdot\hp{}(^{g\cdot h\cdot k}{\Om}^L_{l,m})^{-1}.\label{eq:eq21}
\end{align}
On the other hand,
\begin{align}
    &^{(g,h)}\bar\Delta_{gh,k,(l,m)}\cdot\hp{}\bar\Delta_{g,h,^k(l,m)}\cdot\hp{}^{^{g\cdot h\cdot k}(l,m)}\bar{\Ga}_{g,h,k}\\
    &\hspace{10pt}=\hp{}^{(g,h)\cdot(gh,k)\cdot ghk}{\Om}^L_{l,m}(^{g\cdot h\cdot k}{\Om}^L_{l,m})^{-1}\cdot\hp{}^{^{g\cdot h\cdot k}(l,m)}\bar{\Ga}_{g,h,k}\\
    &\hspace{10pt}=\hp{}^{(g,h)\cdot(gh,k)\cdot ghk}{\Om}^L_{l,m}\cdot\bar{\Ga}_{g,h,k}\cdot(^{g\cdot h\cdot k}{\Om}^L_{l,m})^{-1}.\label{eq:eq22}
\end{align}
Comparing (\ref{eq:eq21}) with (\ref{eq:eq22}), we obtain (\ref{eq:equality2}).

Finally, to prove the 4-cocycle condition, we will evaluate the expression 
\begin{equation}
    \bar{\Ga}_{g,h,k}\cdot\hp{}^{^g(h,k)}\bar{\Ga}_{g,hk,l}\cdot\hp{}^g\bar{\Ga}_{h,k,l}\cdot\hp{}^{^{g\cdot h}(k,l)\cdot\hp{}^g(h,kl)}\bar{\Ga}_{g,hkl,m}\cdot\hp{}^{g\cdot^h(k,l)}\bar{\Ga}_{h,kl,m}\cdot\hp{}^{g\cdot h}\bar{\Ga}_{k,l,m}    
\end{equation}
in two different ways. For brevity we denote $\omega(g,h,k,l)$ by $\omega_{g,h,k,l}$. On one hand,
\begin{align}
    &\bar{\Ga}_{g,h,k}\cdot\hp{}^{^g(h,k)}\bar{\Ga}_{g,hk,l}\cdot\hp{}^g\bar{\Ga}_{h,k,l}\cdot\hp{}^{^{g\cdot h}(k,l)\cdot\hp{}^g(h,kl)}\bar{\Ga}_{g,hkl,m}\cdot\hp{}^{g\cdot^h(k,l)}\bar{\Ga}_{h,kl,m}\cdot\hp{}^{g\cdot h}\bar{\Ga}_{k,l,m}\\
    &\hspace{10pt}=\omega_{g,h,k,l}\cdot\hp{}^{(g,h)}\bar{\Ga}_{gh,k,l}\cdot\hp{}\bar\Delta_{g,h,(k,l)}\cdot\hp{}^{^{g\cdot h}(k,l)}\bar{\Ga}_{g,h,kl}\\\nonumber
    &\hspace{20pt}\cdot\hp{}^{^{g\cdot h}(k,l)\cdot\hp{}^g(h,kl)}\bar{\Ga}_{g,hkl,m}\cdot\hp{}^{g\cdot^h(k,l)}\bar{\Ga}_{h,kl,m}\cdot\hp{}^{g\cdot h}\bar{\Ga}_{k,l,m}\\
    &\hspace{10pt}=\omega_{g,h,k,l}\cdot\omega_{g,h,kl,m}\cdot\hp{}^{(g,h)}\bar{\Ga}_{gh,k,l}\cdot\hp{}^{(g,h)\cdot\hp{}^{gh}(k,l)}\bar{\Ga}_{gh,kl,m}\cdot\hp{}\bar\Delta_{g,h,(k,l)}\\\nonumber
    &\hspace{20pt}\cdot\hp{}^{^{g\cdot h}(k,l)}\bar\Delta_{g,h,(kl,m)}\cdot\hp{}^{g\cdot h}\bar{\Ga}_{k,l,m}\cdot\hp{}^{^{g\cdot h\cdot k}(l,m)\cdot\hp{}^{g\cdot h}(k,lm)}\bar{\Ga}_{g,h,klm}\\
    &\hspace{10pt}=\omega_{g,h,k,l}\cdot\omega_{g,h,kl,m}\cdot\hp{}^{(g,h)}\bar{\Ga}_{gh,k,l}\cdot\hp{}^{(g,h)\cdot\hp{}^{gh}(k,l)}\bar{\Ga}_{gh,kl,m}\cdot\hp{}^{(g,h)\cdot gh}\bar{\Ga}_{k,l,m}\label{eq:equality3}\\\nonumber
    &\hspace{20pt}\cdot\hp{}\bar\Delta_{g,h,^k(l,m)}\cdot\hp{}^{^{g\cdot h\cdot k}(l,m)}\bar\Delta_{g,h,(k,lm)}\cdot\hp{}^{^{g\cdot h\cdot k}(l,m)\cdot\hp{}^{g\cdot h}(k,lm)}\bar{\Ga}_{g,h,klm}\\
    &\hspace{10pt}=\omega_{g,h,k,l}\cdot\omega_{g,h,kl,m}\cdot\omega_{gh,k,l,m}\cdot\hp{}^{(g,h)\cdot(gh,k)}\bar{\Ga}_{ghk,l,m}\cdot\hp{}^{(g,h)}\bar\Delta_{gh,k,(l,m)}\cdot\hp{}\bar\Delta_{g,h,^k(l,m)}\label{eq:4cocycle1}\\\nonumber
    &\hspace{20pt}\cdot\hp{}^{^{g\cdot h\cdot k}(l,m)}\left(^{(g,h)}\bar{\Ga}_{gh,k,lm}\cdot\hp{}\bar{\Delta}_{g,h,(k,lm)}\cdot\hp{}^{^{g\cdot h}(k,lm)}\bar{\Ga}_{g,h,klm}\right).
\end{align}
To obtain (\ref{eq:equality3}) we have used (\ref{eq:equality1}). On the other hand,
\begin{align}
    &\bar{\Ga}_{g,h,k}\cdot\hp{}^{^g(h,k)}\bar{\Ga}_{g,hk,l}\cdot\hp{}^g\bar{\Ga}_{h,k,l}\cdot\hp{}^{^{g\cdot h}(k,l)\cdot\hp{}^g(h,kl)}\bar{\Ga}_{g,hkl,m}\cdot\hp{}^{g\cdot^h(k,l)}\bar{\Ga}_{h,kl,m}\cdot\hp{}^{g\cdot h}\bar{\Ga}_{k,l,m}\\
    &\hspace{10pt}=\omega_{h,k,l,m}\cdot\hp{}\bar{\Ga}_{g,h,k}\cdot\hp{}^{^g(h,k)}\bar{\Ga}_{g,hk,l}\cdot\hp{}^{^g(h,k)\cdot\hp{}^g(hk,l)}\bar{\Ga}_{g,hkl,m}\\\nonumber
    &\hspace{20pt}\cdot\hp{}^g\left(\hp{}^{(h,k)}\bar{\Ga}_{hk,l,m}\cdot\hp{}\bar\Delta_{h,k,(l,m)}\cdot\hp{}^{^{h\cdot k}(l,m)}\bar{\Ga}_{h,k,lm}\right)\\
    &\hspace{10pt}=\omega_{h,k,l,m}\cdot\omega_{g,hk,l,m}\cdot\hp{}^{(g,h)\cdot(gh,k)}\bar{\Ga}_{ghk,l,m}\bar{\Ga}_{g,h,k}\cdot\hp{}^{^g(h,k)}\bar\Delta_{g,hk,(l,m)}\\\nonumber
    &\hspace{20pt}\cdot\hp{}^g\bar\Delta_{h,k,(l,m)}\cdot\hp{}^{^{g\cdot h\cdot k}(l,m)\cdot\hp{}^g(h,k)}\bar{\Ga}_{g,hk,lm}\cdot\hp{}^{g\cdot\hp{}^{h\cdot k}(l,m)}\bar{\Ga}_{h,k,lm}\\
    &\hspace{10pt}=\omega_{h,k,l,m}\cdot\omega_{g,hk,l,m}\cdot\hp{}^{(g,h)\cdot(gh,k)}\bar{\Ga}_{ghk,l,m}\cdot\hp{}^{(g,h)}\bar\Delta_{gh,k,(l,m)}\cdot\hp{}\bar\Delta_{g,h,^k(l,m)}\label{eq:equality4}\\\nonumber
    &\hspace{20pt}\cdot\hp{}^{^{g\cdot h\cdot k}(l,m)}\left(\bar{\Ga}_{g,h,k}\cdot\hp{}^{^g(h,k)}\bar{\Ga}_{g,hk,lm}\cdot\hp{}^{g}\bar{\Ga}_{h,k,lm}\right)\\
    &\hspace{10pt}=\omega_{h,k,l,m}\cdot\omega_{g,hk,l,m}\cdot\omega_{g,h,k,lm}\cdot\hp{}^{(g,h)\cdot(gh,k)}\bar{\Ga}_{ghk,l,m}\cdot\hp{}^{(g,h)}\bar\Delta_{gh,k,(l,m)}\cdot\hp{}\bar\Delta_{g,h,^k(l,m)}\label{eq:4cocycle2}\\\nonumber
    &\hspace{20pt}\cdot\hp{}^{^{g\cdot h\cdot k}(l,m)}\left(^{(g,h)}\bar{\Ga}_{gh,k,lm}\cdot\hp{}\bar{\Delta}_{g,h,(k,lm)}\cdot\hp{}^{^{g\cdot h}(k,lm)}\bar{\Ga}_{g,h,klm}\right).
\end{align}
To obtain (\ref{eq:equality4}) we have used (\ref{eq:equality2}). Comparing (\ref{eq:4cocycle1}) with (\ref{eq:4cocycle2}), we obtain the 4-cocycle condition (\ref{eq:4cocycle}).

\section{Coboundary ambiguity of the anomaly index}
\label{app:ambiguity}

In this appendix, we demonstrate that different choices of restricted operators $\Om^I_{g,h}$ and $U^A_g$ give rise to equivalent to 4-cocycles.

\subsection{Ambiguity from $\Om^I_{g,h}$}
\label{appendix:ambiguity1}

First, we consider the choice of restriction $\Om^I_{g,h}$ of $\Om'_{g,h}$ to $I$ in step 5 of the procedure. Suppose we instead choose the restriction
\begin{equation}
    \wt\Om^I_{g,h}=\La_{g,h}\Om^I_{g,h},
\end{equation}
where $\Lambda_{g,h}=\Lambda^a_{g,h}\Lambda^b_{g,h}$ is an arbitrary unitary supported in the vicinity of points $a$ and $b$. Given this choice, instead of $\Ga_{g,h,k}$ we obtain the operator
\begin{align}
    \wt\Ga_{g,h,k}&=\wt\Om_{g,h}\wt\Om_{gh,k}\left(\hp{}^g\wt\Om_{h,k}\wt\Om_{g,hk}\right)^{-1}\\&=\La_{g,h}\cdot\hp{}^{(g,h)}\La_{gh,k}\Ga_{g,h,k}\left(\hp{}^g\La_{h,k}\cdot\hp{}^{^g(h,k)}\La_{g,hk}\right)^{-1}.
\end{align}
Moreover, instead of $\Delta_{g,h,(k,l)}$, we obtain the operator
\begin{equation}
    \wt\Delta_{g,h,(k,l)}\equiv\hp{}^{\wt{(g,h)}\cdot gh}\wt\Om^I_{k,l}\left(\hp{}^{g\cdot h}\wt\Om^I_{k,l}\right)^{-1},
\end{equation}
where $\wt{(g,h)}$ is a shorthand for $\wt\Om^I_{g,h}$. We are free to decompose $\wt\Om_{g,h}^I$ as $\wt\Om^I_{g,h}=\wt\Om^L_{g,h}\wt\Om^R_{g,h}$ where $\wt\Om^L_{g,h}=\La^a_{g,h}\Om^L_{g,h}$ and $\wt\Om^R_{g,h}=\La^b_{g,h}\Om^R_{g,h}$. Thus the canonical restriction of $\wt\Delta_{g,h,(k,l)}$ can be expressed as
\begin{align}
    \wt\Delta^a_{g,h,(k,l)}&=\hp{}^{\wt{(g,h)}\cdot gh}\wt\Om^L_{k,l}\left(\hp{}^{g\cdot h}\wt\Om^L_{k,l}\right)^{-1}\\&=\La^a_{g,h}\cdot\hp{}^{(g,h)\cdot gh}\La^a_{k,l}\Delta^a_{g,h,(k,l)}\left(\hp{}^{g\cdot h}\La^a_{k,l}\cdot\hp{}^{^{g\cdot h}(k,l)}\La^a_{g,h}\right)^{-1}.
\end{align}
To continue the procedure, next we choose a restriction of $\wt\Ga_{g,h,k}$ to point $a$. We are free to choose, in particular,
\begin{equation}
    \widetilde\Ga^a_{g,h,k}=\La^a_{g,h}\cdot\hp{}^{(g,h)}\La^a_{gh,k}\Ga^a_{g,h,k}\left(\hp{}^g\La^a_{h,k}\cdot\hp{}^{^g(h,k)}\La^a_{g,hk}\right)^{-1}.
\end{equation}
Finally we obtain the 4-cocycle
\begin{equation}
    \wt\omega(g,h,k,l)=\wt\Ga^a_{g,h,k}\cdot\hp{}^{^g\wt{(h,k)}}\wt\Ga^a_{g,hk,l}\cdot\hp{}^g\wt\Ga^a_{h,k,l}\left(\hp{}^{\wt{(g,h)}}\wt\Ga^a_{gh,k,l}\cdot\hp{}\wt\Delta^a_{g,h,(k,l)}\cdot\hp{}^{^{g\cdot h}\wt{(k,l)}}\wt\Ga^a_{g,h,kl}\right)^{-1}.
\end{equation}
We now show that $\wt\omega(g,h,k,l)=\omega(g,h,k,l)$. For convenience, we use the notation $\bar\La_{g,h}\equiv\La^a_{g,h}$ and $\bar\Om_{g,h}\equiv\Om^I_{g,h}$. First, we evaluate the following expression:
\begin{align}
    &\wt\Gamma^a_{g,h,k}\cdot\hp{}^{^g\wt{(h,k)}}\wt\Gamma^a_{g,hk,l}\cdot\hp{}^g\wt\Gamma^a_{h,k,l}\\\nonumber
    &\hspace{10pt}=\bar\La_{g,h}\cdot\hp{}^{(g,h)}\bar\La_{gh,k}\wt\Ga^a_{g,h,k}\cdot\hp{}^{^g(h,k)}\bar\La^{-1}_{g,hk}\cdot\hp{}^g\bar\La^{-1}_{h,k}\\
    &\hspace{20pt}\cdot\hp{}^g\bar\La_{h,k}\cdot\hp{}^g\bar\Omega_{h,k}\bar\La_{g,hk}\cdot\hp{}^{(g,hk)}\bar\La_{ghk,l}\wt\Ga^a_{g,hk,l}\cdot\hp{}^{^g(hk,l)}\bar\La^{-1}_{g,hkl}\cdot\hp{}^g\bar\La^{-1}_{hk,l}\cdot\hp{}^g\bar\Omega^{-1}_{h,k}\cdot\hp{}^g\bar\La^{-1}_{h,k}\\\nonumber
    &\hspace{20pt}\cdot\hp{}^g\bar\La_{h,k}\cdot\hp{}^{g\cdot(h,k)}\bar\La_{hk,l}\cdot\hp{}^g\wt\Ga^a_{h,k,l}\cdot\hp{}^{g\cdot\hp{}^h(k,l)}\bar\La^{-1}_{h,kl}\cdot\hp{}^{g\cdot h}\bar\La^{-1}_{k,l}\\
    &\hspace{10pt}=\bar\La_{g,h}\cdot\hp{}^{(g,h)}\bar\La_{gh,k}\cdot\hp{}^{(g,h)\cdot(gh,k)}\bar\La_{ghk,l}\left(\wt\Ga^a_{g,h,k}\cdot\hp{}^{^g(h,k)}\wt\Ga^a_{g,hk,l}\cdot\hp{}^g\wt\Ga^a_{h,k,l}\right)\label{eq:OmegaAmbi1}\\\nonumber
    &\hspace{20pt}\cdot\hp{}^{^{g\cdot h}(k,l)\cdot\hp{}^g(h,kl)}\bar\La^{-1}_{g,hkl}\cdot\hp{}^{g\cdot\hp{}^h(k,l)}\bar\La^{-1}_{h,kl}\cdot\hp{}^{g\cdot h}\bar\La^{-1}_{k,l}.
\end{align}
Second, we evaluate the expression
\begin{align}
    &^{\wt{(g,h)}}\wt\Ga^a_{gh,k,l}\cdot\hp{}\wt\Delta^a_{g,h,(k,l)}\cdot\hp{}^{^{g\cdot h}\wt{(k,l)}}\wt\Ga^a_{g,h,kl}\\\nonumber
    &\hspace{10pt}=\bar\La_{g,h}\bar\Omega_{g,h}\bar\La_{gh,k}\cdot\hp{}^{(gh,k)}\bar\La_{ghk,l}\Ga^a_{gh,k,l}\cdot\hp{}^{^{gh}(k,l)}\bar\La^{-1}_{gh,kl}\cdot\hp{}^{gh}\bar\La^{-1}_{k,l}\bar\Omega_{g,h}^{-1}\bar\La_{g,h}^{-1}\\
    &\hspace{20pt}\cdot\bar\La_{g,h}\cdot\hp{}^{(g,h)\cdot gh}\bar\La_{k,l}\Delta^a_{g,h,(k,l)}\cdot\hp{}^{^{g\cdot h}(k,l)}\bar\La^{-1}_{g,h}\cdot\hp{}^{g\cdot h}\bar\La^{-1}_{k,l}\\\nonumber
    &\hspace{20pt}\cdot\hp{}^{g\cdot h}\bar\La_{k,l}\cdot\hp{}^{g\cdot h}\bar\Om_{k,l}\bar\La_{g,h}\cdot\hp{}^{(g,h)}\bar\La_{gh,kl}\Ga^a_{g,h,kl}\cdot\hp{}^{^{g}(h,kl)}\bar\La^{-1}_{g,hkl}\cdot\hp{}^{g}\bar\La^{-1}_{h,kl}\cdot\hp{}^{g\cdot h}\bar\Om_{k,l}^{-1}\cdot\hp{}^{g\cdot h}\bar\La_{k,l}^{-1}\\
    &\hspace{10pt}=\bar\La_{g,h}\cdot\hp{}^{(g,h)}\bar\La_{gh,k}\cdot\hp{}^{(g,h)\cdot(gh,k)}\bar\La_{ghk,l}\left(\hp{}^{(g,h)}\Ga^a_{gh,k,l}\cdot\hp{}^{(g,h)}\Delta^a_{g,h,(k,l)}\cdot\hp{}^{^{g\cdot h}(k,l)}\Ga^a_{g,h,kl}\right)\label{eq:OmegaAmbi2}\\\nonumber
    &\hspace{20pt}\cdot\hp{}^{^{g\cdot h}(k,l)\cdot\hp{}^{g}(h,kl)}\bar\La^{-1}_{g,hkl}\cdot\hp{}^{g\cdot\hp{}^h(k,l)}\bar\La^{-1}_{h,kl}\cdot\hp{}^{g\cdot h}\bar\La_{k,l}^{-1}.
\end{align}
Comparing (\ref{eq:OmegaAmbi1}) with (\ref{eq:OmegaAmbi2}), we find that $\wt\omega(g,h,k,l)=\omega(g,h,k,l)$.

\subsection{Ambiguity from $U_g^A$}
\label{appendix:ambiguity2}

Next, we consider the choice of restricted symmetries $U^A_g$. Suppose we instead choose the symmetry restrictions
\begin{equation}
    \wt{U}^A_g=\Sigma_gU^A_g
\end{equation}
where $\Sigma_g$ is an arbitrary 1D QCA supported in the vicinity of $\partial A$. Given this choice, instead of $\Omega_{g,h}$ we obtain the operator
\begin{equation}
    \wt\Om_{g,h}=\Sigma_g\cdot\hp{}^g\Sigma_h\Om_{g,h}\Sigma_{gh}^{-1}.
\end{equation}

Let us define the function $\mu:G\to\mathbb{Q}_+$ where $\mu(g)=\text{Ind}(\Sigma_g)$. Instead of the 2-cocycle $\nu(g,h)=\text{Ind}(\Om_{g,h})$, we obtain an equivalent 2-cocycle
\begin{equation}
    \wt\nu(g,h)=\nu(g,h)\frac{\mu(g)\mu(h)}{\mu(gh)}.
\end{equation}
Thus, different choices of symmetry restriction give 2-cocycles that differ by the 2-coboundary $d\mu$.

To continue the procedure, we define the operator $\wt{T}_{g,h}=T_{\wt\nu(g,h)}^{-1}$ acting on $\mathcal{H}_\partial{A}$.\footnote{In principle, the operator $\wt{T}_{g,h}$ may require ancilla qudits of dimension different from that of the original ancillary system. For simplicity we will assume that is not the case, and that $\wt{T}_{g,h}$ and $T_{g,h}$ act on the same Hilbert space $\mathcal{H}_{\partial A}$.} Furthermore, let us define an operator $T_g=T_{\mu(g)}^{-1}$ for each $g\in G$, such that $\Sigma_g\otimes T_g$ is a 1D FDQC. Due to (\ref{eq:Tcondition}), we may decompose $\wt T_{g,h}$ as
\begin{equation}
    \wt T_{g,h}=T_gT_hT_{g,h}T_{gh}^{-1}.
\end{equation}
Next, we must choose a restriction of $\wt\Omega'_{g,h}\equiv\wt\Om_{g,h}\otimes \wt T_{g,h}$ to the interval $I$. To make a convenient choice, we first choose a restriction $\bar\Sigma$ of $\Sigma'_g\equiv\Sigma_g\otimes T_g$ to the interval $I'=[a-\delta,b-\delta]$, where $\delta$ is some distance larger than the range of the symmetry. We then choose the following restriction of $\wt\Om_{g,h}'$:
\begin{equation}
    \wt\Om^I_{g,h}=\bar\Sigma_g\cdot\hp{}^g\bar\Sigma_h\bar\Om_{g,h}(\bar\Sigma_{gh})^{-1}
\end{equation}
where we use the notation $\bar\Om_{g,h}\equiv\Om^I_{g,h}$. Given this choice, in place of $\Ga_{g,h,k}$ we obtain the operator
\begin{align}
    \wt\Ga_{g,h,k}&=\wt\Om^I_{g,h}\wt\Om^I_{gh,k}\left(\hp{}^g\wt\Om^I_{h,k}\wt\Om^I_{g,hk}\right)^{-1}\\
    &=\bar\Sigma_g\cdot\hp{}^g\bar\Sigma_h\bar\Om_{g,h}\cdot\hp{}^{gh}\bar\Sig_k\bar\Om_{gh,k}\bar\Om_{g,hk}^{-1}\cdot\hp{}^g\bar\Sig_{hk}^{-1}\bar\Sig_g^{-1}\cdot\hp{}^{\wt{g}}(\bar\Sigma_{hk}\bar\Om_{h,k}^{-1}\cdot\hp{}^h\bar\Sig_k^{-1}\bar\Sig_h^{-1})\\
    &=\bar\Sigma_g\cdot\hp{}^g\bar\Sigma_h\cdot\hp{}^{(g,h)\cdot gh}\bar\Sig_k\Ga_{g,h,k}\cdot\hp{}^{^g\bar\Sig_{hk}^{-1}}\bar{\bar\Sig}_g\cdot\hp{}^{g\cdot h}\bar\Sig_k^{-1}\cdot\hp{}^g\bar\Sig_h^{-1}\Sig_g^{-1},
\end{align}
where $\tilde{g}$ is a shorthand for $\wt{U}^A_g$. Here we have defined the operator $\bar{\bar\Sigma}_g=
\bar\Sigma^{-1}_g\Sigma_g$. We note that since $\bar\Sig_g$ is supported on the interval $I'$, it follows that $\bar{\bar\Sig}_g$ commutes with $\bar\Om_{h,k}$.

Instead of $\Delta_{g,h,(k,l)}$, we obtain the operator
\begin{equation}
    \wt\Delta_{g,h,(k,l)}=\hp{}^{\wt{(g,h)}\cdot\wt{gh}}\wt\Om_{k,l}\cdot\hp{}^{\wt{g}\cdot\wt{h}}\wt\Om^{-1}_{k,l},
\end{equation}
where $\wt{(g,h)}$ is a shorthand for $\wt\Om^I_{g,h}$. Let us choose an arbitrary decomposition $\bar\Sig_g=\Sig^L_g\Sig^R_g$. We are free to decompose $\wt\Om_{g,h}^I$ as $\wt\Om^I_{g,h}=\wt\Om^L_{g,h}\wt\Om^R_{g,h}$ where $\wt\Om^L_{g,h}=\Sig^L_g\cdot\hp{}^g\Sig^L_h\Om^L_{g,h}(\Sig^L_{gh})^{-1}$ and similarly for $\wt\Om^R_{g,h}$. Thus the canonical restriction of $\wt\Delta_{g,h,(k,l)}$ can be expressed as
\begin{align}
    \wt\Delta^a_{g,h,(k,l)}&=\hp{}^{\wt{(g,h)}\cdot\wt{gh}}\wt\Om^L_{k,l}\left(\hp{}^{\wt{g}\cdot\wt{h}}\wt\Om^L_{k,l}\right)^{-1}\\
    &=\bar\Sig_g\cdot\hp{}^g\bar\Sig_h\bar\Om_{g,h}\bar\Sig_{gh}^{-1}\cdot\hp{}^{\wt{gh}}\big(\Sig^L_k\cdot\hp{}^k\Sig^L_l\Om^L_{k,l}(\Sig^L_{kl})^{-1}\big)\bar\Sig_{gh}\bar\Om_{g,h}^{-1}\cdot\hp{}^g\bar\Sig_h^{-1}\bar\Sig_g^{-1}
\end{align}

Proceeding onward, we choose a restriction of $\wt\Ga_{g,h,k}$ to point $a$. We choose for simplicity
\begin{align}
    \wt\Ga^a_{g,h,k}&=\bar\Sigma_g\cdot\hp{}^g\bar\Sigma_h\cdot\hp{}^{(g,h)\cdot gh}\bar\Sig_k\Ga^a_{g,h,k}\cdot\hp{}^{^g\bar\Sig_{hk}^{-1}}\bar{\bar\Sig}_g\cdot\hp{}^{g\cdot h}\bar\Sig_k^{-1}\cdot\hp{}^g\bar\Sig_h^{-1}\Sig_g^{-1}.
\end{align}
Finally, we obtain the cocycle
\begin{equation}
    \wt\omega(g,h,k,l)=\wt\Ga^a_{g,h,k}\cdot\hp{}^{^{\wt{g}}\wt{(h,k)}}\wt\Ga^a_{g,hk,l}\cdot\hp{}^{\wt{g}}\wt\Ga^a_{h,k,l}\left(\hp{}^{\wt{(g,h)}}\wt\Ga^a_{gh,k,l}\cdot\hp{}\wt\Delta^a_{g,h,(k,l)}\cdot\hp{}^{^{\wt{g}\cdot \wt{h}}\wt{(k,l)}}\wt\Ga^a_{g,h,kl}\right)^{-1}.
\end{equation}
We now show that $\wt\omega(g,h,k,l)=\omega(g,h,k,l)$. First, we evaluate the following expression:
\begin{align}
    &\wt\Ga^a_{g,h,k}\cdot\hp{}^{^{\wt{g}}\wt{(h,k)}}\wt\Ga^a_{g,hk,l}\cdot\hp{}^{\wt{g}}\wt\Ga^a_{h,k,l}\\\nonumber
    &\hspace{10pt}=\bar\Sig_g\cdot\hp{}^g\bar\Sig_h\cdot\hp{}^{(g,h)\cdot gh}\bar\Sig_k\Ga^a_{g,h,k}\cdot\hp{}^{^g\bar\Sig_{hk}^{-1}}\bar{\bar\Sig}_g\cdot\hp{}^{g\cdot h}\bar\Sig_k^{-1}\cdot\hp{}^g\bar\Sig_h^{-1}\Sig_g^{-1}\\\nonumber
    &\hspace{20pt}\cdot\Sig_g\cdot\hp{}^g\bar\Sig_h\cdot\hp{}^{g\cdot h}\bar\Sig_k\cdot\hp{}^g\bar\Om_{h,k}\cdot\hp{}^g\bar\Sig_{hk}^{-1}\Sig_g^{-1}\cdot\\
    &\hspace{20pt}\cdot\bar\Sig_g\cdot\hp{}^g\bar\Sig_{hk}\cdot\hp{}^{(g,hk)\cdot ghk}\bar\Sig_l\Ga^a_{g,hk,l}\cdot\hp{}^{^g\bar\Sig_{hkl}^{-1}}\bar{\bar\Sig}_g\cdot\hp{}^{g\cdot hk}\bar\Sigma_l^{-1}\cdot\hp{}^g\bar\Sigma_{hk}^{-1}\Sig_g^{-1}\\\nonumber
    &\hspace{20pt}\cdot\Sig_g\cdot\hp{}^g\bar\Sig_{hk}\cdot\hp{}^g\bar\Om_{h,k}^{-1}\cdot\hp{}^{g\cdot h}\bar\Sig_k^{-1}\cdot\hp{}^g\bar\Sig_h^{-1}\Sig_g^{-1}\\\nonumber
    &\hspace{20pt}\cdot\Sig_g\cdot\hp{}^g\bar\Sig_h\cdot\hp{}^{g\cdot h}\bar\Sig_k\cdot\hp{}^{g\cdot(h,k)\cdot hk}\bar\Sig_l\cdot\hp{}^g\Ga^a_{h,k,l}\cdot\hp{}^{g\cdot\hp{}^h\bar\Sig_{kl}^{-1}}\bar{\bar\Sig}_h\cdot\hp{}^{g\cdot h\cdot k}\bar\Sigma_l^{-1}\cdot\hp{}^{g\cdot h}\bar\Sig_k^{-1}\cdot\hp{}^g\Sig_h^{-1}\Sig_g^{-1}\\
    &\hspace{10pt}=\bar\Sig_g\cdot\hp{}^g\bar\Sig_h\cdot\hp{}^{(g,h)\cdot gh}\bar\Sig_k\cdot\hp{}^{(g,h)\cdot(gh,k)\cdot ghk}\bar\Sig_l\left(\Ga^a_{g,h,k}\cdot\hp{}^{^g(h,k)}\Ga^a_{g,hk,l}\cdot\hp{}^g\Ga^a_{h,k,l}\right)\label{eq:OmegaAmbi3}\\\nonumber
    &\hspace{20pt}\cdot\hp{}^{^g\bar\Sig_{hkl}^{-1}}\bar{\bar\Sig}_g\cdot\hp{}^{g\cdot\hp{}^h\bar\Sig_{kl}^{-1}}\bar{\bar\Sig}_h\cdot\hp{}^{g\cdot h\cdot k}\bar\Sigma_l^{-1}\cdot\hp{}^{g\cdot h}\bar\Sig_k^{-1}\cdot\hp{}^g\Sig_h^{-1}\Sig_g^{-1}.
\end{align}
Second, we evaluate the expression
\begin{align}
    &^{\wt{(g,h)}}\wt\Ga^a_{gh,k,l}\cdot\hp{}\wt\Delta^a_{g,h,(k,l)}\cdot\hp{}^{^{\wt{g}\cdot \wt{h}}\wt{(k,l)}}\wt\Ga^a_{g,h,kl}\\\nonumber
    &\hspace{10pt}=\bar\Sig_g\cdot\hp{}^g\bar\Sig_h\bar\Om_{g,h}\cdot\hp{}^{gh}\bar\Sig_k\cdot\hp{}^{(gh,k)\cdot ghk}\bar\Sig_l\Ga^a_{gh,k,l}\cdot\hp{}^{^{gh}\bar\Sig_{kl}^{-1}}\bar{\bar\Sig}_{gh}\cdot\hp{}^{gh\cdot k}\bar\Sig_l^{-1}\cdot\hp{}^{gh}\bar\Sig_k^{-1}\bar{\bar\Sig}_{gh}\bar\Om_{g,h}^{-1}\cdot\hp{}^g\bar\Sig_h^{-1}\bar\Sig_g^{-1}\\
    &\hspace{20pt}\cdot\bar\Sig_g\cdot\hp{}^g\bar\Sig_h\bar\Om_{g,h}\bar\Sig_{gh}^{-1}\cdot\hp{}^{\wt{gh}}\big(\Sig^L_k\cdot\hp{}^k\Sig^L_l\Om^L_{k,l}(\Sig^L_{kl})^{-1}\big)\bar\Sig_{gh}\bar\Om_{g,h}^{-1}\cdot\hp{}^g\bar\Sig_h^{-1}\bar\Sig_g^{-1}\label{eq:Sig}\\\nonumber
    &\hspace{20pt}\cdot\bar\Sig_g\cdot\hp{}^g\bar\Sig_h\cdot\hp{}^{(g,h)\cdot gh}\bar\Sig_{kl}\Ga^a_{g,h,kl}\cdot\hp{}^{^g\bar\Sig_{hkl}^{-1}}\bar{\bar\Sig}_g\cdot\hp{}^{g\cdot h}\bar\Sig_{kl}^{-1}\cdot\hp{}^g\bar\Sig_h^{-1}\Sig_g^{-1}\cdot\hp{}^{\wt{g}\cdot\wt{h}}\big(\Sig^L_k\cdot\hp{}^k\Sig^L_l\Om^L_{k,l}(\Sig^L_{kl})^{-1}\big)^{-1}\\
    &\hspace{10pt}=\bar\Sig_g\cdot\hp{}^g\bar\Sig_h\cdot\hp{}^{(g,h)\cdot gh}\bar\Sig_k\cdot\hp{}^{(g,h)\cdot(gh,k)\cdot ghk}\bar\Sig_l\left(\hp{}^{(g,h)}\Ga^a_{gh,k,l}\cdot\Delta^a_{g,h,k,l}\cdot\hp{}^{^{g\cdot h}(k,l)}\Ga^a_{g,h,kl}\right)\label{eq:OmegaAmbi4}\\\nonumber
    &\hspace{20pt}\cdot\hp{}^{^g\bar\Sig_{hkl}^{-1}}\bar{\bar\Sig}_g\cdot\hp{}^{g\cdot\hp{}^h\bar\Sig_{kl}^{-1}}\bar{\bar\Sig}_h\cdot\hp{}^{g\cdot h\cdot k}\bar\Sig_l^{-1}\cdot\hp{}^{g\cdot h}\bar\Sig_k^{-1}\cdot\hp{}^g\Sig_h^{-1}\Sig_g^{-1}.
\end{align}
To obtain the first equality, we have used the fact that $^{^{\wt{g}\cdot \wt{h}}\wt{(k,l)}}\wt\Ga^a_{g,h,kl}=\hp{}^{^{\wt{g}\cdot \wt{h}}\wt\Om^L_{k,l}}\wt\Ga^a_{g,h,kl}$. Comparing (\ref{eq:OmegaAmbi3}) with (\ref{eq:OmegaAmbi4}), we find that $\wt\omega(g,h,k,l)=\omega(g,h,k,l)$.




