\title{\bf Single-Index Quantile Factor Model with Observed Characteristics}

\author{
  Ruofan Xu\thanks{
    This paper benefited greatly from our discussions with Jiti Gao. We thank Bryan Kelly and Seth Pruitt for sharing the data for the empirical application. All errors are our own.
  } 
  , Qingliang Fan\footnote{
