\section{Generalized Zeeman coupling from the four-band model Hamiltonian}

Let us consider a four-band Hamiltonian for two Kramers' pairs of electronic bands in an ${\mathcal O}_h$ crystalline environment
%---
\begin{equation}
{\mathcal H}_{\textrm{eff}}= \epsilon_0({\bf k}) \tau_0  \sigma_0 + {\mathcal M}({\bf k}) \tau_z \otimes \sigma_0 - \dfrac{P}{\sqrt{3}} \tau_x \otimes {\boldsymbol \sigma} \cdot {\bf k}.
\end{equation}


The eigenvalues are given by $\epsilon^{\pm}({\bf k})=\epsilon_0({\bf k}) \pm \left[ {\mathcal M}({\bf k})^2 + P^2 k^2 /3 \right]^{1/2}$ 
where ${\mathcal M}({\bf k})=M_0 + M_1 k^2$. Now we add a Zeeman coupling which is given by the expression 
%---
\begin{equation}
\Delta {\mathcal H}_{\textrm{eff}}=\bar{g}~\mu_{B}~B_y \tau_0 \otimes \sigma_y + \delta g~\mu_{B}~B_{y} \tau_z \otimes \sigma_y. 
\end{equation}

In matrix form it reads
%----
\begin{equation}
\Delta {\mathcal H}_{\textrm{eff}}
=
\begin{pmatrix} 
  0         & -i(\bar{g} + \delta g )~\mu_{B} B_y & 0 & 0 \\
i (\bar{g} + \delta g )~\mu_{B} B_y &    0        & 0 & 0 \\
      0        & 0 & 0 & -i(\bar{g} - \delta g )~\mu_{B}B_y \\     
  0 & 0 & i(\bar{g} - \delta g )~\mu_{B} B_y & 0 \\     
\end{pmatrix}.
\end{equation}



Let us consider the unperturbed Hamiltonian
%---
\begin{equation}
H_0=
\begin{pmatrix} 
\epsilon_{0\bm k} +\mathcal{M}(\bm k)   & 0  & 0 & 0  \\
0   &  \epsilon_{0\bm k} +\mathcal{M}(\bm k) &  0 & 0  \\
0 & 0 & \epsilon_{0\bm k} - \mathcal{M}(\bm k)   & 0 \\
0   & 0  & 0  & \epsilon_{0\bm k} - \mathcal{M}(\bm k)  \\
\end{pmatrix}
\end{equation}
%--
with the corresponding degenerate eigenvectors
%--
\begin{equation}
|+ \uparrow \rangle_{1}=
\begin{pmatrix} 
1\\
0\\
0\\
0\\
\end{pmatrix} \quad
| + \downarrow \rangle_{2}=
\begin{pmatrix} 
0\\
1\\
0\\
0\\
\end{pmatrix} \quad
| - \uparrow \rangle_{3}=
\begin{pmatrix} 
0\\
0\\
1\\
0\\
\end{pmatrix} \quad
| - \downarrow \rangle_{4}=
\begin{pmatrix} 
0\\
0\\
0\\
1\\
\end{pmatrix}.
\end{equation}
%---


The perturbation reads
%---
\begin{equation}
H'=
\begin{pmatrix} 
                 0                  & -i(\bar{g} + \delta g) ~\mu_{B} B_y              & -\frac{1}{\sqrt{3}}Pk_{z}    & -\frac{1}{\sqrt{3}}Pk_{-}    \\
      i(\bar{g} + \delta g) ~\mu_{B}B_y        &  0                                  &  -\frac{1}{\sqrt{3}}Pk_{+}   & \frac{1}{\sqrt{3}}Pk_{z}   \\
-\frac{1}{\sqrt{3}}Pk_{z}  & -\frac{1}{\sqrt{3}}Pk_{-}  &                   0                    &  -i(\bar{g} - \delta g)~\mu_{B} B_y   \\
-\frac{1}{\sqrt{3}}Pk_{+}  & \frac{1}{\sqrt{3}}Pk_{z}  &             i(\bar{g} - \delta g)~\mu_{B} B_y              &   0  \\
\end{pmatrix}. 
\end{equation}

The Hamiltonian is now understood as $H=H_0 + H'$. In the following we will apply the L\"owdin partioning~\cite{RolandWinklerBookSM} method in order to find an effective
$2\times 2$ effective Hamiltonian. 


\subsection{The L\"owdin partioning  up to the third order}

Note that the Zeeman term is already in the block diagonal sector. This means that to the first order in perturbation theory, the effective term is 
%--
\begin{equation}
[H^{(1)}]=
(\bar{g}+\delta g) ~\mu_{B}B_y 
\begin{pmatrix} 
                    0                & -i       \\
      i    &         0                    \\
\end{pmatrix} =
(\bar{g}+\delta g)~\mu_{B}B_y \sigma_y. 
\end{equation}



\subsubsection{Second order terms}

To the second order in perturbation theory we need to compute the quantity 
%---
\begin{equation}
[H^{(2)}]_{mm'}=
\frac{1}{2}\sum_{l\neq (m,m')}[H']_{ml} [H']_{lm'}\left[ \frac{1}{E_{m}-E_{l}} + \frac{1}{E_{m'}-E_{l}} \right]
\end{equation}
%--
where $(m,m')$ belong to the upper sub-space, namely they take values  $m,m'=1,2 $ while $l$ belongs to the bottom sub-space namely $l= 3,4$. Then
we have that $E_{m}-E_{l}=E_{m'}-E_{l}= 2\mathcal{M}(\bm k)$. Second order perturbation theory then gives
%Explicitly, for the diagonal element $[H^{(2)}]_{11}$ we need to calculate 
%%-----
%\begin{align}
%[H^{(2)}]_{11}
%&=
%\frac{1}{2} [H']_{13} [H']_{31}\left[ \frac{1}{E_{1}-E_{3}} + \frac{1}{E_{1}-E_{3}} \right]
%+
%\frac{1}{2} [H']_{14} [H']_{41}\left[ \frac{1}{E_{1}-E_{4}} + \frac{1}{E_{1}-E_{4}} \right] \\
%\end{align}
\begin{align}
[H^{(2)}]_{11} 
=\frac{1}{3}\frac{P^2k^2}{2\mathcal{M}(\bm k)} = [H^{(2)}]_{22}.
\end{align}

The off-diagonal elements are zero, namely, $[H^{(2)}]_{12}=[H^{(2)}]_{21}=0$. 
Then, the second order perturbation theory gives the effective Hamiltonian 
%--
\begin{equation}
[H^{(2)}]=
\frac{1}{ 2\mathcal{M}(\bm k) }\frac{P^2k^2}{ 3 } 
\begin{pmatrix} 
                    1                 &  0     \\
       0     &          1                      \\
\end{pmatrix}.
\end{equation}

This is a renormalized parabola. 



\subsubsection{Third order terms}

Up to third order perturbation theory we need to compute the quantities
%----
\begin{align}
[H^{(3)}]_{mm'}
&=-\frac{1}{2}\sum_{l}\sum_{m''}
\left[
\frac{[H']_{ml}[H']_{lm''}[H']_{m''m'} }{ ( E_{m'} - E_{l})(E_{m''}-E_{l}) }
\right] \\
&-\frac{1}{2}\sum_{l}\sum_{m''}
\left[
\frac{ [H']_{mm''}[H']_{m''l}[H']_{lm'} }{(E_m - E_l )( E_{m''} - E_l ) } 
\right] \\
&+\frac{1}{2}\sum_{l,l'}
[H']_{ml}[H']_{ll'}[H']_{l'm'}
\left[ \frac{1}{ (E_m - E_l )(E_m - E_{l'}) } + \frac{1}{ (E_{m'} - E_l )(E_{m'} - E_{l'} ) }  \right].
\end{align}


The full off-diagonal term reads 
%--
\begin{align}
[H^{(3)}]_{12}
&=
\frac{1}{2} \frac{( P/\sqrt{3})^2 }{(\mathcal{M}(\bm k))^2} (\bar{g} - \delta g) ~\mu_{B}  k_xk_yB_y  
+
i \frac{1}{2} \frac{ ( P/\sqrt{3})^2 }{ (\mathcal{M}(\bm k))^2 } 
[\bar{g}~\mu_{B}  B_y(k^2_x+k^2_z) +  \delta g~\mu_{B}  B_y k^2_y].
\end{align}




In the same manner we calculate the diagonal terms of the third order perturbation theory. We get
%---
\begin{align}
[H^{(3)}]_{11}=\frac{1}{2} \frac{ ( P/\sqrt{3})^2 }{ (\mathcal{M}(\bm k))^2 }( \bar{g} - \delta g)~\mu_{B} B_y k_y k_z  
\end{align}
%%---
and $[H^{(3)}]_{22}=-[H^{(3)}]_{11}$. With the first order perturbation result 
we can define the effective Hamiltonian of the form $[H^{(1)}]+[H^{(3)}]= \bm d \cdot \bm \sigma$ where
%--
\begin{align}
d_x&= \frac{1}{3}\frac{ P^2 }{(2\mathcal{M}(\bm k))^2}   (\bar{g} - \delta g)~\mu_{B} 2 B_y k_xk_y \\
d_y&= ( \bar{g} + \delta g)~\mu_{B}B_y -\frac{1}{3}\frac{ P^2 }{ (2\mathcal{M}(\bm k))^2 }  [ 2\bar{g}~\mu_{B} B_y(k^2_x+k^2_z) +2\delta g~\mu_{B} B_y k^2_y    ]\\
d_z&= \frac{1}{3}\frac{ P^2 }{ (2\mathcal{M}(\bm k))^2 }  (\bar{g} - \delta g) ~\mu_{B} 2B_y k_yk_z,
\end{align}
%--
which to the leading order in momentum can be expressed as 
\begin{align}
\label{eq:effectivevector}
d_x& \approx \frac{1}{3}\frac{ P^2 }{ 2 M^2_0}  B_y (\bar{g} -\delta g)~\mu_{B} k_xk_y \\
d_y& \approx ( \bar{g} + \delta g)~\mu_{B} B_y 
 \\
d_z& \approx \frac{1}{3}\frac{ P^2 }{ 2M^2_0 } (\bar{g} -\delta g)~\mu_{B} B_y k_yk_z.
\end{align}



The effective $2\times 2$ Hamiltonian will be $H=H_0+H^{(1)} + H^{(2)} + H^{(3)}$.
%----
\begin{equation}
H_0= [ \epsilon_{0\bm k} +\mathcal{M}(\bm k)]\sigma_0 + \frac{1}{ 2\mathcal{M}(\bm k) }\frac{P^2k^2}{ 3 } \sigma_0+\bm d \cdot \bm \sigma.
\end{equation}


