\section{Semi-classical transport theory}



The Boltzmann equation for the distribution $f_{\bm k}$ reads
%---
\begin{equation}
\frac{\partial f}{\partial t}+\dot{\bm r} \cdot \frac{\partial f}{\partial \bm r} + \dot{\bm k} \cdot \frac{\partial f}{\partial \bm k} = \mathcal{I}_{coll}[f]. 
\end{equation}

In the above equation we need the semiclassical velocity, namely 
%----
\begin{equation}
\dot{\bm r}=\frac{1}{\hbar} \frac{\partial \varepsilon_{\bm k}}{\partial \bm k} -\dot{\bm k}\times \bm \Omega
\end{equation}
%--
and the semiclassical variation of momentum, namely 
%---
\begin{equation}
\label{Eq:velocity}
\dot{\bm k}=-\frac{e}{\hbar} \left[ \bm E + \dot{\bm r}\times \bm B \right].
\end{equation}

Solving the above coupled equations for $\bm r$ and $\bm k$ we get 
%---
\begin{equation}
\dot{\bm r}=
\left( 1+\frac{e}{\hbar} \bm B \cdot \bm \Omega \right)^{-1}
\left[
\frac{1}{\hbar} \frac{\partial \varepsilon_{\bm k}}{\partial \bm k} + \frac{e}{\hbar }\bm E \times \bm \Omega
+
\frac{e}{\hbar } \left( \frac{1}{\hbar} \frac{\partial \varepsilon_{\bm k}}{\partial \bm k} \cdot \bm \Omega \right) \bm B
\right]
\end{equation}
%----
\begin{equation}
\dot{\bm k}=
\left( 1+\frac{e}{\hbar} \bm B \cdot \bm \Omega \right)^{-1}
\left[
-\frac{e}{\hbar }\bm E - 
\frac{e}{\hbar } \left( \frac{1}{\hbar} \frac{\partial \varepsilon_{\bm k}}{\partial \bm k} \times \bm B \right)
-\frac{e^2}{\hbar^2 } (\bm B \cdot \bm E)\bm \Omega
\right].
\end{equation}

In the relaxation time approximation $\mathcal{I}_{coll}[f] = - g_{\bm k}/\tau$. In stationary states, the Boltzmann equation is 
$ \dot{\bm k} \cdot \frac{\partial f}{\partial \bm k} = - g_{\bm k}/\tau $.
We take $f=f_0+ g_{\bm k}$ where $f_{0}$ is the equilibrium distribution and  $g_{\bm k}$ is the deviation from equilibrium due to the electric field. 
The equation then reads
%--
\begin{equation}
D\left[
-\frac{e}{\hbar }\bm E - 
\frac{e}{\hbar } \left( \frac{1}{\hbar} \frac{\partial \varepsilon_{\bm k}}{\partial \bm k} \times \bm B \right)
-\frac{e^2}{\hbar^2 } (\bm B \cdot \bm E)\bm \Omega
\right]
 \cdot 
\left( \frac{\partial f_0}{\partial \bm k} +  \frac{\partial g_{\bm k}}{\partial \bm k}\right) = - \frac{g_{\bm k}}{\tau } 
\end{equation}
%---
with $D=(1+\frac{e}{\hbar} \bm B \cdot \bm \Omega)^{-1}$. In linear response
%----
\begin{equation}
\label{Eq:BE}
D\left[
-\frac{e}{\hbar }\bm E
-\frac{e^2}{\hbar^2 } (\bm B \cdot \bm E)\bm \Omega
\right] 
\cdot 
\left( \frac{\partial \varepsilon_{\bm k}}{\partial \bm k} \right) 
\left( \frac{\partial f_0}{\partial \varepsilon_{\bm k}} \right)
+
D\left[
- \frac{e}{\hbar } \left( \frac{1}{\hbar} \frac{\partial \varepsilon_{\bm k}}{\partial \bm k} \times \bm B \right)
\right]
 \cdot 
\left(   \frac{\partial g_{\bm k}}{\partial \bm k}\right) 
= - \frac{g_{\bm k}}{\tau }.
\end{equation}

In terms of the group velocity we can write 
%--
\begin{equation}
\label{}
D\left[
-e\bm E\cdot \bm v
-\frac{e^2}{\hbar } (\bm B \cdot \bm E) (\bm \Omega \cdot \bm v )
\right] 
\left( \frac{\partial f_0}{\partial \varepsilon_{\bm k}} \right)
+
D\left[
- \frac{e}{\hbar } \left( \frac{1}{\hbar} \frac{\partial \varepsilon_{\bm k}}{\partial \bm k} \times \bm B \right)
\right]
 \cdot 
\left(   \frac{\partial g_{\bm k}}{\partial \bm k}\right) 
= - \frac{g_{\bm k}}{\tau }.
\end{equation}



We use the ansatz 
\begin{equation}
g_{\bm k}= 
-e\tau D \left[\frac{e}{\hbar } (\bm B \cdot \bm E) (\bm \Omega \cdot \bm v) + \bm \Upsilon \cdot \bm v \right]  \left( -\frac{\partial f_0}{\partial \varepsilon_{\bm k}} \right)
\end{equation}
%---
where $\bm \Upsilon$ is an unknown field independent of $\bm k$. The equation then reads
%---
\begin{equation}
\label{}
(-e\bm E\cdot \bm v)
\left( \frac{\partial f_0}{\partial \varepsilon_{\bm k}} \right)
+
e\tau 
\left[
- \frac{e}{\hbar } \left( \bm v \times \bm B \right)
\right]
\cdot 
\left[ \frac{\partial  }{\partial \bm k}  \left(\frac{e}{\hbar } (\bm B \cdot \bm E)(\bm \Omega \cdot D\bm v  )
+
\bm \Upsilon \cdot D\bm v \right) \left( \frac{\partial f_0}{\partial \varepsilon_{\bm k}} \right)
\right]
= -e\bm v \cdot \bm \Upsilon \left( \frac{\partial f_0}{\partial \varepsilon_{\bm k}} \right).
\end{equation}





We change the cross product in the second term, in order to single out the velocity. Then we get
%---
\begin{equation}
\label{}
(-e\bm E\cdot \bm v)
\left( \frac{\partial f_0}{\partial \varepsilon_{\bm k}} \right)
+e\tau 
\left[
- \frac{e}{\hbar } \bm B \right] \times 
\left[  \left(\frac{e}{\hbar } (\bm B \cdot \bm E) \nabla_{\bm k} (\bm \Omega \cdot D\bm v  )
+
\Upsilon_i \nabla_{\bm k} D v_i \right) \left( \frac{\partial f_0}{\partial \varepsilon_{\bm k}} \right)
\right]\cdot \bm v
= -e\bm v \cdot \bm \Upsilon \left( \frac{\partial f_0}{\partial \varepsilon_{\bm k}} \right)
\end{equation}





The variation of the equilibrium distribution and the electric charge are a common factor on both sides, then they can be eliminated. We get 
%---
\begin{equation}
\label{}
\bm E +
\tau 
\left[
\frac{e}{\hbar } \bm B \right] \times 
\left[  \left(\frac{e}{\hbar } (\bm B \cdot \bm E) \nabla_{\bm k} (\bm \Omega \cdot D\bm v  )
+
\Upsilon_i \nabla_{\bm k} D v_i \right) 
\right] 
= \bm \Upsilon 
\end{equation}





We can define the vector $\bm C=\nabla_{\bm k} (\bm \Omega \cdot D \bm v  )$. The equation then reads
%---
\begin{equation}
\label{}
\bm E 
+
\tau  \frac{e^2}{\hbar^2 }  (\bm B \cdot \bm E) \bm B\times \bm C
+
\tau D\frac{e}{\hbar} 
\bm B \times 
\left[
\Upsilon_i \nabla_{\bm k}D v_i 
\right] 
= \bm \Upsilon 
\end{equation}



The equation can be written as
%---
\begin{equation}
\label{}
\bm E 
+
\tau  \frac{e^2}{\hbar^2 }  (\bm B \cdot \bm E) \bm B\times \bm C
+
\tau  \frac{e}{\hbar}  M_{L}  \bm \Upsilon
= \bm \Upsilon 
\end{equation}



where the matrix $ M_{L}$ reads (for notation we omit the factor $D$ in front of the velocity)
%---
\begin{equation}
M_{L}=
\begin{pmatrix}
B_y\frac{\partial v_x}{\partial k_z}-B_z\frac{\partial v_x}{\partial k_y} 
& B_y\frac{\partial v_y}{\partial k_z}-B_z\frac{\partial v_y}{\partial k_y} 
& B_y\frac{\partial v_z}{\partial k_z}-B_z\frac{\partial v_z}{\partial k_y} \\
B_z\frac{\partial v_x}{\partial k_x}-B_x\frac{\partial v_x}{\partial k_z} 
& B_z\frac{\partial v_y}{\partial k_x}-B_x\frac{\partial v_y}{\partial k_z} 
& B_z\frac{\partial v_z}{\partial k_x}-B_x\frac{\partial v_z}{\partial k_z} \\
B_x\frac{\partial v_x}{\partial k_y}-B_y\frac{\partial v_x}{\partial k_x} 
& B_x\frac{\partial v_y}{\partial k_y}-B_y\frac{\partial v_y}{\partial k_x} 
& B_x\frac{\partial v_z}{\partial k_y}-B_y\frac{\partial v_z}{\partial k_x} \\
\end{pmatrix}.
\end{equation}


Then it follows 
%---
\begin{equation}
\label{}
\bm \Upsilon = \left(I - \tau  \frac{e}{\hbar} M_{L} \right)^{-1}
\left[
\bm E 
+
\tau  \frac{e^2}{\hbar^2 }  (\bm B \cdot \bm E) \bm B\times \bm C
\right] 
\end{equation}

We can take the electric field as a common factor by writing the equation as
%---
\begin{equation}
\label{}
\bm \Upsilon = \left( I - \tau  \frac{e}{\hbar} M_{L} \right)^{-1}
\left[
I_{3\times 3}
+
\tau  \frac{e^2}{\hbar^2 }M_{\nabla}
\right] \bm E 
\end{equation}

with the matrix 
%---
\begin{equation}
M_{\nabla}=  (\bm B\times \bm C ) \otimes \bm B
=
\begin{pmatrix}
(\bm B\times \bm C )_x B_x & (\bm B\times \bm C )_x B_y & (\bm B\times \bm C )_x B_z \\ 
(\bm B\times \bm C )_y B_x & (\bm B\times \bm C )_y B_y & (\bm B\times \bm C )_y B_z \\ 
(\bm B\times \bm C )_z B_x & (\bm B\times \bm C )_z B_y & (\bm B\times \bm C )_z B_z 
\end{pmatrix}.
\end{equation}
%---





and finally we can find the distribution 
%----
\begin{equation}
g_{\bm k}= -e\tau D \left[-\frac{e}{\hbar } (\bm B \cdot \bm E) ( \bm \Omega \cdot \bm v ) - \bm v \cdot \bm \Upsilon  \right] \left( \frac{\partial f_0}{\partial \varepsilon_{\bm k}} \right). 
\end{equation}


In order to put every element in terms of a field proportional to the electric field, we can define a new matrix 
%---
\begin{equation}
M_{\Omega}= \bm \Omega \otimes \bm B
=
\begin{pmatrix}
\Omega_x B_x & \Omega_x B_y & \Omega_x B_z\\
\Omega_y B_x & \Omega_y B_y & \Omega_y B_z \\
\Omega_z B_x & \Omega_z B_y & \Omega_z B_z
\end{pmatrix}.
\end{equation}
%---

We define a new field $\bm \Phi=\frac{e}{\hbar } M_{\Omega}\bm E$ and can write the distribution as
%---
\begin{equation}
g_{\bm k}= -e\tau D \left[-\bm v  \cdot \bm \Phi - \bm v \cdot \bm \Upsilon \right] \left( \frac{\partial f_0}{\partial \varepsilon_{\bm k}} \right). 
\end{equation}





The first term takes into account a $\bm k$-dependent driving field $\bm \Phi$. 
The second term contains $\bm \Upsilon$ 
which takes into account the Lorentz force and corrections due to the Berry curvature and its variations. This is explicit in the 
vector $\bm C=\nabla_{\bm k} (\bm \Omega \cdot D\bm v)$. 

In order to find the current we take the trace $j_i = -e \sum_{\bm k} \dot{\bm r}_{i} g_{\bm k}$. In changing the sum to an integral, we take into account that 
the density of states is corrected by the presence of the external magnetic field. Then, the rule is 
$\sum_{\bm k} \rightarrow \int \frac{ d^3\bm k }{(2\pi)^3} \left( 1+\frac{e}{\hbar} \bm B \cdot \bm \Omega \right) $. With this and using Eq.\eqref{Eq:velocity} the current follows as
%---
\begin{align}
j_{i}
&=
e^2\tau 
\int \frac{ d^3\bm k }{(2\pi)^3} 
% \sum_{\bm k}
\left( 1+\frac{e}{\hbar} \bm B \cdot \bm \Omega \right)^{-1}
\left( \bm v  \cdot \bm \Phi + \bm v \cdot \bm \Upsilon \right)
\left(
\frac{1}{\hbar} \frac{\partial \varepsilon_{\bm k}}{\partial \bm k} + \frac{e}{\hbar }\bm E \times \bm \Omega
+
\frac{e}{\hbar } \left( \frac{1}{\hbar} \frac{\partial \varepsilon_{\bm k}}{\partial \bm k} \cdot \bm \Omega \right) \bm B
\right)
%\left[
%v_i + \frac{e}{\hbar } \left(\bm v \cdot \bm \Omega \right) B_i
%\right]^2
\left(-\frac{\partial f_0}{\partial \varepsilon_{0\bm k}} \right).
\end{align}

So far the equation is general. In order to calculate the longitudinal current contribution, we set the electric field in the direction of the velocity. Also, we set the magnetic field in the same direction as the electric field since we are interested in longitudinal magnetoresistance. In this case, the term $\propto \frac{e}{\hbar }\bm E \times \bm \Omega$ will not contribute since it is transversal and gives rise to the anomalous Hall effect. Also, $\bm \Gamma = \bm E$, since the other terms are transversal and give rise to the Lorentz force. The current can be written as
$j_{i}= \sigma_{ii}E_i$, where the conductivity reads
%---
\begin{align}
\sigma_{ii}
&=
e^2\tau 
\int \frac{ d^3\bm k }{(2\pi)^3} 
% \sum_{\bm k}
\left( 1+\frac{e}{\hbar} \bm B \cdot \bm \Omega \right)^{-1}
\left[
v_i + \frac{e}{\hbar } \left(\bm v \cdot \bm \Omega \right) B_i
\right]^2
\left(-\frac{\partial f_0}{\partial \varepsilon_{0\bm k}} \right).
\end{align}

Expanding the correction of the density of states up to the second order in the magnetic field we get 
%---
\begin{align}
\left( 1+\frac{e}{\hbar} \bm B \cdot \bm \Omega \right)^{-1}
\approx
1
-\frac{e}{\hbar} \bm B \cdot \bm \Omega 
+\left( \frac{e}{\hbar} \bm B \cdot \bm \Omega \right)^2.
\end{align}



The zeroth order term in magnetic field is the Drude conductivity
%----
\begin{align}
\sigma_{ii,0}
&=e^2\tau  
\int \frac{ d^3\bm k }{(2\pi)^3} 
v^2_{i,0} \delta(\varepsilon_F - \varepsilon_{0\bm k} ) 
\end{align}

The first order in magnetic field reads
%--
\begin{align}
\sigma_{ii,1}
&=
e^2\tau 
\int \frac{ d^3\bm k }{(2\pi)^3} 
\left[
2v_{i} \frac{e}{\hbar } \left(\bm v \cdot \bm \Omega \right) B_i
-\frac{e}{\hbar} \bm B \cdot \bm \Omega  v^2_i 
\right]
\left(-\frac{\partial f_0}{\partial \varepsilon_{0\bm k}} \right).
\end{align}

This term will vanish in our systems since we need to add the bands and the Berry curvature changes sign. 
The second order term in magnetic field reads
%---
\begin{align}
\sigma_{ii,2}
&=
e^2\tau 
\left(  \frac{e}{\hbar } \right)^2
\int \frac{ d^3\bm k }{(2\pi)^3} 
\left[
v^2_{i} \left(  \bm B \cdot \bm \Omega \right)^2
-2v_{i}  \bm B \cdot \bm \Omega \left(\bm v \cdot \bm \Omega \right) B_i
+\left(\bm v \cdot \bm \Omega \right)^2 B^2_i
\right]
\left(-\frac{\partial f_0}{\partial \varepsilon_{0\bm k}} \right).
\end{align}





%\newpage

\subsection{Longitudinal magnetoresistance for the generalized Zeeman coupling of an ${\mathcal O}_h$ crystal }
%----



%
In particular we get
%----
\begin{align}
\sigma_{xx}(\bm B=0)
&=e^2\tau  
\left( \frac{2m}{\hbar^2} \right)
\left( \frac{\hbar}{m} \right)^2
\frac{1}{(2\pi)^3} \int d\phi \int \sin(\theta)d\theta \int dk k^4 \sin^2(\theta)\cos^2(\phi) \frac{\delta( k_F - k )}{2k_F} \\
&=e^2\tau  
\left( \frac{2m}{\hbar^2} \right)
\left( \frac{\hbar}{m} \right)^2
\frac{4\pi}{3}
\frac{1}{(2\pi)^3} \left( \frac{k^3_F}{2} \right)
\end{align}
%---
After including spin degeneracy we find the usual expression $\sigma_{xx}(0)=n_{e}e^2\tau /m$ with $n_e =k^3_F/3\pi^2$.




%-----
For a magnetic field in the $y$-direction we get the second order correction
%---
\begin{align}
\label{}
\sigma_{yy,2}(B_y)
&=
B^2_y e^2\tau  
\left( \frac{e}{\hbar } \right)^2 
\int \frac{ d^3\bm k }{(2\pi)^3} 
(v_x\Omega_x+ v_z\Omega_z)^2 
\delta(\varepsilon_F - \varepsilon_{0\bm k} )
\end{align}


We can calculate the Berry curvature as
%---
\begin{equation}
\Omega^{+}_x
=\frac{1}{2}a^2b\frac{k_y k_x}{ [b^2+k^2_ya^2(k^2_x+k^2_z) ]^{3/2} }
=\frac{a^2}{2b^2}\frac{k_y k_x}{ \left[ 1+ k^2_y \frac{a^2}{b^2} (k^2_x+k^2_z) \right]^{3/2} }
\end{equation}
%%---
%\begin{equation}
%\Omega^{++}_y=-\frac{1}{2}abc\frac{ k^2_y}{ [b^2+k^2_y(a^2k^2_x+c^2k^2_z) ]^{3/2} }
%\end{equation}
%----
\begin{equation}
\Omega^{+}_z=
\frac{1}{2}a^2b\frac{k_y k_z}{ [b^2+k^2_ya^2(k^2_x+k^2_z) ]^{3/2} }
=\frac{a^2}{2b^2}\frac{k_y k_z}{ \left[ 1+ k^2_y \frac{a^2}{b^2} (k^2_x+k^2_z) \right]^{3/2} }
\end{equation}








To zeroth order in magnetic field the velocity reads $v_{x,0}= \hbar k_{x}/m $ and $v_{z,0}=\hbar k_{z}/m$. In the single relaxation time approximation we can write the 
conductivity as
%---
\begin{align}
\label{}
\sigma_{yy,2}(B_y)
&=
2B^2_y e^2\tau  
\left( \frac{e}{\hbar } \right)^2 
\int \frac{ d^3\bm k }{(2\pi)^3} 
%\sum_{\bm k}
(v_{x,0}\Omega_x + v_{z,0}\Omega_z)^2 
\delta(\varepsilon_F - \varepsilon_{0\bm k} ).
\end{align}

The factor $2$ in front of the conductivity is because we need to sum over both bands, and both give the same result. 
The factor in parenthesis reads
%---
\begin{align}
\label{}
(v_x\Omega_x + v_z\Omega_z)^2 =
\left(\frac{a^2}{2b^2} \right)^2  \left( \frac{\hbar}{m} \right)^2
\frac{1}{ \left[1+k^2_y\frac{a^2}{b^2}(k^2_x+k^2_z) \right]^{3}}k^2_y (  k^2_{x} + k^2_{z} )^2.
\end{align}


Then the integral reads
%---
\begin{align}
\label{}
\Delta \sigma_{yy,2}(B_y)
&=
2B^2_y e^2\tau  
\left( \frac{e}{\hbar } \right)^2
\left(\frac{a^2}{2b^2} \right)^2 
\left( \frac{\hbar}{m} \right)^2
\frac{1}{(2\pi)^3}
\int d^3\bm k
\frac{ k^2_y ( k^2_{x} +  k^2_{z} )^2\delta(\varepsilon_F - \varepsilon_{0\bm k} )  }{ 
\left[ 1+k^2_y \frac{a^2}{b^2} (k^2_x + k^2_z ) \right]^{3}}
\end{align}






In spherical coordinates the integral reads
%---
\begin{align}
\label{}
\int^{2\pi}_{0} d\phi
\int^{\pi}_{0} \sin(\theta)d\theta 
\int^{\infty}_0 k^2 dk 
\frac{ k^6 \sin^2(\theta)\sin^2(\phi)  ( \sin^2(\theta)\cos^2(\phi)  + \cos^2(\theta) )^2 }
{ \left[1+  k^4 \frac{a^2}{b^2}\sin^2(\theta)\sin^2(\phi) \left(\sin^2(\theta)\cos^2(\phi) + \cos^2(\theta) \right) \right]^{3}} 
\frac{\delta( k - k_F)}{2k_F} 
\end{align}



The integral over momentum is easily calculated. Defining the integral
%--
\begin{align}
\label{}
I(k_F)= 
\int^{2\pi}_{0} d\phi
\int^{\pi}_{0} \sin(\theta)d\theta 
\frac{\sin^2(\theta)\sin^2(\phi)  ( \sin^2(\theta)\cos^2(\phi)  + \cos^2(\theta) )^2 }
{ \left[1 +  k^4_F\frac{a^2}{b^2} \sin^2(\theta)\sin^2(\phi) \left( \sin^2(\theta)\cos^2(\phi) + \cos^2(\theta) \right) \right]^{3}} 
\end{align}
%--









the conductivity can be written as
%---
\begin{align}
\label{}
\Delta \sigma_{yy,2}(B_y)=
2B^2_y e^2\tau  
\left( \frac{e}{\hbar } \right)^2
\left(\frac{a^2}{2b^2} \right)^2 
\left( \frac{\hbar}{m} \right)^2
\frac{1}{(2\pi)^3} 
\left( \frac{2m}{\hbar^2} \right)
\frac{k^7_F}{2}
I(k_F).
\end{align}

Using the definition of the Drude conductivity we find
%---------
\begin{align}
\label{}
\frac{ \Delta \sigma_{yy,2}(B_y)}{\sigma_{yy}(0)} 
=
\left( \frac{eB_y}{\hbar } \right)^2
\left(\frac{a^2}{2b^2}\right)^2 
\frac{3}{2\pi} k^4_FI(k_F).
\end{align}


The first factor defines the magnetic length or momentum as $1/l_{B} = k_{B}=\sqrt{eB/\hbar}$. We define a characteristic length  
related to the material properties as $l_{0}=\sqrt{a/b}$ or conversely a characteristic momentum $k_0=1/l_0$. Then one writes 
%--
\begin{align}
\label{}
\frac{ \Delta \sigma_{yy,2}(B_y)}{\sigma_{yy}(0)} 
&= \left( \frac{l_0}{l_B} \right)^4 \frac{3}{8\pi} \left( \frac{k_F}{k_0}\right)^4 I( k_F/k_0) 
%&= \alpha^4 \frac{3}{8\pi} \left( k_F l_0 \right)^4 I( k_Fl_0)
\end{align}

%where we define the dimensionless parameter $\alpha=\frac{l_0}{l_B}$. 
The integral reads
\begin{align}
\label{}
I(k_F/k_0)= 
\int^{2\pi}_{0} d\phi
\int^{\pi}_{0} \sin(\theta)d\theta 
\frac{\sin^2(\theta)\sin^2(\phi)  ( \sin^2(\theta)\cos^2(\phi)  + \cos^2(\theta) )^2 }
{ \left[1 +  \left( k_F l_{0} \right)^4 \sin^2(\theta)\sin^2(\phi) \left( \sin^2(\theta)\cos^2(\phi) + \cos^2(\theta) \right) \right]^{3}}.
\end{align}
