\title{High-Dimensional Unfolding in Large Backgrounds}

\author[a]{Alexandre F. Falc\~ao}
\author[b]{and Adam Takacs}

\affiliation[a]{Department of Physics and Technology, University of Bergen, Allegaten 55, 5007 Bergen, Norway}
\affiliation[b]{Institute for Theoretical Physics, Heidelberg University, Philosophenweg 16, 69120 Heidelberg, Germany}

\emailAdd{alexandre.falcao@uib.no}
