\subsection{Dependence  of the construction on a point $Q$ from the chamber orbit}

We noted that the manifold $M_{Q}^{7}$ does not depend, up to diffeomorphism, on a point $Q$  from the orbit of the chamber $x_1+x_i<1$, $i = 2,3,4$.  We point here that still the embedding 
$S^5\to \C P^5$ and the appropriate representation $T^2\to T^6$ do depend on a choice of a chamber  from the given orbit. 

The representative points of the chambers from this orbit are: $(\frac{1}{3}, \frac{5}{9}, \frac{5}{9}, \frac{5}{9})$,  $(\frac{5}{9}, \frac{1}{3}, \frac{5}{9}, \frac{5}{9})$,  $(\frac{5}{9}, \frac{5}{9}, \frac{1}{3}, \frac{5}{9})$,  $(\frac{5}{9}, \frac{5}{9}, \frac{5}{9}, \frac{1}{3})$. 
For example, for $Q= (\frac{5}{9}, \frac{1}{3}, \frac{5}{9}, \frac{5}{9})$, following the above construction,  we obtain  the embedding $f : S^5\to \C P^5$ given by
\[
f(z_0, z_3, z_4) = (z_0:|z_1|:|z_2|:z_3 : z_4 :|z_5|),
\]
and the representation $\rho _{1}: T^2\to T^6$ given by
\[
\rho_1 (t_2, t_5) = (1,1, t_2, 1, 1, t_5),\]
that is the representation $\rho _2 : T^5\to T^6$ given by
\[
\rho _2(t_1, t_2, t_3, t_4, t_5) = (t_1, 1, t_2, t_3, t_4, t_5).
\]
According to Remark~\ref{eq}, we can consider two other equivalent representations $(t_1, t_2, t_3, t_4, t_5) \to (t_1, t_2, 1, t_3, t_4, t_5)$ or $(t_1, t_2, t_3, t_4, t_5) \to (t_1, t_2, t_3, t_4, t_5,1).$  

\begin{rem}
All these representations of $T^5\to T^6$ are different from those pointed in Remark~\ref{eq}.
\end{rem}

\subsection{Construction for the second orbit}

We consider now the chamber $x_1+x_i>1$, $i=2,3,4$ and the point $Q= (\frac{2}{3}, \frac{4}{9}, \frac{4}{9}, \frac{4}{9})$ from this chamber. Then,   $M_{Q}^{7}\subset \C P^5$ is given by the following system:
\[
3(|z_0|^2 + |z_1|^2 + |z_2|^2) = 2Z, \;\;\; 9(|z_0|^2 + |z_3|^2 + |z_4|^2) =4Z,
\]
\[
9(|z_1|^2 + |z_3|^2 + |z_5|^2) =4Z, \;\; 9(|z_2|^2 + |z_4|^2 + |z_5|^2) =4Z,
\]
 for   $Z= \sum\limits _{i=0}^{5}|z_i|^2$ . This implies that 
\[
|z_0|^2 + |z_4|^2 = |z_1|^2 + |z_5|^2, \;\; 	|z_0|^2 + |z_3|^2 = |z_2|^2 + |z_5|^2,\;\; |z_1|^2 + |z_3|^2 = |z_2|^2 + |z_4|^2,
\]
that is 
\begin{equation}\label{z4second}
|z_4|^2 =|z_1|^2 -|z_2|^2 + |z_3|^2
\end{equation}
 and
\begin{equation}\label{z5second}
|z_5|^2 = |z_0|^2-|z_2|^2 +|z_3|^2.
\end{equation}
Together with the first equation we obtain
\[
|z_2|^2 = \frac{1}{5}(|z_0|^2 +|z_1|^2 +6|z_3|^2).
\]
This gives that
\[
|z_0|^2 =\frac{1}{3}(|z_3|^2 + |z_4|^2 +4 |z_5|^2), \; |z_1|^2= \frac{1}{3}(|z_3|^2+4|z_4|^2+|z_5|^2),
\]
which implies 
\[
|z_2|^2 = \frac{1}{3}(4|z_3|^2 + |z_4|^2 +|z_5|^2).
\]
Comparing with~\eqref{z3},~\eqref{z4z5} we see that $M_{Q}^7$ can be obtained from the case previously considered  by the permutation $z_0\to z_3, z_1\to z_4, z_2\to z_5$.   Therefore, all previously said holds for the points of the chambers from this orbit.

Altogether we proved:

\begin{thm}\label{mainCP5}
The manifold $M_{Q}^{7}$ is homeomorphic to $S^5\times T^2$ for any regular value $Q\in \Delta _{4,2}$ of the standard moment map $\tilde{\mu} : \C P^{5}\to \Delta _{4,2}$.
\end{thm}


\section{The canonical $T^4$-action on $G_{4,2} =G_{4,2}(\C)$}

For the  Grassmann manifold $G_{4,2}$ the image of the  Pl\"ucker embedding   $p : G_{4,2}\to \C P^5$ is   the hypersurface $z_0z_5 +z_2z_3= z_1z_4$.  The torus $T^4$ acts canonically on $G_{4,2}$, where $S^1=\text{diag}( T^4)$ fixes any point, so the torus $T^{3} = T^4/S^1$ acts effectivelly.
The moment map $\mu : G_{4,2}\to \Delta _{4,2}$ is given by
\[
\mu (L)  = \frac{1}{\sum\limits_{1\leq i<j\leq 4} |P^{I}(L)|^2}\sum\limits_{1\leq i<j\leq 4}|P^{ij}(L)|^2\Lambda _{ij}.
\]

Then  $M^{5}_{\bf x} = \mu ^{-1}({\bf x})$ is a smooth manifold for any ${\bf x}\in \stackrel{\circ}{\Delta} _{4,2}$ which belongs to a chamber of maximal dimension $3$. It holds $M_{\bf x}^{5} = M_{\bf x}^{7}\cap \{z_0z_5 +z_2z_3= z_1z_4\}$. Therefore, from Theorem~\ref{mainCP5} it follows:

\begin{cor}
 The manifolds   $M^{5}_{\bf x}$ and $M^{5}_{\bf y}$ are diffeomorphic for all ${\bf x}, {\bf y}$ which belong to  the chambers of maximal dimension.
\end{cor}

We determine homeomorphic type of $M_{\bf x}^{5}$. It is enough to consider the point 
$Q = (\frac{1}{3}, \frac{5}{9}, \frac{5}{9}, \frac{5}{9})$ and denote by $M_{Q}^{5}$ the preimage of $Q$ by the moment map $\mu$. 



Since $\mu  = A\circ \tilde{\mu}$ we describe the projection $P^{'} = \tilde{\mu}(M_{Q}^{5})$.

\begin{lem}\label{P'}
The image $P^{'} \subset P\subset \Delta ^{5}$ is  a curve
\begin{equation}\label{curve}
\sqrt{x_0(x_0+\frac{1}{9})} + \sqrt{(\frac{1}{3} - x_0 -x_1)(\frac{4}{9} - x_0 - x_1)} = \sqrt{x_{1}(x_1 +\frac{1}{9})},
\end{equation}
whose intersection points  $X_i$ with the edges  $I_i$ of the triangle $P$ are:\\
$X_0 = (0, 1/6, 1/6, 5/18, 5/18, 1/9)$, $ X_1 = (1/6, 0,  1/6, 5/18,  1/9, 5/18),$ \\ $X_2 = (1/6, 1/6, 0, 1/9, 5/18 , 5/18)$.
\end{lem}

\begin{proof}  Since $\tilde{\mu}(z_0: z_1:z_3:z_4:z_5) = \tilde{\mu}(|z_0|: |z_1|: |z_2|:|z_3|: |z_4|: |z_5|)$ it follows that $P^{'}$ is given by those points 
$x_i=\frac{|z_i|^{2}}{\|\bf{z}\|^{2}}$ for which $|z_0||z_5| + |z_3|z_4|=|z_1||z_5|$ which together with  Lemma~\ref{triangle} give~\eqref{curve}.  The intersection of $P^{'}$ with $I_{0}$ is given by those points from $I_0$ for which $x_2x_3=x_1x_4$. By Corollary~\ref{edges} this is the same as  $(\frac{1}{3}-x_1)(\frac{4}{9}-x_1) = x_1(\frac{1}{9}+x_1)$,  which implies $x_1=\frac{1}{6}$ and we get the point $X_0$, and similarly  for the others.
\end{proof}

The preimages $M_{Q, i}^{3} = \tilde{\mu}^{-1}(X_i)$, $i=0,1,2$, in $G_{4,2}$ are then torus $T^3$, where $X_i$ are given by Lemma~\ref{P'}.

\begin{lem}
The $M_{Q, i}$ are
\[
M_{Q, 0} = T^{3}\cdot  (0: \frac{1}{\sqrt{6}}: \frac{1}{\sqrt{6}} : \sqrt{\frac{5}{18}}: \sqrt{\frac{5}{18}}: \frac{1}{3}), \;\; T^{3} = (1, \tau _1, \tau_2, \frac{1}{\tau _2}, \frac{1}{\tau _1}, \tau _3),\]
\[M_{Q, 1} = T^{3}\cdot   ( \frac{1}{\sqrt{6}}: 0: \frac{1}{\sqrt{6}} : \sqrt{\frac{5}{18}}: \frac{1}{3}: \sqrt{\frac{5}{18}}), \;\; T^{3} = (\tau _1, 1, \tau_2, \frac{1}{\tau _2}, \tau _3, \frac{1}{\tau _1}),\]
\[
M_{Q, 2} = T^{3}\cdot  (\frac{1}{\sqrt{6}}: \frac{1}{\sqrt{6}} :  0:  \frac{1}{3}: \sqrt{\frac{5}{18}}: \sqrt{\frac{5}{18}}), \;\; T^{3} = (\tau _1, \tau_2, 1, \tau _3, \frac{1}{\tau _2}, \frac{1}{\tau _1}).\]

\end{lem}

 As we already said, the torus $T^3=T^4/S^1$ acts freely on $M_{Q}^{5}$, where $S^1$ is the diagonal in $T^4$ and  the action of $T^4$ is given by the composition of the  second symmetric power representation $T^4\to T^6$ and the standard $T^6$-action.

We first emphasize the following:

\begin{prop}\label{MQ54}
There is no representation $T^3\to T^6$ which composed with the canonical $T^6$-action  realizes  free $T^3=T^4/S^1$ -action on $M_{Q}^{5}$.
\end{prop} 

\begin{proof}
Let $T^3$ acts on $M_{Q}^{5}\subset G_{4,2}\subset \C P^5$ by a representation $\rho : T^3\to T^6$ given by $\rho = (\rho _0, \ldots , \rho _5)$. Then it holds $\rho _0\rho _5 = \rho _1\rho _4=\rho _2\rho _3$. Namely,  notice that   for $(z_0: \ldots :z_5) \in M_{Q}^{5}$  we have  $z_0z_5+z_2z_3=z_1z_4$, then $z_3, z_4, z_5\neq 0$ and $|z_i|^2+|z_j|^2\neq 0$ for $1\leq i<j\leq 2$.    Therefore, the equality $\rho _0\rho _5z_0z_5 + \rho _2\rho _3z_2z_3 = \rho _1\rho _4z_1z_4$ implies for $z_0=0$ that 
\begin{equation}\label{rhos}
\rho _2\rho _3=\rho _1\rho _4,  
\end{equation}
 since $z_i\neq 0$ for $i\neq 0$.

Let  $\rho _{k} = e^{i\langle  \Lambda _k, {\bf x}\rangle}$, $0\leq k\leq 5$, ${\bf x}\in \R^3$,   Then~\eqref{rhos} gives $\Lambda _5 = \Lambda _2 + \Lambda _3 -\Lambda _0$ and $\Lambda _4 =\Lambda _2+\Lambda _3 - \Lambda _1$. Without loss of generality we can take that  $\Lambda _0$, $\Lambda _1, \Lambda _2$ are linearly independent.   Let $\Lambda _3 = a\Lambda _0 + b\lambda _1 + c\Lambda _2$ for $a, b, c\in \Z$.  Then in this basis the representation $\rho$ writes as 
\[
\rho (t_1, t_2, t_3) = (t_1, t_2, t_3, t_{1}^{a}t_{2}^{b}t_{3}^{c}, t_{1}^{a-1}t_{2}^{b}t_{3}^{c+1}, t_{1}^{a}t_{2}^{b-1}t_{3}^{c+1}).
\] 

For a point $(z_0:\ldots :z_5)\in M_{Q}^{4}$ such that $z_0, z_1, z_2\neq 0$,  the assumption that $T^4$-action and the action given by $\rho$ coincide, implies that 
$\tau _1\tau _2 = \lambda t_1$, $\tau _1\tau_3 =\lambda t_2, \tau _1\tau _4=\lambda t_3$, $\tau _2\tau _3 = \lambda t_{1}^{a}t_{2}^{b}t_{3}^{c}$, $\tau _{2}\tau _{4} = \lambda t_{1}^{a-1}t_{2}^{b}t_{3}^{c+1}$ and $\tau _3\tau _4 = \lambda t_{1}^{a}t_{2}^{b-1}t_{3}^{c+1}$  for $\lambda \in S^1$ and for all $(\tau _1, \tau _2, \tau _3, \tau _4)\in T^4$ and $(t_1, t_2,t_3)\in T^3$. 
 But, we obtain  
\[
\tau _1 = t_{1}^{-a}t_{2}^{1-b}t_{3}^{-c} \tau _2 = t_{1}^{1-a}t_{2}^{-b}t_{3}^{-c}\tau _2,
\]
which gives $t_1=t_2$ 

\end{proof}

This also gives, compare to  Theorem~\ref{MQ4} and Remark~\ref{T4MQ7}:

\begin{cor}
The  free $T^3=T^{4}/\text{diag}(T^4)$- action on $M_{Q}^{7}$ can not be realized by the composition of the representation $T^3\to T^6$ and the canonical $T^6$-action on $M_{Q}^{7}$.
\end{cor}

\begin{rem}\label{T3free}
Note that there are representations $T^3\to T^6$ which composed with the canonical $T^6$-  action produce free $T^3$-action on $M_{Q}^{5}$. Such representation would be $(t_1, t_2, t_3, 1, \frac{t_{3}}{t_2}, \frac{t_{3}}{t_1})$.
\end{rem} 
