\end{thm}




\section{The structure of   the principal fiber bundle $M_{Q}^{5}\to \C P^{1}$}

The torus $T^3 = T^{4}/\text{diag}(T^4)$ acts freely on $M_{Q}^{5}$ and it induces principal fiber bundle $M^{5}_{Q} \stackrel{\pi}{\to} M_{Q}^{5}/T^3$  with a fiber $T^3$. In~\cite{BT1}, it is proved that $G_{4,2}/T^3\cong S^3\ast \C P^1\cong S^5$ and, in particular, that  $\mu ^{-1}({\bf x})/T^3 \cong \C P^1$ for any ${\bf x}\in \stackrel{\circ}{\Delta} _{4,2}$. 


 %The point $Q$ belongs to the chamber in $\Delta _{4,2}$ defined by $x_1+x_i<1$, $i=2,3, 4$.

 The Pl\"ucker charts on $G_{4,2}$ are given by $M_{ij} =\{ L\in G_{4,2} | P^{ij}(L)\neq 0\}$, $1\leq i <j\leq 4$. It follows that
\[
M_{Q}^{5}\not\subset M_{1i}  , \; i=2,3,4\\;\; M_{Q}^{5}\subset M_{ij}, \; 2\leq i<j\leq 4.
\]
In particular, we deduce in another way:
\begin{cor}
$M_{Q}^{5}$ is  a smooth  affine manifold.
\end{cor}
The strata in $G_{4,2}$  with the free $T^3$ -action are the main stratum $W_4$ and  $W_{ij} = \{L\in G_{4,2} | P^{ij}(L) = 0\}$, $1\leq i<j\leq 4$. It follows that 
\[
M_{Q}^{5} \cap  W \neq \emptyset, \;  W= W_4,  W_{12}, W_{13}, W_{14}, \;\; M_{Q}^{5}\cap W_{ij} =\emptyset, \;  2\leq i<j\leq 4.
\]


Let $A =\{(0:1), (1:0), (1:1)\}$ and $\C P^{1}_{A} = \C P^{1}\setminus A$. For any $(c:c^{'})\in \C P^{1}_{A}$ the set $\pi^{-1}((c:c^{'}))$ belongs, according to~\cite{BT1},  to the main stratum $W_4$, that is
\[
\pi ^{-1}(\C P^{1}_{A})\cong T^{3}\times \C P^{1}_{A}.
\]
Let $B_{0} = (0:1), B_1=(1:1)$, $B_{\infty} =(1:0)$ and $\C P ^{1}_{B_i} = \C P^{1}\setminus \{B_i\}$, $i=0,1,\infty$.

\begin{prop}\label{bezstrata}
 The following holds
\[ 
M_{Q}^{5}\setminus( M_{Q}^{5}\cap W_{12})  \cong T^3\times \C P^{1}_{B_{\infty}},\]
\[ M_{Q}^{5}\setminus( M_{Q}^{5}\cap W_{13})  \cong T^3\times \C P^{1}_{B_{0}}, \] 
\[M_{Q}^{5}\setminus( M_{Q}^{5}\cap W_{14})  \cong T^3\times \C P^{1}_{B_{1}}, 
\]
\end{prop}
\begin{proof}
Consider the chart  $M_{23}$ on $G_{4,2}$ with the local coordinates $a_1, a_2, a_3, a_4$. Then any $L\in G_{4,2}$  represents in $M_{23}$   by
\[
A_{L} =\left (
\begin{array}{cc}
a_1 & a_3\\
1 & 0\\
0 & 1\\
a_2 & a_4
\end{array}\right ).
\]
For the points from $M_{Q}^{5}$ we have that $|a_i|^2+|a_{j}|^{2}\neq 0$, $1\leq i<j\leq 4$ and $a_2, a_4\neq 0$. In addition, 
\begin{equation}\label{jednacine}
1= \frac{1}{3} (|a_3|^2 + |a_1|^2 +4 |a_1a_4-a_2a_3|^2), \; |a_4|^2 = \frac{1}{3} (|a_3|^2 + 4 |a_1|^2 + |a_1a_4-a_2a_3|^2),
\end{equation}
\[
|a_2|^2 = \frac{1}{3} (4|a_3|^2 + |a_1|^2 + |a_1a_4-a_2a_3|^2)
\]
The  points of the space $M_{Q}^{5}\setminus( M_{Q}^{5}\cap W_{12})$  satisfy additional condition $a_3\neq 0$.
 Consider the map $f : M_{Q}^{5}\setminus( M_{Q}^{5}\cap W_{14}) \to \C P^{1}_{B_{1}}\times T^3$ defined 
\[
f(a_1, a_2, a_3, a_4) = ((a_1a_4:a_2a_3), (t_2, t_3, t_4)), 
\]
where $a_k = |a_k|t_k$, $k=1,2,3,4$. The map $f$ is homeomorphism since $f(a_1, a_2, a_3, a_4)= f(a_{1}^{'}, a_{2}^{'}, a_{3}^{'}, a_{4}^{'})$ implies
$t_i^{'} = t_i$ for $i=2,3, 4$ and $a_{1}^{'}a_{4}^{'} = c a_1a_4$,  $a_{2}^{'}a_{3}^{'} = c a_2a_3$ for $c = |c|\lambda \in \C$, $c\neq 0, \lambda \in S^1$.  It   implies
$t_{2}^{'}t_{3}^{'} = \lambda t_{2}t_{3}$,  that is $\lambda =1$. Since  $a_1\neq 0$ iff $a_{1}^{'}\neq 0$, we have that  $t_{1}^{'} = t_1$ for $a_1\neq 0$.  Now,  from~\eqref{jednacine} we deduce that $a_i=a_{i}^{'}$, $i=1,2,3,4$. 
\end{proof}

Consider now the standard charts on $\C P^{1}$ given by $M_{0} = \{(1:c) | c\in \C\}$ and $M_{1} = \{(c:1) | c\in \C \}$ and the projection $\pi : M_{Q}^{5}\to \C P^{1}$.


\begin{lem}\label{CP1}
It holds 
\begin{equation}
\pi ^{-1}(M_0) = M_{Q}^{5}\setminus( M_{Q}^{5}\cap W_{13}), \;\;  \pi ^{-1}(M_1) =M_{Q}^{5}\setminus( M_{Q}^{5}\cap W_{12}) .
\end{equation}
\end{lem}

\begin{proof}
It follows immediately from  the proof of Proposition~\ref{bezstrata}
\end{proof}


\begin{thm}
The structure of the principal fiber bundle can be described by two  charts $M_{0}$, $M_{1}$  for  $\C P^{1}$   with  the transition function 
$h_{01} : \pi ^{-1}(M_0 \cap M_1) \to \pi ^{-1}(M_0\cap M_1)$ given by
\[
h_{01}((c:c^{'}), (t_{1}^{0}, t_{2}^{0}, t_{3}^{0})) = ((c:c^{'}), (t_{1}^{1}, t_{2}^{1}, t_{3}^{1})), 
\]
where 
\begin{equation}\label{transition}
t_{1}^{1}= \frac{t_{1}^{0}t_{2}^{0}}{t_{3}^{0}},\; t_{2}^{1} =t_{1}^{0}, \; t_{3}^{1} = t_{3}^{0}.
\end{equation}
\end{thm}

 \begin{proof}
Since  $\pi ^{-1}(M_0 \cap M_1) = M_{Q}^{5}\setminus ( M_{Q}^{5}\cap W_{13} \cup  M_{Q}^{5}\cap W_{12})$ it follows from Proposition~\ref{bezstrata} that $\pi ^{-1}(M_0\cap M_1)$ is  homeomorphic to  $\C P^1\setminus \{B_{0}, B_{\infty}\} \times T^3$. The canonical action of  $T^4$ on $G_{4,2}$ gives the action of $T^3$ on the coordinates  of the chart $M_{23}\cong \C ^4$ defined by the coordinate wise action of  $(\frac{t_1}{t_{2}}, \frac{t_4}{t_2}, \frac{t_1}{t_3}, \frac{t_4}{t_{3}})$. 
In the chart $\pi ^{-1}(M_0)$ we have that $a_3\neq 0$ so the torus $T_{0}^{3} = ( \frac{t_4}{t_2}, \frac{t_1}{t_3}, \frac{t_4}{t_{3}} )$ acts freely on $\pi ^{-1}(M_0)$  and 
$\pi ^{-1}(M_0) \cong \C P^{1}_{B_1}\times T^{3}_{0}$. In the chart $\pi ^{-1}(M_1)$ we have that $a_1\neq 0$ and the torus $T^{3}_{1} = ( \frac{t_1}{t_2}, \frac{t_4}{t_2}, \frac{t_4}{t_{3}} )$ acts freely on $\pi ^{-1}(M_1)$  and  $\pi ^{-1}(M_1) \cong \C P^{1}_{B_{\infty}}\times T^{3}_{1}$. Thus,  the transition map is given by~\eqref{transition}.
\end{proof}





\section{Relations between $M^2$, $M^3$ and $\C P^1$ towards $M_{Q}^5$}

We determine the relations among the spaces $M^2$, $M^3$ and $\C P^1$ which lead to the more    explicit description of $M_{Q}^{5}$.

\subsection{$M^2$ towards  $\C P^1$ and $M_{Q}^{5}$}

Recall that the space $M^{2}$ belongs to the  intersection   of $M_{Q}^{5}$ and $S^{5}$  in $M_{Q}^{7}$ and  it is given  by the points $(z_0 : z_1 : |z_2| : |z_3| : |z_4| : |z_5|)\in \C P^5$ such that
\[
z_0|z_5| + |z_2||z_3| = z_1|z_4|,
\]
where $|z_k|$ is given by~\eqref{2345}  for $k=2,3,4,5$. 



Since $M_{Q}^{5}\subset M_{23}$ it follows that $M^{2}\subset M_{23}$ and its coordinates in this chart are:
\[
a_1=\frac{P^{13}}{P^{23}}, \; a_2 = -\frac{P^{34}}{P^{23}}, \; a_3=-\frac{P^{12}}{P^{23}}, \; a_4 = \frac{P^{24}}{P^{23}}.
\]
We  obtain  that
\[
a_1 =\frac{z_1}{|z_3|}, \; a_2 = -\frac{|z_5|}{|z_3|}, \; a_3 = -\frac{z_0}{|z_3|},\; a_4 = \frac{|z_4|}{|z_3|}.
\]
The quotient $M_{Q}^{5}/T^4$ for the canonical action of $T^4$ on $G_{4,2}$ is $\C P^1$ and, according to~\cite{BT1},  it can be described  by the projection $M_{Q}^{5}\to \C P^1$ defined  by $(a_1,a_2, a_3, a_4)\to (a_1a_4 : a_2a_3)$. In this way we obtain the projection $p : M^{2} \to \C P^1$  defined by
\begin{equation}\label{M2CP1}
p(z_0:z_1: |z_2|: |z_3|: |z_4|: |z_5|) = (z_1|z_4| : z_0|z_5|).
\end{equation}

Recall that the circle $S^1\subset M^2$ defined by $z_0=z_1$ is given by $(\frac{e^{i\psi _{0}}}{\sqrt{6}}, \frac{e^{i\psi _{0}}}{\sqrt{6}},  0 , \frac{1}{3}, \frac{\sqrt{5}}{\sqrt{18}} , \frac{\sqrt{5}}{\sqrt{18}})$.
\begin{thm}\label{M2ramified}
The projection $p : M^{2}\setminus S^{1}\to \C P^1\setminus\{(1:1)\}$ is a  homeomorphism.
\end{thm}
\begin{proof}
The condition $p({\bf z}) = p({\bf z^{'}})$ implies that $z_0|z_5| = re^{i\psi} z_{0}^{'}|z_{5}^{'}|$ and $z_1|z_4| = re^{i\psi}z_{1}^{'}|z_{4}^{'}|$. 
It gives  $\phi _k = \phi _{k}^{'} + \psi$ for  $k = 0, 1$, where $z_k= |z_k|e^{i\phi _k}$ and  $z_k^{'}= |z_k^{'}|e^{i\phi _k^{'}}$. In addition,  the points ${\bf z}$ and ${\bf z^{'}}$ belong to the same $T^{4}$-orbit in $M_{Q}^{5}$ which gives that $|z_k|=|z_{k}^{'}|$, $k=0,1,2,3,4,5$.

Assume that $z_0\neq  z_1$, $z_0, z_1\neq 0$.  Since 
\[
z_0|z_5| + |z_2||z_3|  = z_1|z_4|\]
\[
 re^{i\psi}z_{0}^{'}|z_{5}^{'}| + re^{i\psi}|z_{2}^{'}||z_{3}^{'}|  = re^{i\psi}z_{1}^{'}|z_{4}^{'}|,
\]
we obtain that 
\[
 re^{i\psi}|z_{2}^{'}||z_{3}^{'}|  - |z_{2}||z_{3}| = 0.
\]
Thus,
\[
re^{i\psi}  =1.
\]
%It follows 
%\[
%\psi = 1, \frac{2\pi}{3}, \frac{4\pi}{3}.
%\]
%For $z_0=0$  we have $z_{0}^{'}=0$ and $z_1|z_4| = re^{i\psi}z_{1}^{'}|z_{4}^{'}|$. It follows that $\phi _{1} = \phi _{1}^{'}+\psi$ . The equations
%\[
 %|z_2||z_3| e^{-i(\phi _{1}^{'}+\psi  )} = z_1|z_4|, \;\;\;\;  re^{i\psi}|z_{2}^{'}||z_{3}^{'}| e^{-i\phi _{1}^{'}} = re^{i\psi}z_{1}^{'}|z_{4}^{'}|
%\]
%gives that
%\[
%re^{i\psi} -  e^{-i\psi} =0\; \rightarrow \; e^{2i\psi} = 1, \;\; r=1.
%\]


\end{proof}

In addition we have
\begin{lem}\label{circle}
The preimage $p^{-1}(1:1)$ of the projection $p: M^{2}\to \C P^1$ is the circle $S^1$.
\end{lem}
\begin{proof}
If $p({\bf z}) = (1:1)$ then $z_0|z_5| = z_1|z_4|$.  Thus,
\[
|z_0|^2|z_5|^2 = |z_1|^2|z_4|^2 \; \rightarrow \; \frac{1}{9}(|z_0|^2 -|z_1|^2) + |z_0|^4 - |z_1|^4 =0.
\]
It implies
\[
(|z_0|^2 -|z_1|^2)(\frac{1}{9} + |z_0|^2 + |z_1|^2) =0 \; \rightarrow \; |z_0|=|z_1|.
\]
Since $z_0|z_5| +|z_2||z_3|= z_1|z_4|$, we have that $|z_2|=0$, which is equivalent to $|z_0|^2 + |z_1|^2 =\frac{1}{3}$. It follows
\[
|z_0| = |z_1|=\frac{1}{\sqrt{6}}, \; |z_3| = \frac{1}{\sqrt{3}},\;  |z_4| = |z_5| =\frac{\sqrt{5}}{\sqrt{18}}.
\]
Therefore, $\phi _{0} =\phi _{1}=\psi$  and 
\[
p^{-1}(1:1) = (\frac{1}{\sqrt{6}}e^{i\psi}:\frac{1}{\sqrt{6}}e^{i\psi} : 0 : \frac{1}{\sqrt{3}} : \frac{\sqrt{5}}{\sqrt{18}} : \frac{\sqrt{5}}{\sqrt{18}}).
\]
\end{proof}

\begin{cor} \label{cor1}
The sphere $\C P^1$ is homeomorphic to the quotient space $\tilde{M}^{2}$  of $M^{2}$ by  the equivalence relations defined by the projection $p$, that is
$(z_0^{'}, z_{1}^{'})\approx (z_0, z_1)$ if and only if 
\begin{itemize}
\item $z_k = z_{k}^{'}$, $k=0,1$  for  $z_0\neq z_1$ 
\item  $z_0=z_1$ and $z_{0}^{'} = z_{1}^{'}$.
\end{itemize}
