\end{cor}


\begin{cor}\label{disc}
The space $M^{2} = \overline{M^{2}\setminus S^1}$ is homeomorphic to the closed disc $D^2$.
\end{cor}
From Corollary~\ref{equiv5}  and Lemma~\ref{equiv23} we deduce:

\begin{cor}\label{cor2}
The orbit space $\tilde{M}^{5}_{Q}/T^3$ by the action induced from the $T^3$-action on $M^{2}\times T^3$ is homeomorphic to $\C P ^1$.
\end{cor}


Let  $M_{2} = D^{2}\setminus S^1$, where $ S^1  = \{(\frac{e^{i\phi _0}}{\sqrt{6}}, \frac{e^{i\phi _0}}{\sqrt{6}})\in M^{2}\}$.   Lemma ~\ref{equiv23} gives:

\begin{cor}\label{tildeMproduct1}
\begin{itemize}
\item
The space $(M_{2}\times T^3) /\approx$ is homeomorphic to $M_{2}\times T^{3}$.
\item 
The space $(S^1\times T^3)/\approx$ is homeomorphic to $T^4/S^1$, where $S^1$ acts on $T^4$ by 
$\lambda \cdot  (t_{0}, t_{1}, t_{2}, t_3) = (\frac{1}{\lambda}t_0, \lambda t_1, \lambda t_2, \lambda t_3)$.
\end{itemize}
\end{cor}



Altogether, we proved:


\begin{thm}
The manifold $M_{Q}^{5}$ is homeomorphic to the quotient space 
\[
(D^2\times T^3)/\approx ,\;\;  \text{where}\;\;
  ({\bf z}, {\bf t})\approx ({\bf z}^{'}, {\bf t}^{'})\;\;  \text{iff}\;\; \]

\begin{enumerate}
 \item ${\bf z}={\bf z}^{'}\not\in S^1\; \text{and} \; {\bf t}^{'} =  {\bf t}$
\item ${\bf z}, {\bf z}^{'} \in S^1$  and  there exists $\lambda \in S^1$ such that  $ ({\bf {z}}^{'}, {\bf t}^{'}) = \rho _{14} (\lambda)\cdot ({\bf z}, {\bf t})$ for the representation $\rho _{14} : S^1\to T^4$ given by $\rho (\lambda) = ( \frac{1}{\lambda}, \lambda , \lambda, \lambda)$.
\end{enumerate} 
\end{thm} 

In addition we derive:

\begin{cor}
The space $M_{Q}^{5}$ is not homeomorphic to $\C P^1 \times T^3$.
\end{cor}
\begin{proof}
By  Corollary~\ref{tildeMproduct1} the homeomorphism between  $((M^2\setminus S^1)\times T^3)/\approx$  and  $(M^2\setminus S^1)\times T^3$ does not extend to the homeomorphism between $\tilde{M}_{Q}^{5}$ and $\tilde{M}^{2}\times T^3$.
\end{proof}  





\subsection{$M^3$ towards  $\C P^1$ and $M_{Q}^{5}$}
Recall that $M^{3}$ from Lemma~\ref{intersection} is a subspace in $\C P^{5}$ consisting of the points $(z_0 : z_1 : z_2 : |z_3| : |z_4| : |z_5|)$, where $z_k = |z_k|e^{i\psi _k}$, $k=0,1,2$, then  $|z_k|$ are given by formulas~\eqref{2345} for $k=2,3,4,5$ , and  $z_0, z_1, z_2$ satisfy equation~\eqref{surface}.   
 The conditions $z_i=0$, $i=0,1,2$ give the three circles:
\[
S^{1}_{0} = (0: \frac{e^{i\psi }}{\sqrt{6}}:  \frac{e^{i\psi }}{\sqrt{6}}: \frac{\sqrt{5}}{\sqrt{18}}:  \frac{\sqrt{5}}{\sqrt{18}}: \frac{1}{3}), \; 
S^{1}_{1}= (\frac{e^{i\psi }}{\sqrt{6}} : 0 :   \frac{e^{i\psi }}{\sqrt{6}}:  \frac{\sqrt{5}}{\sqrt{18}}: \frac{1}{3}: \frac{\sqrt{5}}{\sqrt{18}}), 
\]
\[
S^{1}_{2} = (\frac{e^{i\psi }}{\sqrt{6}}:  \frac{e^{i\psi }}{\sqrt{6}}: 0: \frac{1}{3}: \frac{\sqrt{5}}{\sqrt{18}}:  \frac{\sqrt{5}}{\sqrt{18}}).
\]

The circle $S^1$ acts freely  on $M^3$ by the representation $S^1\to T^6$ given by $t\to (t,t, t, 1, 1,1)$ that is by
\begin{equation}\label{S1action}
t\cdot (z_0:z_1:z_2: |z_3|:|z_4|: |z_5|) = (tz_0 : tz_1 : tz_2 : |z_3| : |z_4|: |z_5|).
\end{equation}


\begin{prop}\label{M3S1}
The orbit space of $M^3$ by the free $S^1$-action  is $\C P^1$. 
\end{prop}

\begin{proof}
Let us consider the map $p : M^3 \to \C P^1$ given by $p(z_0:z_1:z_2:|z_3|:|z_4|:|z_5|) = (z_1|z_4|: z_0|z_5|) $. It is continuous surjection and $p^{-1}(z_1|z_4| : z_0|z_5|) = \{(z_{0}^{'}:z_{1}^{'}:z_{2}^{'}:|z_{3}^{'}|:|z_{4}^{'}|:|z_{5}^{'}|)\}$ such that $z_{0}^{'}|z_{5}^{'}| = \lambda z_0|z_5|$ and $z_{1}^{'}|z_{4}^{'}|=\lambda z_1|z_4|$ for $\lambda \in S^1$. It implies  that $\frac{1}{9}(|z_i|^{2}-|z_{i}^{'}|^2) + (|z_i|^4-|z_{i}^{'}|^4)=0$ for $i=0,1$, which gives $|z_i|=|z_{i}^{'}|$ for $i=0,1$. Therefore, $|z_i|=|z_{i}^{'}|$, $i=2,3,4,5$ as well, and $z_{i}^{'} =\lambda z_i$ for $i=0,1$.  Since $(z_0, z_1, z_2), (z_{0}^{'}, z_{1}^{'}, z_{2}^{'})$  satisfy~\eqref{surface},  it follows $z_{2}^{'} = \lambda  z_{2}$.  Therefore, $p$ induces homeomorphism $M^3/S^1 \to \C P^1$. 
\end{proof}

We push up this further.  
\begin{prop}\label{M3S5}
The inclusion   $M^{3}\subset S^5$ induces the embedding $\C P^1\to \C P^2$ of their  orbit spaces by the  free $S^1$-action, which is given by
% into  the sphere $S^{5}$ by
%\[
%(z_0, z_1, z_2) \stackrel{\varphi}{\to} \frac{1}{A}(z_1a(z_1), z_0a(z_0), z_2a(z_2)),
%\]
%where $A =\sqrt{|z_0|^2a(z_0)^2 +|z_1|^2a(z_1)^2 + |z_2|^2a(z_2)^2}$.
%The orbit space $M^{3}/S^1 \cong \C P^1$ can embedded in the orbit space $S^5/S^1\cong \C P^{2}$ by
\[
(c : c^{'})\stackrel{\varphi}{\to} (c :c^{'}: c-c^{'}).
\]
\end{prop}
\begin{proof}
The projection $q : S^5\subset \C P^5\to \C P^2$ of the Hopf fibration $S^5 \stackrel{S^1}{\to}\C P^2$  is   given by
\[
q(z_0:z_1:z_2: |z_3|: |z_4| : |z_5|) = (z_1|z_4|: z_0|z_5|: z_2|z_3|).
\]
Namely,  $q^{-1} (z_1|z_4|: z_0|z_5|: z_2|z_3|) =\{(z_{0}^{'}:z_{1}^{'}:z_{2}^{'}:|z_{3}^{'}|:|z_{4}^{'}|:|z_{5}^{'}|)\}$ such that  $z_{0}^{'}|z_{5}^{'}|= \lambda z_0|z_5|$,  $z_{1}^{'}|z_{4}^{'}|=\lambda z_1|z_4|$ and  $z_{2}^{'}|z_{3}^{'}| = \lambda z_2|z_3|$ for $\lambda \in S^1$.  In an analogous way as in the previous proof we deduce that $z_{i}^{'}=\lambda z_i$, $i=0,1,2$. 

Let $i : M^3\to S^5\subset \C P^5$ be the inclusion. We obtain a commutative diagram
\[ \begin{tikzcd}
M^3 \arrow{r}{i} \arrow[swap]{d}{p} & S^5 \arrow{d}{q} \\%
\C P^1 \arrow{r}{\varphi}& \C P^2
\end{tikzcd}
\]
where the embedding $\varphi : \C P^1\to \C P^2$ is given as stated, because   $z_0|z_5|+z_2|z_3|=z_1|z_4|$.
\end{proof}



Since the  inclusion  $S^3\subset S^5$  induces the embedding $\C P^1\to \C P^2$ of their orbit spaces by the free $S^1$-action, which is given by
$(c:c^{'})\to (c: c^{'}:0)$,  we deduce:

\begin{thm}
The space $M^3$ is homeomorphic to $S^3$.
\end{thm}
\begin{proof}
For the  space $M^3\subset S^5$ we consider   the map $ g: M^3\to S^3$ defined  by 
\[
g(z_0, z_1, z_2) = (\frac{z_1a(z_1)}{|z_0|^2a(z_0)^2 +|z_1|^2a(z_1)^2},  \frac{z_0a(z_0)}{|z_0|^2a(z_0)^2 +|z_1|^2a(z_1)^2}, 0),
\]
where $a(z_i) = \sqrt{\frac{1}{9}+|z_i|^2}$, $i=0,1,2$.
This map is  $S^1$- equivariant and  by  Proposition~\ref{M3S5}  induces commutative diagram 
\[ \begin{tikzcd}
M^3 \arrow{r}{g} \arrow[swap]{d}{p} & S^3 \arrow{d}{q} \\%
\C P^1 \arrow{r}{\tilde{g}}& \C P^1
\end{tikzcd},
\]
where $\tilde{g}(c:c^{'}:c-c^{'}) = (c:c^{'}:0)$ is a homeomorphism. Since the $S^1$-action is free it follows that $g$ is a homeomorphism.

\end{proof}





From Proposition~\ref{M3MQ5}  we see that the representation  $T^2\to T^6$ defined by $(t_1, t_2) \to (t_1, t_2, 1, 1, \frac{1}{t_2}, \frac{1}{t_1})$  produces free $T^2$ action on $M_{Q}^{5}$.  By~\eqref{S1action}  we have defined  free circle action on $M_{Q}^{5}$. Altogether we obtain  $T^3$-action on $M_{Q}^{5}$.  It is straightforward to see:

\begin{lem}
The   $T^3$-action on $M_{Q}^{5}$ given  by the representation $T^3\to T^6$, which is defined by $(t_1, t_2, t_3) \to (t_1t_3, t_2t_3, t_3, 1, \frac{1}{t_2}, \frac{1}{t_1})$ is free.
\end{lem} 

\begin{cor}
The orbit space of $M_{Q}^{5}$ by the given $T^3$- action is homeomorphic to $\C P^1$.
\end{cor}

\begin{proof}
This orbit space is homeomorphic to the orbit  space  $M^{3}\times T^2$  by the diagonal action of $S^1\times T^2$ which is $M^{3}/S^1\cong \C P^1$
\end{proof} 

Altogether we proved:

\begin{thm}
The manifold $M_{Q}^{5}$ is homeomorphic to  $S^3\times T^2$.
\end{thm}


\section{Structure of $M_{Q}^{5}$ as a  complete intersection}

The manifold $M_{Q}^{5}\subset \C ^{4} = \R^{8}$ is an affine manifold  and we denote by  $a_k=u_k+iv_k$, $1\leq k\leq 4$ the coordinates in the chart $M_{2,3}$.

Then  $a_1a_4-a_2a_3 = A + iB$, where $A= u_1u_4-v_1v_4-u_2u_3+v_2v_3$ and $B=u_1v_4+v_1u_4-u_2v_3-u_3v_2$.

