\section{One-loop self-energy in the ancilla theory with quantum bosons}
\label{app:oneloop}
%
In this section, we present a calculation of the electron spectral function up to second order in the electron-spinon-chargon coupling. We consider the Hamiltonian given by Eqs.~\eqref{eq:fermionhop}, \eqref{Top2layers_Hamiltonian}, \eqref{Yukawa} and \eqref{Eq:quadraticB}, where we only focus on the quadratic part of Eq.~\eqref{Eq:quadraticB} and set $U_{\vi\vj}=\mathbbm{1}$.

The second order correction to the mean-field propagator can be represented by the Feynman diagram in Fig.~\ref{fig:Fock_self_energy_diagram}.

\begin{figure}[t]
    \centering
    \includegraphics[width=0.25\linewidth]{Self_energy_diagram.png}
    \caption{Fenyman diagram for the 1-loop self-energy within the ancilla theory. The solid lines represent incoming and outgoing $c$ or $f_1$ electrons, the dashed line the propagator of the fermionic spinon $G$, and the wiggly one the propagator of the bosonic chargon $D$.}
    \label{fig:Fock_self_energy_diagram}
\end{figure}

Evaluating the diagram, we obtain the self-energy (in real space and imaginary time) at finite temperature $T$:
%
\begin{equation}\label{eq: self energy}
    \Sigma_{\vi \vj}(\tau,\tau')=\left(
    \begin{array}{cc}
        \Sigma^{cc} & \Sigma^{cf}  \\
        \Sigma^{fc} & \Sigma^{ff}
    \end{array}\right) = \left(
    \begin{array}{cc}
        g_1^2 & g_1\,g_2  \\
        g_1 \,g_2 & g_2^2
    \end{array}\right)
    %
    \mathrm{Tr}\left[G_{\vi \vj}(\tau,\tau')\,D_{\vj \vi}(\tau',\tau)\right]\,,
\end{equation}
%
where the couplings $g_{1,2}$ have been defined in Eq.~\eqref{Yukawa}.
We have also defined the spinon propagator $G$ as 
%
\begin{equation}
    G_{\vi \vj}(\tau,\tau') = T\!\sum_{n=-\infty}^{+\infty}\,e^{i\omega_n(\tau-\tau')}\,\left[i\omega_n\mathbbm{1}\delta_{\vi \vj}+\frac{J}{\sqrt{2}}\chi_{\vi \vj}\right]^{-1}\,,
\end{equation}
%
and the chargon propagator as
%
\begin{equation}
    D_{\vi \vj}(\tau,\tau') = T\!\sum_{n=-\infty}^{+\infty}\,e^{i\Omega_n(\tau-\tau')}\,\left[ (-\Omega_n^2-r-2\sqrt{2}w)\mathbbm{1}\delta_{\vi \vj}+\frac{w}{\sqrt{2}}\chi_{\vi \vj}\right]^{-1}\,, 
\end{equation}
%
where $\omega_n=(2n+1)\pi T$ and $\Omega_n=2n\pi T$ are the fermionic and bosonic Matsubara frequencies, respectively. Here $\chi_{\vi \vj}$ are the $\pi$-flux hoppings expressed in the so-called $d$-wave gauge (the analogue of $i\, e_{\vi \vj}$ of the main text, which however uses a different gauge)
%
\begin{equation}
    \chi_{\vi \vj}=\begin{cases}
            \tau^3+\tau^1\quad\text{if}\quad \vj=\vi\pm\hat{\boldsymbol{x}}\,,\\
            \tau^3-\tau^1\quad\text{if}\quad \vj=\vi\pm\hat{\boldsymbol{y}}\,,\\
            0\quad\text{otherwise,}
        \end{cases}
\end{equation}
%
with $\tau^a$ the Pauli matrices.
Note that the self-energy in Eq.~\eqref{eq: self energy} is SU(2) gauge invariant. 

Defining $\Sigma^{(0)}(\bk,\omega)$ as the Fourier transform of $\mathrm{Tr}\left[G_{\vi \vj}(\tau,\tau')\,D_{\vj \vi}(\tau',\tau)\right]$ continued to real frequencies, we obtain
%
\begin{subequations}
    \begin{align}
        \Sigma^{(0)}(\mathbf{k}, \omega) = \int_{\mathbf{q}} \sum_{b, f = \pm} \frac{\mathrm{Tr}\left[U_\bq^b\, U^f_{\bk+\bq}\right]}{4 \mathcal{E}_{b, \mathbf{q}}} \Bigg\{
        &\left[ \tanh\left( \frac{E_{f, \mathbf{k} + \mathbf{q}}}{2T} \right) + \coth\left( \frac{\mathcal{E}_{b, \mathbf{q}}}{2T} \right) \right] \frac{1}{ - \omega_+ + \mathcal{E}_{b, \mathbf{q}} + E_{f, \mathbf{k} + \mathbf{q}}} \\
        + &\left[\tanh\left( \frac{E_{f, \mathbf{k} + \mathbf{q}}}{2T} \right) - \coth\left( \frac{\mathcal{E}_{b, \mathbf{q}}}{2T} \right) \right] \frac{1}{\omega_+ + \mathcal{E}_{b, \mathbf{q}} - E_{f, \mathbf{k} + \mathbf{q}}} 
        \Bigg\}\,,
    \end{align}    
\end{subequations}
%
where $\omega_+=\omega+i0^+$ and $E_{\pm,\bk}=\pm 2J\sqrt{\cos^2 k_x+\cos^2 k_y}$, $\mathcal{E}_{\pm,\bq}=\sqrt{r+2\sqrt{2}w\pm 2w\sqrt{\cos^2 q_x+\cos^2 q_y} }$. Note that, as the bosonic excitation energies must be real, we require $r\geq 0$. The coherence matrices are defined as 
%
\begin{subequations}
    \begin{align}
        &U^+_\bk =\left(
        \begin{array}{cc}
            v_\bk^2 & -u_\bk v_\bk  \\
            -u_\bk v_\bk & u_\bk^2
        \end{array}
        \right)\,,\\
        %
        &U^-_\bk =\left(
        \begin{array}{cc}
            u_\bk^2 & u_\bk v_\bk  \\
            u_\bk v_\bk & v_\bk^2
        \end{array}
        \right)\,,\\
        %
        &u_\bk=\sqrt{\frac{1}{2}\left(1+\frac{\cos k_x+\cos k_y}{\sqrt{2}\sqrt{\cos^2 k_x + \cos^2 k_y}}\right)}\,,\\
        %
        &v_\bk=\sqrt{\frac{1}{2}\left(1-\frac{\cos k_x+\cos k_y}{\sqrt{2}\sqrt{\cos^2 k_x + \cos^2 k_y}}\right)}\,.
    \end{align}
\end{subequations}
%
The electron Green's function can be calculated as 
%
\begin{equation}
    \hat{G}(\bk,\omega)=\left[\omega_+\mathbbm{1}-\left(
    \begin{array}{cc}
        \epsilon^c_\bk & \phi \\
        \phi^* & \epsilon^f_\bk
    \end{array}
    \right) - \left(
    \begin{array}{cc}
        g_1^2 & g_1\,g_2  \\
        g_1 \,g_2 & g_2^2
    \end{array}\right)\Sigma^{(0)}(\bk,\omega)
    \right]^{-1}\,,
\end{equation}
%
with $\epsilon^c_\bk$ and $\epsilon^f_\bk$ the Fourier transforms of $t^c_{\vi \vj}$ and $t^f_{\vi \vj}$ in Eq.~\eqref{Top2layers_Hamiltonian}. The electron spectral function reads
%
\begin{equation}
    A(\bk,\omega)=-\frac{1}{\pi}\mathrm{Im}\,\hat{G}_{cc}(\bk,\omega)\,.
\end{equation}
%

\begin{figure}[t]
    \centering
    \includegraphics[width=1.0\linewidth]{Fock_self_energy_ancilla_sp_fun_Phi_0.36.png}
    \caption{Zero frequency cuts of the electron spectral function. Left: mean-field result ($\Sigma^{(0)}(\bk,\omega)=0$). Right: Fock self-energy included. For this calculation we used a broadening of the electron Green's function equal to 0.01. The spectral intensity is plotted normalized by its maximum value $A_0$.}
    \label{fig:Fock_self_energy}
\end{figure}

In Fig.~\ref{fig:Fock_self_energy} we show the compare the mean-field electron spectral function (that is, with $\Sigma^{(0)}(\bk,\omega)=0$) and the one with $\Sigma^{(0)}(\bk,\omega)$ included. The parameters defining $\epsilon^c_\bk$ and $\epsilon^f_\bk$, as well as the value of $\phi$ are the same as in Figs.~\ref{fig:mascot}, \ref{fig:fermionMC}(a-b), \ref{fig:GaussianBosons_r}, and \ref{fig:GaussianBosons_beta}, while the other parameters read $r=0.005$, $w=0.2/(2\sqrt{2})$ (eV) and $J=0.2/\sqrt{2}$, $T=0.1$, $g_1=0$, $g_2=0.15$. We observe that inclusion of the self-energy provides a decay channel for the electrons that is kinematically more efficient near the backsides of the hole pockets, as the spinon low energy excitations lie near those, washing them out. The inner side of the pockets, instead, is barely modified by the self-energy inclusion, making the spectral function appear "arc-like".

