\section{Main Results}\label{sec:main-results}

Here we present our main results for the quantum relay channel $\mathcal{N}_{AD\rightarrow BE}$. We establish achievable rates that are based on different coding strategies, with and without the entanglement assistance.

\begin{figure}[t]
  \centering{\includegraphics[width=0.55\linewidth]{fig_three_party.pdf}}
   \caption{Three-terminal quantum relay schematic. The transmitters at the sender and relay are denoted by $A$ and $D$, respectively, while the receivers at the relay and destination are labeled $E$ and $B$.}
    \label{fig:qrelay-three-party}
\end{figure}

\subsection{Rate-Limited Entanglement Assistance}
In the decode-forward case, the relay decodes the entire information. Consider the three party communication scheme shown in \Fig{fig:qrelay-three-party}. Let $\mathcal{N}_{AD\rightarrow BE}$ be a quantum channel, and let $\ket{\sigma}_{AA_1 D}$ be any pure state with $\omega_{A_1 BE}=\mathcal{N}_{AD\rightarrow BE}(\sigma_{A_1 A D})$.

\begin{proposition}
\label{prop:full-dec-rates}
Assume that Bob has access to entanglement assistance represented by entanglement consumption and generation rates $L_B$ and $\hat{L}_B$, respectively. Then any rate point $(Q, L_B, \hat{L}_B)$ such that:
\begin{equation}
\label{eq:full-achievable-rates}
\begin{split}
    Q \leq H(A_1 | D)_\sigma - L_B + \hat{L}_{B}\\
    Q \leq I(A_1\rangle E)_\omega - L_B - \hat{L}_{B}\\
    Q \leq I(A_1\rangle B)_\omega + L_B - \hat{L}_{B},
\end{split}
\end{equation}
is achievable for transmission with rate-limited entanglement assistance, where $A_1$ is an arbitrary auxiliary system.

The first condition states that the quantum information transmitted by Alice, along with the entanglement consumed from her share of the EPR pairs, must fit within the channel input available to Alice, conditioned on the relay's input to the channel.
Specifically, let $\Delta L_B = L_B - \hat{L}_{B}$ denote the net entanglement consumption. Then, the first condition states that $Q+\Delta L_B\leq H(A_1|D)_\sigma$. 
The third condition says that the channel can transmit $Q-\Delta L_B\leq I(A_1\rangle B)$ qubits per channel use, when taking the cost of entanglement into account, hence subtracting the net entanglement consumption. 
The second condition directly reflects the bottleneck introduced by the relay, where both $L_B$ and $\hat{L}_{B}$ appear with the negative sign. This arises due to the nature of our Block Markov coding scheme, where the entanglement assistance available to Bob in block $j$ is effectively generated by the relay in block $j-1$. See \Sec{sec:encoding-decoding-isometries}.
\end{proposition}

\subsection{Without Entanglement Assistance}
Our main result is given below. 
Define
    \begin{equation*}
        \mathsf{Q}_{\text{D-F}}(\mathcal{N})\EqDef\max_{\sigma} \left[\min \left\{ I(A_1\rangle B)_\omega, I(A_1\rangle E)_\omega \right\}\right],
    \end{equation*}
    where the maximum is taken over all pure states of the form $\ket{\sigma_{A_1 A D}}$, and where $\omega_{A_1 BE}=\mathcal{N}_{AD\rightarrow BE}(\sigma_{A_1 A D})$.
    The subscript \mbox{`D-F'} stands for decode-forward bound. 
\begin{theorem}
\label{thm:full-dec-thm-ent-no-ass}
    The quantum capacity of the quantum relay channel $\mathcal{N}_{AD\rightarrow BE}$ without assistance satisfies:
    \begin{equation}
    C(\mathcal{N})\geq \mathsf{Q}_{\text{D-F}}(\mathcal{N}).
\end{equation}
\end{theorem}

\subsection{Unlimited Entanglement Assistance}
In the next theorem, we consider communication of quantum information via the quantum relay channel, when Alice and Bob are provided with pre-shared entanglement assistance, in which case, $L_B>\hat{L}_B>0$ (see Proposition~\ref{prop:full-dec-rates}). Let
    \begin{equation*}
        \mathsf{Q}_{\text{EA,D-F}}(\mathcal{N})\EqDef\max_{\sigma} \left[\frac{1}{2}I(A_1 ; B)_\omega - \frac{1}{2}I(A_1 ; D)_\sigma\right],
    \end{equation*}
    where the maximization is as before, and the subscript `EA' indicates the availability of entanglement assistance.  
\begin{theorem}
\label{thm:full-dec-thm-ent-with-ass} 
    The entanglement-assisted quantum capacity of the quantum relay channel $\mathcal{N}_{AD\rightarrow BE}$ satisfies:
    \begin{equation}
    C_{\text{EA}}(\mathcal{N})\geq \mathsf{Q}_{\text{EA,D-F}}(\mathcal{N}).
\end{equation}
\end{theorem}

\begin{remark}
The theorem above has an immediate consequence on the transmission of classical information with entanglement assistance. Specifically, using the superdense coding protocol, classical information can be sent at a rate of $R\geq$ $ 2\cdot \mathsf{Q}_{\text{EA,D-F}}(\mathcal{N})$ (classical information bits per transmission).
\end{remark}

\begin{remark}
The input state $\ket{\sigma}_{AA_1 D}$ represents the correlation that is generated between the transmitter and the relay. 
Intuitively, we think of the auxiliary system $A_1$ as Alice's entanglement resource. Due to entanglement monogamy, if the resource $A_1$ is maximally entangled with the relay's transmission, $D$, then there is no correlation with the channel input, $A$. Similarly, if the resource is maximally entangled with the channel input,  then it has no correlation with the relay. Therefore, it is not immediately obvious how to distribute the correlation between $A_1$, $A$, and $D$. 

Taking $\ket{\sigma}_{AA_1 D} = \ket{\phi_{A_1 A}} \otimes \ket{\psi}_D$ yields the direct transmission bound:
    \begin{align*}
\mathsf{Q}_{\text{D-F}}(\mathcal{N})\geq
\max_{\sigma} \left[ I(A_1\rangle B)_\omega\right]
    \end{align*}
    i.e., the coherent information of the channel from Alice to Bob. 
    Similarly, we recover the entanglement-assisted-capacity:
    \begin{align*}
\mathsf{Q}_{\text{EA,D-F}}(\mathcal{N})\geq
\max_{\sigma} \left[ I(A_1; B)_\omega\right] .
    \end{align*}    
    On the other hand,  $\ket{\sigma}_{AA_1 D} = \ket{\psi}_A \otimes \ket{\xi_{A_1 D}}$ results in a zero rate, as $H(A_1 |D)$ in \Prop{prop:full-dec-rates} becomes non-positive.
\end{remark}

\begin{remark}
    In our communication setting (see \Fig{fig:qrelay-three-party}), the links are \emph{not} orthogonal; that is, $\mathcal{N}_{AD\rightarrow BE} \neq \mathcal{P}_{A\rightarrow E} \otimes \mathcal{M}_{D\rightarrow B}$. In contrast, if the channel links were orthogonal, i.e., $\mathcal{N}_{AD\rightarrow BE} = \mathcal{P}_{A\rightarrow E} \otimes \mathcal{M}_{D\rightarrow B}$,  \Thm{thm:full-dec-thm-ent-no-ass} yields:
    \begin{equation*}
        \mathsf{Q}_{\text{D-F}}(\mathcal{N}) \geq \min \left\{ I_{c}(\mathcal{M}), I_{c}(\mathcal{P}) \right\},
    \end{equation*}
    in the unassisted case.
    The orthogonal links model was previously considered by Ghalaii and Pirandola\cc{ref:Ghalaii2020, ref:Pirandola2016}, Gyongyosi and Imre\cc{ref:Gyongyosi2012, ref:Gyongyosi2014}, and Shi et al.\cc{ref:Shi2012}. Intuitively, the generalized communication model allows for entanglement between the inputs of Alice and the relay, allowing for a higher achievable rate.
\end{remark}

\begin{remark}
    The results presented in \Thm{thm:full-dec-thm-ent-no-ass} and \Thm{thm:full-dec-thm-ent-with-ass} bear resemblance to the entanglement-assisted quantum capacity of a quantum channel with side information at the transmitter, as studied in \cRef{ref:Dupuis2009}.
    In the side information model, the channel $\tilde{\mathcal{N}}_{DA\to B}$ is governed by an external environment $D$, which is entangled with the transmitter. 
    The connection becomes apparent if we interpret the transmission to the relay as entangling the transmitter with the channel's environment (see \Fig{fig:qrelay-three-party}).
    Note, however, that  the environment state in the side information model\cc{ref:Dupuis2009} is fixed, i.e., $\sigma_D
    $ is dictated by the model. 
    In contrast, our formula involves optimization as we are free to choose the entanglement constellation between the transmitter and the relay. 
\end{remark}

In the upcoming sections, we provide a detailed proof for the achievable rates  in \Thm{thm:full-dec-thm-ent-no-ass} and \Thm{thm:full-dec-thm-ent-with-ass}.

