\section{Computation of the stabilities}
\label{sec:replicaGardner}

Given the loss function
\[
L(\pmb{w}) \;=\; \sum_{\mu=1}^{
\alpha N} V(\Delta^\mu),
\qquad
\Delta^\mu \;\equiv\;
y^{\mu}\!\left(
      \pmb{w}\!\cdot\!\pmb{x}^{\mu}
\right),
\]
where $\Delta^\mu$ is the \emph{stability} of pattern~$\mu$, we wish to determine the margin distribution
$P_{\alpha, \beta}(\Delta)$ averaged over the dataset
$\{\pmb{x}^\mu\}_{\mu=1}^{\alpha N}, \; x^\mu_i = \pm 1 \; \text{randomly}$, and over weight vectors $\pmb{w} \in \mathbb{R}^N$ drawn from the Boltzmann measure on the sphere
$\lVert\pmb{w}\rVert=1$, with density proportional to $\exp[-\beta L(\pmb{w})]$
The integration element
\[
d\mu(\pmb{w}) \;=\;
\frac{d^{N}\pmb{w}}{\Omega_{N}}\,
\delta\!\bigl(\lVert\pmb{w}\rVert^{2}-1\bigr),
\qquad
\Omega_{N}=\frac{2\pi^{N/2}}{\Gamma(N/2)},
\]
is the \emph{uniform measure} on that sphere. 
Explicitly, we write the stability distribution as
\begin{equation}
\label{eq:Pbeta_def}
P_{\alpha,\beta}(\Delta) \;=\;
\left\langle
\frac{
      \displaystyle
      \int d\mu(\pmb{w})\,
      e^{-\beta \sum_{\mu=1}^{\alpha N}
          V\!\bigl(y^\mu\pmb{w}\cdot\pmb{x}^\mu\bigr)}
      \,\delta\!\Bigl(
          \tfrac{y^{1}}{\sqrt{N}}\pmb{w}\cdot\pmb{x}^{1}-\Delta
      \Bigr)}
     {
      \displaystyle
      \int d\mu(\pmb{w})\,
      e^{-\beta \sum_{\mu=1}^{\alpha N}
          V\!\bigl(y^\mu\pmb{w}\cdot\pmb{x}^\mu\bigr)}
      }
\right\rangle_{\!\pmb{x}^\mu},
\end{equation}
where, by symmetry, we insert the $\delta$–function for the first pattern only.

Applying the replica trick, we (non-rigorously) rewrite \eqref{eq:Pbeta_def} as
\begin{equation}
\label{eq:margin_dist}
P_{\alpha,\beta}(\Delta) \;=\;
\lim_{n\to 0}\Bigl\langle
 \int\!\prod_{a=1}^{n} d\mu(\pmb{w}^{a})\,
      e^{-\beta\sum_{\mu,a}
      V\!\bigl(y^\mu\pmb{w}^{a}\!\cdot\!\pmb{x}^\mu\bigr)}
      \,\delta\!\Bigl(
          y^{1}\pmb{w}^{1}\!\cdot\!\pmb{x}^{1}-\Delta
      \Bigr)
\Bigr\rangle_{\!\pmb{x}^\mu}\!.
\end{equation}

Focusing on minimisers of the loss ($\beta\to\infty$), by assuming that $V(\Delta)$ has a unique minimum in $\Delta$ and assuming symmetry between replicas \cite{mezard1987spin}, we obtain
\[
P_{\alpha,\beta\to\infty}(\Delta)
 \;=\;
 \int_{-\infty}^{\infty}\!\frac{dt}{\sqrt{2\pi}}
      e^{-t^{2}/2}\,
      \delta\!\Bigl(\Delta-\Delta_{0}\bigl(t,\bar{x}(\alpha)\bigr)\Bigr),
\]
with
\[
\Delta_{0}(t,x)\;=\;
\mathop{\arg\min}_{\Delta}
      \Bigl[V(\Delta)+\tfrac{(\Delta-t)^{2}}{2x}\Bigr],
\qquad
1 \;=\; \alpha
      \int \mathcal{D}y\,
      \bigl[\Delta_{0}(y,\bar{x}(\alpha))-y\bigr]^{2},
\]
and $\mathcal{D}y = e^{-y^{2}/2}dy/\sqrt{2\pi}$.

