\section{Proof of Theorem \ref{contractrep} and \ref{theorem: contract rep value}}\label{proofcontractrep}

\subsection{Lemmas}

For any stopping time $\tau$ valued in $[0,T]$, we define
\begin{equation}
    J(\tau, \nu) :=  \E^\nu_\tau \left[ - \exp \left\{ -\gamma\, \left(\rew + \rwealth_{\tau,T}^\nu\right) \right\} \right]\,,
\end{equation}
where $\nu$ is in $\mcA_{\tau,T}$ (the restriction of $\mcA$ on time horizon $[\tau,T]$) and $\rwealth$ is the running wealth
\begin{align}
    \rwealth_{s,t}^\nu &= - \int_s^t \left\{\tempLP\, \nu_{u\shortminus}^2 \right\}\, \d u + \eta\, \int_s^t (S_{u\shortminus} + Z_{u\shortminus})\, \d B_u^{\nu}\\
    &\phantom{{}={}} + \sigma\, \int_s^t Y_{u\shortminus}\, \d W_u + \sum_{i\in\{+,-\}} \int_s^t \left\{ \deltai\, \xi\, \left( S_{u} - \frac{Z_{u\shortminus}\, Y_{u\shortminus}}{Y_{u\shortminus} + \deltai\, \xi} \right) \right\}\, \d \Ni_u\,.
\end{align}
Recall that the value function $V$ is defined as
\begin{equation}
    V_\tau = \esssup_{\nu\in \mcA_{\tau,T}} J(\tau, \nu)\,.
\end{equation}

\begin{lemma}\label{DPPMM}
    Let $\tau$ be a stopping time valued in $[t,T]$. Then
    \begin{equation}
        V_t = \esssup_{\nu\in \mcA_{t,\tau}} \E^\nu_t \left[ \exp\{-\gamma\, \rwealth_{t,\tau}^\nu\}\, V_\tau\right]\,,
    \end{equation}
\end{lemma}

\begin{proof}
    By tower property and the definition of the value function $V_t$, we have that
    \begin{align}
        V_t &= \esssup_{\nu \in \mcA_{t,\tau}} \E_t^\nu \left[ \exp \left\{ - \gamma\, \rwealth^\nu_{t,\tau} \right\}\, \E^\nu_\tau \left[ - \exp \left\{ -\gamma\, \left(\rew + \rwealth_{\tau,T}^\nu\right) \right\} \right]  \right]\\
        &\leq \esssup_{\nu \in \mcA_{t,\tau}} \E_t^\nu \left[ \exp \left\{ - \gamma\, \rwealth^\nu_{t,\tau} \right\}\, V_\tau  \right]\,.
    \end{align}
    For the other direction, by Proposition VI-1-1 in \cite{neveu1972martingales}, there exists $(\tilde{\nu}^k)_{k\in \N}\subset \mcA_{\tau,T}$ such that $J(\tau, \tilde{\nu}^k) \uparrow V_\tau$. By defining $\nu^k_s = \nu_s\, \ch_{t\leq s< \tau} + \tilde{\nu}^k\, \ch_{\tau\leq s\leq T}$, we obtain
    \begin{align}
        \frac{K_T^{\nu^k}}{K_\tau^{\nu^k}} &= \frac{K_T^{\tilde{\nu}^k}}{K_\tau^{\tilde{\nu}^k}} \quad \text{and}\quad
        Q_{\tau,T}^{\nu^k} = Q_{\tau,T}^{\tilde{\nu}^k}\,.
    \end{align}
    Thus, it follows that
    \begin{equation}
        \begin{split}
            \E^{\nu^k}_\tau \left[ - \exp \left\{ -\gamma\, \left(\rew + \rwealth_{\tau,T}^{\nu^k}\right) \right\} \right] &= \E_\tau \left[ - \frac{K_T^{\nu^k}}{K_\tau^{\nu^k}}\, \exp \left\{ -\gamma\, \left(\rew + \rwealth_{\tau,T}^{\nu^k}\right) \right\} \right]\\
            &= \E_\tau \left[ - \frac{K_T^{\tilde{\nu}^k}}{K_\tau^{\tilde{\nu}^k}}\, \exp \left\{ -\gamma\, \left(\rew + \rwealth_{\tau,T}^{\tilde{\nu}^k}\right) \right\} \right]\\
            &= J(\tau, \tilde{\nu}^k)\,.
        \end{split}
    \end{equation}
    We then obtain
    \begin{equation}
        \begin{split}
            J(t,\nu^k) &= \E_t \left[ - \frac{K_T^{\nu^k}}{K_\tau^{\nu^k}}\, \frac{K_\tau^{\nu^k}}{K_t^{\nu^k}}\, \exp \left\{ -\gamma\, \rwealth_{t,\tau}^{\nu^k} \right\}\, \exp \left\{ -\gamma\, \left(\rew + \rwealth_{\tau,T}^{\nu^k}\right) \right\} \right]\\
            &= \E_t \left[ \frac{K_\tau^{\nu^k}}{K_t^{\nu^k}}\, \exp \left\{ -\gamma\, \rwealth_{t,\tau}^{\nu^k} \right\}\, \E_\tau \left[- \frac{K_T^{\nu^k}}{K_\tau^{\nu^k}}\, \exp \left\{ -\gamma\, \left(\rew + \rwealth_{\tau,T}^{\nu^k}\right) \right\} \right]\right]\\
            &= \E_t \left[ \frac{K_\tau^{\nu}}{K_t^{\nu}}\, \exp \left\{ -\gamma\, \rwealth_{t,\tau}^{\nu} \right\}\, \E^{\nu^k}_\tau \left[  - \exp \left\{ -\gamma\, \left(\rew + \rwealth_{\tau,T}^{{\nu}^k}\right) \right\} \right] \right]\\
            &= \E_t \left[ \frac{K_\tau^{\nu}}{K_t^{\nu}}\, \exp \left\{ -\gamma\, \rwealth_{t,\tau}^{\nu} \right\}\, J(\tau, \tilde{\nu}^k) \right]\,.
        \end{split}
    \end{equation}
    Note that ${K_T^{\nu}}/{K_\tau^{\nu}}$ has mean of unity and is independent of $\F_\tau$. Thus,
    \begin{equation}
        \begin{split}
            \E_t \left[ \frac{K_\tau^{\nu}}{K_t^{\nu}}\, \exp \left\{ -\gamma\, \rwealth_{t,\tau}^{\nu} \right\}\, J(\tau, \tilde{\nu}^k) \right]
            &= \E_t \left[ \frac{K_\tau^{\nu}}{K_t^{\nu}}\, \exp \left\{ -\gamma\, \rwealth_{t,\tau}^{\nu} \right\}\, J(\tau, \tilde{\nu}^k) \right] \E_t \left[\frac{K_T^{\nu}}{K_\tau^{\nu}} \right]\\
            &= \E_t \left[ \frac{K_T^{\nu}}{K_t^{\nu}}\, \exp \left\{ -\gamma\, \rwealth_{t,\tau}^{\nu} \right\}\, J(\tau, \tilde{\nu}^k) \right]\\
            &= \E^{\nu}_t \left[ \exp \left\{ -\gamma\, \rwealth_{t,\tau}^{\nu} \right\}\, J(\tau, \tilde{\nu}^k) \right]
        \end{split}
    \end{equation}
   Due to Condition \ref{assumptionRgamma}, the expression $\E^{\nu}_t \left[ \exp \left\{ -\gamma\, \rwealth_{t,\tau}^{\nu} \right\}\, J(\tau, \tilde{\nu}^1) \right]$ is finite and we can use monotone convergence theorem to obtain
    \begin{equation}
        \begin{split}
            \lim_{k\uparrow \infty} J(t, \nu^k) &=  \E^{\nu}_t \left[ \exp \left\{ -\gamma\, \rwealth_{t,\tau}^{\nu} \right\}\, \lim_{k\to \infty} J(\tau, \tilde{\nu}^k) \right]\\
            &= \E^{\nu}_t \left[ \exp \left\{ -\gamma\, \rwealth_{t,\tau}^{\nu} \right\}\, V_\tau \right]\,.
        \end{split}
    \end{equation}
    Thus, we obtain 
    \begin{equation}
        \begin{split}
            V_t &\geq \lim_{k\uparrow \infty} J(t, \nu^k)\\
            &= \E^{\nu}_t \left[ \exp \left\{ -\gamma\, \rwealth_{t,\tau}^{\nu} \right\}\, V_\tau \right]\,,
        \end{split}
    \end{equation}
    which concludes the proof.
\end{proof}

\begin{lemma}\label{boundproba}
    Let $\Gamma \in \mathcal F$ such that $\mathbb P(\Gamma) >0$. Then there exists $\varepsilon >0$ such that
    $$\mathbb P^\nu (\Gamma) >\varepsilon \qquad \forall \nu \in \mathcal A.$$
\end{lemma}

\begin{proof}
    We will prove this by contradiction. Assume there exists $\left(\nu^k\right)_{k\in \N}$ a sequence in $\mcA$ such that $\lim_{n\to \infty} \Pb^{\nu^n}(\Gamma) = 0$. Thus,
    \begin{align}
        0 &= \lim_{n\to \infty} \E^{\nu^n}\left[ \ch_{\Gamma} \right]\\
        &=  \lim_{n\to \infty} \E \left[ \big|K_T^{\nu^n} \ch_{\Gamma}\big| \right]\,.
    \end{align}
    Then we can take a subsequence $(n_k)_{k\in \N} \subseteq (n)_{n\in \N}$ such that $\lim_{k\to \infty} K_T^{\nu^{n_k}} \ch_{\Gamma} = 0$ $\Pb$-almost surely. Because $\Gamma$ has $\Pb$-positive probability, then $\Pb (\lim_{k\to \infty} K_T^{\nu^{n_k}} = 0) > 0$, or equivalently,
    \begin{align}
        \Pb \left( \lim_{k\to \infty} \int_0^T \frac{\nu_t^{n_k}}{\eta}\, \d B_t - \frac{1}{2}\int_0^T \frac{(\nu_t^{n_k})^2}{\eta^2}\, \d t = -\infty \right) >0\,,\\
        \Leftrightarrow  \Pb \left( \lim_{k\to \infty} \int_0^T \frac{\nu_t^{n_k}}{\eta}\, \d B_t = -\infty \right) >0\,. \label{eq: contradiction}
    \end{align}
    However, by Ito isometry,
    \begin{align}
        \E \left[\left(\int_0^T \frac{\nu_u^{n_k}}{\eta}\, \d B_u\right)^2 \right] &= \E \left[\int_0^T \frac{(\nu_u^{n_k})^2}{\eta^2}\, \d u\right]\\
        &\leq \frac{T\, (\nu_\infty)^2}{\eta^2}\,,
    \end{align}
    because $\nu^{n_k}$ is bounded by $\nu_\infty$ $\d \Pb \otimes \d t \text{ a.e.}$ given that  $\nu_t^{n_k} \in \mcA$.
    Thus, the collection of random variables $\left\{ \int_0^T \frac{\nu_u^{n_k}}{\eta}\, \d B_u \right\}_{k\in \N}$ is bounded in $L^2(\Omega, \F_T, \Pb)$. From Equation \eqref{eq: contradiction}, we have
    \begin{equation}
        \begin{split}
            \Pb \left(\liminf_{k\to \infty} \left| \int_0^T \frac{\nu_t^{n_k}}{\eta}\, \d B_t \right|^2 = \infty \right) > 0\\
            \Rightarrow \E \left[ \liminf_{k\to \infty} \left| \int_0^T \frac{\nu_t^{n_k}}{\eta}\, \d B_t \right|^2 \right] = \infty\,.
        \end{split}
    \end{equation}
    However, by Fatou's lemma,
    \begin{equation}
        \begin{split}
            \infty &= \E \left[ \liminf_{k\to \infty} \left| \int_0^T \frac{\nu_t^{n_k}}{\eta}\, \d B_t \right|^2 \right]\\
            &\leq \liminf_{k\to \infty}  \E \left[ \left| \int_0^T \frac{\nu_t^{n_k}}{\eta}\, \d B_t \right|^2 \right]\\
            &\leq \frac{T\, (\nu_\infty)^2}{\eta^2}\,,
        \end{split}
    \end{equation}
    which is a contradiction.
\end{proof}

\begin{lemma}\label{lem:posV}
    For all $t\in \mfT$, we have $V_t < 0$ $\Pb$-almost surely.
\end{lemma}

\begin{proof}
    Let $\Gamma = \{ V_t = 0 \}$. By \cite{neveu1972martingales}, there exists $\left(\nu^k\right)_{k \in \N}$ a sequence in $\mcA_{t,T}$ such that $J(t,\nu^k)\uparrow 0$ on $\Gamma$. From monotone convergence theorem, $\E\left[ \ch_{\Gamma}\, J(t,\nu^k) \right]\to 0$. Then, there is a subsequence $k_1, k_2 , \cdots $ such that
    \begin{equation}
        K_T^{\nu^{k_m}}\,  \exp \left\{ -\gamma\, \left( \rew + \rwealth_{0,T}^{\nu^{k_m}} \right) \right\} \to 0 \quad \Pb-\text{a.s. on $\Gamma$}\,.
    \end{equation}
    This implies
    \begin{equation}
        \begin{split}
            &\int_0^T \frac{\nu^{k_m}_u}{\eta}\, \d B_u + \int_0^T  - \gamma\, \eta (S_{u\shortminus} + Z_{u\shortminus})\, \d B_u + \int_0^T \frac{\gamma\, \eta\, \nu^{k_m}_u\, (S_{u\shortminus} + Z_{u\shortminus})}{\eta}\, \d s\\
            - &\int_0^T  \gamma\, \sigma\, Y_{u\shortminus}\, \d W_u -  \sum_{i\in\{+,-\}} \int_0^T \gamma\, \left\{ \deltai\, \xi\, \left( S_{u} - \frac{Z_{u\shortminus}\, Y_{u\shortminus}}{Y_{u\shortminus} + \deltai\, \xi} \right) \right\}\, \d \Ni_u \to -\infty\, 
        \end{split}
    \end{equation}
$\Pb$-almost surely on $\Gamma$. However, 
\begin{align}
    \sup_{t\in \mfT} Y_t \leq Y_0 + \xi\, (\hatNa_T + \hatNb_T) + \sup_{t\in \mfT} B_t\,,\qquad \text{and} \qquad 
    \sup_{t\in \mfT} Z_t \leq Z_0\, 4^{\hatNa_T + \hatNb_t}\,.
\end{align}

Moreover, given that $\nu^{k_m}$ is bounded and using the above inequalities, we conclude that the last four terms in the above expression are finite a.s., therefore,  it has to be the case that
    \begin{equation}
        \int_0^T \frac{\nu^{k_m}_u}{\eta}\, \d B_u \to -\infty\qquad \Pb-\text{a.s. on $\Gamma$}\,.
    \end{equation}
From Lemma \ref{boundproba}, we should have $\Pb(\Gamma)=0$. Thus, we have $V_t < 0$ $\Pb$-almost surely.
\end{proof}

\subsection{Contract representation}\label{appendix 2}




\begin{proof}[\textbf{Proof of Theorem \ref{contractrep}}]
%    \phantom{{}={}}
By the DPP in Lemma \ref{DPPMM}, one can show that for any $t\ge s$
$$V_s = \sup_{\nu \in \mcA} \E_s^\nu \left[\, \exp \left\{ -\gamma\, \rwealth^\nu_{s,t} \right\}\, V_t\,  \right]\,.$$
Then, $U^\nu$ defined as
$$U_t^\nu = \exp \left\{ -\gamma\, \rwealth^\nu_{0,t} \right\}\, V_t$$
is a $\Pb^\nu$-supermartingale. By Doob-Meyer decomposition, we can write $U^\nu$ as
\begin{equation}
    \d U^\nu_t = \d M^\nu_t - \d A^{\nu,c}_t - \d A^{\nu, d}_t\,,
\end{equation}
where $M^\nu$ is a $(\Fb, \Pb^\nu)$-martingale, $A^{\nu,c}$ is a continuous non-decreasing process, $A^{\nu, d}$ is a pure-jump non-decreasing process, and $A^{\nu,c}_0 = A^{\nu,d}_0 = 0$. By Martingale Representation Theorem, there exists a $\Fb$-predictable process $(\tilde{A}^{\nu, W}, \tilde{A}^{\nu, B}, \tilde{A}^{\nu, -}, \tilde{A}^{\nu, +})$ such that
\begin{equation}
    \d M^\nu_t = \tilde{A}^{\nu, W}_t\, \d W_t + \tilde{A}^{\nu, B}_t\, \d B^\nu_t + \sum_{i\in\{+,-\}} \tilde{A}^{\nu, i}_t\, \d \tildeNi_t\,.
\end{equation}
%
By Ito's formula, we have that
%
\begin{equation}
    \begin{split}
        \d V_t &= U^\nu_{t\shortminus}\, \d \left( \exp \left\{ \gamma\, \rwealth^\nu_{0,t} \right\} \right) + \exp \left\{ \gamma\, \rwealth^\nu_{0,t\shortminus} \right\}\, \d\, U^\nu_t\\
        &\phantom{{}={}}+ \sum_{i\in\{+,-\}} (U^\nu_{t} - U^\nu_{t\shortminus})\left(\exp \left\{ \gamma\, \rwealth^\nu_{0,t} \right\} - \exp \left\{ \gamma\, \rwealth^\nu_{0,t\shortminus} \right\} \right)\, \d \hatNi_t\\
        &\phantom{{}={}} + \d \langle U^{\nu, c}, \exp \left\{ \gamma\, \rwealth^{\nu,c}_{0,\cdot} \right\}\rangle_t
    \end{split}
\end{equation}
%
where $U^{\nu, c}$ and $\rwealth^{\nu,c}_{0,\cdot}$ are the continuous parts of $U^{\nu}$ and $\rwealth^{\nu}_{0,\cdot}$ respectively. As $\langle \hat \Ni, A^{\nu,d}\rangle = 0$, we have
$$ (U^\nu_{t} - U^\nu_{t\shortminus})\left(\exp \left\{ \gamma\, \rwealth^\nu_{0,t} \right\} - \exp \left\{ \gamma\, \rwealth^\nu_{0,t\shortminus} \right\} \right)\, \d \hatNi_t = \tilde{A}^{\nu,i}_t \left(\exp \left\{ \gamma\, \rwealth^\nu_{0,t} \right\} - \exp \left\{ \gamma\, \rwealth^\nu_{0,t\shortminus} \right\} \right)\, \d \hatNi_t\,.$$
%
We also calculate
%
\begin{align}
    \d \left( \exp \left\{ \gamma\, \rwealth^\nu_{0,t} \right\} \right) &= \gamma\, \left( \exp \left\{ \gamma\, \rwealth^\nu_{0,t\shortminus} \right\} \right)\, \d \rwealth^{\nu,c}_{0,t} + \frac{\gamma^2}{2}\, \left( \exp \left\{ \gamma\, \rwealth^\nu_{0,t\shortminus} \right\} \right)\, \d \langle \rwealth^{\nu,c}_{0,\cdot} \rangle_t\\
    &\phantom{{}={}} + \sum_{i\in\{+,-\}}\, \left[ \exp \left\{ \gamma\, \rwealth^\nu_{0,t} \right\} - \exp \left\{ \gamma\, \rwealth^\nu_{0,t\shortminus} \right\}\right]\, \d \hatNi_t\,,\footnotemark
\end{align}\footnotetext{Note that even though the jump processes included in $\rwealth_{0,\cdot}^\nu$ are $\Na$ and not $\hatNa$, we have $\rwealth^\nu_{0,t}= \rwealth^\nu_{0,t\shortminus}$ and $\Deltarwealtha_t = 0$ on the event $\{ \Na_t = \Na_{t\shortminus}+1, Y_{t\shortminus}\leq \xi\}$.} 
and finally, 
%
\begin{align}
    \d \langle U^{\nu, c}, \exp \left\{ \gamma\, \rwealth^{\nu,c}_{0,\cdot} \right\}\rangle_t &= \gamma\, \exp \left\{ \gamma\, \rwealth^\nu_{0,t\shortminus} \right\}\, \left(\sigma\, Y_{t\shortminus}\, \tilde{A}^{\nu, W}_t + \eta\, (S_{t\shortminus} + Z_{t\shortminus})\, \tilde{A}^{\nu\, B}_t\right)\, \d t\\
    &= \frac{\gamma\, V_{t\shortminus}}{U^{\nu}_{t\shortminus}}\, \left(\sigma\, Y_{t\shortminus}\, \tilde{A}^{\nu, W}_t + \eta\, (S_{t\shortminus} + Z_{t\shortminus})\, \tilde{A}^{\nu\, B}_t\right)\, \d t\,.
\end{align}
Thus, we are able to rewrite $\d V_t$ as
%
\begin{align}
    \d V_t &= \gamma\, U^\nu_{t\shortminus}\, \left( \exp \left\{ \gamma\, \rwealth^\nu_{0,t\shortminus} \right\} \right)\, \d \rwealth^{\nu,c}_{0,t} + \frac{\gamma^2\, U^\nu_{t\shortminus}}{2}\, \left( \exp \left\{ \gamma\, \rwealth^\nu_{0,\shortminus} \right\} \right)\, \d \langle \rwealth^{\nu,c}_{0,\cdot} \rangle_t\\
    &\phantom{{}={}} + \sum_{i\in\{+,-\}}\, U^\nu_{t\shortminus}\, \left[ \exp \left\{ \gamma\, \rwealth^\nu_{0,t} \right\} - \exp \left\{ \gamma\, \rwealth^\nu_{0,t\shortminus} \right\}\right]\, \d \hat {N}^i_t\\
    &\phantom{{}={}} + \exp \left\{ \gamma\, \rwealth^\nu_{0,t\shortminus} \right\}\, \tilde{A}^{\nu, W}_t\, \d W_t + \exp \left\{ \gamma\, \rwealth^\nu_{0,t\shortminus} \right\}\, \tilde{A}^{\nu, B}_t\, \d B^\nu_t + \sum_{i\in\{+,-\}} \exp \left\{ \gamma\, \rwealth^\nu_{0,t\shortminus} \right\}\, \tilde{A}^{\nu, i}_t\, \left(\d \hatNi_t - \lambdai_t\, \d t\right)\\
    &\phantom{{}={}} - \exp \left\{ \gamma\, \rwealth^\nu_{0,t\shortminus} \right\}\, \d A^{\nu,c}_t - \exp \left\{ \gamma\, \rwealth^\nu_{0,t\shortminus} \right\}\, \d A^{\nu, d}_t + \sum_{i\in\{+,-\}} \tilde{A}^{\nu,i}_t\,\left(\exp \left\{ \gamma\, \rwealth^\nu_{0,t} \right\} - \exp \left\{ \gamma\, \rwealth^\nu_{0,t\shortminus} \right\} \right)\, \d \hat {N}^i_t\\
    &\phantom{{}={}} + \frac{\gamma\, V_{t\shortminus}}{U^{\nu}_{t\shortminus}}\, \left(\sigma\, Y_{t\shortminus}\, \tilde{A}^{\nu, W}_t + \eta\, (S_{t\shortminus} + Z_{t\shortminus})\, \tilde{A}^{\nu\, B}_t\right)\, \d t\,,\\
    &= \gamma\, V_{t\shortminus}\, \d \rwealth^{\nu,c}_{0,t} + \frac{\gamma^2\, V_{t\shortminus}}{2}\,\d \langle \rwealth^{\nu,c}_{0,\cdot} \rangle_t\\
    &\phantom{{}={}} + \sum_{i\in\{+,-\}}\, V_{t\shortminus}\, \left( \exp \left\{ \gamma\, \Deltarwealthi_{t} \right\} - 1\right)\, \d \hat {N}^i_t\\
    &\phantom{{}={}} + \frac{V_{t\shortminus}\, \tilde{A}^{\nu, W}_t}{U^\nu_{t\shortminus}}\, \d W_t + \frac{V_{t\shortminus}\, \tilde{A}^{\nu, B}_t}{U^\nu_{t\shortminus}}\, \d B^\nu_t + \sum_{i\in\{+,-\}} \frac{V_{t\shortminus}\, \tilde{A}^{\nu, i}_t}{U^\nu_{t\shortminus}}\, \left(\d \hatNi_t - \lambdai_t\, \d t\right)\\
    &\phantom{{}={}} - \frac{V_{t\shortminus}}{U^\nu_{t\shortminus}}\, \d A^{\nu,c}_t - \frac{V_{t\shortminus}}{U^\nu_{t\shortminus}}\, \d A^{\nu, d}_t + \sum_{i\in\{+,-\}} \frac{V_{t\shortminus}\, \tilde{A}^{\nu, i}_t}{U^\nu_{t\shortminus}}\,\left(\exp \left\{ \gamma\, \Deltarwealthi_{t} \right\} - 1 \right)\, \d \hat {N}^i_t\\
    &\phantom{{}={}} + \frac{\gamma\, V_{t\shortminus}}{U^{\nu}_{t\shortminus}}\, \left(\sigma\, Y_{t\shortminus}\, \tilde{A}^{\nu, W}_t + \eta\, (S_{t\shortminus} + Z_{t\shortminus})\, \tilde{A}^{\nu\, B}_t\right)\, \d t\,.
\end{align}
%
Let $P_t = -\frac{1}{\gamma} \log (-V_t)$. Then, by Ito's formula
\begin{align}
    \d P_t &= -\frac{1}{\gamma\, V_{t\shortminus}}\, \d V_t^{c} + \frac{1}{2\,\gamma\, V_{t\shortminus}^2}\, \d \langle V^c \rangle_t - \frac{1}{\gamma}\, \sum_{i\in\{+,-\}} \log \left(\frac{V_t}{V_{t\shortminus}} \right)\, \d \hat \Ni_t - \frac{1}{\gamma\, \Delta A_{t}^{\nu, d}}\, \log \left(\frac{V_t}{V_{t\shortminus}} \right)\, \d A^{\nu, d}_t\,\\
    &= -\frac{1}{\gamma\, V_{t\shortminus}}\, \d V_t^{c} + \frac{1}{2\,\gamma\, V_{t\shortminus}^2}\, \d \langle V^c \rangle_t - \frac{1}{\gamma}\, \sum_{i\in\{+,-\}} \log \left( 1 +\frac{\Delta^i V_t}{V_{t\shortminus}} \right)\, \d \hat \Ni_t - \frac{1}{\gamma\, \Delta A_{t}^{\nu, d}}\, \log \left(1 + \frac{\Delta^d V_t}{V_{t\shortminus}} \right)\, \d A^{\nu, d}_t\,,
\end{align}
with $V^c$ is the continuous part of $V$ and $Y_T = \rew$. We calculate
\begin{align}
    \frac{d\langle V^c\rangle_t}{\d t} &= \left(\frac{V_{t\shortminus}\, \tilde{A}^{\nu, W}_t}{U^\nu_{t\shortminus}} + \gamma\, V_{t\shortminus}\, \sigma\, Y_{t\shortminus}\right)^2 + \left(\frac{V_{t\shortminus}\, \tilde{A}^{\nu, B}_t}{U^\nu_{t\shortminus}} + \gamma\, V_{t\shortminus}\, \eta\, (S_t + Z_{t\shortminus})\right)^2 \,,\\
   \Delta^i V_t &= \left(1 + \frac{\tilde{A}^{\nu,i}_t}{U^\nu_{t\shortminus}}\right)\, V_{t\shortminus}\, \exp \left\{ \gamma\, \Deltarwealthi_{t}  \right\} - V_{t\shortminus}\,,\\
   \Delta^d V_t &=  - \frac{V_{t\shortminus}\, \Delta {A}^{\nu,d}_t}{U^\nu_{t\shortminus}}\,,\\
   \d V^c_t &= \gamma\, V_{t\shortminus}\, \d \rwealth^{\nu,c}_{0,t} + \frac{\gamma^2\, V_{t\shortminus}}{2}\,\d \langle \rwealth^{\nu,c}_{0,\cdot} \rangle_t + \frac{\gamma\, V_{t\shortminus}}{U^{\nu}_{t\shortminus}}\, \left(\sigma\, Y_{t\shortminus}\, \tilde{A}^{\nu, W}_t + \eta\, (S_{t\shortminus} + Z_{t\shortminus})\, \tilde{A}^{\nu\, B}_t\right)\, \d t\\
   &\phantom{{}={}} +\frac{V_{t\shortminus}\, \tilde{A}^{\nu, W}_t}{U^\nu_{t\shortminus}}\, \d W_t + \frac{V_{t\shortminus}\, \tilde{A}^{\nu, B}_t}{U^\nu_{t\shortminus}}\, \d B^\nu_t - \sum_{i\in\{+,-\}} \frac{\lambdai_t\, V_{t\shortminus}\, \tilde{A}^{\nu, i}_t}{U^\nu_{t\shortminus}}\, \d t - \frac{V_{t\shortminus}}{U^\nu_{t\shortminus}}\, \d A^{\nu,c}_t\,.
\end{align}
%
We may rewrite $\d P_t$ as
%
\begin{align}
    \d P_t &= -\d \rwealth^{\nu,c}_{0,t} - \frac{\gamma}{2}\,\d \langle \rwealth^{\nu,c}_{0,\cdot} \rangle_t - \frac{\tilde{A}^{\nu, W}_t}{\gamma\, U^\nu_{t\shortminus}}\, \d W_t - \frac{\tilde{A}^{\nu, B}_t}{\gamma\, U^\nu_{t\shortminus}}\, \d B^\nu_t + \sum_{i\in\{+,-\}} \frac{\lambdai_t\, \tilde{A}^{\nu, i}_t}{\gamma\, U^\nu_{t\shortminus}}\, \d t + \frac{1}{\gamma\, U^\nu_{t\shortminus}}\, \d A^{\nu,c}_t\\
    &\phantom{{}={}} + \frac{1}{2\, \gamma}\, \left[ \left(\frac{\tilde{A}^{\nu, W}_t}{U^\nu_{t\shortminus}} + \gamma\, \sigma\, Y_{t\shortminus}\right)^2 + \left(\frac{\tilde{A}^{\nu, B}_t}{U^\nu_{t\shortminus}} + \gamma\, \eta\, (S_t + Z_{t\shortminus})\right)^2 \right]\, \d t\\
    &\phantom{{}={}} - \frac{1}{U^{\nu}_{t\shortminus}}\, \left(\sigma\, Y_{t\shortminus}\, \tilde{A}^{\nu, W}_t + \eta\, (S_{t\shortminus} + Z_{t\shortminus})\, \tilde{A}^{\nu\, B}_t\right)\, \d t\\
    &\phantom{{}={}} - \frac{1}{\gamma}\, \sum_{i\in\{+,-\}} \left\{\log \left( 1 + \frac{\tilde{A}^{\nu,i}_t}{U^\nu_{t\shortminus}} \right) + \gamma\, \Deltarwealthi_{t} \right\}\, \d \hat {N}^i_t\\
    &\phantom{{}={}} - \frac{1}{\gamma\, \Delta A_{t}^{\nu, d}}\, \log \left(1 - \frac{\Delta A^{\nu,d}_t}{U^\nu_{t\shortminus}} \right)\, \d A^{\nu, d}_t\\
    &= \Bigg\{ \tempLP\, \nu_{t\shortminus}^2  + \frac{1}{2\, \gamma}\, \left[ \left(\frac{\tilde{A}^{\nu, W}_t}{U^\nu_{t\shortminus}} + \gamma\, \sigma\, Y_{t\shortminus}\right)^2 + \left(\frac{\tilde{A}^{\nu, B}_t}{U^\nu_{t\shortminus}} + \gamma\, \eta\, (S_t + Z_{t\shortminus})\right)^2 \right]\\
    &\phantom{{}={}} - \frac{\gamma}{2}\, \left[ (\sigma\,Y_{t\shortminus})^2 + \eta^2\, (S_t + Z_{t\shortminus})^2 \right] + \sum_{i\in\{+,-\}} \frac{\lambdai_t\, \tilde{A}^{\nu, i}_t}{\gamma\, U^\nu_{t\shortminus}} + \frac{1}{\gamma\, U^\nu_{t\shortminus}}\, \frac{\d A^{\nu,c}_t}{\d t}\\
    &\phantom{{}={}} - \frac{1}{U^{\nu}_{t\shortminus}}\, \left(\sigma\, Y_{t\shortminus}\, \tilde{A}^{\nu, W}_t + \eta\, (S_{t\shortminus} + Z_{t\shortminus})\, \tilde{A}^{\nu\, B}_t\right)\Bigg\}\, \d t\\
    &\phantom{{}={}} - \frac{1}{\gamma}\, \sum_{i\in\{+,-\}} \left\{\log \left( 1 + \frac{\tilde{A}^{\nu,i}_t}{U^\nu_{t\shortminus}} \right) + \gamma\, \Deltarwealthi_{t} \right\}\, \d \hat {N}^i_t\\
    &\phantom{{}={}} - \frac{1}{\gamma\, \Delta A_{t}^{\nu, d}}\, \log \left(1 - \frac{\Delta A^{\nu,d}_t}{U^\nu_{t\shortminus}} \right)\, \d A^{\nu, d}_t\\
    &\phantom{{}={}} - \left\{ \sigma\, Y_{t\shortminus} + \frac{\tilde{A}^{\nu, W}_t}{\gamma\, U^\nu_{t\shortminus}} \right\}\, \d W_t - \left\{ \eta\, (S_{t\shortminus} + Z_{t\shortminus}) + \frac{\tilde{A}^{\nu, B}_t}{\gamma\, U^\nu_{t\shortminus}} \right\}\, \d B^\nu_t\\
    &= \Bigg\{ \tempLP\, \nu_{t\shortminus}^2 + \frac{1}{2\, \gamma}\, \left[ \left(\frac{\tilde{A}^{\nu, W}_t}{U^\nu_{t\shortminus}} + \gamma\, \sigma\, Y_{t\shortminus}\right)^2 + \left(\frac{\tilde{A}^{\nu, B}_t}{U^\nu_{t\shortminus}} + \gamma\, \eta\, (S_t + Z_{t\shortminus})\right)^2 \right]\\
    &\phantom{{}={}} - \frac{\gamma}{2}\, \left[ (\sigma\,Y_{t\shortminus})^2 + \eta^2\, (S_t + Z_{t\shortminus})^2 \right] + \sum_{i\in\{+,-\}} \frac{\lambdai_t\, \tilde{A}^{\nu, i}_t}{\gamma\, U^\nu_{t\shortminus}} + \frac{1}{\gamma\, U^\nu_{t\shortminus}}\, \frac{\d A^{\nu,c}_t}{\d t}\\
    &\phantom{{}={}} - \frac{1}{U^{\nu}_{t\shortminus}}\, \left(\sigma\, Y_{t\shortminus}\, \tilde{A}^{\nu, W}_t + \eta\, (S_{t\shortminus} + Z_{t\shortminus})\, \tilde{A}^{\nu\, B}_t\right) - \nu_{t\shortminus}\, (S_{t\shortminus} + Z_{t\shortminus}) - \frac{\tilde{A}^{\nu, B}_t\, \nu_{t\shortminus}}{\gamma\, \eta\, U^\nu_{t\shortminus}}\Bigg\}\, \d t\\
    &\phantom{{}={}} - \frac{1}{\gamma}\, \sum_{i\in\{+,-\}} \left\{\log \left( 1 + \frac{\tilde{A}^{\nu,i}_t}{U^\nu_{t\shortminus}} \right) + \gamma\, \Deltarwealthi_{t} \right\}\, \d \hat {N}^i_t\\
    &\phantom{{}={}} - \frac{1}{\gamma\, \Delta A_{t}^{\nu, d}}\, \log \left(1 - \frac{\Delta A^{\nu,d}_t}{U^\nu_{t\shortminus}} \right)\, \d A^{\nu, d}_t\\
    &\phantom{{}={}} - \left\{ \sigma\, Y_{t\shortminus} + \frac{\tilde{A}^{\nu, W}_t}{\gamma\, U^\nu_{t\shortminus}} \right\}\, \d W_t - \left\{ \eta\, (S_{t\shortminus} + Z_{t\shortminus}) + \frac{\tilde{A}^{\nu, B}_t}{\gamma\, U^\nu_{t\shortminus}} \right\}\, \d B_t\,.
\end{align}

Simplifying the above equations, we get
%
\begin{align}
    \d P_t &= \Bigg\{ \tempLP\, \nu_{t\shortminus}^2 + \frac{1}{2\, \gamma}\, \left[ \left(\frac{\tilde{A}^{\nu, W}_t}{U^\nu_{t\shortminus}}\right)^2 + \left(\frac{\tilde{A}^{\nu, B}_t}{U^\nu_{t\shortminus}}\right)^2 \right]\\
    &\phantom{{}={}} + \sum_{i\in\{+,-\}} \frac{\lambdai_t\, \tilde{A}^{\nu, i}_t}{\gamma\, U^\nu_{t\shortminus}} + \frac{1}{\gamma\, U^\nu_{t\shortminus}}\, \frac{\d A^{\nu,c}_t}{\d t} + \nu_{t\shortminus}\, (S_{t\shortminus} + Z_{t\shortminus}) + \frac{\tilde{A}^{\nu, B}_t\, \nu_{t\shortminus}}{\gamma\, \eta\, U^\nu_{t\shortminus}}\Bigg\}\, \d t\\
    &\phantom{{}={}} - \frac{1}{\gamma}\, \sum_{i\in\{+,-\}} \left\{\log \left( 1 + \frac{\tilde{A}^{\nu,i}_t}{U^\nu_{t\shortminus}} \right) + \gamma\, \Deltarwealthi_{t} \right\}\, \d \hat {N}^i_t\\
    &\phantom{{}={}} - \frac{1}{\gamma\, \Delta A_{t}^{\nu, d}}\, \log \left(1 - \frac{\Delta A^{\nu,d}_t}{U^\nu_{t\shortminus}} \right)\, \d A^{\nu, d}_t\\
    &\phantom{{}={}} - \left\{ \sigma\, Y_{t\shortminus} + \frac{\tilde{A}^{\nu, W}_t}{\gamma\, U^\nu_{t\shortminus}} \right\}\, \d W_t - \left\{ \eta\, (S_{t\shortminus} + Z_{t\shortminus}) + \frac{\tilde{A}^{\nu, B}_t}{\gamma\, U^\nu_{t\shortminus}} \right\}\, \d B_t\,.
\end{align}

If we rewrite 
\begin{align}
    \Ai_t &= - \frac{1}{\gamma}\, \left(\log \left( 1 + \frac{\tilde{A}^{\nu,i}_t}{U^\nu_{t\shortminus}} \right) + \gamma\, \Deltarwealthi_{t} \right)\\
    \AW_t &= - \left( \sigma\, Y_{t\shortminus} + \frac{\tilde{A}^{\nu, W}_t}{\gamma\, U^\nu_{t\shortminus}} \right)\\
    \AB_t &= - \left( \eta\, (S_{t\shortminus} + Z_{t\shortminus}) + \frac{\tilde{A}^{\nu, B}_t}{\gamma\, U^\nu_{t\shortminus}} \right)\,
\end{align}
where $i\in\{+,-\}$, we  have
\begin{align}
    \d P_t &= \Bigg\{ \tempLP\, \nu_{t\shortminus}^2 + \frac{\gamma}{2}\, \left[ \left(\AW_t + \sigma\, Y_{t\shortminus}\right)^2 + \left(\AB_t + \eta\, (S_{t\shortminus} + Z_{t\shortminus})\right)^2 \right]\\
    &\phantom{{}={}} - \sum_{i\in\{+,-\}} \frac{\lambdai_t\,(1 - e^{-\gamma(\Ai_t + \Deltarwealthi_t)})}{\gamma} + \frac{1}{\gamma\, U^\nu_{t\shortminus}}\, \frac{\d A^{\nu,c}_t}{\d t} - \frac{\AB_t\, \nu_{t\shortminus}}{\eta}\Bigg\}\, \d t\\
    &\phantom{{}={}} + \sum_{i\in\{+,-\}} \Ai_t\, \d \hat {N}^i_t - \frac{1}{\gamma\, \Delta A_{t}^{\nu, d}}\, \log \left(1 - \frac{\Delta A^{\nu,d}_t}{U^\nu_{t\shortminus}} \right)\, \d A^{\nu, d}_t\\
    &\phantom{{}={}} + \AW_t\, \d W_t + \AB_t\, \d B_t\,.
\end{align}
%
Note that
\begin{align}
    P_u &= \rew - \int_u^T  \Bigg\{ \tempLP\, \nu_{t\shortminus}^2 + \frac{\gamma}{2}\, \left[ \left(\AW_t + \sigma\, Y_{t\shortminus}\right)^2 + \left(\AB_t + \eta\, (S_{t\shortminus} + Z_{t\shortminus})\right)^2 \right]\\
    &\phantom{{}={}} - \sum_{i\in\{+,-\}} \frac{\lambdai_t\,(1 - e^{-\gamma(\Ai_t + \Deltarwealthi_t)})}{\gamma} + \frac{1}{\gamma\, U^\nu_{t\shortminus}}\, \frac{\d A^{\nu,c}_t}{\d t} - \frac{\AB_t\, \nu_{t\shortminus}}{\eta}\Bigg\}\, \d t\\
    &\phantom{{}={}} -\sum_{i\in\{+,-\}} \int_u^T  \Ai_t\, \d \hat {N}^i_t - \int_u^T \AW_t\, \d W_t -\int_u^T \AB_t\, \d B_t + \int_u^T \d A^d_t\,,
\end{align}
with  $\d A^d_t = \frac{1}{\gamma\, \Delta A_{t}^{\nu, d}}\, \log \left(1 - \frac{\Delta A^{\nu,d}_t}{U^\nu_{t\shortminus}} \right)\, \d A^{\nu, d}_t$, i.e.
$$A^d_t = \frac 1\gamma \sum_{s\le t}\log \left(1 - \frac{\Delta A^{\nu,d}_t}{U^\nu_{t\shortminus}} \right).$$
This shows in particular that $\Delta a_t = \frac{-\Delta A^{\nu, d}_t}{U^\nu_{t-}} \ge 0$ is independent from $\nu \in \mathcal A$.\\

Therefore, we have $P_T = \rew$ and
\begin{align}
    \d P_t &=  - \Bigg\{\bar h \left(\nu_t, A_t, Z_t, Y_t, S_t \right) -\frac{1}{\gamma\, U^\nu_{t\shortminus}}\, \frac{\d A^{\nu,c}_t}{\d t} \Bigg\}\, \d t +\sum_{i\in\{+,-\}}  \Ai_t\, \d \hat {N}^i_t +  \AW_t\, \d W_t + \AB_t\, \d B_t -  \d A^d_t\,
\end{align}
with
\begin{align}
 \bar h \left(\nu, A, Z, Y, S \right) & = h(\nu, A) + \sum_{i\in\{+,-\}} \frac{\barlambdai(Z, Y, S)\,(1 - e^{-\gamma(\Ai + \Deltarwealthi)})}{\gamma} - \frac{\gamma}{2}\, \left[ \left(\AW + \sigma\, Y\right)^2 + \left(\AB + \eta\, (S + Z)\right)^2 \right].   
\end{align}



We introduce the process $I$ given by
$$I_t = \int_0^t \Bigg\{\bar h \left(\nu_s, A_s, Z_s, Y_s, S_s \right) \d s-\frac{1}{\gamma\, U^\nu_{s\shortminus}}\, \d A^{\nu,c}_s \Bigg\}.$$
By the DPP, we have

\begin{align}
    0 &= \sup_{\nu \in \mathcal A} \mathbb E^\nu \left[ U^\nu_T \right] - V_0 = \sup_{\nu \in \mathcal A} \mathbb E^\nu \left[ U^\nu_T  - M^\nu_T \right] = \sup_{\nu \in \mathcal A} \mathbb E^\nu \left[\int_0^T \left( -\d A^{\nu, c}_t - \d A^{\nu, d}_t \right) \right]\\
    &= \gamma \sup_{\nu \in \mathcal A} \mathbb E^\nu \left[\int_0^T U^\nu_{t-}\left( \d I_t - \bar h \left(\nu_t, A_t, Z_t, Y_t, S_t \right) \d t  + \frac{\d a_t }{\gamma}\right) \right]
\end{align}
where $\d a_t = \frac{-\d A^{\nu, d}_t}{U^\nu_{t-}} \ge 0.$ \\

Moreover, by Lemma \ref{lem:posV}, we have
$$U^\nu_t = e^{-\gamma \rwealth^\nu_{0,t}} V_t \le -\beta_t V_t  <0,$$
where we write
$$\beta_t = -e^{-\gamma \left(  + \eta \int_0^t (S_u + Z_{u\shortminus}) \d B_u + \int_0^t |S_u + Z_{u\shortminus}|\nu_{\infty} \d u + \sigma \int_0^t Y_{t\shortminus} \d W_u + \underset{i=a,b }{\sum}\int_0^t \left\{ \deltai\, \xi\, \left( S_{u} - \frac{Z_{u\shortminus}\, Y_{u\shortminus}}{Y_{u\shortminus} + \deltai\, \xi} \right) \right\}\, \d \Ni_u \right) }.$$
Therefore we have
\begin{align}
    0 & \le \sup_{\nu \in \mathcal A} \mathbb E^\nu \left[\int_0^T -\beta_t V_t\left( \d I_t - \bar h \left(\nu_t, A_t, Z_t, Y_t, S_t \right) \d t  + \frac{\d a_t }{\gamma}\right) \right]\\
    & \le \sup_{\nu \in \mathcal A} \mathbb E^\nu \left[\int_0^T -\beta_t V_t\left( \d I_t - \bar H \left(A_t, Z_t, Y_t, S_t \right) \d t  + \frac{\d a_t }{\gamma}\right) \right].
\end{align}

Let us denote by $\Theta$ the random variable
$$\Theta = \int_0^T -\beta_t V_t\left( \d I_t - \bar H \left(A_t, Z_t, Y_t, S_t \right) \d t  + \frac{\d a_t }{\gamma}\right)\le 0.$$
We then have
$$0\le \sup_{\nu \in \mathcal A} \mathbb E^\nu \left[\Theta \right].$$

Let $\varepsilon >0$. For all $\nu \in \mathcal A$, we have 
$$\mathbb E^\nu \left[\Theta \right]  = \mathbb E^\nu \left[\Theta \mathds{1}_{\Theta \le -\varepsilon} + \Theta \mathds{1}_{\Theta >\varepsilon} \right] \le -\varepsilon \mathbb P^\nu (\Theta \le - \varepsilon ).$$
Therefore,
$$0\le \sup_{\nu \in \mathcal A} -\varepsilon \mathbb P^\nu (\Theta \le - \varepsilon ),$$
which implies that 
$$\inf_{\nu \in \mathcal A}  \mathbb P^\nu (\Theta \le - \varepsilon ) = 0.$$

By Lemma \ref{boundproba}, this implies that 
$$\mathbb P (\Theta \le - \varepsilon ) = 0.$$
This is true for all $\varepsilon >0$, therefore we have that 

$$\Theta = \int_0^T -\beta_t V_t\left( \d I_t - \bar H \left(A_t, Z_t, Y_t, S_t \right) \d t  + \frac{\d a_t }{\gamma}\right) = 0 \qquad \text{a.s.}$$

Since $\beta V > 0,$ $\d I_t - \bar H \left(A_t, Z_t, Y_t, S_t \right)\d t \ge 0 $, and $\d a_t \ge 0,$ this finally implies that 
$$\d I_t  = \bar H \left(A_t, Z_t, Y_t, S_t \right)\d t \quad \text{and} \quad \d a_t = \d A^d_t = 0.$$

It remains to prove that $A\in \Lambda$, i.e.
\begin{equation}
    \sup_{\nu \in \mcA} \sup_{t\in \mfT} \E^\nu \left[ \exp\left\{ -\gamma'\, P_t \right\}  \right] < \infty \quad \text{ for some } \gamma'>\gamma\,.
\end{equation}
Condition \ref{assumptionRgamma} together with Hölder inequality guarantees that there exists $r>0$ such that 
$$ \sup_{\nu \in \mcA}  \E^\nu \left[ | U^\nu_T|^{r+1} \right] < \infty.$$
Therefore, as $U^\nu$ is a negative $\mathbb P^\nu -$supermartingale, we get
$$\sup_{\nu \in \mcA} \sup_{t\in \mfT}  \E^\nu \left[ | U^\nu_t|^{r+1} \right] =  \sup_{\nu \in \mcA}  \E^\nu \left[ | U^\nu_T|^{r+1} \right] < \infty,$$
which leads to the result by using again Hölder inequality and the fact that $e^{-\gamma P_t} = U^\nu_t e^{\gamma Q^\nu_{0,t}}.$

\end{proof}

\begin{proof}[\textbf{Proof of Theorem \ref{theorem: contract rep value}}]
%    \phantom{{}={}}    
    Let $\rew = P_T^{P_0, A}$, $\bar{P}_t = P_t^{P_0, A} + \rwealth_{0,t}^\nu$. Then
    \begin{align}
        \d e^{-\gamma\, \bar{P}_t} &= \gamma\, e^{-\gamma\, \bar{P}_{t\shortminus}}\, \Bigg\{ \big(H(A_t) - h(\nu_t, A_t)\big)\, \d t - \AW_t\, \d W_t - \AB_t\, \d B_t^{\nu} + \sum_{i\in\{+,-\}} \frac{e^{-\gamma\, (\Deltarwealthi_t + \Ai_t)}-1}{\gamma}\, \d \tildeNi_t\Bigg\}\,.
    \end{align}

    We observe that $H(A)\geq h(\nu, A)$. As $A\in \Lambda$, the process $(-e^{-\gamma\, \bar{P}_t})_{t\in \mfT}$ is a $\Pb^\nu$-supermartingale. Thus,
    \[  \E^\nu \left[ -e^{-\gamma\, \bar{P}_T}\right] \leq -e^{-\gamma\, P_0}\,.  \]
    Equality applies if and only if $H(A_t) = h(\nu_t, A_t)$, $\d t \otimes \d \Pb$ a.s., i.e. $\nu_t = \bar{\nu}(A_t)$.
\end{proof}

