\begin{abstract}
We  briefly discuss the contribution of Ha\"im Brezis and his co-authors on the characterizations of the Sobolev norms and the total variation using non-local functionals. Some ideas of the analysis are  given and new results are presented. 
\end{abstract}


\medskip 
\noindent {\bf Key words.} Sobolev norms, total variations, Gamma-convergence, inequalities, non-local functionals. 

\noindent {\bf AMS subject classification.} 26B15, 26B25, 26B30, 42B25


\tableofcontents

\section{Introduction} \label{sect-introduction}

In this paper, we first briefly discuss the contribution of Ha\"im Brezis and his co-authors on the characterizations of the Sobolev norms and the total variation using non-local functionals, and related problems. Some ideas of the analysis are also given. We then present several new results by developing these ideas. 

\medskip 
We begin with the BBM formula due to Bourgain, Brezis, and Mironescu \cite{BBM-01} (see also \cite{Brezis-02, Davila-02}). To this end, for $N \ge 1$, $p \ge 1$,  and $u \in L^p(\mR^N)$, it is convenient to denote
\be
\Phi (u) =  \left\{  \begin{array}{c} \|\nabla u \|_{L^p(\mR^N)}^p \, dx \mbox{ if } p > 1\\[6pt]
 \| \nabla u \|_{\cM(\mR)} \mbox{ if } p =1.   
\end{array}\right. 
\ee
Recall that, for $f \in L^1(\mR^N)$, 
$$
\|\nabla f \|_{\cM(\mR^N)} : = \sup \left\{ \left| \int_{\mR^N} f \dive \varphi \right| ; \varphi \in C^\infty_c(\mR^N) \mbox{ with } \| \varphi \|_{L^\infty(\mR^N)}  \le 1\right\}. 
$$
In what follows, a sequence of functions  $(\rho_n)_{n
\ge 1} \subset L^1(0, + \infty)$ is called a sequence of non-negative mollifiers if the following properties hold: 
\begin{equation*}
\begin{array}{ccc}
\rho_n \geq 0, 
\end{array}
\end{equation*}
\begin{equation*}
\dsp \lim_{ n \lr \infty } \int_\tau^\infty \rho_n(r) r^{N-1} \,
dr = 0 \quad   \forall \, \tau >0, \quad \mbox{ and } \quad
\lim_{n \lr  \infty} \int_{0}^{+ \infty} \rho_n(r) r^{N-1} \, dr =
1.
\end{equation*}

Here is the BBM formula.  

\begin{theorem}[BBM formula, Bourgain \& Brezis \& Mironescu]\label{thm-BBM}
Let $N \ge 1$, $1 \le  p < + \infty$, and let $(\rho_n)_{n \ge 1}$ be a sequence of non-negative  mollifiers.  Then, for $u \in L^p(\mR^N)$,  
\be\label{thm-BBM-cl1}
\mathop{\iint}_{\mR^N \times \mR^N} \frac{|u(x)
- u(y)|^p}{|x-y|^p} \rho_n(|x-y|)\, dx \, dy \le  C_{N, p} \Phi (u), 
\ee
and 
\begin{equation}\label{thm-BBM-cl2}
\lim_{n  \lr  \infty } \mathop{\iint}_{\mR^N \times \mR^N} \frac{|u(x)
-u(y)|^p}{|x-y|^p} \rho_n(|x-y|)\, dx \, dy = K_{N, p} \Phi(u), 
\end{equation}
where $K_{N,p}$ is defined by 
\begin{equation}\label{def-K}
K_{N,p}= \int_{\mS^{N-1}} |e \cdot \sigma|^p \, d \sigma,
\end{equation}
for any $e \in \mS^{N-1}$, the unit sphere of $\mR^N$. 
\end{theorem}

Here and in what follows, $C_{N, p}$ denotes a positive constant depending only on $N$ and $p$, and might change from one place to another. 

\medskip 




As a convention, the RHS of \eqref{thm-BBM-cl1} or \eqref{thm-BBM-cl2} is infinite  if $u\not \in W^{1, p}(\mR^N)$ for $p> 1$ and $u \not \in BV(\mR^N)$ for $p=1$. 

\medskip 
\Cref{thm-BBM} was established by Bourgain, Brezis, and Mironesu \cite{BBM-01} (see also \cite{Brezis-02}) in the case $p>1$. In the case $p=1$, they also showed there that the $\liminf$ and the $\limsup$ of the LHS of \eqref{thm-BBM-cl1} as $n \to + \infty$ is of the order of the RHS of \eqref{thm-BBM-cl1} instead of \eqref{thm-BBM-cl2}. The proof of \eqref{thm-BBM-cl2} in the case $p=1$ and $u \in BV(\mR^N)$ is due to Davila \cite{Davila-02}. 

\medskip 
We next briefly discuss some ideas of the proof. We begin deal with \eqref{thm-BBM-cl1} under the additional assumption that $\Phi(u) < + \infty$. We first consider the case where $u \in C^\infty_c(\mR^N)$. Using the fact, for $x, y \in \mR^N$,  
$$
u(y) - u(x) = \int_0^1 \nabla u(x + t (y -x)) \cdot (y-x) \, dt, 
$$
and Jensen's inequality, one can prove that 
\begin{multline} \label{thm-BBM-p1}
\mathop{\iint}_{\mR^N \times \mR^N} \frac{|u(x)
- u(y)|^p}{|x-y|^p} \rho_n(|x-y|)\, dx \, dy \\[6pt] 
\le \mathop{\iint}_{\mR^N \times \mR^N}  \int_0^1 |\nabla u(x + t (y-x))|^p \, dt \,  \rho_n (|y-x|) \, d x \, d y.  
\end{multline}
By a change of variables $(x, z) = (x, x-y)$ and by applying the Fubini theorem, we obtain \eqref{thm-BBM-cl1} from \eqref{thm-BBM-p1}. We next deal with \eqref{thm-BBM-cl1} for which $\Phi(u) < + \infty$.  
The proof in this case follows from the previous case by considering a sequence $(u_k) \subset  C^\infty_c(\mR^N)$ such that $\Phi(u_k) \to \Phi(u)$ and $u_k \to u$ for almost every $x \in \mR^N$, as $k \to + \infty$. By Fatou's lemma, one has, for $n \ge 1$,  
\be \label{thm-BBM-p2}
\liminf_{k \to + \infty} \mathop{\iint}_{\mR^N \times \mR^N} \frac{|u_k(x)
- u_k(y)|^p}{|x-y|^p} \rho_n(|x-y|)\, dx \, dy 
\ge \mathop{\iint}_{\mR^N \times \mR^N} \frac{|u(x)
- u(y)|^p}{|x-y|^p} \rho_n(|x-y|)\, dx \, dy. 
\ee
Assertion \eqref{thm-BBM-cl1} now follows from \eqref{thm-BBM-p2} by applying \eqref{thm-BBM-p1} to $u_k$ and then letting $k \to + \infty$.  


We now address \eqref{thm-BBM-cl2}, for which $\Phi(u)< + \infty$. Using the properties of the mollifier sequence $(\rho_n)$, in particular, the mass of $\rho_n$ concentrates around 0,  and the Taylor expansion, one can prove \eqref{thm-BBM-cl2} if $u$ belonging to $C^\infty_c (\mR^N)$ in addition. Combining this with \eqref{thm-BBM-cl1}, one can derive \eqref{thm-BBM-cl2} for $u$ satisfying $\Phi(u) < + \infty$ after using the fact that, for $u_k, u \in L^p(\mR^N)$,  
\begin{multline*}
\left| \mathop{\iint}_{\mR^N \times \mR^N} \frac{|u_k(x)
- u_k(y)|^p}{|x-y|^p} \rho_n(|x-y|)\, dx \, dy - \mathop{\iint}_{\mR^N \times \mR^N} \frac{|u(x)
- u(y)|^p}{|x-y|^p} \rho_n(|x-y|)\, dx \, dy \right| \\[6pt]
\le C_p \mathop{\iint}_{\mR^N \times \mR^N} \frac{|(u_k - u)(x)
- (u_k-u) (y)|^p}{|x-y|^p} \rho_n(|x-y|)\, dx \, dy. 
\end{multline*}

It remains to prove that if the $\liminf_{n\to +\infty}$ of the LHS of \eqref{thm-BBM-cl1} is finite then $\Phi(u) < + \infty$. One way to prove this fact is to use the convexity of $t^p$ and the convolution suggested by Stein and presented in \cite{Brezis-02} as follows. Let $(\varphi_k)_{k \ge 1}$ be a smooth non-negative sequence of approximations to the identity such that $\supp \varphi_k \subset B_{1/k}$. Set 
$$
u_k = \varphi_k  * u \mbox{ for } k \ge 1. 
$$
Using Jensen's inequality, we derive that, for $n \ge 1$,  
$$
\mathop{\iint}_{\mR^N \times \mR^N} \frac{|u_k(x)
- u_k(y)|^p}{|x-y|^p} \rho_n(|x-y|)\, dx \, dy  \le \mathop{\iint}_{\mR^N \times \mR^N} \frac{|u(x)
- u(y)|^p}{|x-y|^p} \rho_n(|x-y|)\, dx \, dy \mbox{ for } k \ge 1. 
$$
Since $u_k \in C^\infty(\mR^N)$, one can show that, for $R>2$ and $0< r < 1$,  
$$
\lim_{n \to + \infty} \mathop{\iint}_{x  \in B_R, |y - x| < r} \frac{|u_k(x)
- u_k(y)|^p}{|x-y|^p} \rho_n(|x-y|)\, dx \, dy \ge K_{N, p} \int_{B_R} |\nabla u_k|^p \, dx. 
$$
Here and in what follows,  $B_R$ denotes the open ball in $\mR^N$ centered at $0$ and of radius $R$ for $R>0$.  This implies 
$$
\lim_{n \to + \infty} \mathop{\iint}_{\mR^N \times \mR^N} \frac{|u_k(x)
- u_k(y)|^p}{|x-y|^p} \rho_n(|x-y|)\, dx \, dy \ge K_{N, p} \int_{\mR^N} |\nabla u_k|^p \, dx. 
$$
We thus obtain 
\be \label{thm-BBM-p3}
+ \infty > \liminf_{n \to + \infty} \mathop{\iint}_{\mR^N \times \mR^N} \frac{|u(x)
- u(y)|^p}{|x-y|^p} \rho_n(|x-y|)\, dx \, dy \ge  K_{N, p} \int_{\mR^N} |\nabla u_k|^p \, dx \mbox{ for } k \ge 1. 
\ee
Since $k \ge 1$ is arbitrary,  we obtain $\Phi(u) < + \infty$. The details of these arguments can be found in \cite{BBM-01} and \cite{Brezis-02}. 


\medskip 
We next give a useful consequence of \Cref{thm-BBM}. 

\begin{proposition} \label{pro-BBM}
Let $N \ge 1$, $1 \le p < + \infty$, and $r > 0$, and let $u \in L^p(\mR^N)$. Then 
\begin{equation}\label{pro-BBM-cl1}
\lim_{\eps \to  0}  \mathop{\mathop{\iint}_{\mR^N \times \mR^N}}_{|x - y| < r} \frac{|u(x)
-u(y)|^p}{|x-y|^{p}} \frac{\eps}{|x-y|^{N-\eps}} \, dx \, dy =  K_{N, p} \Phi(u). 
\end{equation}
Consequently, if $u \in L^p(\mR^N)$ satisfies 
$$
\mathop{\iint}_{\mR^N \times \mR^N} \frac{|u(x)
-u(y)|^p}{|x-y|^{N+p}} \, dx \, dy <  + \infty, 
$$
then $u$ is constant. 
\end{proposition}


The reader can find many other interesting examples in \cite{BBM-01,Brezis-02,BSVY-222} on the way to determine whether or not a given function is constant. One of the motivations for determining whether or not a function is a constant is from the study of the Ginzburg-Landau equations, see, e.g., \cite{BBM-94}. Further properties related to the BBM formula can be found in \cite{BrNg-16,PS-17} (see also \cite{LS-11}) and the references therein. 

\begin{remark} \rm The limit of the term in the LHS of \eqref{pro-BBM-cl1} for $\eps \to 1_-$ was studied 
by Maz’ya and Shaposhnikova \cite{MS-02}. 
\end{remark}

\medskip 

We next discuss a related result of \Cref{thm-BBM} due to Nguyen \cite{NgSob1}, and  Bourgain and Nguyen \cite{BN-06}. 

\begin{theorem} [Bourgain \& Nguyen] \label{thm-I}
Let $N \ge 1$ and $1\le  p < + \infty$. The following two facts hold: 
\begin{enumerate}
\item[i)] For $p>1$ and  $u \in W^{1, p}(\mR^N)$, we have
\begin{equation} \label{thm-I-cl1-1}
\mathop{\mathop{\iint}_{\mR^N  \times \mR^N} }_{|u(x)-u(y)| > \delta}
\frac{\delta^p}{|x-y|^{N+p}} \, dx \, dy \le C_{N,p} \Phi(u)  \quad \mbox{ for } \delta > 0, 
\end{equation}
and 
\begin{equation} \label{thm-I-cl1-2}
\lim_{\delta \to 0_+} \mathop{\mathop{\iint}_{\mR^N  \times \mR^N} }_{|u(x)-u(y)| > \delta}
\frac{\delta^p}{|x-y|^{N+p}} \, dx \, dy =  \frac{1}{p}K_{N,p}  \Phi (u), 
\end{equation}
where $K_{N,p}$ is defined by \eqref{def-K}.


\item[ii)] If $u \in L^p(\mR^N)$ and $p \ge 1$, 
then 
\be \label{thm-I-cl2}
\Phi (u) \le C_{N, p}\liminf_{\delta \to 0_+}\mathop{\mathop{\iint}_{\mR^N  \times \mR^N} }_{|u(x)-u(y)| > \delta}
\frac{\delta^p}{|x-y|^{N+p}} \, dx \, dy. 
\ee
In particular, $u \in W^{1, p}(\mR^N)$ if $p>1$ and $u \in BV(\mR^N)$ if $p=1$ if the RHS of \eqref{thm-I-cl2} is finite. 
\end{enumerate}
\end{theorem}

\begin{remark} \rm The quantity given in the LHS of \eqref{thm-I-cl1-1} has its roots in estimates for the topological degree of continuous maps from a sphere into itself, which is due to Bourgain,  Brezis, and  Nguyen \cite{BBN-05} (see also \cite{BBM-04, BBM-05,Ng-Opt,Ng-refine}). 
\end{remark}

Assertion \eqref{thm-I-cl1-1} is based on the theory of maximal function. As in the analysis of \eqref{thm-BBM-cl1}, it suffices to consider the case $u \in C^\infty_c (\mR^N)$. Using spherical coordinates,  we have 
\be \label{thm-I-p0}
\mathop{\mathop{\iint}_{\mR^N  \times \mR^N} }_{|u(x)-u(y)| > \delta}
\frac{\delta^p}{|x-y|^{N+p}} \, dx \, dy = \mathop{\int_{\mR^N} \int_{\mS^{N-1}} \int_0^\infty }_{|u(x+ h \sigma) - u(x)| > \delta} \frac{\delta^p}{h^{p+1}} \, dh \, d \sigma \, dx. 
\ee
By a change of variables we obtain 
\be  
 \mathop{\int_{\mR^N} \int_{\mS^{N-1}} \int_0^\infty }_{|u(x+ h \sigma) - u(x)| > \delta} \frac{\delta^p}{h^{p+1}} \, dh \, d \sigma \, dx = \mathop{\int_{\mR^N} \int_{\mS^{N-1}} \int_0^\infty }_{\frac{1}{\delta h}|u(x+ \delta h \sigma) - u(x)| h > 1} \frac{1}{h^{p+1}} \, dh \, d \sigma \, dx. 
\ee
Since  
$$
\frac{1}{\delta}|u(x+ \delta h \sigma) - u(x)| = h \left|\int_0^1 \nabla u (x + t \delta h \sigma) \cdot \sigma \, dt \right|  
\le M (\nabla u, \sigma) (x) h, 
$$
where 
$$
M(\nabla u, \sigma)(x): = \sup_{t > 0} \fint_{0}^t  \Big| \nabla u (x + s \sigma) \cdot \sigma| \, ds. 
$$
It follows that 
\begin{multline} \label{thm-I-p1-*}
\mathop{\mathop{\iint}_{\mR^N  \times \mR^N} }_{|u(x)-u(y)| > \delta}
\frac{\delta^p}{|x-y|^{N+p}} \, dx \, dy \le  \mathop{\int_{\mR^N} \int_{\mS^{N-1}} \int_0^\infty }_{M (\nabla u, \sigma) (x) h > 1} \frac{1}{h^{p+1}} \, dh \, d \sigma \, dx \\[6pt]= \frac{1}{p}  \int_{\mS^{N-1}} \int_{\mR^N} |M(\nabla u, \sigma)|^p \, dx \, d \sigma. 
\end{multline}
Applying the theory of maximal functions, see, e.g., \cite{Stein-70}, we have 
\be \label{thm-I-p2-*}
 \int_{\mR^N} |M(\nabla u, \sigma)|^p \, dx  =  \int_{\mR_\sigma^\perp}  \int_{\mR_\sigma}|M(\nabla u, \sigma)|^p \, dx 
 \le c_p \int_{\mR_\sigma^\perp} \int_{\mR_\sigma} |\nabla u \cdot \sigma|^p \, dx  \le c_p \int_{\mR^N} |\nabla u|^p. 
\ee
Here, for $\sigma \in \mS^{N-1}$,  
$$
\mR_\sigma = \{ t \sigma; t \in \mR \} \quad \mbox{ and } \quad \mR_\sigma^\perp = \{ x \in \mR^{N-1}; x \cdot \sigma = 0 \}. 
$$
Assertion \eqref{thm-I-cl1-1} for $u \in C^\infty_c(\mR^N)$ now follows from \eqref{thm-I-p1-*} and \eqref{thm-I-p2-*}. 

\medskip 
The proof of \eqref{thm-I-cl1-2} for $u \in C^\infty_c(\mR^N)$ follows from \eqref{thm-I-p0-1} and the Taylor expansion. The arguments used to prove \eqref{thm-I-cl1-2} in the general case follows from this case and \eqref{thm-I-cl1-1} as in the analysis of the BBM formula. 

\begin{remark} \rm Part $i)$ was also obtained independently by Ponce and Van Schaftingen with a different proof as mentioned in \cite{NgSob1}.   
\end{remark}


We next briefly discuss the proof of \eqref{thm-I-cl2} under the stronger assumption in which the liminf is replaced by the limsup, i.e., 
\be \label{thm-I-cl2-2}
\Phi (u) \le C_{N, p}\limsup_{\delta \to 0}\mathop{\mathop{\iint}_{\mR^N  \times \mR^N} }_{|u(x)-u(y)| > \delta}
\frac{\delta^p}{|x-y|^{N+p}} \, dx \, dy. 
\ee
The ideas of the proof of \eqref{thm-I-cl2} under the assumption stated in \Cref{thm-I} will be later given in \Cref{sect-thm-neg-1p}. 

To be able to apply the arguments used in the proof of the BBM formula, one arranges to gain some convexity so that the arguments involving the convolution can be used. This can be done by an appropriate integration with respect to $
\delta $ as suggested in \cite{NgSob1}. Indeed, we first assume that $u \in L^\infty(\mR^N)$ and let $a$ be a positive constant which is greater than $2 \| u\|_{L^\infty(\mR^N)} + 1$.  
We have, by using Fubini's theorem,  
\be \label{thm-I-p0-1}
\int_0^a \eps \delta^{-1 + \eps} \mathop{\mathop{\iint}_{\mR^N  \times \mR^N} }_{|u(x)-u(y)| > \delta}
\frac{\delta^p}{|x-y|^{N+p}} \, dx \, dy = \mathop{\iint}_{\mR^N  \times \mR^N} \frac{\eps}{p+\eps}
\frac{|u(x) - u(y)|^{p+\eps}}{|x-y|^{N+p}} \, dx \, dy.
\ee 
Let $(\varphi_k)_{k \ge 1}$ be a smooth non-negative sequence of approximations to the identity such that $\supp \varphi_k \subset B_{1/k}$. Set 
$$
u_k = \varphi_k  * u \mbox{ for } k \ge 1. 
$$
Since, by Jensen's inequality,  
$$
\mathop{\iint}_{\mR^N  \times \mR^N} \frac{\eps}{p+\eps}
\frac{|u_k(x) - u_k(y)|^{p+\eps}}{|x-y|^{N+p}} \, dx \, dy \le \mathop{\iint}_{\mR^N  \times \mR^N} \frac{\eps}{p+\eps}
\frac{|u(x) - u(y)|^{p+\eps}}{|x-y|^{N+p}} \, dx \, dy, 
$$
it follows from \eqref{thm-I-p0-1} that 
\be \label{thm-I-p1}
\int_0^a \eps \delta^{-1 + \eps} \mathop{\mathop{\iint}_{\mR^N  \times \mR^N} }_{|u(x)-u(y)| > \delta}
\frac{\delta^p}{|x-y|^{N+p}} \, dx \, dy \ge \mathop{\iint}_{\mR^N  \times \mR^N} \frac{\eps}{p+\eps}
\frac{|u_k(x) - u_k(y)|^{p+\eps}}{|x-y|^{N+p}} \, dx \, dy. 
\ee 

Using the fact $u_k \in C^\infty(\mR^N)$, we obtain, as in the proof of \eqref{thm-BBM-p3},  
$$
\mathop{\iint}_{\mR^N  \times \mR^N} \frac{\eps}{p+\eps}
\frac{|u_k(x) - u_k(y)|^{p+\eps}}{|x-y|^{N+p}} \, dx \, dy \ge C_{N, p} \int_{\mR^N} |\nabla u_k|^p \, dx, 
$$
which yields, by \eqref{thm-I-p1},  
$$
\limsup_{\delta \to 0_+} \mathop{\mathop{\iint}_{\mR^N  \times \mR^N} }_{|u(x)-u(y)| > \delta}
\frac{\delta^p}{|x-y|^{N+p}} \, dx \, dy  \ge C_{N, p} \int_{\mR^N} |\nabla u_k|^p \, dx. 
$$
Since $k \ge 1$ is arbitrary, the conclusion follows. 

The proof in the general case, without the assumption $u \in L^\infty(\mR^N)$, follows from this case after noting that 
\be \label{thm-I-p1-2}
\mathop{\mathop{\iint}_{\mR^N  \times \mR^N} }_{|u(x)-u(y)| > \delta}
\frac{\delta^p}{|x-y|^{N+p}} \, dx \, dy \ge \mathop{\mathop{\iint}_{\mR^N  \times \mR^N} }_{|u_A(x)-u_A(y)| > \delta}
\frac{\delta^p}{|x-y|^{N+p}} \, dx \, dy,  
\ee
where 
$$
u_A = \min\{ \max\{u, - A\}, A\}. 
$$
Indeed, since $u_A \in L^\infty(\mR^N)$, we have 
\be \label{thm-I-p2}
\limsup_{\delta \to 0_+ }\mathop{\mathop{\iint}_{\mR^N  \times \mR^N} }_{|u_A(x)-u_A(y)| > \delta}
\frac{\delta^p}{|x-y|^{N+p}} \, dx \, dy \ge C_{N, p} \Phi(u_A). 
\ee
Combining \eqref{thm-I-p1-2} and \eqref{thm-I-p2} yields 
$$
\mathop{\mathop{\iint}_{\mR^N  \times \mR^N} }_{|u(x)-u(y)| > \delta}
\frac{\delta^p}{|x-y|^{N+p}} \, dx \, dy \ge C_{N, p} \Phi(u_A), 
$$
which implies \eqref{thm-I-cl2-2} after letting $A \to + \infty$.  

\medskip 
The setting considered in \Cref{thm-I} has been extended in several directions. See, e.g., \cite{NgSob2,BN-18,BVY-21,BSVY-24} where a more general functional was considered, see, e.g., \cite{NPSV-18,PSV-19} where a magnetic field was involved  (related properties for the BBM formula was also considered, see, e.g., \cite{NPSV-18,PSV-19,NS-19}). 

\medskip
One of these extensions, recently proposed by Brezis, Seeger, Van Schaftingen, and Yung \cite{BSVY-24}, will be now discussed.  
Set, for a measurable function $u$ defined in $\mR^N$,  
$$
Q_b u (x, y) = \frac{u(x) - u(y)}{|x - y|^{1 + b}} \mbox{ for } x, y \in \mR^N, 
$$
and, for a measurable set $E$ of $\mR^{N} \times \mR^{N}$, 
$$
\nu_{\gamma} (E) = \iint_{E} |x - y|^{-N+ \gamma} \, dx \, dy, 
$$
and 
$$
 E_{\lambda, b} (u)= \Big\{ (x, y); |Q_b u(x, y)| > \lambda \Big\}. 
$$

Given $\gamma \in \mR$ and $p \ge 1$, set 
$$
\Phi_\lambda(u) = \nu_{\gamma} \Big( E_{\lambda, \gamma/p} (u) \Big) \mbox{ for } \lambda > 0. 
$$
Given a measurable subset $\Omega$ of $\mR^N$ and a measurable function $u$ defined in $\Omega$, we also denote  
$$
 E_{\lambda, b, \Omega} (u)= \Big\{ (x, y) \in \Omega \times \Omega; |Q_b u(x, y)| > \lambda \Big\}. 
$$
and 
$$
\Phi_{\lambda, \Omega} (u) = \lambda^p \nu_{\gamma} \Big( E_{\lambda, \gamma/p, \Omega} (u) \Big). 
$$

One has 

\begin{theorem}[Brezis \& Seeger \& Van Schaftingen \& Yung] \label{thm-B} Let $N \ge 1$, $1 \le   p < + \infty$, $\gamma \in \mR \setminus \{0 \}$. The following facts hold: 
\begin{enumerate}
\item[i)] For $p>1$ and  $u \in W^{1, p}(\mR^N)$, we have
\begin{equation} \label{thm-B-cl1-1}
\Phi_\lambda (u) \le C_{N,p}  \Phi(u)  \quad  \mbox{ for } \lambda > 0, 
\end{equation}
and 
\begin{equation} \label{thm-B-cl1-2}
\lim_{\lambda \to 0_+} \Phi_\lambda (u) =  \frac{1}{|\gamma|}K_{N,p} \Phi (u) \mbox{ if } \gamma < 0, 
\end{equation}
and 
\begin{equation} \label{thm-B-cl1-3}
\lim_{\lambda \to + \infty} \Phi_\lambda (u) =  \frac{1}{|\gamma|}K_{N,p} \Phi(u) \mbox{ if } \gamma > 0, 
\end{equation}
where $K_{N,p}$ is defined by \eqref{def-K}.


\item[ii)] If $u \in L^p(\mR^N)$ and $p \ge 1$, then 
\be \label{thm-B-cl2}
\Phi(u) \le C \sup_{\lambda > 0} \Phi_\lambda (u). 
\ee
In particular, $u \in W^{1, p}(\mR^N)$ if $p>1$ and $u \in BV(\mR^N)$ if $p=1$ if the RHS of \eqref{thm-B-cl2} is finite. 
\end{enumerate}

\end{theorem}

\begin{remark} \rm For $\gamma = -p$, one has 
$$
\Phi_\delta (u) = \mathop{\mathop{\iint}_{\mR^N  \times \mR^N} }_{|u(x)-u(y)| > \delta}
\frac{\delta^p}{|x-y|^{N+p}} \, dx \, dy, 
$$
the quantity considered in \Cref{thm-I}. For $\gamma = N$, the quantity $\Phi_\lambda$ was previously considered by Brezis, Van Schaftingen, and Yung \cite{BVY-21}. 
A generalization in this case to
one-parameter families of operators in this case was considered by Domínguez and Milman \cite{DM-22}.
\end{remark}

\begin{remark} \rm It is worth noting that \eqref{thm-B-cl1-2} and \eqref{thm-B-cl1-3} fail for $p=1$ and for $u \in BV(\mR^N)$ or  even for $u \in W^{1, 1}(\mR^N)$. This has been noted by Brezis, Seeger, Van Schaftingen, and Yung  \cite{BSVY-24}. This phenomenon in the case $\gamma = -1$ was previously observed by Ponce, see also the work of Brezis and Nguyen \cite{BN-18}. 
\end{remark}

We next briefly discuss the proof of part $i)$.  The proof is closely related to the proof of \Cref{thm-I} mentioned previously and is different from the one given in \cite{BSVY-24}. We only discuss the case $N=1$. The general case follows similarly as in the proof of \Cref{thm-I}.  We begin with the proof of assertion \eqref{thm-B-cl1-1}. As in the proof of \eqref{thm-I}, it suffices to consider only the case $u \in C^\infty_c(\mR)$.  
We have 
\be \label{thm-B-pp0}
 \mathop{\mathop{\iint}_{\mR \times \mR}}_{\frac{|u(x) - u(y)|}{|x-y|^{1 + \frac{\gamma}{p}}} > \lambda} |x-y|^{-1 + \gamma} \, dx \, dy = 2  \mathop{\int_{\mR} \int_0^\infty}_{\frac{|u(x+ h) - u(h)|}{h^{1 + \frac{\gamma}{p}}} > \lambda} h^{-1 + \gamma} \, dh  \, dx. 
\ee
Since 
$$
|u(x+ h) - u(x)| = \left| \int_{x}^{x+ h} u'(s) \, ds \right| \le  \int_{x}^{x+ h} |u'(s)| \, ds \le M(u')(x) h,  
$$
where $M(u')(x) = \sup_{h > 0} \fint_{x}^{x+h} |u'(s)| \, ds$, it follows that 
\be
 \mathop{\int_{\mR} \int_0^\infty}_{\frac{|u(x+ h) - u(x)|}{h^{1 + \frac{\gamma}{p}}} > \lambda} h^{-1 + \gamma} \, dh  \, dx \le  \mathop{\int_{\mR} \int_0^\infty}_{\frac{M(u')(x)}{h^{\frac{\gamma}{p}}} > \lambda} h^{-1 + \gamma} \, dh  \, dx.
\ee
By considering $\gamma > 0$ and $\gamma < 0$ separately, one can show that 
\be
\lambda^p \mathop{\int_{\mR} \int_0^\infty}_{\frac{M(u')(x)}{h^{\frac{\gamma}{p}}} > \lambda} h^{-1 + \gamma} \, dh  \, dx \le C_\gamma \int_{\mR} \frac{1}{\lambda^p} |M(u')(x)|^p \, dx. 
\ee
Since, by the theory of maximal functions, 
$$
\int_{\mR} |M(u')(x)|^p \, dx \le c_p \int_{\mR} |u'|^p \, dx, 
$$
assertion \eqref{thm-B-cl1-1} follows for $u \in C^\infty_c(\mR)$. 

To prove \eqref{thm-B-cl1-2} and \eqref{thm-B-cl1-3}, one notes that, by a change of variables, with $\delta^{- \frac{\gamma}{p}} = \lambda$, 
$$
\lambda^p \mathop{\int_{\mR} \int_0^\infty}_{\frac{|u(x+ h) - u(x)|}{h^{1 + \frac{\gamma}{p}}} > \lambda} h^{-1 + \gamma} \, dh  \, dx =  \mathop{\int_{\mR} \int_0^\infty}_{\frac{|u(x+ \delta h) - u(x)|}{\delta h} h^{-\frac{\gamma}{p}} > 1} h^{-1 + \gamma} \, dh  \, dx,  
$$
which yields, by \eqref{thm-B-pp0}, with $\delta^{- \frac{\gamma}{p}} = \lambda$,  
\be \label{thm-B-p1}
\Phi_\lambda(u) =  \mathop{\int_{\mR} \int_0^\infty}_{\frac{|u(x+ \delta h) - u(x)|}{\delta h} h^{-\frac{\gamma}{p}} > 1} h^{-1 + \gamma} \, dh  \, dx,  
\ee

The proof of \eqref{thm-B-cl1-2} and  \eqref{thm-B-cl1-3} for $u \in C^\infty_c(\mR)$ follows from \eqref{thm-B-p1} and the Taylor expansion. The arguments in the general case follows from this case and \eqref{thm-B-cl1-1} as in the analysis of the BBM formula. 

The proof of part $ii)$ given in \cite{BSVY-24} is based on the BBM formula and the Lorentz duality, which in turn involves 
rearrangement properties.  Later, we state and prove a stronger version of part $ii)$ (see \Cref{sect-Sobolev}). Our proof is in the spirit of the one of \Cref{thm-I} and thus different from \cite{BSVY-24}. 


\medskip 
Brezis, Seeger, Van Schaftinger, and Yung \cite{BSVY-24} also proved that, for $p=1$,  the following result. 

\begin{proposition}[Brezis \& Seeger \& Van Schaftingen \& Yung]  \label{pro-B} Let $N \ge 1$, $p=1$, and $\gamma \in \mR \setminus \{0 \}$. Then 
\eqref{thm-B-cl1-2} holds for $u \in C^1_c(\mR^n)$ if $\gamma \not \in [-1, 0)$ and for $u \in W^{1, 1}(\mR^N)$ if $\gamma > 0$. We also have, for $\gamma \not \in [-1, 0]$ 
\begin{equation} \label{pro-B-cl1}
\Phi_\lambda (u) \le C_{N,1} \| \nabla u \|_{\cM},  \quad \forall \, \lambda > 0, 
\end{equation}
\end{proposition}

\begin{remark} \label{rem-gamma-0-1} \rm Brezis \& Seeger \& Van Schaftingen \& Yung \cite{BSVY-24} also showed that \eqref{pro-B-cl1} fails for $ \gamma \in [-1, 0)$. 
\end{remark}

\begin{remark} \rm The improvement of \eqref{thm-B-cl1-1} and \eqref{pro-B-cl1} in the Lorentz scale
for $\gamma = N$ was obtained by Brezis, Van Schaftinger, and Yung \cite{BVY-21b}. They also discussed there variants of  Gagliardo \& Nirenberg interpolation inequalities for functions in $W^{1,1}(\mR^N)$.  
\end{remark}

The proof of \eqref{pro-B-cl1} is based on the Vitali covering lemma in the case $\gamma > 0$ and involves a clever way to estimate double integrals in the case $\gamma < -1$ (and $N=1$), see \cite{BSVY-24}. 


\medskip 
Viewing \Cref{thm-B} and \Cref{pro-B}, the following questions are proposed, in the spirit of \Cref{thm-I}. 

\begin{question}\label{question-limsup} Let $N \ge 1$, $p \ge 1$, and  $\gamma \in \mR \setminus \{0\}$, and let $u \in L^p(\mR^N)$. Is it true that, for some positive constant $C_{N, p}$,  
$$
\limsup_{\lambda \to 0_+} \Phi_\lambda (u) \ge C_{N, p} \Phi (u) \mbox{ for } \gamma < 0
$$
and
$$
\limsup_{\lambda \to + \infty} \Phi_\lambda (u) \ge C_{N, p} \Phi (u) \mbox{ for } \gamma > 0. 
$$
\end{question}

A stronger version which have been proposed by Brezis \& Seeger \& Van Schaftingen \& Yung \cite{BSVY-24} is the following question. 

\begin{question} \label{question-liminf} Let $N \ge 1$, $p \ge 1$, and  $\gamma \in \mR \setminus \{0\}$, and let $u \in L^p(\mR^N)$. Is it true that, for some positive constant $C_{N, p}$,  
$$
\liminf_{\lambda \to 0_+} \Phi_\lambda (u) \ge C_{N, p} \Phi (u) \mbox{ for } \gamma < 0
$$
and
$$
\liminf_{\lambda \to + \infty} \Phi_\lambda (u) \ge C_{N, p} \Phi (u) \mbox{ for } \gamma > 0. 
$$
\end{question}

If the answer to  \Cref{question-liminf}  or \Cref{question-limsup} is positive, one then improves  \eqref{thm-B-cl1-1} and \eqref{pro-B-cl1}. 
Various results related to these questions will be stated in the next sections, \Cref{sect-Sobolev} - \Cref{sect-thm-neg-1p}. In \Cref{sect-Gamma}, we discuss about the Gamma-convergence of $\Phi_\lambda$,  and in \Cref{sect-Inequality} we discuss various inequalities related to $\Phi_\lambda$. 

\section{Characterizations of the Sobolev norms and the total variations} \label{sect-Sobolev}

In this section, we present various positive and negative results related to \Cref{question-limsup} and \Cref{question-liminf}. These results improvespart ii) of \Cref{thm-B} and its variants given in \Cref{pro-B} in the case $p=1$. Here are the main results in this direction. We begin with the case $\gamma < 0$. 


\begin{theorem} \label{thm-neg-p} Let $N \ge 1$, $1 \le p  < + \infty$, and $\gamma < -p$, and  let $u \in L^p(\mR^n)$. We have 
\be \label{thm-neg-p-cl}
\frac{K_{N, p}}{|\gamma|} \Phi(u)  \le \limsup_{\lambda \to 0_+} \Phi_\lambda (u).  
\ee
In particular, $u \in W^{1, p}(\mR^N)$ if $p> 1$ and $u \in BV(\mR^N)$ if $p=1$ if the RHS of \eqref{thm-neg-p-cl} is finite. 
\end{theorem} 

The proof of \Cref{thm-neg-p} is in the spirit of the one of \eqref{thm-I-cl2-2} and is given in \Cref{sect-thm-neg-p}. 


\begin{theorem} \label{thm-neg-1p} Let $N \ge 1$, $1 \le p  < + \infty$, and $-p \le \gamma \le - 1$, and let $u \in L^p(\mR^N)$. We have
\be \label{thm-neg-1p-cl}
C_{N, p} \Phi(u) \le  \liminf_{\lambda \to 0_+} \Phi_\lambda (u)
\ee
for some positive constant $C_{N, p}$. In particular, $u \in W^{1, p}(\mR^N)$ if $p> 1$ and $u \in BV(\mR^N)$ if $p=1$ if the RHS of \eqref{thm-neg-1p-cl} is finite. 
\end{theorem} 


As mentioned previously, the case $\gamma = - p$ is due to Bourgain and Nguyen \cite{BN-06}. The proof of \Cref{thm-neg-p} is in the same spirit and is presented in \Cref{sect-thm-neg-1p}. 






\medskip 
The case $-1 < \gamma < 0$ is quite special. We have the following result whose proof  is given in \Cref{sect-pro-CE}. 

\begin{proposition}\label{pro-CE} Let $N \ge 1$, $1 \le p  < + \infty$, and $-1 < \gamma < 0$. There exists $u \in BV(\mR^N)$ with compact support such that 
$$
\lim_{\lambda \to 0_+} \Phi_\lambda (u) = 0. 
$$
\end{proposition} 

\Cref{pro-CE} gives a negative answer to \Cref{question-limsup} and \Cref{question-liminf} in the case $-1 < \gamma < 0$. 
Nevertheless, we can prove the following result which improves part ii) of \Cref{thm-B} in the case $-1 < \gamma < 0$. 


\begin{theorem}\label{thm-pos-neg} Let $N \ge 1$, $1 \le p  < + \infty$, and $-1 < \gamma < 0$, and  let $u \in L^p(\mR^n)$.  Then 
\be \label{thm-pos-neg-cl}
 \frac{K_{N, p}}{\gamma + p } \Phi(u) \le  \limsup_{\lambda \to + \infty} \Phi_\lambda (u). 
\ee 
In particular, $u \in W^{1, p}(\mR^N)$ if $p> 1$ and $u \in BV(\mR^N)$ if $p=1$ if the RHS of \eqref{thm-pos-neg-cl} is finite. 
\end{theorem} 


We next deal with the case $\gamma > 0$. 
\begin{theorem}\label{thm-pos} Let $N \ge 1$, $1 \le p  < + \infty$, and $\gamma > 0$, and  let $u \in L^1_{\loc}(\mR^n)$.  Then 
\be \label{thm-pos-cl}
 \frac{K_{N, p}}{\gamma + p } \Phi(u) \le  \limsup_{\lambda \to + \infty} \Phi_\lambda (u). 
\ee 
In particular, $u \in W^{1, p}(\mR^N)$ if $p> 1$ and $u \in BV(\mR^N)$ if $p=1$ if $u \in L^p(\mR^N)$ and the RHS of \eqref{thm-pos-cl} is finite. 
\end{theorem} 

The proof of \Cref{thm-pos} and  \Cref{thm-pos-neg} is in the spirit of the one of \Cref{thm-I} mentioned in the introduction and is given at the same time in \Cref{sect-thm-pos-neg}. 

\medskip 
\Cref{thm-pos} is known in the case $p>1$ and partially known in the case $p=1$. In the case $\gamma = - N$ and $p \ge 1$, \Cref{thm-pos} was established by Poliakovsky \cite{Poliakovsky-22} with $C_{N, p}$ instead of $\frac{K_{N, p}}{\gamma + p}$ in the LHS of \eqref{thm-pos-cl}. A stronger result of \Cref{thm-pos} with $C_{N, p, \gamma}$, which explores as $\gamma \to 0_+$, instead of $\frac{K_{N, p}}{\gamma + p}$ in the LHS of \eqref{thm-pos-cl} but with liminf instead of limsup on the RHS was obtained by Gobbino and Picenni \cite{GB-25}. Their results do not imply ours in the case $p=1$ since \eqref{thm-B-cl1-3} does not hold for $p=1$. \Cref{thm-pos} for $p=1$ is sharp in the sense that the equality holds in \eqref{thm-pos-cl} when $u$ is the characteristic function of a bounded convex domain with smooth boundary, see \cite[Lemma 3.6]{BSVY-24} (see also \cite{Picenni-24}).




\section{Proof of \Cref{thm-neg-p}} \label{sect-thm-neg-p}
 The proof is based on the ideas of the convexity and the BBM formula as mentioned in the proof of \eqref{thm-I-cl2-2}. We first assume that $u \in L^\infty(\mR^N)$ and let $m \ge 1$ be such that 
\be
\| u\|_{L^\infty(\mR^N)} \le m. 
\ee

Fix $a > 0$ sufficiently small. Then 
\be \label{thm-neg-p-p0}
\limsup_{\lambda \to 0_+} \Phi_\lambda (u) \ge \limsup_{\eps \to 0_+} \int_0^a \frac{\eps}{\lambda^{1 - \eps}} \Phi_\lambda(u) \, d \lambda. 
\ee
We have, for $\eps > 0$,  
\begin{multline*}
\int_0^a \frac{\eps}{\lambda^{1 - \eps}} \Phi_{\lambda} (u) \, d \lambda = \int_0^a \frac{\eps}{\lambda^{1 - \eps}}  \lambda^p \mathop{\iint}_{\frac{|u(x) - u(y)|}{|x-y|^{1 + \frac{\gamma}{p}} } > \lambda} |x-y|^{-N + \gamma} \, dx \, dy \\[6pt]
= \mathop{\iint}_{\mR^N \times \mR^N}  |x-y|^{-N + \gamma} d x \, dy \int_0^a \eps \lambda^{p- 1 + \eps} \mathds{1}_{\lambda < \frac{|u(x) - u(y)|}{|x-y|^{1 + \frac{\gamma}{p}} }} \, d \lambda \\[6pt]
\ge  \mathop{\iint}_{\frac{|u(x) - u(y)|}{|x-y|^{1 + \frac{\gamma}{p}}} < a}|x-y|^{-N + \gamma}   \frac{\eps}{p+\eps}  \frac{|u(x) - u(y)|^{p+ \eps}}{|x-y|^{p+ \eps + \frac{\gamma (p+ \eps)}{p}}} d x \, dy. 
\end{multline*}
We thus obtain 
\be\label{thm-neg-p-p1}
\int_0^a \frac{\eps}{\lambda^{1 - \eps}} \Phi_{\lambda} (u) \, d \lambda 
\ge  \mathop{\iint}_{\frac{|u(x) - u(y)|}{|x-y|^{1 + \frac{\gamma}{p}}} < a}\frac{1}{p+\eps}   \frac{|u(x) - u(y)|^{p+ \eps}}{|x-y|^{p+ \eps}} \frac{\eps}{|x-y|^{N + \frac{\gamma \eps}{p}}}d x \, dy.
\ee

Set 
$$
\beta = 1 + \frac{\gamma}{p}. 
$$
Since $\gamma < -p$, it follows that $ \beta < 0.$  Denote
$$
r = (2m/a)^{1/\beta}.   
$$
Since $\beta < 0$, it follows that if $|x-y| < r$ then $\frac{|u(x) - u(y)|}{|x- y|^\beta} < \frac{2m}{r^\beta} = a$. 
We derive from \eqref{thm-neg-p-p1} that 
\be \label{thm-neg-p-p2}
\int_0^a \frac{\eps}{\lambda^{1 - \eps}} \Phi_{\gamma} (u) \, d \lambda 
\ge  \mathop{\iint}_{|x-y| < r} \frac{1}{p+\eps}   \frac{|u(x) - u(y)|^{p+ \eps}}{|x-y|^{p+ \eps}} \frac{\eps}{|x-y|^{N + \frac{\gamma \eps}{p}}}d x \, dy.
\ee

Let $(\varphi_k)$ be a smooth non-negative sequence of approximations to the identity such that $\supp \varphi_k \subset B_{1/k}$. Set 
$$
u_k = \varphi_k  * u \mbox{ for } k \ge 1. 
$$
Since $p + \eps >  1$, we have, by Jensen's inequality,
\begin{multline} \label{thm-neg-p-p3}
\mathop{\iint}_{|x-y| < r} \frac{1}{p+\eps}   \frac{|u(x) - u(y)|^{p+ \eps}}{|x-y|^{p+ \eps}} \frac{\eps}{|x-y|^{N + \frac{\gamma \eps}{p}}}d x \, dy \\[6pt] \ge \mathop{\iint}_{|x-y| < r} \frac{1}{p+\eps}   \frac{|u_k(x) - u_k(y)|^{p+ \eps}}{|x-y|^{p+ \eps}} \frac{\eps}{|x-y|^{N + \frac{\gamma \eps}{p}}}d x \, dy. 
\end{multline}

Combining  \eqref{thm-neg-p-p2} and  \eqref{thm-neg-p-p3} yields, for $k \ge 1$,  
\be
\int_0^a \frac{\eps}{\lambda^{1 - \eps}}  \Phi_{\gamma} (u) \, d \lambda \ge \mathop{\iint}_{|x-y| < r} \frac{1}{p+\eps}   \frac{|u_k(x) - u_k(y)|^{p+ \eps}}{|x-y|^{p+ \eps}} \frac{\eps}{|x-y|^{N + \frac{\gamma \eps}{p}}}d x \, dy. 
\ee
By letting $\eps \to 0_+$, and noting that $\gamma < 0$ and using \eqref{thm-neg-p-p0}, we obtain, as in the proof of \eqref{thm-BBM-p3},  
\be
\limsup_{\lambda \to 0} \Phi_\lambda (u) \ge \frac{1}{|\gamma|} K_{N,p} \int_{\mR^N} |\nabla u_k|^p \, dx. 
\ee
By taking $k \to + \infty$, we reach the conclusion when $u \in L^\infty(\mR^N)$. The proof in the general case follows from the case where $u \in L^\infty(\mR^N)$ as in the proof of \Cref{thm-I} after noting that 
$$
\Phi_\lambda (u) \ge \Phi_\lambda (u_A), 
$$
where 
$$
u_A = \min\{ \max\{u, - A\}, A\}. 
$$
The details are omitted. \qed



\section{Proof of \Cref{thm-pos-neg} and \Cref{thm-pos}} \label{sect-thm-pos-neg}

 The proof is again based on the ideas of the convexity and the BBM formula as mentioned in the proof of \eqref{thm-I-cl2-2} related to \Cref{thm-I}. We first assume that 
$$
\| u\|_{L^\infty} \le m. 
$$

Let $a > 0$ be sufficiently large. Then 
\be \label{thm-pos-neg-p0}
\limsup_{\lambda \to + \infty} \Phi_\lambda (u) \ge \limsup_{\eps \to 0_+} \int_a^\infty \frac{\eps}{\lambda^{1 + \eps}} \Phi_{\lambda} (u) \, d \lambda. 
\ee
We have 
\begin{multline*}
\int_a^\infty \frac{\eps}{\lambda^{1 + \eps}} \Phi_{\lambda} (u) \, d \lambda = \int_a^\infty \frac{\eps}{\lambda^{1 + \eps}}  \lambda^p \mathop{\iint}_{\frac{|u(x) - u(y)|}{|x-y|^{1 + \frac{\gamma}{p}} } > \lambda} |x-y|^{-N + \gamma} \, dx \, dy 
\\[6pt]
= \mathop{\iint}_{\mR^N \times \mR^N}  |x-y|^{-N + \gamma} d x \, dy \int_a^\infty \eps \lambda^{p- 1 - \eps} \mathds{1}_{\lambda < \frac{|u(x) - u(y)|}{|x-y|^{1 + \frac{\gamma}{p}} }} \, d \lambda. 
\end{multline*}
It follows that, for every $R> 2$ and $ 0< r < 1$, 
\begin{multline} \label{thm-pos-neg-p1}
\int_a^\infty \frac{\eps}{\lambda^{1 + \eps}} \Phi_{\lambda} (u) \, d \lambda \ge \mathop{\iint}_{x \in B_R; |x-y| < r}  |x-y|^{-N + \gamma} d x \, dy \int_a^\infty \eps \lambda^{p- 1 - \eps} \mathds{1}_{\lambda < \frac{|u(x) - u(y)|}{|x-y|^{1 + \frac{\gamma}{p}} }} \, d \lambda 
\\[6pt]
\ge  \mathop{\iint}_{x \in B_R; |x-y| < r}   |x-y|^{-N + \gamma}  \left( \frac{\eps}{p-\eps} \frac{|u(x) - u(y)|^{p- \eps}}{|x-y|^{p- \eps + \frac{\gamma (p- \eps)}{p}}} - \frac{\eps}{p-\eps} a^{p-\eps}  \right) d x \, dy 
\\[6pt]
= \frac{1}{p-\eps}\mathop{\iint}_{x \in B_R; |x-y| < r}     \frac{|u(x) - u(y)|^{p- \eps}}{|x-y|^{p- \eps}} \frac{\eps}{|x-y|^{N - \frac{\eps \gamma}{p}}}  d x \, dy \\[6pt]
 -  \frac{\eps a^{p-\eps}}{p-\eps}  \mathop{\iint}_{x \in B_R; |x-y| < r}  |x-y|^{-N + \gamma} \, dx \, dy. 
\end{multline}
We have 
\begin{multline}\label{thm-pos-neg-p2}
\frac{1}{p-\eps}\mathop{\iint}_{x \in B_R; |x-y| < r}    \frac{|u(x) - u(y)|^{p- \eps}}{|x-y|^{p -  \eps }}  \frac{\eps}{|x-y|^{N - \frac{\eps \gamma}{p}}}d x \, dy \\[6pt]
\ge \frac{1}{p-\eps} \frac{1}{|2m|^{\eps}}\mathop{\iint}_{x \in B_R |x-y| < r}     \frac{|u(x) - u(y)|^{p}}{|x-y|^{p}}  \frac{\eps}{|x-y|^{N - \frac{\eps \gamma}{p} - \eps}}d x \, dy. 
\end{multline}

Let $(\varphi_k)_{k \ge 1}$ be a smooth non-negative sequence of approximations to the identity such that $\supp \varphi_k \subset B_{1/k}$. Set 
$$
u_k = \varphi_k  * u \mbox{ for } k \ge 1. 
$$
We have, by Jensen's inequality,  
\begin{multline}\label{thm-pos-neg-p3}
 \frac{1}{p-\eps} \frac{1}{|2m|^{\eps}}\mathop{\iint}_{x \in B_R; |x-y| < r}    \frac{|u(x) - u(y)|^{p}}{|x-y|^{p - \eps}} \frac{\eps}{|x-y|^{N - \frac{\eps \gamma}{p} - \eps}} d x \, dy \\[6pt] \ge  \frac{1}{p-\eps} \frac{1}{|2m|^{\eps}} \mathop{\iint}_{x \in B_{R-1}; |x-y| < r}  \frac{|u_k(x) - u_k(y)|^{p}}{|x-y|^{p}} \frac{\eps}{|x-y|^{N - \frac{\eps \gamma}{p} - \eps}} d x \, dy. 
\end{multline}
Since, thanks to fact that $\gamma > -1$, 
\be
\lim_{\eps \to 0_+} \frac{\eps a^{p-\eps}}{p-\eps}  \mathop{\iint}_{x \in B_R; |x-y| < r}  |x-y|^{-N + \gamma} \, dx \, dy = 0, 
\ee
we derive from \eqref{thm-pos-neg-p1}, \eqref{thm-pos-neg-p2}, and \eqref{thm-pos-neg-p3} that 
$$
\limsup_{\eps \to 0_+} \int_a^\infty \frac{\eps}{\lambda^{1 - \eps}} \Phi_{\lambda} (u) d \lambda \ge \liminf_{\eps \to 0_+} \frac{1}{p-\eps} \frac{1}{|2m|^{\eps}}\mathop{\iint}_{x \in B_{R-1}; |x-y| < 1}    \frac{|u_k(x) - u_k(y)|^{p}}{|x-y|^{p}} \frac{\eps}{|x-y|^{N - \frac{\eps \gamma}{p} - \eps}}  d x \, dy. 
$$
Using \eqref{thm-pos-neg-p0}, we obtain  
\be
\limsup_{\lambda \to + \infty} \Phi_\lambda(u)  \ge \frac{K_{N,p}}{\gamma + p}  \int_{B_{R-1}} |\nabla u_k|^p \, dx. 
\ee
Since $R>2$ is arbitrary, we reach 
\be
\limsup_{\lambda \to + \infty} \Phi_\lambda(u) \ge \frac{K_{N,p}}{\gamma + p}  \int_{\mR^N} |\nabla u_k|^p \, dx. 
\ee
Letting $k \to + \infty$, we reach the conclusion when $u \in L^\infty(\mR^N)$. 

The proof in the general case follows from the case where $u \in L^\infty(\mR^N)$ as in the proof of \Cref{thm-I} after noting that 
$$
\Phi_\lambda (u) \ge \Phi_\lambda (u_A), 
$$
where 
$$
u_A = \min\{ \max\{u, - A\}, A\}. 
$$
The details are omitted.
\qed



\section{Proof of \Cref{pro-CE}} \label{sect-pro-CE}

This section consisting of two subsections is devoted to the proof of \Cref{pro-CE}. In the first subsection, we present state and prove a lemma which is used in the proof of \Cref{pro-CE}. The proof of \Cref{pro-CE} is given in the second subsection. 


\subsection{A useful lemma}

Here is the result of this section. 

\begin{lemma}\label{lem1} Let $1 \le p < + \infty$, $\beta \in \mR$,  and let $g$ be a measurable function on $\mR^N$. There exist positive constants $c_1, c_2$ independent of $g$ such that, for $\gamma \in \mR \setminus \{0 \}$, 
\begin{multline} \label{lem1-cl1}
\mathop{\int_{\mR^{N-1}} \int_{\mR} \int_{\mR}}_{\frac{|g(x_i', x_i) -
g(x_i', y_i)|}{|x_i - y_i|^{\beta}} > c_1 \lambda} |x_i - y_i|^{-1 + \gamma} \, dx_i \,
dy_i \, dx_i' \\[6pt]
\le c_2  \mathop{\int_{\mR^N} \int_{\mR^N}}_{\frac{|g(x)
- g(y)|}{|x-y|^\beta} > \lambda} |x-y|^{-N+\gamma} \, dx \, dy \quad
\forall \, \lambda>0, \mbox{ for } 1 \le i \le N,  
\end{multline}
and, for $\gamma < 1$, 
\begin{equation}\label{lem1-cl2}
\mathop{\int_{\mR^N} \int_{\mR^N}}_{\frac{|g(x)
- g(y)|}{|x-y|^\beta} > c_1 \lambda} |x-y|^{-N+\gamma} \, dx \, dy \le c_2  \sum_{i=1}^N \mathop{\int_{\mR^{N-1}} \int_{\mR} \int_{\mR}}_{\frac{|g(x_i', x_i) - g(x_i', y_i)|}{|x_i - y_i|^{\beta}} > \lambda} |x_i - y_i|^{-1 + \gamma} \, dx_i \,
dy_i \, dx_i', \forall \, \lambda>0. 
\end{equation}
\end{lemma}

Here and in what follows, for $1 \le i \le N$ and for a mesurable function $f$ defined in $\mR^N$, we denote
$$
f(x_i', x_i) = f (x) \mbox{ for } x = (x_1, \cdots, x_N) \in \mR^N
$$
where 
$$
x_i' = (x_1, \cdots, x_{i-1}, x_{i+1}, \cdots, x_N) \in \mR^{N-1}. 
$$

\begin{proof} We begin with the proof of \eqref{lem1-cl1}. For notational ease, we only consider the case $i=N$ and denote $x_N'= x'$ in this case. We have 
\begin{multline} \label{lem1-cl1-p1}
\mathop{\int_{\mR^{N-1}} \int_{\mR} \int_{\mR}}_{\frac{|g(x', x_N) -
g(x', y_N)|}{|x_N- y_N|^{\beta}} > c_1 \lambda} |x_N - y_N|^{-1 + \gamma} \, dx_N  \,
dy_N \, dx' 
\\[6pt]
=  \mathop{\int_{\mR^{N-1}} \int_{\mR} \int_{\mR}}_{\frac{|g(x', x_N) -
g(x', y_N)|}{|x_N- y_N|^{\beta}} > c_1 \lambda} \fint_{B_{
\mR^{N-1}}(x', |y_N - x_N |/2)} |x_N - y_N|^{-1 + \gamma} \, dz' \, dx_N  \,
dy_N \, dx'. 
\end{multline}
Here, for $z' \in \mR^{N-1}$ and $r>0$, we denote $B_{\mR^{N-1}} (z', r)$ the open ball in $\mR^{N-1}$ centered at $z' \in \mR^{N-1}$ and of radius $r>0$, and $\fint_{B_{\mR^{N-1}}(z', r)} = \frac{1}{|B_{\mR^{N-1}(z', r)}|} \int_{B_{\mR^{N-1}}(z', r)}$.

Since $|g(x', x_N) - g(x', y_N)| \le |g(x', x_N) - g(z, \frac{x_{N} + y_N}{2})| + |g(z, \frac{x_{N} + y_N}{2}) -
g(x', y_N)|$, we obtain
\begin{multline}\label{lem1-cl1-p2}
\mathop{\int_{\mR^{N-1}} \int_{\mR} \int_{\mR}}_{\frac{|g(x', x_N) -
g(x', y_N)|}{|x_N- y_N|^{\beta}} > c_1 \lambda} \fint_{B_{
\mR^{N-1}}(x', |y_N - x_N |/2)} |x_N - y_N|^{-1 + \gamma} \, dz' \, dx_N  \,
dy_N \, dx'
\\[6pt]
\le \mathop{\int_{\mR^{N-1}} \int_{\mR} \int_{\mR}}_{\frac{|g(x', y_N) - g(z', \frac{x_{N} + y_N}{2})|}{|x_N- y_N|^{\beta}} > c_1\lambda/2} \fint_{B_{
\mR^{N-1}(x', |y_N - x_N |/2)}} |x_N- y_N|^{-1 + \gamma} \, dz' \, dx_N  \,
dy_N \, dx' \\[6pt]
\mathop{\int_{\mR^{N-1}} \int_{\mR} \int_{\mR}}_{\frac{|g(x', x_N) - g(z', \frac{x_{N} + y_N}{2})|}{|x_N-  y_N|^{\beta}} > c_1\lambda/2} \fint_{B_{
\mR^{N-1}(x', |y_N - x_N |/2)}} |x_N- y_N|^{-1 + \gamma} \, dz' \, dx_N  \,
dy_N \, dx'. 
\end{multline}
We have, by a change of variables, for $c_1$ sufficiently large, 
\begin{multline}\label{lem1-cl1-p3}
\mathop{\int_{\mR^{N-1}} \int_{\mR} \int_{\mR}}_{\frac{|g(x', x_N) - g(z', \frac{x_{N} + y_N}{2})|}{|x_N -  y_N|^{\beta}} > c_1\lambda/2} \fint_{B_{
\mR^{N-1}}(x', |y_N - x_N |/2)} |x_N- y_N|^{-1 + \gamma} \, dz' \, dx_N  \,
dy_N \, dx' \\[6pt]
\le C \mathop{\iint_{\mR^{N} \times \mR^N}}_{\frac{|g(x) - g(y)|}{|x-y|^{\beta}} > \lambda}  |x-y|^{-N+ \gamma}\, dx \, dy,
\end{multline}
and 
\begin{multline}\label{lem1-cl1-p4}
\mathop{\int_{\mR^{N-1}} \int_{\mR} \int_{\mR}}_{\frac{|g(x', y_N) - g(z', \frac{x_{N} + y_N}{2})|}{|x_N- y_N|^{\beta}} > c_1 \lambda/2} \fint_{B_{
\mR^{N-1}}(x', |y_N - x_N |/2)} |x_N- y_N|^{-1 + \gamma} \, dz' \, dx_N  \,
dy_N \, dx'  \\[6pt] \le C \mathop{\iint_{\mR^{N} \times \mR^N}}_{\frac{|g(x) - g(y)|}{|x-y|^{\beta}} > \lambda}  |x-y|^{-N+ \gamma}\, dx \, dy.
\end{multline}
Combining \eqref{lem1-cl1-p1}, \eqref{lem1-cl1-p2}, \eqref{lem1-cl1-p3}, and \eqref{lem1-cl1-p4} yields \eqref{lem1-cl1}.    

We next give the proof of \eqref{lem1-cl2}. For notational ease, we only consider the case $N=2$. The general case follows similarly. Since 
$|g(x_1, x_2) - g(y_1, y_2)| \le |g(x_1, x_2) - g(x_1, y_2)| + |g(x_1, y_2) - g(x_2, y_2)|$, we derive that, for $c_1$ sufficiently large, 
\begin{multline} \label{lem1-cl2-p1}
\mathop{\iint_{\mR^{2} \times \mR^2}}_{\frac{|g(x_1, x_2) - g(y_1, y_2)|}{|x-y|^{\beta}} > c_1 \lambda}  |x-y|^{-2+ \gamma}\, dx \, dy \\[6pt]
\le \mathop{\iint_{\mR^{2} \times \mR^2}}_{\frac{|g(x_1, x_2) - g(x_1, y_2)|}{|x_2-y_2|^{\beta}} > \lambda}  |x-y|^{-2+ \gamma}\, dx \, dy + \mathop{\iint_{\mR^{2} \times \mR^2}}_{\frac{|g(x_1, y_2) - g(y_1, y_2)|}{|x_1 - y_1|^{\beta}} > \lambda}  |x-y|^{-2+ \gamma}\, dx \, dy.
\end{multline}
Since $\gamma < 1$, it follows that 
\be \label{lem1-cl2-p2} 
\mathop{\iint_{\mR^{2} \times \mR^2}}_{\frac{|g(x_1, x_2) - g(x_1, y_2)|}{|x_2-y_2|^{\beta}} > \lambda}  |x-y|^{-2+ \gamma}\, dx \, dy \\[6pt]
 \le C \int_{\mR} \mathop{\iint_{\mR \times \mR}}_{\frac{|g(x_1, x_2) - g(x_1, y_2)|}{|x_2-y_2|^{\beta}} > \lambda}  |x_2-y_2|^{-1+ \gamma}\, dx_1 \, dx_2 \, dy_2, 
\ee
and
\be \label{lem1-cl2-p3}
\mathop{\iint_{\mR^{2} \times \mR^2}}_{\frac{|g(x_1, y_2) - g(y_1, y_2)|}{|x_1 - y_1|^{\beta}} > \lambda}  |x-y|^{-2+ \gamma}\, dx \, dy \le C \int_{\mR} \mathop{\iint_{\mR^{2} \times \mR^2}}_{\frac{|g(x_1, y_2) - g(y_1, y_2)|}{|x_1 - y_1|^{\beta}} > \lambda}  |x_1-y_1|^{-1+ \gamma}\, dx_1 \, dy_1 \, d y_2. 
\ee 
Combining \eqref{lem1-cl2-p1}, \eqref{lem1-cl2-p2}, and \eqref{lem1-cl2-p3} yields \eqref{lem1-cl2}.   

\medskip 
The proof is complete. 
\end{proof}

\begin{remark} \rm The method used to
prove Lemma~\ref{lem1} is also applied in the theory of fractional Sobolev spaces (see, e.g., \cite[Chapter 7]{Adams-75}).
\end{remark}

\subsection{Proof of \Cref{pro-CE}}
Set
$$
\beta: = 1 + \gamma/p. 
$$
Then $\beta > 0$ since $-1 < \gamma < 0$.  Consider
$$
u = \mathds{1}_{Q} \mbox{ where } Q = (0, 1)^N \subset \mR^N. 
$$
By \Cref{lem1}, there exist two positive constants $c_1, c_2$ such that, for all $\lambda > 0$,  
\begin{multline}\label{pro-CE-p1}
\mathop{\int_{\mR^N} \int_{\mR^N}}_{\frac{|u(x)
- u(y)|}{|x-y|^\beta} > c_1 \lambda} |x-y|^{-N+\gamma} \, dx \, dy \le c_2  \sum_{i=1}^N \mathop{\int_{\mR^{N-1}} \int_{\mR} \int_{\mR}}_{\frac{|u(x_i', x_i) - u(x_i', y_i)|}{|x_i - y_i|^{\beta}} >  \lambda} |x_i - y_i|^{-1 + \gamma} \, dx_i \,
dy_i \, dx_i' \\[6pt]
=  c_2 N \mathop{\int_{\mR^{N-1}} \int_{\mR} \int_{\mR}}_{\frac{|u(x', x_N) - u(x', y_N)|}{|x_N - y_N|^{\beta}} >  \lambda} |x_N - y_N|^{-1 + \gamma} \, dx_N \,
dy_N \, dx', 
\end{multline}
where we denote $x_N'$ by $x'$ for notational ease. Since
\begin{multline*}
\left\{ (x', x_N, y_N) \in \mR^{N-1} \times \mR \times \mR ; \frac{|u(x', x_N) - u(x', y_N)|}{|x_N - y_N|^{\beta}} > \lambda \right\} \\[6pt]
=\left\{ (x', x_N, y_N) \in (0, 1)^{N-1} \times (0, 1) \times (\mR \setminus (0, 1)) ; |x_N - y_N|^{\beta} < 1/ \lambda \right\},
\end{multline*}
it follows that, for $\lambda^{1/\beta} < 1/4$,  
\be \label{pro-CE-p2}
\lambda^p \mathop{\int_{\mR^{N-1}} \int_{\mR} \int_{\mR}}_{\frac{|u(x', x_N) - u(x', y_N)|}{|x_N - y_N|^{\beta}} >  \lambda} |x_N - y_N|^{-1 + \gamma} \, dx_N \,
dy_N \, dx' \le C \lambda^p \int_0^1 x_N^{\gamma} \, dx_N \le C_{\gamma} \lambda^p.  
\ee
The conclusion now follows from \eqref{pro-CE-p1} and \eqref{pro-CE-p2}. \qed


