\section{Proof of \Cref{thm-neg-1p}} \label{sect-thm-neg-1p}

\subsection{A fundamental lemma}

We follows the approach of Bourgain and Nguyen \cite{BN-06}.  The following lemma is the key ingredient.

\begin{lemma}\label{lem-fund} Let $1\le p < + \infty$, $-p \le \gamma \le -1$, and let $f$ be a measurable function on a
bounded open nonempty interval $I$. Then
\begin{equation}\label{lem-fund-cl}
\dsp \mathop{\liminf}_{\lambda \to 0_+}
\Phi_{\gamma, I} (f)
 \ge c \frac{1}{| I|^{p-1}}(\esssup f - \essinf f)^{p},
\end{equation}
where $c=c_p$ is a positive constant depending only on $p$.
\end{lemma}
%Hereafter $|A|$ denotes Lebesgue measure of  measurable set $A \subset \mR$.
%\medskip

\begin{proof} Set 
$$
\beta = 1 + \gamma / p. 
$$
Then 
\be \label{lem-fund-beta}
0 \le \beta < 1. 
\ee
In what follows, we assume that 
\be \label{lem-fund-p0}
\mathop{\liminf}_{\lambda \to 0_+}
\Phi_{\gamma, I} (u) < + \infty 
\ee
since there is nothing to prove otherwise. 

\medskip 
The proof is now divided into two steps. 

\medskip 
\noindent \underline{Step 1.} Proof of \eqref{lem-fund-cl}  for $f \in
L^\infty(I)$.

\medskip 
By rescaling, we may assume $ I= (0,1)$. Denote $s_+ = \esssup f$ and  $s_- = \essinf f$. Rescaling $f$, one
may also assume
\begin{equation}\label{varf}
s_+ - s_- =1
\end{equation}
(unless $f$ is constant on $ I$ and there is nothing to prove in this case). 


Take $0< \delta < 1$ small enough to ensure that there are
(density) points $t_+$, $t_- \in [40 \delta, 1- 40\delta] \subset
[0,1]$ with
\begin{equation}\label{pointt}
\left\{\begin{array}{l} \dsp \left| \left[ t_+ - \tau, t_+ +
\tau\right] \cap \left[f
> \frac{3}{4}s_+ + \frac{1}{4}s_- \right]\right| > \frac{9}{5}
\tau,\\[6pt]
\dsp \left| \left[ t_- - \tau, t_- + \tau\right] \cap \left[f <
\frac{3}{4}s_- + \frac{1}{4}s_+ \right]\right| > \frac{9}{5} \tau,
\end{array}\right. \quad \forall  \, 0< \tau < 40 \delta.
\end{equation}
Take $K \in \ZZ_+$ such that $\delta < 2^{-K} \le 5 \delta/4$ and
denote
\begin{equation*}
J =\left\{ j \in \ZZ_+; \frac{3}{4}s_- + \frac{1}{4}s_+ < j 2^{-K}
< \frac{3}{4} s_+ + \frac{1}{4} s_- \right\}.
\end{equation*}
Then
\begin{equation}\label{cardJ}
|J| \ge 2^{K-1} - 2  \approx \frac{1}{\delta}.
\end{equation}
For each $j$, define the following sets
\begin{equation*}
\begin{array}{c}
A_j = \left\{ x \in [0,1]; \, (j-1)2^{-K} \le f(x) < j
2^{-K}\right\}, \quad  B_j = \bigcup_{j'< j}A_{j'} \quad
\mbox{and} \quad C_j = \bigcup_{j'>j}A_{j'},
\end{array}
\end{equation*}
so that $B_j \times C_j \subset \left[|f(x)-f(y)| \ge
2^{-K}\right] \subset \left[|f(x)-f(y)| > \delta\right]$.

Since the sets $A_j$ are disjoint, it follows from \eqref{cardJ}
that
\begin{equation}\label{cardG}
\mathrm{card}(G) \ge 2^{K-2} - 3 \approx \frac{1}{\delta},
\end{equation}
where $G$ is defined by
\begin{equation*}
G=\{j \in J; \, |A_j| < 2^{-K+2}\}.
\end{equation*}

For each $j \in G$, set $\lambda_{1,j} = |A_j|$ and  consider the
function $\psi_1(t)$ defined as follows
\begin{equation*}
\psi_1(t)=\left|[t- 4 \lambda_{1,j}, t + 4 \lambda_{1,j}] \cap B_j
\right|, \quad \forall \, t \in [40 \delta , 1- 40 \delta].
\end{equation*}
Then, from \eqref{pointt}, $\psi_1(t_+) < 4 \lambda_{1,j}$ and
$\psi_1(t_-) > 4 \lambda_{1,j}$. Hence, since $\psi_1$ is a
continuous function on the interval $[40 \delta, 1- 40 \delta ]$
containing the two points $t_+$ and $t_-$, there exists $t_{1,j}
\in [40 \delta, 1 - 40 \delta ]$ such that
\begin{equation}\label{deft1}
\psi_1(t_{1,j})= 4 \lambda_{1,j}.
\end{equation}
We have 
$$  
\mathop{\mathop{\iint}_{ I \times I}}_{|f(x)-
f(y)|> \delta} |x-y|^{-2} \, dx \, dy< + \infty
$$ 
by \eqref{lem-fund-p0} and the fact that $\beta \ge 0$ and $\gamma \le - 1$.  It
follows that $\left|[t_{1,j}- 4 \lambda_{1,j}, t_{1,j} + 4
\lambda_{1,j}] \cap A_j \right|>0$. Indeed, suppose $\left|[t_{1,j}- 4 \lambda_{1,j}, t_{1,j} + 4
\lambda_{1,j}] \cap A_j \right|=0$. Then
\begin{equation*}
\mathop{\mathop{\iint}_{x \in [t_{1,j}- 4 \lambda_{1,j}, t_{1,j} +
4 \lambda_{1,j}] \cap B_j}}_{y \in [t_{1,j}- 4 \lambda_{1,j},
t_{1,j} + 4 \lambda_{1,j}] \setminus B_j}\frac{1}{|x-y|^{2}} \, dx
\, dy  \le \mathop{\mathop{\iint}_{ I \times I}}_{|f(x)- f(y)|>
\delta} \frac{1}{|x-y|^{2}} \, dx \, dy < + \infty.
\end{equation*}
Hence $|[t_{1,j}- 4 \lambda_{1,j}, t_{1,j} + 4 \lambda_{1,j}] \cap
B_j| =0$ or $|[t_{1,j}- 4 \lambda_{1,j}, t_{1,j} + 4
\lambda_{1,j}] \setminus B_j| =0$. This is a
contradiction since $\psi_1(t_{1,j})=|[t_{1,j}- 4 \lambda_{1,j},
t_{1,j} + 4 \lambda_{1,j}] \cap B_j|=  4
\lambda_{1,j}$ (see \eqref{deft1}).

If $ \dsp \left|[t_{1,j}- 4 \lambda_{1,j}, t_{1,j} + 4
\lambda_{1,j}] \cap A_j \right| < \lambda_{1,j}/4,$ then take
$\lambda_{2,j}>0$ such that $\lambda_{1,j}/\lambda_{2,j} \in
\ZZ_+$ and
\begin{equation*}
\frac{\lambda_{2,j}}{2} < \left|[t_{1,j}- 4 \lambda_{1,j}, t_{1,j}
+ 4 \lambda_{1,j}] \cap A_j \right| \le \lambda_{2,j}.
\end{equation*}
Since $\dsp \left|[t_{1,j}- 4 \lambda_{1,j}, t_{1,j} + 4
\lambda_{1,j}] \cap A_j \right| < \lambda_{1,j}/4$, we infer that
$ \dsp
\lambda_{2,j} \le \lambda_{1,j}/2$.  

Set $E_{2,j} = [t_{1,j} - 4 \lambda_{1,j} + 4 \lambda_{2,j},
t_{1,j} + 4 \lambda_{1,j} - 4 \lambda_{2,j}]$ and consider the
function $\psi_2(t)$ defined as follows
\begin{equation*}
\psi_2(t)=\left|[t- 4 \lambda_{2,j}, t + 4 \lambda_{2,j}] \cap B_j
\right|, \quad \forall \, t \in E_{2,j}.
\end{equation*}

We claim that there exists $t_{2,j} \in E_{2,j}$ such that
$\psi_2(t_{2,j}) = 4 \lambda_{2,j}$.


To see this, we argue by contradiction. Suppose that $\psi_2(t)
\neq 4 \lambda_{2,j}$, for all $t \in E_{2,j}$. Since $\psi_2$ is
a continuous function on $E_{2,j}$, we assume as well that
$\psi_2(t)< 4 \lambda_{2,j}$, for all $t \in E_{2,j}$. Since
$\lambda_{1,j}/\lambda_{2,j} \in \ZZ_+$, it follows that
$\psi_1(t_{1,j}) < 4
\lambda_{1,j}$, hence we have a contradiction to \eqref{deft1}. Thus the claim is proved. 

It is clear that
\begin{equation*}
\mathop{\mathop{\iint}_{[t_{2,j}- 4 \lambda_{2,j}, t_{2,j} + 4
\lambda_{2,j}]^2}}_{|f(x)- f(y)|> \delta} \frac{1}{|x-y|^{2}} \,
dx \, dy \ge \mathop{\mathop{\iint}_{[t_{2,j}- 4 \lambda_{2,j},
t_{2,j} + 4 \lambda_{2,j}]^2} }_{x \in B_j; \, y \in C_j}
\frac{1}{|x-y|^{2}} \, dx \, dy \sge 1.
\end{equation*}

If $ \dsp \left|[t_{2,j}- 4 \lambda_{2,j}, t_{2,j} + 4
\lambda_{2,j}] \cap A_j \right| < \lambda_{2,j}/4, $
then take $\lambda_{3,j}$ ($\lambda_{3,j} \le \dsp \lambda_{2,j}/2$) and  $t_{3,j}$, etc. 
On the other hand, since $\dsp \mathop{\mathop{\iint}_{ I \times
 I}}_{|f(x)- f(y)|> \delta} \frac{1}{|x-y|^{2}} \, dx \, dy< +
\infty, $ we have
\begin{equation}\label{proborne}
\mathop{\limsup_{\mathrm{diam}(Q) \lr 0}}_{Q \mathrm{ :\, an \;
interval\; of \;}  I} \mathop{\mathop{\iint}_{Q \times Q}}_{|f(x)-
f(y)|> \delta} \frac{1}{|x-y|^{2}} \, dx \, dy =0.
\end{equation}
Thus, from \eqref{proborne} and the construction of $t_{k,j}$ and
$\lambda_{k,j}$, there exist $t_j \in [40 \delta, 1- 40 \delta]$
and $\lambda_j > 0$ ($t_j = t_{k, j}$ and $\lambda_j =
\lambda_{k,j}$ for some $k$) such that
\begin{equation}\label{measAj}
a) \, \left|[t_j- 4 \lambda_j, t_j + 4 \lambda_j] \cap B_j \right|
= 4 \lambda_j \quad \mbox{and} \quad b) \, \frac{\lambda_j}{4} \le
\left|[t_j- 4 \lambda_j, t_j + 4 \lambda_j] \cap A_j \right| \le
\lambda_j.
\end{equation}


Set $\lambda =    \inf_{j \in G} \lambda_j$ ($\lambda>0$ since $G$
is finite). Suppose $G=\bigcup_{i=1}^{n} I_m$, where $I_m$ is
defined as follows
\begin{equation*}
I_{m} = \Big\{ j \in G; \, 2^{m-1} \lambda \le \lambda_j < 2^{m}
\lambda \Big\}, \quad \forall \, m \ge 1.
\end{equation*}
Then it follows from \eqref{cardG} that
\begin{equation}\label{cardJ1m}
\sum_{m=1}^{ n }\card{I_{m}} \gtrsim \frac{1}{\delta}.
\end{equation}
For each $m$ ($1 \le m \le n$), since $A_j \cap A_k = \O$ for $j
\neq k$, it follows from (\ref{measAj}-b) that there exists $J_m
\subset I_m$ such that
\begin{equation}\label{defJm0}
 a) \, \card{J_m} \gtrsim \card{I_m} \quad \mbox{and} \quad
b)\,  |t_i - t_j| > 2^{m + 3} \lambda, \quad  \, \forall \, i, j
\in J_m.
\end{equation}
Then, from (\ref{defJm0}-b) and the definition of $I_m$,
\begin{equation}\label{defJm}
[t_i - 4 \lambda_i, t_i + 4 \lambda_i] \cap [t_j - 4 \lambda_j,
t_j + 4 \lambda_j] = \O, \quad \forall \, i, j \in J_m.
\end{equation}
Set $U_0 : = \O$ and
\begin{equation*}
\left\{
\begin{array}{l}  L_m = \dsp \big\{ j \in J_m; \, \big|[t_j - 4
\lambda_j, t_j + 4 \lambda_j] \setminus U_{m-1} \big| \ge 6
\lambda_j \big\},\\[6pt]
 U_m =  \big(\bigcup_{j \in L_m}[t_j - 4 \lambda_j, t_j + 4
\lambda_j]\big) \cup U_{m-1},\\[6pt]
a_m = \card{J_m} \quad \mbox{and}\quad b_m = \card{L_m},
\end{array} \right. \quad \mbox{for } m =1, 2, \dots, n.
\end{equation*}
From \eqref{defJm} and the definitions of $J_m$ and $L_m$,
\begin{equation*}
\frac{1}{4}2^{m -1} (a_m - b_m) \le \sum_{i=1}^{m-1} 2^{i} b_i
\end{equation*}
which shows that
\begin{equation*}
a_m \le b_m + 8 \sum_{i=1}^{m-1} 2^{(i-m)} b_i.
\end{equation*}
Consequently,
\begin{align*}
\sum_{m=1}^n a_m & \le \sum_{m=1}^n b_m + 8  \sum_{m=1}^n
\sum_{i=1}^{m-1} 2^{(i-m)} b_i =  \sum_{m=1}^n b_m + 8
\sum_{i=1}^n b_i \sum_{m=i+1}^{n}2^{(i-m)}.
\end{align*}
Since $\sum_{i=1}^\infty 2^{-i} =1$, it follows from from
\eqref{cardJ1m} and (\ref{defJm0}-a) that
\begin{equation*}
\sum_{m=1}^n b_m \ge \frac{1}{9}\sum_{m=1}^n a_m \sge
\frac{1}{\delta}.
\end{equation*}

Take $\lambda$ such that 
$$
\delta \ge \lambda (8 \delta)^\beta \ge \delta/2. 
$$
 We then have, since $\gamma \le -1$,  
\begin{multline*}
\mathop{\mathop{\iint}_{ I \times  I}}_{\frac{|f(x)- f(y)|}{|x-y|^\beta}> \lambda}
\lambda^p |x-y|^{-1 + \gamma}\, dx \, dy \ge \sum_{m=1}^n \sum_{j \in L_m}
\mathop{\mathop{\iint}_{\left([t_j - 4 \lambda_j, t_j + 4
\lambda_j] \setminus U_{m-1}\right)^2}}_{x \in B_j, \, y \in C_j}
\lambda^p |x-y|^{-1 + \gamma}\, dx \, dy \\[6pt]
\sge \sum_{m=1}^n
b_m \lambda^p \delta^{1+\gamma}  \sge \lambda^p \delta^{\gamma} \sge 1. 
\end{multline*}
which yields \eqref{lem-fund-cl} by \eqref{lem-fund-beta}. 

\underline{Step 2.} Proof of \Cref{lem-fund-cl} in the general case.

For $A> 0$, denote 
\begin{equation*}
f_A = (f \vee (-A))\wedge A,
\end{equation*}
then
\begin{equation*}
|f_A(x) - f_A(y)| \le |f(x) - f(y)| \mbox{ for } (x, y) \in I^2. 
\end{equation*}
Applying the result of Step 1 to the sequence $f_A$ and letting $A$
goes to infinity, we deduce that \eqref{lem-fund-cl} holds for any
measurable function $f$ on $ I$. 

\medskip 
The proof is complete. 
\end{proof}

\subsection{Proof of \Cref{thm-neg-1p}} 

\noindent {\it Step 1:} Proof of \Cref{thm-neg-1p} when $N=1$. 

\medskip Set
$\tau_{h}(u)(x) = \dsp \frac{u(x+h) - u (x)}{h}, \, \forall \, x
\in
\mR$, $0< h< 1$. For each $m \ge 2$, take $K\in \mR_+$ such that $Kh \ge m$, then
\begin{equation*}
\int_{-m}^m |\tau_h(u)(x)|^p \, dx \le \sum_{k = -K}^{K}\int_{k
h}^{(k+1)h } |\tau_h(u)(x)|^p \, dx.
\end{equation*}
Thus, since
\begin{equation*}
\int_a^{a + h } |\tau_{h}(u)(x)|^p \, dx \le \int_a^{a + h
}\frac{1}{h^p} |\mathop{\mathrm{ess \; sup} }_{x \in (a, a + 2h )}
u - \mathop{\mathrm{ess \; inf} }_{x \in (a, a + 2h ) } u|^p \,
dx,
\end{equation*}
it follows from \Cref{lem-fund} that, for some constant
$c=c_p>0$,
\begin{equation}\label{compactbound}
\int_{-m}^m |\tau_h(u)(x)|^p \, dx \le c  \liminf_{\lambda \to 0} \Phi_\lambda (u). 
\end{equation}
Since $m \ge 2$ is arbitrary, \eqref{compactbound} shows that
\begin{equation}\label{estth}
\int_{\mR} |\tau_h(u)(x)|^p \, dx \le c  \liminf_{\lambda \to 0} \Phi_\lambda (u). 
\end{equation}
Since \eqref{estth} holds for all $0< h < 1$, it follows that $\nabla 
\in L^p(\mR)$ for $p>1$ (see e.g. \cite[Chapter 8]{Brezis-FA}) and $\nabla u \in \cM$ (see, e.g., \cite{EGMeasure}). 
Moreover, \eqref{thm-neg-1p-cl} holds. 

\medskip 
\noindent {\it Step 2:} Proof of \Cref{thm-neg-1p} when $N \ge 2$. The result in this case is a consequence of \Cref{lem-fund}, \Cref{lem1}, and \cite[Proposition]{Ng-11}. As in the proof of the case $N=1$, one can show that $\mbox{ess} V(u, j)$ is bounded by $C \liminf_{\lambda \to 0} \Phi_\lambda (u)$ for $1 \le j \le N$ where $\mbox{ess} V (u, j)$ is the essential variation of $u$ in the $j$-th direction whose definition is given in \cite[Definition 5]{Ng-11}. The details are omitted. \qed




\section{Gamma-convergence} \label{sect-Gamma}

In this section, we discuss the $\Gamma$-convergence of the families of nonlocal functionals mentioned in the introduction.  Concerning the BBM formula, the following result was established by Ponce \cite{Ponce-04}. 

\begin{theorem}[Ponce] \label{thm-BBM-Gamma} Let $N \ge 1$, $1 \le  p < + \infty$, and let $(\rho_n)_{n \ge 1}$ be a sequence of non-negative  mollifiers.  Denote 
$$
J_n(u): = \mathop{\iint}_{\mR^N \times \mR^N} \frac{|u(x)
- u(y)|^p}{|x-y|^p} \rho_n(|x-y|)\, dx \, dy. 
$$
Then 
$$
J_n \mbox{ $\Gamma$-converges to } K_{N, p} \Phi \mbox{ in } L^p(\mR^N) \mbox{ as } n \to + \infty. 
$$
\end{theorem}

To establish \Cref{thm-BBM-Gamma}, one needs to show that, given $u \in L^p(\mR^N)$,  
\begin{enumerate}
\item[i)] There exists $(u_n) \to u$ in $L^p(\mR^N)$ such that
$$
\limsup_{n \to + \infty} J_n(u_n) \le K_{N, p} \Phi(u)
$$

\item[ii)] For all $(u_n) \to u$ in $L^p(\mR^n)$, we have 
$$
\liminf_{n \to + \infty} J_n(u_n) \ge K_{N, p} \Phi(u). 
$$
\end{enumerate}
Assertion $i)$ follows from \Cref{thm-BBM} by taking $u_n = u$ for $n \ge 1$. The proof of assertion $ii)$ can be done as follows; following the  arguments 
in the work of Brezis and Nguyen \cite{BrNg-16} where related results were also considered.  
Let $(\varphi_k)_{k \ge 1}$ be a smooth non-negative sequence of approximations to the identity such that $\supp \varphi_k \subset B_{1/k}$.  Since
$$
|a|^p - |b|^p \le C_p |a-b|^p, 
$$ 
it follows that, for $u, v \in L^p(\mR^N)$,  
\be
|J_n(u) - J_n(v)| \le C_{N, p} J_n(u-v). 
\ee
We derive that
\begin{multline}
|J_n(\phi_k*u) - J_n(\phi_k*u_n)| \le C_{N, p} J_n(\phi_k*u -\phi_k*u_n) \\[6pt]
\mathop{\le}^{\Cref{thm-BBM}} C_{N, p} \| \nabla \phi_k*u - \nabla \phi_k*u_n \|_{L^p(\mR^N)} \le  C_{N, p, k} \| u_n - u  \|_{L^p(\mR^N)}.  
\end{multline}
This implies 
\be
J_n(\phi_k*u) \le J_n(\phi_k* u_n) + C_{N, p, k} \| u_n - u  \|_{L^p(\mR^N)} \le J_n(u_n) + C_{N, p, k} \| u_n - u  \|_{L^p(\mR^N)}
\ee
By letting $n \to + \infty$, we obtain 
\be
K_{N, p} \Phi(\phi_k*u) \le \liminf_{n \to + \infty} J_n(u_n). 
\ee
By letting $k \to + \infty$, we obtain assertion $ii)$. 


\medskip 
We next discuss the setting given in \Cref{thm-I} and \Cref{thm-B}. Set  
\be
\ka_{N, p, \gamma} : = \left\{ \begin{array}{cl} \inf \liminf_{\lambda \to 0_+}  \Phi_\lambda(h_\lambda)
& \mbox{ if } \gamma < 0,  \\[6pt]
\inf \liminf_{\lambda \to + \infty}  \Phi_\lambda(h_\lambda) & \mbox{ if } \gamma >0, 
\end{array} \right. 
\ee
where the infimum is taken over all families of measurable functions \( (h_\lambda)_{\lambda \in \mR} \) defined on the open unit cube $Q = (0, 1)^N$ such that \( h_\lambda \to h(x) \equiv \frac{x_1 + \dots + x_N}{\sqrt{N}} \) in Lebesgue measure on \( Q \) as \( \lambda \to 0 \) for $\gamma < 0$ and as $\lambda \to + \infty$ for $\gamma > 0$. It is clear that $\ka_{N, p, \gamma} \ge 0$. 

\medskip 
The following result was obtained in \cite{Ng-07,Ng-11}. 

\begin{theorem}[Nguyen] \label{thm-Gamma-I} Let $N \ge 1$, $p \ge 1$, and $\gamma = -p$. Then $0 < \ka_{N, p, \gamma} < \frac{K_{N, p}}{p}$ and   
\be
\Phi_\lambda \mbox{ $\Gamma$-converges to } \ka_{N, \gamma, p} \Phi \mbox{ in } L^p(\mR^N) \mbox{ as } \lambda \to 0.  
\ee
\end{theorem}

\begin{remark} \rm As a consequence of \Cref{thm-Gamma-I}, the $\Gamma$-limit is strictly smaller than the pointwise limit viewing \Cref{thm-I}. This fact is quite surprising. The proof of the fact $\ka_{N, p, -p} > 0$ is based on the work of Bourgain and Nguyen \cite{BN-06}, see also the proof of \Cref{thm-neg-1p} in \Cref{sect-thm-neg-1p}. The proof of the fact $\ka_{N, p, - p} < \frac{K_{N, p}}{p}$ is based on the construction of an example. The proof of the $\Gamma$-convergence is based on essentially the monotonicity property of $\Phi_\lambda$ in the case $\gamma = -p$. The analysis is delicate but quite robust and can be extended to a more general functionals, which are different from $\Phi_\delta$, by Brezis and Nguyen \cite{BN-18}. In the one dimensional case, we can obtain even a more general result \cite{BrNg-20}. 
\end{remark}


\begin{remark} \rm  The explicit value of $\ka_{N, p, -p}$ was conjectured in \cite{Ng-07} for $N=1$. This value was later confirmed by Antonucci, Gobbino, Migliorini, and Picenni  \cite{AGMP-20} where the case $N \ge 2$ was also established. 
\end{remark}

\begin{remark} \rm $\Gamma$-convergence results for functionals reminiscent of $\Phi_\lambda$ in the case $\gamma = - p$ were studied in by Ambrosio, De Philippis, and Martinazzi \cite{ADM-11}. 
\end{remark}

We conjecture that 
\begin{conjecture} \label{conj-Gamma} Let $N \ge 1$, $p \ge 1$, and $\gamma \in \mR \setminus \{0 \}$. Then 
\be
\Phi_\lambda \mbox{ $\Gamma$-converges to } \ka_{N, p, \gamma} \Phi \mbox{ in } L^p(\mR^N) \mbox{ for } \lambda \to + \infty \mbox{ if $\gamma >0$} \mbox{ and for } \lambda \to 0 \mbox{ if } \gamma < 0. 
\ee
\end{conjecture}




Concerning \Cref{conj-Gamma}, we have the following results. 
%The second result is on the $\Gamma$-convergence of $\Phi_\delta$ for $- 1< \gamma < 0$. 

\begin{theorem} \label{thm-Gamma-Phi} Let $N \ge 1$, $p \ge 1$, and $-1 < \gamma < 0$. Then $\Phi_\delta$ $\Gamma$-converges to $0$ in $L^p (\mR^N)$. 
\end{theorem}

\begin{proof} It suffices to prove that for each $u \in L^p(\mR^N)$, there exists $(u_\lambda)_{\lambda \in (0, 1)}$ such that $u_\lambda \to u$ in $L^p(\mR^N)$ and  $\Phi_\lambda(u_\lambda) \to 0$ as $\lambda \to 0_+$. For notational ease, we only consider the case $N=2$. The general case follows similarly. 

To this end, we first show this for each $u \in C^\infty_c(\mR^2)$ with compact support.  Let $m \in \mN$ be such that 
$$
\supp u \subset [-m, m]^2. 
$$
For $k \in \mN$, denote 
$$
\cQ_k = \Big\{\mbox{ open cubes } Q_{i, j, k}: = ( i 2^{-k}, (i+1) 2^{-k}) \times (j2^{-k},  (j+1)2^{-k}) \subset \mR^2; i, j \in \mZ \Big\}
$$

Set 
$$
u_{k} (x) = \sum_{-m 2^k \le i, j \le m 2^k} v_{i, j, k}(x),  
$$
where 
$$
v_{i, j, k} = u(x_{i, j,k}) \mathds{1}_{Q_{i, j, k}} \mbox{ with } x_{i, j, k} = \Big( (i+1/2) 2^{-k}, (j+1/2) 2^{-k} \Big). 
$$
We have, for some positive constants $c_{k}$ independent of $g$,  
$$
\Phi_{c_{k}\lambda} (u_k) \le \sum_{-m 2^k \le i, j \le m 2^k} \Phi_{\lambda} (v_{i, j, k}). 
$$
Similar to the proof of \Cref{pro-CE}, we have 
$$
\lim_{\lambda \to 0_+} \Phi_{\lambda} (v_{i, j, k}) = 0. 
$$
We then derive that there exists a family $(u_\lambda)_{\lambda \in (0, 1)}$ such that $u_\lambda \to u$ in $L^p(\mR)$ and 
$$
\lim_{\lambda \to 0_+} \Phi_\lambda (u_\lambda) = 0. 
$$

Since for each $u \in L^p(\mR^N)$, there exist a sequence $(U_n) \subset C^\infty_c(\mR^N)$ such that $U_n \to u$ in $L^p(\mR^N)$.  The conclusion then follows from the case $u \in C^\infty_c(\mR^N)$ by a standard approximation. 
\end{proof}


\begin{remark}\rm
Brezis, Seeger, Van Schaftingen, and Yung \cite{BSVY-24} (see also \cite{Brezis-23}) asked whether the $\Gamma$-convergence holds in $L^1_{\loc}$ and the limit is $\Phi$ up to a positive constant. \Cref{thm-Gamma-Phi} gives a negative answer to this question in the case $-1 < \gamma < 0$. 
\end{remark}

\begin{remark} \rm  It would be interesting to revise the arguments in \cite{Ng-11,BN-18} to establish \Cref{conj-Gamma}. 

\end{remark}



\section{Inequalities related to the nonlocal functionals} \label{sect-Inequality}


Since $\Phi_\lambda$ characterize Sobolev norms and the total variations, it is natural to ask whether or not one can obtain  properties of Sobolev spaces using the information of  $\Phi_\lambda$ instead of the one of $\Phi$. We addressed this question in the case $\gamma = -p$ \cite{Ng-Sob-11}. In particular, it was shown \cite{Ng-Sob-11} that a variant of Poincar\'e's inequality holds in this case. 

\begin{theorem}[Nguyen] \label{thm-Poincare}
Let $N \ge 1$, $p \ge 1$,  and $u$ be a real measurable function defined in a ball $B
\subset \mR^N$.  We have
\begin{equation}\label{Poincare}
\int_B \int_B |u(x) - u(y)|^p \, dx \, dy \le C_{N, p} \left(
|B|^{\frac{N+p}{N}}\mathop{\int_B \int_B}_{|g(x) - g(y)|
> \delta} \frac{\delta^p}{|x-y|^{N+p}} \, dx \, dy + \delta^p
|B|^{2} \right). 
\end{equation}
\end{theorem}

The proof of \Cref{thm-Poincare} is based on the arguments of Bourgain and Nguyen \cite{BN-06} used in the proof of \Cref{lem-fund}, and the inequalities associated with $BMO$-functions due to John and Nirenberg \cite{JN-61}.  

\medskip 
Applying Theorem~\ref{thm-Poincare}, one can derive that  $u \in BMO(\mR^N)$, the space of all functions of bounded mean oscillation defined in $\mR^N$ if $u \in L^1(\mR^N)$  and $\Phi_\delta(u) < +\infty$  for $\gamma = -p$ and $p =N$,  and for some $\lambda >0$.
Moreover, there exists a positive constant $C$, depending only on $N$, such that, for $\gamma = - p$ and $p = N$, 
\begin{equation*}
|g|_{BMO} : = \sup_{B} \fint_B \fint_B |g(x) - g(y)| \, dx \, dy
\le C \left( \Phi_{\lambda}^\frac{1}{N} (u) + \lambda \right),
\end{equation*}
where the supremum is taken over all balls of $\mR^N$. In a joint work with Brezis \cite{BN-VMO-11}, we also show that if $u \in L^1(\mR^N)$ and $\Phi_\lambda (u) < + \infty$ with $\gamma =- p$ and  $p=N$ for all $\lambda >0$, then $g \in VMO(\mR^N)$, the spaces of all functions of vanishing mean oscillation. 
\medskip

Using \Cref{thm-Poincare}, we can establish variants of Sobolev's inequalities and Rellich-Kondrachov's compactness criterion \cite{Ng-Sob-11}. The proof of Rellich-Kondrachov's compactness criterion using \Cref{thm-Poincare} is quite standard. The idea of the proof of the Sobolev inequalities using the Poincar\'e inequalities is as follows. We first establish the Sobolev inequalities for the weak type from the Poincar\'e inequalities using covering lemmas. We then used the truncation arguments due to Mazda, see, e.g., \cite{MazyaSobolev}, and an inequality related to sharp maximal functions due to Fefferman and Stein, see, e.g., \cite{Stein-70}, to obtain the desired estimates from the weak-type ones. This kind arguments have been extended to obtain the full range of Gagliardo \& Nirenberg and Caffarelli \& Kohn \& Nirenberg interpolation inequalities associated with Coulomb-Sobolev spaces \cite{Ng-Mallick2}, a result obtained in a collaboration with Mallick. 


In another direction, one can also derive variants of the Hardy inequalities and the Caffarelli \& Kohn \& Nirenberg inequalities using the information of $\Phi_\lambda$ instead of $\Phi$ in the case $\gamma = -p$. This is given in a joint work with Squassina \cite{NS-Hardy-19}.  Interestingly, our proofs are quite elementary and mainly based on the Poincar\'e and Sobolev inequalities for an annulus; the integration-by-part arguments are not required. Our analysis is inspired from the harmonic one, nevertheless, instead of using dyadic decomposition for the frequency, we do it for the space variables. These arguments have also used by us to obtain the full range of the  Caffarelli \& Kohn \& Nirenberg inequalities for fractional Sobolev's spaces \cite{NS-18}, which generalizes the Caffarelli \& Kohn \& Nirenberg inequalities in \cite{CKN}. 


\medskip
In this direction, concerning $\Phi_\lambda$,  we ask the following question viewing \Cref{pro-CE}.  

\begin{question} Let $Q$ be a unit cube of $\mR^N$, and let $p \ge 1$, $\gamma \in \mR \setminus (-1, 0]$ be such that $\ka_{N, p, \gamma} > 0$. Is it true that 
$$
\iint_{Q\times Q} |u(x) - u(y)|^p \, dx \, dy \le C_{N, p} \Big( \Phi_\lambda (u) + \lambda^p \Big) \mbox{ for } u \in L^p(Q)? 
$$
\end{question}



