\end{align*}
where meanings of the symbols are as follows (see Figure \ref{fig:ex-dim2}).
\begin{itemize}
\item $A,B,C \in \mb{A}$ are the solutions of $\xi_2=\xi_3=0, \xi_3=\xi_1=0$ and $\xi_1=\xi_2=0$, respectively. 
\item $(BC), (CA)$ and $(AB)$ refer to the solution set $\{\xi_1=0,\xi_2,\xi_3>0\}$ etc., i.e. the open intervals with designated endpoints.
\item $(ABC)$ refers to the solution set $\{\xi_1,\xi_2,\xi_3 > 0 \}$, i.e. the triangle without boundary.
\item $\sto{\alpha}_j$'s and $\sto{\alpha}_{jl}$'s are the ``refined angles'' (precise definition covered in Definition \ref{def:sto-angle}), 
\begin{align*}
\sto{\alpha}_j & = \{(e^{\mathbf{i} \theta_j},\mathbf{i}e^{\mathbf{i}\theta_j})\} \ \sqcup\ \{(e^{\mathbf{i}t},\pm \mathbf{i}e^{\mathbf{i}t}): \theta_j < t < \theta_j+\pi \} \\
& \phantom{\qquad\qquad\qquad\qquad\qquad\qquad} \ \sqcup\ \{(e^{\mathbf{i}(\theta_j+\pi)},-\mathbf{i}e^{\mathbf{i}(\theta_j+\pi)})\}, \\
\sto{\alpha}_{jl} & = \{(e^{\mathbf{i} \theta_l},\mathbf{i}e^{\mathbf{i}\theta_l})\} \ \sqcup\ \{(e^{\mathbf{i}t},\pm \mathbf{i}e^{\mathbf{i}t}): \theta_l < t < \theta_j+\pi \} \\
& \phantom{\qquad\qquad\qquad\qquad\qquad\qquad} \ \sqcup\ \{(e^{\mathbf{i}(\theta_j+\pi)},-\mathbf{i}e^{\mathbf{i}(\theta_j+\pi)})\},
\end{align*}
(here we identify $(x,y)\in\mb{A}$ as complex number $x+\mathbf{i}y$) where $\theta_j$ is the angle between the line $\xi_j=0$ and the $x-$axis for $j=1,2,3$.
\end{itemize}

In other words, $\sto{P}$ occupies each of vertices $A,B$ and $C$ to the extent $\sto{\alpha}_{23},\sto{\alpha}_{31}$ and $\sto{\alpha}_{12}$, respectively, half of every position in each of sides $BC,CA$ and $AB$ (except its extremities) and whole of every position inside $ABC$. 
This contrasts with the triangle $\kappa^{(2)}(\sto{P}) = \{ \xi_1 \geq 0\} \cap  \{ \xi_2 \geq 0\} \cap  \{ \xi_3 \geq 0\} \subset \mb{A}$, which is the triangle with three vertices $A,B$ and $C$, corresponding to $\sto{P}$ in the conventional formulation.

