Now we state the main theorem, formalization of Question \ref{que:1}, of this article. 

\begin{thm}\label{thm:ref-poly}
Let $\mb{A}$ be an affine space and $\fP_k$ the set of $k-$polytopes in $\mb{A}$, where $k \leq \dim \mb{A}$. 
Likewise, let $\stok{\mb{A}}{k}$ be the $k-$refinement of $\mb{A}$ and $\sto{\fP}_k$ the set of refined $k-$polytopes in $\mb{A}$.
Then the closing map $\clok{k}:\stok{\mb{A}}{k} \rightarrow \mb{A}$ induces a one-to-one correspondence $\sto{\fP}_k\rightarrow\fP_k$, whose inverse $\sto{\ \ }:\fP_k \rightarrow \sto{\fP}_k$ satisfy the following properties for $P,Q \in \fP_k$.
\begin{enumerate}
\item $P \subset Q \quad \Leftrightarrow \quad \sto{P} \subset \sto{Q}$.
\item $\sto{P \cup Q} = \sto{P} \cup \sto{Q}$
\item $P \cap Q \in \fP_k \quad \Rightarrow \quad \sto{P \cap Q} = \sto{P} \cap \sto{Q}$.
\item $\mathrm{rank}(P \cap Q) < k \quad \Leftrightarrow \quad \sto{P} \cap \sto{Q} = \varnothing$. 
\end{enumerate}
\end{thm}

The key feature of refined polytopes appears in item 4 of Theorem \ref{thm:ref-poly}. 
When a rectangle is divided along its diagonal, the resulting two triangles share a side in conventional formulation, whereas they do not in refined formulation. 
Can we ``seamlessly'' divide a rectangle? Yes, we can, by refined formulation. 

\subsection{Proof of main theorem}

Proof of Theorem \ref{thm:ref-poly} is completed at the end of this subsection, after requisite lemmas are set up. 

\begin{lem}\label{lem:k-sto-struct}
For any refined $k-$polytope $\sto{P}$ of $\mb{A}$, we have
\begin{equation*}
\sto{P} = \bigsqcup_{\substack{\mb{B} \leq \mb{A}\\ \dim\mb{B}=k}} \sto{P} \cap \stok{\mb{B}}{k}
\end{equation*}
where the union is taken over all affine subspaces of dimension $k$ of $\mb{A}$. 
Moreover, $\sto{P} \cap \stok{\mb{B}}{k} = \varnothing$ for all but finitely many $\mb{B}$.
\end{lem}

\begin{proof}
The union is disjoint because for any two distinct affine subspaces $\mb{B}$ and $\mb{C}$ of dimension $k$ we have $\stok{\mb{B}}{k} \cap \stok{\mb{C}}{k} = \varnothing$. 
The remaining assertions are immediate from the definition of refined polytope.
\end{proof}

\begin{lem} \label{lem:step-by-step}
Let $\xi_1,\cdots,\xi_m$ be regular affine functionals on $\mb{A}$ and $(x;\rho) \in \bigcap_{i=1}^m \{\stok{\xi_i}{d} \succ 0 \}$. 
Then, for any positive $c \in \bF$, there exists positive scalars $c_1,\cdots,c_d \in \bF$, each less than $c$, such that $\xi_i(x+c_1\rho_1 + \cdots + c_d \rho_d) > 0$ for each $i$.
\end{lem}

\begin{proof}
The condition $\stok{\xi_i}{d} (x;\rho) \succ 0 $ forces one of two alternatives for each $i$, either $\xi_i(x) = 0,\ \xi_i(x+\rho_1) \geq 0$ or $\xi_i(x) > 0$. 
For the initial step, we choose $c_1 > 0$ such that $\xi_i (x+c_1 \rho_1) \geq 0$ for each $i$, especially $\xi_i(x+c_1 \rho_1) > 0$ if $\xi_i(x) > 0$. 
For the induction step, suppose that $c_1,\cdots,c_l$ are determined so that for each $i$, the sequence
\begin{equation*}
\xi_i(x),\ \xi_i(x+c_1 \rho_1),\ \cdots,\ \xi_i (x+c_1 \rho_1 + \cdots + c_l \rho_l)
\end{equation*}
 begin with (possibly no) zeros and the remaining are positive. 
This inductive hypothesis, with the condition $\stok{\xi_i}{d}(x;\rho) \succ 0$ implies that $\xi_i (x+c_1\rho_1 + \cdots + c_l \rho_l + \rho_{l+1}) < 0$ happens only when $\xi_i(x+c_1\rho_1 + \cdots + c_l \rho_l) > 0$.
Therefore by requiring
\begin{multline*}
c_{l+1} < 
\min\left\{ \left(1- \frac{\xi_i(x+c_1\rho_1 + \cdots+c_l \rho_l +\rho_{l+1})}{\xi_i(x+c_1\rho_1 + \cdots+c_l \rho_l )} \right)^{-1}  \in \bF : \right. \\
\left. i \text{ satisfies }\xi_i(x+c_1\rho_1 + \cdots+c_l \rho_l ) > 0 \right\}
\end{multline*}
the inductive hypothesis is maintained. 
Then the induction results in $\xi_i (x+c_1\rho_1 + \cdots + c_d \rho_d) \geq 0$ for each $i$. 
However, $\xi_i (x+c_1\rho_1 + \cdots + c_d \rho_d) = 0$ cannot hold because this implies $\xi_i(x+c_1 \rho_1 + \cdots + c_l \rho_l) = 0$ for all $l$, contradicting the regularity of $\xi_i$. 
\end{proof}

In the following lemma, $\interior{}$ refers to the concept of general topology, i.e. the largest open subset of a given subset in a topological space. 

\begin{lem} \label{lem:poly-vs-sto}
Assume $d > 0$. 
Let $\xi_1 ,\cdots , \xi_m$ be regular affine functionals on $\mb{A}$ and $P = \bigcap _{i=1}^m \{ \xi_i \geq 0 \}$.
\begin{enumerate}
\item If $\interior{P} \neq \varnothing$, then we have
\begin{equation*}\label{eq:poly-vs-sto}
\clok{d}\left( \bigcap_{i=1}^m \{\stok{\xi_i}{d} \succ 0 \} \right) = P.
\end{equation*}

\item If $\interior{P} = \varnothing$, then we have
\begin{equation*}
\bigcap_{i=1}^m \{\stok{\xi_i}{d} \succ 0 \} = \varnothing
\end{equation*}
\end{enumerate}
\end{lem}

\begin{proof}
\begin{enumerate}
\item From $\clok{d}(\{\stok{\xi_i}{d} \succ 0 \}) = \{ \xi_i \geq 0 \}$ the $\subset$ side is immediate. 
Conversely, if $\interior{P} \neq \varnothing$, then for any $x \in P$ we can choose $y\in \interior{P} - \{x\}$. 
This implies that $\xi_i(x) \geq 0$ and $\xi_i(x+(y-x)) > 0$, so that $\stok{\xi_i}{d} (x;\rho) \succ 0$ for any $\rho \in \stok{\mb{R}}{d-1}$ with $\rho_1 = \frac{y-x}{\|y-x\|}$ for each $i$. 
In other words, we have $(x;\rho) \in \bigcap_{i=1}^m \{\stok{\xi_i}{d} \succ 0 \}$ and consequently $x\in \clok{d} ( \bigcap_{i=1}^m \{\stok{\xi_i}{d} \succ 0 \}  )$. 

\item If $(x;\rho) \in \bigcap_{i=1}^m \{\stok{\xi_i}{d} \succ 0 \}$, then by Lemma \ref{lem:step-by-step} $y=x+c_1\rho_1+\cdots+c_d\rho_d$ for some $c_1,\cdots,c_d$ satisfies $\xi_i(y) > 0$ for each $i$, or equivalently $y \in \interior{P}$. 
\end{enumerate}
\end{proof}

\begin{lem}\label{lem:sto-int}
For every two disjoint refined $d-$polytope $\sto{P}$ and $\sto{Q}$, we have $\interior{\clok{d}(\sto{P})} \cap {\clok{d}(\sto{Q})} = {\clok{d}(\sto{P})} \cap \interior{\clok{d}(\sto{Q})} = \varnothing$. 
\end{lem}

\begin{proof}
Without loss of generality, we may assume that $\sto{P}=\bigcap_{i=1}^m \{ \stok{\xi_i}{d} \succ 0 \}$ and prove ${\clok{d}(\sto{P})} \cap \interior{\clok{d}(\sto{Q})} = \varnothing$. 
If $(x;\rho) \in \clok{d}(\sto{P})$, by Lemma \ref{lem:step-by-step} we can choose sufficiently small $c_1,\cdots,c_d \in \bF$ such that 
\begin{equation*}
y := x+c_1\rho_1 + \cdots + c_d \rho_d \in \interior{\clok{d}(\sto{P})},
\end{equation*}
or equivalently $\{y\} \times \stok{\mb{R}}{d-1} \subset \sto{P}$. 
This implies $y \not\in \clok{d}(\sto{Q})$ since we are assuming $\sto{P} \cap \sto{Q} = \varnothing$. 
Since the coefficients $c_1,\cdots,c_d \in \bF$ could be choosen arbitraily small, we have $x \not\in \interior{\clok{d}(\sto{Q})}$. 
\end{proof}

\begin{prop} \label{prop:1-1}
\begin{enumerate}
\item For any $k-$polytope $P$ in $\mb{A}$, there exists a refined $k-$polytope $\sto{P}$ in $\mb{A}$ such that $\clok{k}(\sto{P}) = P$. 
Conversely, for any refined $k-$polytope $\sto{P}$ in $\mb{A}$, $\clok{k}(\sto{P})$ is a $k-$polytope in $\mb{A}$. 

\item For two refined $k-$polytopes $\sto{P}$ and $\sto{Q}$, $\clok{k}(\sto{P}) \subset \clok{k}(\sto{Q})$ implies $\sto{P} \subset \sto{Q}$. 
In particular, $\clok{k}(\sto{P}) = \clok{k}(\sto{Q})$ implies $\sto{P} = \sto{Q}$. 
\end{enumerate}
\end{prop}

\begin{proof}
\begin{enumerate}
\item 
By item 1 of Lemma \ref{lem:poly-vs-sto}, every convex $k-$polytope $\bigcap_{i=1}^m \{\xi_i \geq 0\}$ in $\mb{B}$, for some affine $k-$subspace $\mb{B}$ of $\mb{A}$ and regular affine functionals $\xi_i$ on $\mb{B}$, is the image under $\clok{k}$ of refined $k-$polytope $\bigcap_{i=1}^m \{\stok{\xi_i}{k} \succ 0 \}$ in $\mb{B}$. 
The general case follows from taking finite union.

For the converse, we may assume first that $\sto{P}=\bigcap_{i=1}^m \{ \stok{\xi_i}{k} \succ 0 \} \subset \mb{B}$ and $\sto{P} \neq \varnothing$ for some affine $k-$subspace $\mb{B}$ of $\mb{A}$ and regular affine functionals $\xi_i$ on $\mb{B}$. 
From item 2 of Lemma \ref{lem:poly-vs-sto}, we must have $\interior{P} \neq \varnothing$ (here the interior is taken relative to $\mb{B}$) for $P = \bigcap_{i=1}^m \{ \xi_i \geq 0 \}$ and so $\clok{k}(\sto{P}) = P$ by item 1 of Lemma \ref{lem:poly-vs-sto}. 
Again, the general case follows from taking finite union.

\item Let $\sto{P}$ and $\sto{Q}$ be two refined $k-$polytopes in $\mb{A}$ such that $\sto{P} \not\subset \sto{Q}$. 
Then by Lemma \ref{lem:k-sto-struct} there exists an affine $k-$subspace $\mb{B}$ of $\mb{A}$ such that $\sto{P}_1 := \sto{P} \cap \stok{\mb{B}}{k} \not\subset \sto{Q}_1 := \sto{Q} \cap \stok{\mb{B}}{k}$. 
Since $\sto{S}_1:=\sto{P}_1 - \sto{Q}_1 \neq \varnothing$ is a nonempty refined $k-$polytope in $\mb{B}$ by Lemma \ref{lem:sto-alg}, we have $\clok{k}(\sto{P}_1) \supset \interior{\clok{k}(\sto{S}_1)} \neq \varnothing$ and $\interior{\clok{k}(\sto{S}_1)} \cap \sto{Q}_1 = \varnothing$ by Lemma \ref{lem:sto-int}, which forces $\clok{k}(\sto{P}) \not\subset \clok{k}(\sto{Q})$.
\end{enumerate}
\end{proof}


\begin{proof}[Proof of Theorem \ref{thm:ref-poly}]
By Proposition \ref{prop:1-1} the map $\sto{\ \ }$ is a one-to-one correspondence.
\begin{enumerate}
\item The $\Leftarrow$ side is immediate, and the $\Rightarrow$ side was proved in item 2 of Proposition \ref{prop:1-1}.

\item This follows from basic set-theory: $\kappa^{(k)}(\sto{P}\cup \sto{Q}) = \kappa^{(k)}(\sto{P}) \cup \kappa^{(k)}(\sto{Q})$.

\item Let $P = \bigcup_{i=1}^m P_i$ and $Q = \bigcup_{j=1}^l Q_j$ where each $P_i$ or $Q_j$ is convex and of rank $k$. 
For each pair $(i,j)$ such that $\interior{(P_i \cap Q_j)} \neq \varnothing$ or $P_i \cap Q_j = \varnothing$, we have $\sto{P_i \cap Q_j} = \sto{P}_i \cap \sto{Q}_j$ by Lemma \ref{lem:poly-vs-sto}. 
Then $P \cap Q$ having rank $k$ implies $P\cap Q = \bigcup_{\interior{(P_i \cap Q_j)} \neq \varnothing} P_i \cap Q_j$, whence 
\begin{align*}
\sto{P \cap Q} 
&= \bigcup_{\interior{(P_i \cap Q_j)} \neq \varnothing} \sto{P_i \cap Q_j}
= \bigcup_{\interior{(P_i \cap Q_j)} \neq \varnothing} \sto{P_i} \cap \sto{Q_j} \\
& \subset \left(\bigcup_{i=1}^m \sto{P_i}\right) \cap \left(\bigcup_{j=1}^l \sto{Q_j}\right) 
= \sto{P} \cap \sto{Q}
\end{align*}
The opposite inclusion follows from basic set theory:
\begin{equation*}
\clok{k}(\sto{P} \cap \sto{Q}) \subset \clok{k}(\sto{P}) \cap \clok{k}(\sto{Q}) = P \cap Q.
\end{equation*}
\item If $\sto{P} \cap \sto{Q} = \varnothing$, we have $(\sto{P} \cap \stok{\mb{B}}{k}) \cap (\sto{Q}  \cap \stok{\mb{B}}{k}) = \varnothing$ for each $\mb{B} \leq \mb{A}$ such that $\dim\mb{B} = k$. 
Then Lemma \ref{lem:sto-int} implies that 
\begin{align*}
(P\cap\mb{B}) \cap (Q\cap\mb{B}) 
& = (\interior{(P\cap\mb{B})} \sqcup \bdry{(P\cap\mb{B})}) \cap (\interior{(Q\cap\mb{B})} \sqcup \bdry{(Q\cap\mb{B})}) \\
& = \bdry{(P\cap\mb{B})} \cap \bdry{(Q\cap\mb{B})}.
\end{align*}
is of dimension $<k$ for each $\mb{B}$. 
This gives $\mathrm{rank}(P \cap Q) < k$. 

Conversely, if $\sto{P} \cap \sto{Q} \neq \varnothing$, then $P \cap Q = \clok{k}(\sto{P}) \cap \clok{k}(\sto{Q}) \supset \clok{k}(\sto{P} \cap \sto{Q})$ has dimension $k$. 
\end{enumerate}
\end{proof}

\section{Angles and curvilinear figures}

\subsection{Angles}

\begin{figure}
\centering
