        \State $T_q^{c\prime} \gets T_q^c \text{\bf if } \irowtile < \floor{\quadtileprime/T_q^c} \text{\bf else } \quadtileprime\bmod T_q^c$

        \For{$i \gets 0 \algTo \ceil{\pqty{T_q^{r\prime}T_{q,1}^{c\prime}}/(N_c\Nwi)}$}
          \State $i_{\mathrm{entry}} \gets $
          \If{$N_c\Nwi i + \Nwi\oclLid{0} + \oclLid{1} \geq T_q^{r\prime}T_q^{c\prime}$}
            \State continue
          \EndIf
          \State $i' \gets \floor{\left(N_c\Nwi i + \Nwi\oclLid{0} + \oclLid{1}\right) / T_q^{c\prime}}$
          \State $j' \gets \left(N_c\Nwi i + \Nwi\oclLid{0} + \oclLid{1}\right) \bmod T_q^{c\prime}$
          \State $I' \gets  T_q^{r\prime}\irowtile+i'$
          \State $J' \gets \iquadtile\quadtileprime +T_q^{c\prime}\icoltile + j'$
          \State{}
          \State $\Psi^{\mathrm{prftch}}_{1}[i', j'] \gets \Psi_1[I',J']$
          \State \vdots
          \State $\Psi^{\mathrm{prftch}}_{\NEval}[i',j'] \gets \Psi_{\NEval}[I',J']$
        \EndFor
        \State {}
        \State \Call{WorkGroupBarrier}{\null}\label{knlline:action.prl.barrrier_quad1}

        \State {}
        \For{$\iodof'' \gets 0 \algTo \ceil{T_q^{r\prime}/\Nwi}$}\label{knlline:action.prl.quad_start}
          \State $j\gets \Nwi j' + \oclLid{1} $
          \If{$j \geq T_q^{r\prime}$}\label{knlline:action.prl.pred2}
            \State continue
          \EndIf
          \For{$\iq'\gets 0 \algTo T_q^{c\prime}$}
            \State $\iq\gets \iq'+T_q^{c\prime}\icoltile$
            \State out$[j] \gets \text{out}[j] + \Psi^{\text{prftch}}_1[j, \iq'] \cdot e_1[\oclLid{0}, \iq]$
            \State \vdots
            \State out$[j] \gets \text{out}[j] + \Psi^{\text{prftch}}_{\NEval}[j, \iq'] \cdot e_{\NEval}[\oclLid{0}, \iq]$
          \EndFor %
        \EndFor\label{knlline:action.prl.quad_end}%
        \State {}
        \State \Call{WorkGroupBarrier}{\null}\label{knlline:action.prl.barrrier_quad2}
        \State {}
      \EndFor %
      \For{$i_W' \gets 0 \algTo \ceil{T_q^{r\prime}/\Nwi}$}
        \State $i_W\gets \Nwi i_W' + \oclLid{1} $
        \If{$j \geq T_q^{r\prime}$}
          \State continue
        \EndIf
        \State \Call{GlobalAtomicAdd}{$\text{out}^{\text{global}}[\iota_W[\icell,i_W]]$, $\text{out}[i_W']$}\label{knlline:action.prl.dof_scatter}
      \EndFor %
    \EndFor %
    \State {}
    \State \Call{WorkGroupBarrier}{\null}\label{knlline:action.prl.barrrier_quadtile_sync}
  \EndFor %
  \end{algorithmic}
\end{algorithm}


\subsubsection{Quantities of Interest}\label{sec:param_space_qois}

The transformed kernel in Algorithm~\ref{knl:action.prl} is parametric in
$\quadtile$, $T_e^r$, $\left\{T_{e,U_i}^c\right\}_{i\in\left\{1, \ldots,
N_U\right\}},$ $\left\{T_{e,V_i}^c\right\}_{i \in \left\{1, \ldots,
N_V\right\}}$, $T_q^r$, $T_q^c$ $N_c$, and $\Nwi$. These parameters enable
tailoring the implementation to a given variational form via auto-tuning.
To fully define the transformation space, it is necessary to fix the
allowable values for each parameter. This involves establishing bounds for the
parameters based on their impact on a set of metrics that significantly
influence the transformed kernel's performance. The metrics considered in our
analysis are as follows.


\begin{description}
  \item[Number of synchronizations] The number of times work-group wide
  barriers are executed within a work-group from start to end.
\begin{align}
  f(q) &= \underbrace{2\sum\limits_{i=1}^{N_U}\pqty{\ceil{\frac{q}{T_e^r}}\ceil{\frac{n_{U_i}}{T_{e,U_i}^c}}} + 2\sum\limits_{i=1}^{N_V}\pqty{\ceil{\frac{q}{T_e^r}}\ceil{\frac{n_{V_i}}{T_{e,V_i}^c}}}}_{\circledone} + \underbrace{2\ceil{\frac{n_W}{T_q^r}}\ceil{\frac{q}{T_q^c}}}_{\circledtwo} + \underbrace{2}_{\circledthree}\label{eq:nsync_fq}\\
  \Nsync &= \floor{\frac{N_q}{\quadtile}}f(\quadtile) + f(N_q \bmod \quadtile).
\end{align}
In the above equation, $f(q)$ represents the number of work-group wide barriers
executed in an iteration of $\iquadtile$ that computes the partial sum over $q$
quadrature nodes. As defined in~\eqref{eq:nsync_fq}, $f(q)$ is a sum of 3 terms, \circledone, \circledtwo and
\circledthree. \circledone is the number of barriers in the evaluation phase,
specifically the barriers on
lines~\ref{knlline:action.prl.barrrier_eval1},~\ref{knlline:action.prl.barrrier_eval2}
of Algorithm~\ref{knl:action.prl}. \circledtwo is the number of barriers in the
quadrature phase, i.e. the barriers on
lines~\ref{knlline:action.prl.barrrier_quad1},~\ref{knlline:action.prl.barrrier_quad2}
of Algorithm~\ref{knl:action.prl}. Finally, \circledthree is the number of barriers needed
for synchronization between the evaluation and quadrature phase
(line~\ref{knlline:action.prl.barrrier_eval_quad_sync} of
Algorithm~\ref{knl:action.prl}) and synchronization needed between iterations of
$\iquadtile$-loop (line~\ref{knlline:action.prl.barrrier_quadtile_sync} of
Algorithm~\ref{knl:action.prl}). If all other kernel features are kept the same,
having lower $\Nsync$ favors the kernel's performance.

\item[Local Memory Allocated] Aggregating all the local memory variables of
  the kernel in Algorithm~\ref{knl:action.prl}, we arrive at:
\begin{align}
\mathcal{L} = \underbrace{\max\pqty{\max\limits_{i=1}^{N_{U}}\pqty{N^{\text{deriv}}_{u_i} T_e^r T_{e,U_i}^c}, \max\limits_{i=1}^{N_V}\pqty{N^{\text{deriv}}_{v_i} T_e^r T_{e,V_i}^c}, \NEval T_q^r T_q^c}}_{\circledone} + \underbrace{N_c\quadtile\NEval}_{\circledtwo}.
\end{align}
In the equation above, $\mathcal{L}$ is the sum of two terms,
\circledone and \circledtwo. \circledone corresponds to the local memory
allocations for the prefetched reference matrices
(see~\eqref{eq:size_of_buffer_B}), while \circledtwo captures the local
memory allocations required to store the results of the evaluation phase, i.e.,
$\left\{e_i\right\}_{i \in \left\{1, \ldots, \NEval\right\}}$. It must be noted
that we count $\mathcal{L}$ in terms of number of floating point words which
depends on the floating point precision employed.

If all other kernel features are kept the same, having lower local memory
usage ($\mathcal{L}$) tends to improve the kernel's performance as discussed in
Section~\ref{sec:prftch_deriv_mtrx}.
\item[SIMD Efficiency ($\etasimd$)] GPUs execute instructions in a SIMD
fashion. This implies that if the work-group size is not a multiple of
device's SIMD width (i.e. 32), an inefficiency arises from masked vector
lanes. We capture this effect using the following quantity which we call
SIMD efficiency:
\begin{align}
\etasimd = \frac{N_c\Nwi}{32\ceil{\pqty{N_c\Nwi}/32}}.
\end{align}
If all other kernel features are kept the same, having higher \(\etasimd\) is
favorable for higher performance.
\item[Predication Efficiency ($\etapred$)] Loop tiling inherently leads to conditionals, like
lines~\ref{knlline:action.prl.pred1},~\ref{knlline:action.prl.pred2} of
Algorithm~\ref{knl:action.prl}, and results in diverged execution within a
work-group. On a GPU's SIMD-like execution model, this leads to an a loss of efficiency due to
masked vector lanes. We characterize this inefficiency as the ratio of usable floating point
operations performed to the number of floating point operations that would have been performed
had there been no masking. Consequently, we define
\begin{align}
  \etapred = \frac{\text{Ops}^{\text{usable\quad\;}}}{\text{Ops}^{\text{performed}}},
\end{align}
where $\text{Ops}^{\text{usable}}$ is the total number of floating-point
operations in the untransformed kernel (Algorithm~\ref{knl:action.vanilla})
particularly in the small matrix-vector multiplies for a single cell.
Aggregating the multiply and add operations from the evaluation and quadrature
phase, we obtain
\begin{equation}\label{eq:ops_usable}
  \text{Ops}^{\text{usable}} = \sum\limits_{i=1}^{N_U}\pqty{2\cdot N^{\text{deriv}}_{u_i}  Q n_{U_i}} + \sum\limits_{i=1}^{N_V}\pqty{2\cdot N^{\text{deriv}}_{v_i}  Q n_{U_i}} + 2\cdot \NEval Q n_W.
\end{equation}
$\text{Ops}^{\text{performed}}$ is the number of corresponding floating point
operations performed for a single cell by $\Nwi$ work-items in
Algorithm~\ref{knl:action.prl}. After accounting for the tiling of the quadrature loop
by $T^Q$, we get
\begin{align}
\text{Ops}^{\text{performed}} = \floor{\frac{Q}{\quadtile}}f_e(\quadtile) + f_e(Q \bmod \quadtile) + \floor{\frac{Q}{\quadtile}}f_q(\quadtile) + f_q(Q \bmod \quadtile),
\end{align}
where $f_e(x)$ is the number of floating point operations performed in the
evaluation phase for $x$ quadrature nodes being evaluated in the
$\iquadtile$-loop, and, $f_q(x)$ is the number of floating point
operations performed in the quadrature phase for $x$ quadrature nodes being
evaluated in the $\iquadtile$-loop. Aggregating the floating point operations
from
lines~\ref{knlline:action.prl.eval_start}--\ref{knlline:action.prl.eval_end} of
Algorithm~\ref{knl:action.prl}, we obtain
\begin{equation}
  f_{e}(x) = \left(\Nwi\floor{\frac{x}{T_e^r}}\ceil{\frac{T_e^r}{\Nwi}} + \Nwi\ceil{\frac{x \bmod T_e^r}{\Nwi}}\right) \left(\sum\limits_{i=1}^{N_U} N^{\text{deriv}}_{u_i}n_{U_i} + \sum\limits_{i=1}^{N_V}N^{\text{deriv}}_{v_i}n_{V_i}\right).\\
\end{equation}
Similarly, aggregating the floating point operations from lines~~\ref{knlline:action.prl.quad_start}--\ref{knlline:action.prl.quad_end} of Algorithm~\ref{knl:action.prl}, we obtain
\begin{align}
  f_{q}(x) = \floor{\frac{n_W}{T_q^r}}\Nwi\ceil{\frac{T_q^r}{\Nwi}}\NEval  T_q^r x + \Nwi\ceil{\frac{n_W \bmod T_q^r}{\Nwi}} \NEval x.\\
\end{align}


If all other kernel features are invariant, higher $\etapred$ typically
corresponds to a better-performing kernel.
\item \emph{Local Memory Aliasing Efficiency}: From our discussion in
Section~\ref{sec:map_to_gpu_axes}, we use the same local memory buffer for the
tiled prefetches in both the evaluation and quadrature stages. However, the tile
size choices might lead to inefficient use of the allocated buffer space. We
define this efficiency factor as the ratio of the minimum of the allocated local
memory being used for an evaluation phase for the prefetched reference
derivative matrices to the size of the allocated local memory for the prefetched
tiles. Hence we say:
\begin{equation}
  \eta_{\text{alias}} = \frac{\min\pqty{\min\limits_{i=1}^{N_U}\pqty{N^{\text{deriv}}_{u_i} T_e^rT_{e,U_i}^c}, \min\limits_{i=1}^{N_V}\pqty{N^{\text{deriv}}_{v_i} T_e^rT_{e,V_i}^c}, \NEval T_q^rT_q^c}}{\max\pqty{\max\limits_{i=1}^{N_U}\pqty{N^{\text{deriv}}_{u_i} T_e^rT_{e,U_i}^c}, \max\limits_{i=1}^{N_V}\pqty{N^{\text{deriv}}_{v_i} T_e^rT_{e,V_i}^c}, \NEval T_q^rT_q^c}}.
\end{equation}

If all other kernel features are kept the same, higher $\eta_{\text{alias}}$ is
generally favorable for kernel performance as it allows for better usage of the
allocated local memory which competes with the device's latency hiding
capabilities.
\end{description}


\subsubsection{Parameter Search Space}\label{sec:param_search_space}
In this section, we use the quantities of interest defined in
Section~\ref{sec:param_space_qois} to describe our parameter space.
We limit the size of the search space mainly through the enforcement
of four constraints:

\begin{enumerate}[leftmargin=20ex, label={\it Constraint \arabic*. }]
  \item \begin{align}
  \quadtile & \in \Bqty{Q, \ceil{\frac{Q}{2}}, \ceil{\frac{Q}{3}}, \ldots} \\
  T_e^r     & \in \Bqty{\quadtile, \ceil{\frac{\quadtile}{2}}, \ceil{\frac{\quadtile}{3}}, \ldots} \\
  T_{e,U_k}^c & \in \Bqty{n_{U_k}, \ceil{\frac{n_{U_k}}{2}}, \ceil{\frac{n_{U_k}}{3}}, \ldots} \\
  T_{e,V_k}^c & \in \Bqty{n_{V_k}, \ceil{\frac{n_{V_k}}{2}}, \ceil{\frac{n_{V_k}}{3}}, \ldots} \\
  T_q^r     & \in \Bqty{n_W, \ceil{\frac{n_W}{2}}, \ceil{\frac{n_W}{3}}, \ldots} \\
  T_q^c     & \in \Bqty{\quadtile, \ceil{\frac{\quadtile}{2}}, \ceil{\frac{\quadtile}{3}}, \ldots}
\end{align}

\item \(\eta_{\text{alias}} \geq 0.8\)
\item \(\etasimd \geq 0.97\)
\item $N_c\Nwi \leq 256$
\end{enumerate}


By applying constraints (1) and (2), we can enumerate all possible tile sizes
within the parameter space. Similarly, constraints (3) and (4) allow for the
enumeration of all valid $N_c$-$\Nwi$ pairs. Constraint (1) has been chosen to
only include tile sizes that allocate the minimum amount of local memory for a
given $\Nsync$. An illustration of constraint (1) is provided in
Fig.~\ref{fig:tile_constraint_1} as an example.

Furthermore, considering our preference for higher values of $\etasimd$ and
$\eta_{\text{alias}}$, we impose lower bounds on these quantities. The specific
lower bounds, currently set at 0.8 and 0.97, can be adjusted to either expand
or reduce the size of the parameter space.

