 Since $\mathcal{R}\otimes\mathcal{C}\otimes\mathcal{C}\otimes\mathcal{T}$ is closed under $\Der$ and $\bar{\pi}$ acts as the identity on it, $\bar{\mathcal{C}}$-linearity of $\Der$ implies $\bar{\pi}\circ\Der=\Der$ on $\bar{\pi}(\mathrm{IDR}(\mathcal{R}))$.
 Factoring by $\ker(\bar{\pi})=J_1$, we obtain a bijective integro-differential ring homomorphism $\psi:\mathrm{IDR}(\mathcal{R})/J_1\to\mathcal{R}\otimes\mathcal{D}\otimes\mathcal{C}_2\otimes\mathcal{T}$ satisfying $\psi(\pi(f))=\bar{\pi}(f)$.
\end{proof}

Note that in general, i.e.\ if the effect of factoring out constants is not essentially limited to $\mathcal{C}_1$ as in the lemma, the multiplication \eqref{eq:GeneralizedShuffle} on $\mathcal{C}\otimes\mathcal{C}_1\otimes\mathcal{C}_2\otimes\mathcal{T}$ will need to be adapted as well.
In particular, this happens not only in the situation treated in Section~\ref{sec:closure}, but also when we recover the construction of the free integro-differential algebra (with weight $0$) presented in \cite{GuoRegensburgerRosenkranz} as follows.
\begin{remark}\label{rem:IDA}
 To obtain the free integro-differential algebra $\mathrm{IDA}(\mathcal{R})^*$ of \cite{GuoRegensburgerRosenkranz}, we additionally need to impose multiplicativity of evaluation.
 Explicitly, it suffices to factor out from $\mathrm{IDR}(\mathcal{R})$ the ideal generated by the following constants.
 \[
  \{1\otimes(\ep(\Q\Der{fg})-\ep(f)\ep(g))\otimes1\otimes\et\ |\ f,g \in \mathcal{R}_\mathrm{J}\}, \quad\{1\otimes\ep(f\otimes{t})\otimes1\otimes\et\ |\ f \in \mathcal{R}_\mathrm{J},t \in \widetilde{\mathcal{T}}\},
 \]
 \[
  \{1\otimes1\otimes\ep(s\odot{t})\otimes\et\ |\ s,t \in \widetilde{\mathcal{T}}\}
 \]
 Effectively, this eliminates the involved definition of $(\mathcal{C}_2\otimes\mathcal{T},+,\cdot)$ from the construction of $\mathrm{IDR}(\mathcal{R})$, as it corresponds to replacing $(\mathcal{C}_2\otimes\mathcal{T},+,\cdot)$ by the shuffle algebra $(\mathcal{T},+,\shuffle)$ in addition to replacing $\mathcal{C}_1$ by an isomorphic copy of $\mathcal{R}$.
\end{remark}


\subsection{The free integro-differential ring on a commutative quasi-integro-differential ring}
\label{sec:ExtQIDR}

In Section~\ref{sec:free}, we considered a commutative differential ring that admits a quasi-integration and we constructed the free commutative integro-differential ring on it.
In the construction below, we consider a commutative differential ring with a distinguished quasi-integration instead.
To this end, we introduce the concept of a (not necessarily commutative) quasi-integro-differential ring.
Note that the following definition and lemma are a generalization of Definition~\ref{def:IDR} and Lemma~\ref{lem:IDRvariety}, no longer requiring the derivation to be surjective and turning integration into quasi-integration.

\begin{definition}\label{def:quasiIDR}
 Let $(\mathcal{R},\Der)$ be a differential ring with ring of constants $\mathcal{C}$.
 Let $\Q:\mathcal{R}\to\mathcal{R}$ be a quasi-integration.
 Then, $(\mathcal{R},\Der,\Q)$ is called a \emph{quasi-integro-differential ring} and we denote the two induced projectors onto the kernels of $\Der$ and $\Q$ by
 \[
  \E:=\id-\Q\Der \quad\text{and}\quad \T:=\id-\Der\Q.
 \]
\end{definition}
Quasi-integro-differential rings form a variety based on the following lemma whose proof is exactly as the proof of Lemma~\ref{lem:IDRvariety}.
\begin{lemma}\label{lem:QIDRvariety}
 Let $(\mathcal{R},\Der)$ be a differential ring with constants $\mathcal{C}$.
 Let $\Q:\mathcal{R}\to\mathcal{R}$ be a map such that $\Der\Q\Der=\Der$ and $\Q\Der\Q=\Q$ and define $\E:=\id-\Q\Der$.
 Then, $\Q$ is $\mathcal{C}$-linear if and only if it is additive and satisfies $(\E{g})\Q{f}=\Q(\E{g})f$ and $(\Q{f})\E{g}=\Q{f}\E{g}$ for all $f,g\in\mathcal{R}$.
\end{lemma}
\begin{proof}
 If $\Q$ is $\mathcal{C}$-linear, then the other properties immediately follow from $\Der\E=0$.
 Conversely, $\mathcal{C}$-linearity follows since $\E{g}=g$ holds for $g\in\mathcal{C}$.
\end{proof}

The differential rings which the construction in Section~\ref{sec:free} is based on are precisely those arising as reducts of commutative quasi-integro-differential rings.

\begin{remark}\label{rem:restriction}
In an integro-differential ring $(\mathcal{S},\Der,\Int)$ with evaluation $\E$, we can obtain a quasi-integration $\Q$ on a differential subring $\mathcal{R}\subseteq\mathcal{S}$ as follows, if $\E\mathcal{R}\subseteq\mathcal{R}$ and $\Der\mathcal{R}$ has a complement in $\mathcal{R}$ over $\E\mathcal{R}$.
For any $\mathcal{R}_\T$ that is such a complement of $\Der\mathcal{R}$ in $\mathcal{R}$, we can define $\Q{f}:=\Int(f-f_\T)$ for any $f\in\mathcal{R}$, where $f_\T\in\mathcal{R}_\T$ such that $f-f_\T\in\Der\mathcal{R}$.
Then, $\Q$ is $\mathcal{C}$-linear and we have $\Q\Der\Q{f}=\Q\Der\Int(f-f_\T)=\Q(f-f_\T)=\Q{f}$.
By $\Q\Der{f}=\Int\Der{f}$, we obtain $\Der\Q\Der{f}=\Der\Int=\Der{f}$ and $\Q\mathcal{R}=\Q\Der\mathcal{R}=\Int\Der\mathcal{R}=(\id-\E)\mathcal{R}\subseteq\mathcal{R}$.
So, $\Q$ is indeed a quasi-integration on $\mathcal{R}$ and the induced projector $\T{f}=f-\Der\Int(f-f_\T)=f_\T$ maps onto $\mathcal{R}_\T$.
Note that, in this construction, the induced projector $\id-\Q\Der$ is the restriction of the evaluation $\E$ from $\mathcal{S}$ and that $\Q\mathcal{R}=\Int\Der\mathcal{R}$ too is independent of the choice of $\mathcal{R}_\T$.
\end{remark}

For the rest of this section, we fix a commutative quasi-integro-differential ring $(\mathcal{R},\Der,\Q)$ and construct the free commutative integro-differential ring $\mathrm{IDR}_\Q(\mathcal{R})$ on it that respects $\Q$.
Recall that this can be done by factoring $\mathrm{IDR}(\mathcal{R})$ by the integro-differential ideal generated by the constants \eqref{eq:constgenerators} in order to make $\Int$ agree with $\Q$ on $\Der\mathcal{R}$.
Lemma~\ref{lem:FactorConst} already allows to construct $\mathrm{IDR}_\Q(\mathcal{R})$ equivalently by restricting to a subring of $\mathrm{IDR}(\mathcal{R})$ instead of taking a quotient, but the integration operation is still defined as projection of the integration of the full ring $\mathrm{IDR}(\mathcal{R})$.
In contrast, we now present a more direct construction of $(\mathrm{IDR}_\Q(\mathcal{R}),\Der,\Int)$ entirely without first constructing $\mathrm{IDR}(\mathcal{R})$ and performing underlying operations there.
In short, compared to the construction of $\mathrm{IDR}(\mathcal{R})$ in Section~\ref{sec:free}, we only need to modify the definitions of $M_1$ and $\Int$ slightly, as predicted by Lemma~\ref{lem:FactorConst}.

First, we replace the module $M_1$ defined in \eqref{eq:DefM1} by the submodule
\begin{equation}\label{eq:DefM1tilde}
 \widetilde{M}_1:=\mathcal{R}_\mathrm{J}\otimes\widetilde{\mathcal{T}}
\end{equation}
of it, which consequently leads to the definitions
\begin{align}
 \widetilde{\mathcal{C}}_1 &:= \Sym(\ep(\widetilde{M}_1))\label{eq:DefC1tilde}\\
 \mathrm{IDR}_\Q(\mathcal{R}) &:= \mathcal{R}\otimes\widetilde{\mathcal{C}}_1\otimes\mathcal{C}_2\otimes\mathcal{T}\label{eq:DefIDRQ}\\
 \widetilde{\mathcal{C}} &:= \mathcal{C}\otimes\widetilde{\mathcal{C}}_1\otimes\mathcal{C}_2\otimes\mathcal{C}\et \subseteq \mathrm{IDR}_\Q(\mathcal{R})\label{eq:DefCtilde}
\end{align}
instead of \eqref{eq:DefC1}, \eqref{eq:DefIDR}, and \eqref{eq:Cbar}, respectively.
Together with the other definitions and results of Section~\ref{sec:AlgebraStructure}, this completely explains $\mathrm{IDR}_\Q(\mathcal{R})$ as a $\mathcal{C}$-algebra.

Second, we modify the definition \eqref{eq:DefInt} of the integration by dropping from the $n=0$ case the term that involves an element of $M_1$ which lies in the complement of $\widetilde{M}_1$.
More explicitly, for $n\in\mathbb{N}$, $c=c_1\otimes{c_2}\in\widetilde{\mathcal{C}}_1\otimes\mathcal{C}_2$, and pure tensors $f\in\mathcal{R}_\T^{\otimes{n}}$, we use the formula
\begin{equation}\label{eq:DefIntQ}
 \Int(f_0\otimes{c}\otimes{f}):=
 \begin{cases}(\Q{f_0})\otimes{c}\otimes{f}+1\otimes{c}\otimes((f_0-\Der\Q{f_0})\otimes{f})&n=0\\[\smallskipamount]
 (\Q{f_0})\otimes{c}\otimes{f}-1\otimes(c_1{\cdot}\ep((\Q{f_0})\otimes{f}))\otimes{c_2}\otimes\et-{}\\\quad{}-\Int(((\Q{f_0})f_1)\otimes{c}\otimes{f_2^n})+1\otimes{c}\otimes((f_0-\Der\Q{f_0})\otimes{f})&n>0\end{cases}
\end{equation}
instead of \eqref{eq:DefInt}.
Together with definitions \eqref{eq:DefDeriv} and \eqref{eq:DefEval}, the lemmas stated in Section~\ref{sec:DerInt} remain true in $\mathrm{IDR}_\Q(\mathcal{R})$, except for formula \eqref{eq:Evaluation} being replaced by \eqref{eq:EvaluationExt} below.

For the sake of completeness, we explicitly state the analogs of the results in Section~\ref{sec:DerInt} and we mention what changes in their proofs, before we formulate and prove the main results Theorem~\ref{thm:IDRext} and Corollary~\ref{cor:universalExt} about $(\mathrm{IDR}_\Q(\mathcal{R}),\Der,\Int)$.
First, on $(\mathrm{IDR}_\Q(\mathcal{R}),\Der,\Int)$, $\Der$ and $\Int$ are $\widetilde{\mathcal{C}}$-linear, since \eqref{eq:linDer} and \eqref{eq:linInt} hold for all $f_0\in\mathcal{R}$, $c_1,d_1\in\widetilde{\mathcal{C}}_1$, $c_2,d_2\in\mathcal{C}_2$, $n\in\mathbb{N}$, and pure tensors $f\in\mathcal{R}_\T^{\otimes{n}}$.

\begin{lemma}\label{lem:Ext}
 For $\mathrm{IDR}_\Q(\mathcal{R})$, $\Der$, $\Int$, and $\E$ defined above, we have the following properties.
 \begin{enumerate}
  \item\label{item:LeibnizExt} The $\mathcal{C}$-linear map $\Der$ defined by \eqref{eq:DefDeriv} is a derivation on $\mathrm{IDR}_\Q(\mathcal{R})$.
  \item\label{item:RightInverseExt} On $\mathrm{IDR}_\Q(\mathcal{R})$, the $\mathcal{C}$-linear map $\Int$ defined by \eqref{eq:DefIntQ} is a right inverse of $\Der$.
  \item\label{item:EvaluationExt} Let $f_0\otimes{c_1}\otimes{c_2}\otimes{f} \in \mathrm{IDR}_\Q(\mathcal{R})$ with $f \in \mathcal{R}_\T^{\otimes{n}}$ for some $n \in \{0,1,2,\dots\}$. Then,
   \begin{equation}\label{eq:EvaluationExt}
    \E(f_0\otimes{c_1}\otimes{c_2}\otimes{f})=
    \begin{cases}1\otimes\big(c_1{\cdot}\big(\underbrace{f_0-\Q\Der{f_0}}_{\in \mathcal{C} \subseteq \widetilde{\mathcal{C}}_1}\big)\big)\otimes{c_2}\otimes{f}&n=0\\
    1\otimes(c_1{\cdot}\ep((\Q\Der{f_0})\otimes{f}))\otimes{c_2}\otimes\et&n>0\end{cases}.
   \end{equation}
  \item\label{item:constExt} The constants of $\mathrm{IDR}_\Q(\mathcal{R})$ are given by $\const_\Der(\mathrm{IDR}_\Q(\mathcal{R}))=\widetilde{\mathcal{C}}$.
 \end{enumerate}
\end{lemma}
\begin{proof}
 The proof of statement~\ref{item:LeibnizExt} is literally the same as that of Lemma~\ref{lem:Leibniz}.
 For statement~\ref{item:RightInverseExt}, the proof of Lemma~\ref{lem:RightInverse} carries over with $c=c_1\otimes{c_2}\in\widetilde{\mathcal{C}}_1\otimes\mathcal{C}_2$.
 For the base case $n=0$, the computation now reads
 \begin{align*}
  \Der\Int(f_0\otimes{c}\otimes\et) &= \Der\big((\Q{f_0})\otimes{c}\otimes\et+1\otimes{c}\otimes(f_0-\Der\Q{f_0})\big)\\
  &= (\Der\Q{f_0})\otimes{c}\otimes\et+(f_0-\Der\Q{f_0})\otimes{c}\otimes\et\\
  &= f_0\otimes{c}\otimes\et.
 \end{align*}
 For statement~\ref{item:EvaluationExt}, the proof of Lemma~\ref{lem:Evaluation} carries over.
 For the case $n=0$, the computation now reads
 \begin{align*}
  \E(f_0\otimes{c}\otimes{f}) &= f_0\otimes{c}\otimes{f} - \Int((\Der{f_0})\otimes{c}\otimes{f})\\
  &= f_0\otimes{c}\otimes{f} - \big((\Q\Der{f_0})\otimes{c}\otimes{f}+1\otimes{c}\otimes((\Der{f_0}-\Der\Q\Der{f_0})\otimes{f})\big)\\
  &= 1\otimes\big(c_1{\cdot}\big(\underbrace{f_0-\Q\Der{f_0}}_{\in \mathcal{C} \subseteq \widetilde{\mathcal{C}}_1}\big)\big)\otimes{c_2}\otimes{f}.
 \end{align*}
 Finally, for statement~\ref{item:constExt}, the proof of Lemma~\ref{lem:const} carries over, using statement~\ref{item:RightInverseExt} and \eqref{eq:EvaluationExt} instead of Lemma~\ref{lem:RightInverse} and \eqref{eq:Evaluation}, respectively.
\end{proof}

\begin{theorem}\label{thm:IDRext}
 With the above definitions, the following hold.
 \begin{enumerate}
  \item $(\mathrm{IDR}_\Q(\mathcal{R}),\Der,\Int)$ is a commutative integro-differential ring.
  \item\label{item:embeddingExt} $\iota:\mathcal{R}\to\mathrm{IDR}_\Q(\mathcal{R})$ defined by \eqref{eq:DefIota} is an injective differential ring homomorphism such that $\Int\iota(f)=\iota(\Q{f})$ holds for all $f \in \Der\mathcal{R}$.
  \item Let $J_1\subseteq\mathrm{IDR}(\mathcal{R})$ be the integro-differential ideal generated by \eqref{eq:constgenerators}.
   Then, there is a unique bijective integro-differential ring homomorphism $\psi:\mathrm{IDR}(\mathcal{R})/J_1\to\mathrm{IDR}_\Q(\mathcal{R})$ such that $\psi(\pi(\iota(f)))=\iota(f)$, where $\pi:\mathrm{IDR}(\mathcal{R})\to\mathrm{IDR}(\mathcal{R})/J_1$ is the canonical projection.
 \end{enumerate}
\end{theorem}
\begin{proof}
 Using Lemma~\ref{lem:Ext} instead of Lemmas \ref{lem:Leibniz}, \ref{lem:RightInverse}, and \ref{lem:const}, the proof of Theorem~\ref{thm:embedding} carries over to show that $(\mathrm{IDR}_\Q(\mathcal{R}),\Der,\Int)$ is a commutative integro-differential ring and that $\iota$ is an injective differential ring homomorphism.
 Moreover, by \eqref{eq:DefIntQ}, it follows that $\Int\iota(\Der{f})=\iota(\Q\Der{f})$ holds for all $f \in \mathcal{R}$.
\par
 Finally, we show that $\psi:\mathrm{IDR}(\mathcal{R})/J_1\to\mathrm{IDR}_\Q(\mathcal{R})$ satisfying the claimed properties exists.
 By Theorem~\ref{thm:universal}, there exists a unique integro-differential homomorphism $\bar{\pi}:\mathrm{IDR}(\mathcal{R})\to\mathrm{IDR}_\Q(\mathcal{R})$ such that $\bar{\pi}(\iota(f))=\iota(f)$ for all $f\in\mathcal{R}$.
 Since $\bar{\pi}(1\otimes\ep(f)\otimes1\otimes\et)=\bar{\pi}(\E\iota(f))=\E\bar{\pi}(\iota(f))=\E\iota(f)=0$ for $f\in\Q\Der\mathcal{R}$ by \eqref{eq:Evaluation} and \eqref{eq:EvaluationExt}, it follows that $J_1\subseteq\ker(\bar{\pi})$.
 Hence, by factoring out $J_1$, $\bar{\pi}$ induces a unique integro-differential ring homomorphism $\psi:\mathrm{IDR}(\mathcal{R})/J_1\to\mathrm{IDR}_\Q(\mathcal{R})$ with $\psi\circ\pi=\bar{\pi}$.
 Lemma~\ref{lem:FactorConst} implies that $\psi$ is bijective.
 Finally, $\psi$ is unique with $\psi\circ\pi\circ\iota=\iota$, since any such integro-differential ring homomorphism $\psi$ arises from the corresponding $\bar{\psi}:=\psi\circ\pi$ by factoring out $J_1$.
\end{proof}

\begin{remark}
If we consider the free integro-differential ring $\mathrm{IDR}(\mathcal{R})$ over $(\mathcal{R},\Der)$, we have that the evaluation of any non-constant element $f \in \mathcal{R}\setminus\mathcal{C}$ yields a new constant $\E\iota(f)\not\in\iota(\mathcal{R})$ by \eqref{eq:Evaluation}.
In contrast, in $\mathrm{IDR}_\Q(\mathcal{R})$, the property $\Int\iota(f)=\iota(\Q{f})$ implies instead that the evaluation of all $f \in \mathcal{R}$ yields a constant from $\mathcal{C}$ by $\E\iota(f)=\iota(f-\Q\Der{f})\in\iota(\mathcal{C})$.
\end{remark}

In particular, the construction described in Remark~\ref{rem:restriction} can be applied to obtain a quasi-integration on $\mathcal{R}$ from the integration of $\mathrm{IDR}_\Q(\mathcal{R})$, whereby we recover the same $\Q$ only if we choose the same $\mathcal{R}_\T$.
From Theorems \ref{thm:IDRext} and \ref{thm:universal}, we can deduce the following analog of Theorem~\ref{thm:universal}.

\begin{corollary}\label{cor:universalExt}
 Let $(\mathcal{S},\Der,\Int)$ be a commutative integro-differential ring and let $\varphi:\mathcal{R}\to\mathcal{S}$ be a differential ring homomorphism such that $\varphi(\Q\Der{f})=\Int\Der\varphi(f)$.
 Then, there exists a unique integro-differential ring homomorphism $\eta:\mathrm{IDR}_\Q(\mathcal{R})\to\mathcal{S}$ such that $\eta(\iota(f))=\varphi(f)$ for all $f\in\mathcal{R}$.
\end{corollary}
\begin{proof}
 By Theorem~\ref{thm:universal}, there is a unique integro-differential ring homomorphism $\bar{\eta}:\mathrm{IDR}(\mathcal{R})\to\mathcal{S}$ such that $\bar{\eta}(\iota(f))=\varphi(f)$ for all $f\in\mathcal{R}$.
 By assumption on $\varphi$, we have $\bar{\eta}(1\otimes\ep(\Q\Der{f})\otimes1\otimes\et) = \bar{\eta}(\E\iota(\Q\Der{f})) = \E\bar{\eta}(\iota(\Q\Der{f})) = \E\varphi(\Q\Der{f}) = \E\Int\Der\varphi(f) = 0$ for all $f\in\mathcal{R}$.
 With $J_1,\psi,\pi$ from Theorem~\ref{thm:IDRext}, we have $J_1=\ker(\psi\circ\pi)$ and $\bar{\eta}(J_1)=0$.
 Therefore, we obtain a unique integro-differential ring homomorphism $\eta:\mathrm{IDR}_\Q(\mathcal{R})\to\mathcal{S}$ such that $\bar{\eta}=\eta\circ\psi\circ\pi$.
 By Theorem~\ref{thm:IDRext}, on $\mathcal{R}$, we have $\eta\circ\iota=\eta\circ\psi\circ\pi\circ\iota=\bar{\eta}\circ\iota=\varphi$.
