\par
 Now, assume that $\eta:\mathrm{IDR}_\Q(\mathcal{R})\to\mathcal{S}$ is an arbitrary integro-differential ring homomorphism such that $\eta(\iota(f))=\varphi(f)$ for all $f\in\mathcal{R}$.
 Then, $\tilde{\eta}:=\eta\circ\psi\circ\pi$ is an integro-differential ring homomorphism $\mathrm{IDR}(\mathcal{R})\to\mathcal{S}$ such that $\tilde{\eta}\circ\iota = \eta\circ\psi\circ\pi\circ\iota = \eta\circ\iota = \varphi$ on $\mathcal{R}$.
 By Theorem~\ref{thm:universal}, $\tilde{\eta}$ is identical with $\bar{\eta}$ above.
 Hence $\eta$ satisfies $\bar{\eta}=\eta\circ\psi\circ\pi$, which makes it unique as shown above.
\end{proof}

We briefly revisit the three basic examples treated in Section~\ref{sec:examples}.

\begin{example}
 If $(\mathcal{R},\Der,\Q)=(\mathcal{C},0,0)$ is a quasi-integro-differential ring with trivial derivation and quasi-integration, it follows that $\mathcal{C}_1=\widetilde{\mathcal{C}}_1=\mathcal{C}$, since $\mathcal{R}_\mathrm{J}=\{0\}$.
 So, nothing changes compared to Example~\ref{ex:FreeConstant} and we have $\mathrm{IDR}_\Q(\mathcal{R})=\mathrm{IDR}(\mathcal{R})$.
\end{example}

\begin{example}\label{ex:LaurentExt}
 For $(\mathcal{R},\Der,\Q)=(\mathcal{C}((x)),\frac{d}{dx},\Q)$ and $\Q$ as in Example~\ref{ex:FreeLaurent}, we have $\widetilde{\mathcal{C}}_1=\Sym(\ep(\mathcal{R}_\mathrm{J}\otimes\bigoplus_{n=1}^\infty\mathcal{C}x_n))$.
 Moreover, in contrast to Example~\ref{ex:FreeLaurent}, we have $\E\iota(f)=\iota(c)$ for $f\in\mathcal{R}$, where $c\in\mathcal{C}$ is the constant term of $f$, cf.~\eqref{eq:LaurentEval}.
 In analogy to Example~\ref{ex:FreeLaurent}, as a $\widetilde{\mathcal{C}}$-module, $\mathrm{IDR}_\Q(\mathcal{R})$ is isomorphic to $\widetilde{\mathcal{C}}\otimes\mathcal{R}[\ln(x)]$.
\end{example}

\begin{example}
 If $(\mathcal{R},\Der,\Q)$ is an integro-differential ring, then $\mathcal{R}_\T$ and hence $\widetilde{M}_1$ are the trivial module.
 Consequently, $\widetilde{\mathcal{C}}_1=\mathcal{C}$.
 Together with $\mathcal{C}_2=\mathcal{C}$ and $\mathcal{T}=\mathcal{C}\et$ obtained in Example~\ref{ex:FreeSurjective}, this yields $\mathrm{IDR}_\Q(\mathcal{R})=\iota(\mathcal{R})$, i.e.\ we recover the integro-differential ring we started with by Theorem~\ref{thm:IDRext}.\ref{item:embeddingExt}.
\end{example}


\subsection{Internal closure in a commutative integro-differential ring}
\label{sec:closure}

In this section, we assume that $(\mathcal{S},\Der,\Int)$ is a commutative integro-differential ring such that $(\mathcal{S},\Der)$ is a differential ring extension of a fixed commutative differential ring $(\mathcal{R},\Der)$.
In other words, the inclusion map of $\mathcal{R}$ into $\mathcal{S}$ is a differential ring homomorphism.
Additionally, based on Theorem~\ref{thm:universal}, we fix $\eta:\mathrm{IDR}(\mathcal{R})\to\mathcal{S}$ as the unique integro-differential ring homomorphism such that $\eta(\iota(f))=f$ for all $f \in \mathcal{R}$.
As explained in Remark~\ref{rem:closure1}, $\eta$ maps the free integro-differential ring $\mathrm{IDR}(\mathcal{R})$ onto the internal integro-differential ring closure of $\mathcal{R}$ in $(\mathcal{S},\Der,\Int)$ and this internal closure $\bar{\mathcal{R}}:=\eta(\mathrm{IDR}(\mathcal{R}))$ is isomorphic to the quotient $\mathrm{IDR}(\mathcal{R})/\ker(\eta)$.
So, we provide a more explicit characterization of $\ker(\eta)$ in the following.
To this end, we additionally assume
\begin{equation}\label{eq:NNC}
 \const_\Der(\bar{\mathcal{R}})=\mathcal{C},
\end{equation}
i.e.\ that the internal closure has no new constants, in all that follows.

In the above setting, we can assign to any new constant from $\bar{\mathcal{C}}\setminus\iota(\mathcal{C})$ a value in $\mathcal{C}$ by computing the corresponding constant in $(\mathcal{S},\Der,\Int)$.
Explicitly, we have the following straightforward consequence.

\begin{lemma}\label{lem:closure}
 Let $J\subseteq\mathrm{IDR}(\mathcal{R})$ be the ideal generated by the constants
 \begin{equation}\label{eq:constantvalues}
  \begin{gathered}
   1\otimes\big(\ep(f)-\E{f_0}\Int{f_1}\dots\Int{f_n}\big)\otimes1\otimes\et \in \bar{\mathcal{C}} \quad\text{and}\\
   1\otimes1\otimes\big(\ep(s\odot{t})-\E\big(\Int{s_1}\dots\Int{s_m}\big)\Int{t_1}\dots\Int{t_l}\big)\otimes\et \in \bar{\mathcal{C}}
  \end{gathered}
 \end{equation}
 for all pure tensors $f=f_0\otimes\dots\otimes{f_n} \in M_1$ and $s=s_1\otimes\dots\otimes{s_m},t=t_1\otimes\dots\otimes{t_l} \in\widetilde{\mathcal{T}}$.
 Then, $J\subseteq\ker(\eta)$ and there is a unique integro-differential ring homomorphism $\tilde{\eta}:\mathrm{IDR}(\mathcal{R})/J\to\mathcal{S}$ with $\tilde{\eta}([\iota(f)]_J)=f$ for all $f \in \mathcal{R}$.
\end{lemma}
\begin{proof}
 In \eqref{eq:constantvalues}, the evaluations $\E{f_0}\Int{f_1}\dots\Int{f_n}$ and $\E\big(\Int{s_1}\dots\Int{s_m}\big)\Int{t_1}\dots\Int{t_l}$ in $(\mathcal{S},\Der,\Int)$ yield constants and hence lie in $\mathcal{C}$ by \eqref{eq:NNC}.
 Consequently, the quantities constructed in \eqref{eq:constantvalues} are indeed elements of $\bar{\mathcal{C}}$ for all pure tensors $f=f_0\otimes\dots\otimes{f_n} \in M_1$ and $s=s_1\otimes\dots\otimes{s_m},t=t_1\otimes\dots\otimes{t_l} \in\widetilde{\mathcal{T}}$.
 Therefore, the ideal $J\subseteq\mathrm{IDR}(\mathcal{R})$ is well-defined.
\par
 Note that $\Int{f_1}\dots\Int{f_n}=\eta(1\otimes1\otimes1\otimes{f_1^n})$.
 We clearly have $J\subseteq\ker(\eta)$, since $\eta$ maps every generator \eqref{eq:constantvalues} of $J$ to zero by definition, cf.\ the proof of Theorem~\ref{thm:universal}.
 Hence, $\eta$ induces a unique integro-differential ring homomorphism $\tilde{\eta}:\mathrm{IDR}(\mathcal{R})/J\to\mathcal{S}$ with $\tilde{\eta}([\iota(f)]_J)=f$ for all $f \in \mathcal{R}$.
\end{proof}

The following lemma provides a characterization of the equality $J=\ker(\eta)$ for the above ideal generated by constants \eqref{eq:constantvalues}.
Recall from Section~\ref{sec:independence} the definitions of $\sigma$ and $\tau$, which allow to abbreviate nested integrals
\[
 \sigma(W)=\Int{a_{w_1}}\dots\Int{a_{w_{|W|}}} \in \mathcal{S}
\]
and tensors $\tau(W)=a_{w_1}\otimes\dots\otimes{a_{w_{|W|}}} \in \mathcal{T}$ in terms of words $W=w_1\dots{w_{|W|}} \in \langle{I}\rangle$ using a fixed subset $\{a_i\ |\ i\in{I}\}\subseteq\mathcal{R}_\mathrm{T}$.
Note that we have $\sigma(W)=\eta(1\otimes1\otimes1\otimes\tau(W))$.
If $\linspan_\mathcal{C}\{a_i\ |\ i\in{I}\}=\mathcal{R}_\mathrm{T}$, then with these definitions it is clear that the ideal $J\subseteq\mathrm{IDR}(\mathcal{R})$ given in Lemma~\ref{lem:closure} is generated by all
\begin{equation}\label{eq:constantvaluesW}
 \begin{gathered}
  1\otimes\big(\ep(f\otimes\tau(W))-\E{f}\sigma(W)\big)\otimes1\otimes\et \in \bar{\mathcal{C}}\quad\text{and}\\
  1\otimes1\otimes\big(\ep(\tau(U)\odot\tau(V))-\E\sigma(U)\sigma(V)\big)\otimes\et \in \bar{\mathcal{C}}
 \end{gathered}
\end{equation}
with $f \in \mathcal{R}_\mathrm{J}$, $W \in \langle{I}\rangle$, and $U,V \in \langle{I}\rangle^*$.

\begin{lemma}\label{lem:closure2}
 Assume that $\mathcal{R}_\T$ is a free $\mathcal{C}$-module with basis $\{a_i\ |\ i\in{I}\}\subseteq\mathcal{R}_\mathrm{T}$.
 Let the ideal $J\subseteq\mathrm{IDR}(\mathcal{R})$ be generated by \eqref{eq:constantvaluesW}.
 Then, $J=\ker(\eta)$ holds if and only if the nested integrals $\{\sigma(W)\ |\ W \in \langle{I}\rangle\}\subseteq\mathcal{S}$ are $\mathcal{R}$-linearly independent.
\end{lemma}
\begin{proof}
 Let $\tilde{\eta}$ be given by Lemma~\ref{lem:closure}.
 Since $J\subseteq\ker(\eta)$, the equality $J=\ker(\eta)$ is equivalent to $\tilde{\eta}$ being injective.
 By \eqref{eq:constantvalues}, factoring by $J$ amounts to assigning to any new constant from $\bar{\mathcal{C}}\setminus\iota(\mathcal{C})$ a value in $\mathcal{C}$ in such a way that the resulting canonical projection $\tilde{\pi}:\mathrm{IDR}(\mathcal{R})\to\mathrm{IDR}(\mathcal{R})/J$ is bijective when restricted to the $\mathcal{C}$-submodule
 \begin{equation}\label{eq:defM}
  M:=\mathcal{R}\otimes\mathcal{C}\otimes\mathcal{C}\otimes\mathcal{T}\subseteq\mathrm{IDR}(\mathcal{R}).
 \end{equation}
 Altogether, by $\eta=\tilde{\eta}\circ\tilde{\pi}$, we have $J=\ker(\eta)$ if and only if $\eta$ restricted to $M$ is injective.
 It remains to show that injectivity of $\eta|_M$ is equivalent to $\mathcal{R}$-linear independence of $\{\sigma(W)\ |\ W \in \langle{I}\rangle\}$.
\par
 By assumption on $\mathcal{R}_\T$, $\mathcal{T}$ is a free $\mathcal{C}$-module with basis $\{\tau(W)\ |\ W \in \langle{I}\rangle\}$.
 So, by Lemma~\ref{lem:tensorproduct}, we can write any $f \in M$ uniquely as $f=\sum_{i=1}^nf_i\otimes1\otimes1\otimes\tau(W_i)$, where $W_i\in\langle{I}\rangle$ are pairwise distinct and $f_i\in\mathcal{R}$ are nonzero, and we note that $\eta(f)=\sum_{i=1}^nf_i\sigma(W_i)$.
 If $\eta|_M$ is injective and $\sum_{i=1}^nf_i\sigma(W_i)$ is zero in $\mathcal{S}$ for some nonzero $f_i\in\mathcal{R}$ and pairwise distinct $W_i\in\langle{I}\rangle$, then $\sum_{i=1}^nf_i\otimes1\otimes1\otimes\tau(W_i)=0$.
 So, $n=0$ follows by uniqueness.
 Conversely, assume that $\{\sigma(W)\ |\ W \in \langle{I}\rangle\}\subseteq\mathcal{S}$ is $\mathcal{R}$-linearly independent and $f \in M\cap\ker(\eta)$.
 By $0=\eta(f)=\sum_{i=1}^nf_i\sigma(W_i)$, it then follows that $n=0$ and hence $f=0$.
\end{proof}

In order to make use of Lemma~\ref{lem:closure2}, we now focus on a large class of differential rings $(\mathcal{R},\Der)$, for which Theorem~\ref{thm:independence} shows that nested integrals of this form are indeed $\mathcal{R}$-linearly independent.
If $\mathcal{R}$ is a field of characteristic zero, then independence also follows by \cite[Thm.~1]{DeneufchatelEtAl}.

\begin{theorem}\label{thm:closure}
 Assume that $\mathcal{R}_\T$ is a free $\mathcal{C}$-module with basis $\{a_i\ |\ i\in{I}\}\subseteq\mathcal{R}_\mathrm{T}$.
 Let the ideal $J$ be generated by all constants \eqref{eq:constantvaluesW}
 with $f \in \mathcal{R}_\mathrm{J}$, $W \in \langle{I}\rangle$, and $U,V \in \langle{I}\rangle^*$.
 Assume further that the differential ring $(\mathcal{R},\Der)$ is such that, for every nonzero element, the differential ideal generated by it contains a nonzero constant.
 Then, $\tilde{\eta}:\mathrm{IDR}(\mathcal{R})/J\to\bar{\mathcal{R}}$ given by Lemma~\ref{lem:closure} is an integro-differential ring isomorphism.
\end{theorem}
\begin{proof}
 By construction, $\tilde{\eta}:\mathrm{IDR}(\mathcal{R})/J\to\bar{\mathcal{R}}$ is a surjective integro-differential ring homomorphism.
 By Theorem~\ref{thm:independence}, $\{\sigma(W)\ |\ W \in \langle{I}\rangle\}\subseteq\mathcal{S}$ is $\mathcal{R}$-linearly independent.
 So, Lemma~\ref{lem:closure2} implies $J=\ker(\eta)$, i.e.\ $\tilde{\eta}$ is injective on $\mathrm{IDR}(\mathcal{R})/J$.
\end{proof}

In principle, an analog of Theorem~\ref{thm:closure} could also be worked out for $\mathrm{IDR}_\Q(\mathcal{R})$ instead of $\mathrm{IDR}(\mathcal{R})$, if $\Q$ agrees with $\Int$ on $\Der\mathcal{R} \subseteq\mathcal{S}$.
Analogously to what we have done in Section~\ref{sec:ExtQIDR} explicitly, one could modify the construction of $\mathrm{IDR}(\mathcal{R})$ to directly respect the relations of constants imposed by $J$ instead of taking the quotient $\mathrm{IDR}(\mathcal{R})/J$.

Finally, we now look at concrete integro-differential closures.
We start with a rather simple case, continuing Example~\ref{ex:FreeLaurent}, where $\mathcal{R}_\T$ is cyclic and all relevant evaluations involving nested integrals are in fact zero in $\mathcal{S}$.
The second example will have neither of these properties and will treat the integro-differential ring formed from rational functions and their nested integrals mentioned at the very beginning of the paper.

\begin{example}\label{ex:LaurentClosure}
 With $\mathbb{Q}\subseteq\mathcal{C}$, let $(\mathcal{R},\Der):=(\mathcal{C}((x)),\frac{d}{dx})$ and $(\mathcal{S},\Der,\Int):=(\mathcal{R}[\ln(x)],\frac{d}{dx},\Int)$ as in Example~\ref{ex:FreeLaurent}.
 Note that $\bar{\mathcal{R}}=\mathcal{S}$ in this case.
 Setting $a_0:=\frac{1}{x}$ and $I:=\{0\}$, we have $\sigma(W)=\frac{\ln(x)}{n!}$ for $W \in \langle{I}\rangle$ where $n=|W|$.
 Consequently, $\E{f}\sigma(U)=0$ and $\E\sigma(U)\sigma(V)=0$ by \eqref{eq:LaurentEval} for all $f\in\mathcal{R}$ and $U,V \in \langle{I}\rangle^*$.
 Since $\mathcal{R}_\mathrm{J}$ was defined in Example~\ref{ex:FreeLaurent} as the set of series without constant term, we also have $\E{f}\sigma(W)=0$ by \eqref{eq:LaurentEval} for all $f \in \mathcal{R}_\mathrm{J}$ when $W$ is the empty word.
 This explains all evaluations occurring in \eqref{eq:constantvaluesW}.
 Then, if $\mathcal{C}$ is Noetherian, Theorem~\ref{thm:closure} can be applied based on Lemma~\ref{lem:Noetherian} and shows that the quotient $\mathrm{IDR}(\mathcal{R})/\ker(\eta)$ can be obtained by setting all constants $1\otimes{c_1}\otimes1\otimes\et$ and $1\otimes1\otimes{c_2}\otimes\et$ with $c_1\in\ep(M_1)$ and $c_2\in\ep(M_2)$ to zero.
 Since $\eta$ is surjective onto $\mathcal{S}$, this quotient is isomorphic to $(\mathcal{S},\Der,\Int)$ as integro-differential ring.
\end{example}

As done in the previous example, one may also consider simply setting all constants in $\mathcal{C}\otimes\ep(M_1)\otimes\mathcal{C}\otimes\mathcal{C}\et$ and $\mathcal{C}\otimes\mathcal{C}\otimes\ep(M_2)\otimes\mathcal{C}\et$ to zero in general.
This means to factor out from $\mathrm{IDR}(\mathcal{R})$ the ideal generated by these constants, where the quotient can be identified with $M$ defined by \eqref{eq:defM}.
Since the $\mathcal{C}$-module $M$ is closed under differentiation, the restriction of $\eta$ to $M$ will be a differential module homomorphism, which is surjective onto $\bar{\mathcal{R}}\subseteq\mathcal{S}$ by \eqref{eq:NNC} and even injective if Lemma~\ref{lem:closure2} applies.
However, we do not obtain an integro-differential ring homomorphism this way in general, since $\mathcal{C}\otimes\ep(M_1)\otimes\mathcal{C}\otimes\mathcal{C}\et$ and $\mathcal{C}\otimes\mathcal{C}\otimes\ep(M_2)\otimes\mathcal{C}\et$ need not be contained in $\ker(\eta)$ and $M\subseteq\mathrm{IDR}(\mathcal{R})$ is not a subring unless $\mathcal{R}_\T$ is the trivial module.

\begin{example}\label{ex:hyperlogs}
 Let $\mathcal{C}$ be a field of characteristic zero, let $(\mathcal{R},\Der)$ be the field of rational functions $(\mathcal{C}(x),\frac{d}{dx})$, and let $(\mathcal{S},\Der,\Int):=(\mathcal{C}((x))[\ln(x)],\frac{d}{dx},\Int)$ as in Example~\ref{ex:IDR}.
 On $\mathcal{R}$, we consider the quasi-integration $\Q$ explained in the introduction.
 Explicitly, $\Q$ is defined such that elements in $\Q\mathcal{R}$ do not involve a constant term in their partial fraction decomposition and $\ker(\Q)$ consists of proper rational functions having only simple poles.
 In fact, on $\Der\mathcal{R}$, this $\Q$ coincides with the restriction of $\Int$ from $\mathcal{S}$.
 Again, $\mathrm{IDR}(\mathcal{R})/\ker(\eta)$ is isomorphic to the internal integro-differential ring closure $\bar{\mathcal{R}}$ of $\mathcal{C}(x)$ in $(\mathcal{S},\Der,\Int)$ and we determine $\ker(\eta)$ based on Theorem~\ref{thm:closure}.
 A particular basis of $\mathcal{R}_\T=\ker(\Q)$ is given by all $\frac{x^k}{p}$ such that $p\in\mathcal{C}[x]$ is monic irreducible and $0\le{k}<\deg(p)$.
 We take a closer look at the evaluations appearing in \eqref{eq:constantvaluesW}.
 With the chosen $\Q$, any element of $\mathcal{R}_\mathrm{J}=\im(\Q)$ has vanishing evaluation \eqref{eq:LaurentEval} in $(\mathcal{S},\Der,\Int)$ and any element of $\mathcal{R}_\T=\ker(\Q)$ lies in $\frac{1}{x}\mathcal{C}[[x]]\subseteq\mathcal{S}$.
 The latter property implies $\eta(1\otimes1\otimes1\otimes{t}) \in \mathcal{C}[[x]][\ln(x)]$ for all $t \in \widetilde{\mathcal{T}}$.
 By \eqref{eq:Evaluation}, we also have $\E\eta(1\otimes1\otimes1\otimes{t})=0$ for all $t \in \widetilde{\mathcal{T}}$.
 Now, \eqref{eq:LaurentEval} implies that $\E\eta(f\otimes1\otimes1\otimes{t})=0$ and $\E\eta(1\otimes1\otimes1\otimes{s})\eta(1\otimes1\otimes1\otimes{t})=0$ for all $f \in \mathcal{C}(x)\cap\mathcal{C}[[x]]$ and $s,t \in \widetilde{\mathcal{T}}$.
 Moreover, $\eta(1\otimes1\otimes1\otimes(t\otimes\frac{1}{x})) \in \ln(x)\mathcal{C}[[x]][\ln(x)]$ for all $t \in \mathcal{T}$ implies $\E\eta(f\otimes1\otimes1\otimes(t\otimes\frac{1}{x}))=0$ for all $f \in \mathcal{C}(x)$ and $t \in \mathcal{T}$.
 Altogether, this explains many evaluations appearing in \eqref{eq:constantvaluesW} to be zero.
 The remaining ones involve more computation and are given by $\E\frac{1}{x^k}\Int{f_1}\dots\Int{f_n}$ for $f_1,\dots,f_n \in \mathcal{R}_\T$ with $k,n\ge1$ and $f_n \in \mathcal{C}[[x]]$.
 In particular, they are not all zero, as $\E\tfrac{1}{x}\Int\tfrac{1}{x+1} = 1$ illustrates.
 By Theorem~\ref{thm:closure}, $J=\ker(\eta)$ is generated by the constants in \eqref{eq:constantvaluesW} and factoring yields an integro-differential ring isomorphism $\tilde{\eta}:\mathrm{IDR}(\mathcal{R})/J\to\bar{\mathcal{R}}$.
\end{example}


