\title[A note on the Greek letter elements]{A note on the Greek letter elements of the homotopy of the $L_n$-local spheres}
\author{Ryo Kato}
\address{Department of Core Studies, Kochi University of Technology, Kami,
Kochi, 782-8502, Japan}
\email{ryo\_kato\_1128@yahoo.co.jp}
\author{ Katsumi Shimomura}
