780-8520, Japan}
\email{katsumi@kochi-u.ac.jp}
\author{Mao-no-suke Shimomura}
\address{Department of Mathematics, Faculty of Science and Technology, Kochi University, Kochi, 780-8520, Japan}
\email{mao.shimomura@outlook.jp}
%\date{\today}

%\subjclass[2010]{Primary~55Q45, Secondary~55T15, 55Q51}
%\keywords{stable homotopy groups of spheres, Greek letter elements}

\begin{abstract}
\if0
We consider the homotopy groups of the $v_3^{-1}BP$-local (resp. $v_4^{-1}BP$) sphere spectrum at prime five (resp. seven), and show the groups contains the gamma (resp. delta) family.  
\fi
Let $BP$ denote the Brown-Peterson spectrum at a prime $p$, whose homotopy groups are isomorphic to the polynomial algebra generated by elements $v_i$'s for $i\ge 1$.
We consider the homotopy groups of the $v_n^{-1}BP$-localized sphere spectrum $L_nS^0$ with $n^2\le 2p-1$, and show that the groups contain the $n$-th Greek letter family.
For the proof of this, we further show the existence of the $v_n^{-1}BP$-localized Smith-Toda spectrum $W_n$ for the case $n^2\le 2p-1$.
If the Smith-Toda spectrum $V(n-1)$ exists, then $L_nV(n-1)$ is an example of $W_n$.
Previously,
$W_n$ is shown to exist if $n^2+n\le 2p-1$. 

We also consider the case where $(p,n)=(7,4)$, and show the existence of the delta family in $\pi_*(L_4S^0)$.  
\end{abstract}
\maketitle

\section{Introduction}

Let $\cS$ denote the stable homotopy category of the $p$-local spectra for a prime number $p$.
In $\cS$, we have the Brown-Peterson spectrum $BP\in \cS$ with homotopy groups $\pi_*(BP)=BP_*=\Z_{(p)}[v_1,v_2,\dots\,]$ for $v_n\in \pi_{2(p^n-1)}(BP)=BP_{2(p^n-1)}$.
Then  we obtain  a Bousfield localization functor $L_n\cln \cS\to \cS$ with respect to $v_n^{-1}BP$ along with the natural transformation $\et_n\cln id \to L_n$.
%Here, $v_n\in \pi_{2(p^n-1)}(BP)=BP_{2(p^n-1)}$ denotes an indecomposable generator.

For studying the homotopy groups $\pi_*(X)$ of a spectrum $X$, 
we have the Adams-Novikov spectral sequence
$$
E_2^{s,t}(X)=\e_{BP_*BP}^{s,t}(BP_*,BP_*(X))\Longrightarrow \pi_{t-s}(X).
$$
In the $E_2$-term $E_2^{s,t}(S^0)$ of this spectral sequence for $\pi_*(S^0)$,
we have the generators called  the $n$-th Greek letter elements $\al_s^{(n)}\in E_2^{n,t}(S^0)$ for $t=2s(p^n-1)-2\sum_{k=1}^{n-1} (p^k-1)$.
It is well known that $\al^{(n)}_s$ is a permanent cycle of the spectral sequence in the following cases:
\ARr {ll}{
n=1:&\al_s(=\al_s^{(1)}) \mbx{is a permanent cycle if $p\ge 3$ and $s\ge 1$,}\\ 
&\hspace{1in}\mbox{ or if $p=2$ and $1\le s\not\cg 3$ $(4)$,}\\
n=2:&\be_s(=\al_s^{(2)}) \mbx{is a permanent cycle if $p\ge 5$ and $s\ge 1$,}\\ 
&\hspace{1in}\mbox{ or if $p=3$ and $1\le s\not\cg 4,7,8$ $(9)$,}\\
n=3:&\ga_s(=\al_s^{(3)}) \mbx{is a permanent cycle if $p\ge 7$ and $s\ge 1$.}
}{known}
Let $E(n)(\in\cS)$ denote the $n$-th Johnson-Wilson spectrum. Then we have the $E(n)$-based Adams spectral sequence
$$
E_2^{s,t}(X)_n=\e_{E(n)_*E(n)}^{s,t}(E(n)_*,E(n)_*(X))\Longrightarrow \pi_{t-s}(L_nX), \lnr{ANSS}
$$
and we have a canonical map $\ell_n\cln BP\to E(n)$, which induces a homomorphism $(\ell_n)_*\cln BP_*=\Z_{(p)}[v_1,v_2,\dots\,] \to E(n)_*=\Z_{(p)}[v_1,\dots, v_n,v_n^{-1}]$ sending $v_k$ to $v_k$ for $k\le n$ and to zero for $k>n$. 
The map $\ell_n$ induces a map 
$(\ell_n)_*\cln \{E_r^{s,t}(X)\} \to \{E_r^{s,t}(X)_n\}$ of spectral sequences from the Adams-Novikov spectral sequence to the $E(n)$-based Adams spectral sequence. 
By the map, the fact \kko{known} implies that
\AR {ll}{
p=2,\ n=1:& \Z/p\lrk{\al_s} \sus \pi_{2s-1}(L_1S^0) \mbx{unless $s\cg 3$ $(4)$,}\\
p=3,\ n=2:& \Z/p\lrk{\be_s}\sus \pi_{16s-6}(L_2S^0) \mbx{unless $s\cg 4,7,8$ $(9)$.}
} 
In this paper, we consider the Greek letter elements in $\pi_*(L_nS^0)$.
First we have  results  for   $(p,n)=(5,3)$ and $(7,4)$.

\thm{main}{For each integer $s\ne 0$,
 the third Greek letter element $\ga_s\in E_2^3(S^0)_3$ at $p=5$ and the fourth Greek letter element $\de_s\in E_2^4(S^0)_4$ at $p=7$
are permanent cycles in the respective spectral sequences. These permanent cycles detect generators of submodules of $\pi_*(L_3S^0)$ and $\pi_*(L_4S^0)$ isomorphic to $\Z/p$.
}

The case for $(p,n)=(5,3)$ is generalized as follows:

\thm{main2}{Let $p$ and $n$ satisfy $n^2\le 2p-1$ and $(p,n)\ne (2,1)$, $(3,2)$, and $s$ be a non-zero integer.
Then, the $n$-th Greek letter element $\al^{(n)}_s\in E_2^n(S^0)_n$ at $p$
is a permanent cycle, which yields a generator of a submodule of $\pi_*(L_nS^0)$ isomorphic to $\Z/p$.
}

Theorems \ref{main} and \ref{main2} imply the following:
\cor{main2c}{
We have the fourth Greek letter element $\de_s\in \pi_*(L_4S^0)$ of order $p$  if $p\ge 7$.
}

Theorem \ref{main2} is based on the existence of the $L_n$-local Smith-Toda spectrum $W_n$, which is defined by the $BP_*$-homology 
$$
BP_*(W_n)=v_n^{-1}BP_*/I_n
$$
 for the invariant prime ideal $I_n=(p,v_1,\dots , v_{n-1})$ of $E(n)_*$.
 We notice that $W_n$ is not determined uniquely.
Since $E(n)_*(X)=E(n)_*\ox_{BP_*}BP_*(X)$, we also have
$$
E(n)_*(W_n)=E(n)_*/I_n
$$
We notice that  if the Smith-Toda spectrum $V(n-1)$ exists, the localized spectrum $L_nV(n-1)$ is one of $W_n$'s.
The theorem \cite[Th.~5.7]{sy} implies that if  $n^2+n\le 2p-1$, then $W_n$ exists uniquely.
Consider a condition on $(p,n)$:
$$
p\cg 3\ (4),\ \text{ or \ \ $n$ is even.}\lnr{pn}
$$
\if0
Let $MJ$ denote the generalized Moore spectrum such that $BP_*(MJ)=BP_*/J$ for an invariant regular ideal $J$.
Then, $V(n-1)=MI_n$.
On the existence, we read off from \cite[Th.~5.7]{sy} that $L_nMJ_n$ for an invariant regular ideal $J_n$ of length $n$ exists if $n^2+n\le 2p-1$.
\fi
Then, we improve the results:

\thm{main3}{ Let $n^2\le  2p-1$ and $(p,n)\ne (2,1)$, $(3,2)$.
