\section{Preliminaries}\label{sec:prelim}

\subsection{Notation}

Throughout this exposition, we will work on a stochastic basis $(\Omega ,\mathcal{F},(\mathcal{F}_t)_{t\geq 0},\Q)$ given by a filtered probability space with a right-continuous, complete filtration $(\mathcal{F}_t)_{t\geq 0}$ and measure $\Q$, which will play the role of the risk-neutral measure. Let $\P$ denote a measure such that $\P\ll\Q$, that is, $\P$ is absolutely continuous with respect to $\Q$, then we will denote by $\frac{d\P}{d\Q}$ the Radon-Nikodym derivative of $\P$ with respect to $\Q$.

Let $\R$ denote the set of real numbers. We will denote by $\R_+$ the subset of non-negative real numbers and for $d\in\mathbb N$, $\R^d$ the $d$-dimensional Euclidean space. Given a vector $u\in\R^d$, we will write $u^{\top}=(u_1,\dots ,u_d)$ to denote its components, where $u^{\top}$ is the vector transpose of $u$. For two elements $v,w\in\R^d$, the Euclidean scalar product will be written as $\langle v,w\rangle = v^{\top}w$. We will make use of the so-called extended vector notation: given $d\in\mathbb N$, we will call $\R^{d+1}$ the extended vector space and start indexing the first coordinate with $0$, that is, for $u\in\R^{d+1}$, we will write $u=(u_0,\dots ,u_d)^{\top}$. Furthermore, given a vector $v\in\R^d$ and $v_0\in\R$, we will write $(v_0,v)^{\top}\in\R^{d+1}$. We will use the same notational conventions for matrices. The identity matrix of dimension $d$ will be denoted by $\mathbbm 1_d\in\R^{d\times d}$. Let $A\subseteq\R^d$ be a set, then $\text{aff}(A)\subseteq\R^d$ denotes the affine hull of $A$.

Let $f:\R^n\rightarrow\R^m$, $y\mapsto f(y)$ be a smooth function. We will denote by $\partial _{y_k}f$ the partial derivative of $f$ with respect to the coordinate $y_k$ for $k=1,...,n$. We will use the notation $D_yf=(\partial _{y_i}f_j)_{i=1\dots,n, j=1,\dots,m}$ for the Jacobian matrix of $f$ with respect to the variable $y$ and for $k=1,...,m$, $D^2_yf_k=(\partial _{y_i}\partial _{y_j}f_k)_{i,j=1,\dots, n}$ will denote the Hessian matrix and $\nabla _yf_k=(\partial _{y_1}f_k,\dots ,\partial _{y_n}f_k)^{\top}$ will denote the gradient of the $k$-th component of $f$ with respect to the variable $y$.

Let $(\mathcal{H},\lVert\cdot\rVert _{\mathcal H})$ be a separable Hilbert space of functions from $\mathbb R_+$ to $\mathbb R$ fulfilling
\begin{itemize}
	\item[\textbf{(H1)}] $\delta_0:\mathcal{H}\rightarrow\mathbb R, h\mapsto h(0)$ is continuous linear.\customlabel{H1}{(H1)}
	\item[\textbf{(H2)}] $\mathcal \Sg_h:\mathcal{H}\rightarrow \mathcal{H}, f\mapsto (x\mapsto f(x+h))$ defines a $c_0$-semigroup $\mathcal (\Sg_h)_{h\geq 0}$ on $\mathcal{H}$ whose generator will be denoted by $\partial_x$, cf.\ \cite[pp.\ 6--8]{EK}.\customlabel{H2}{(H2)}
\end{itemize}
The inner product on $\mathcal{H}$ will be denoted $\<h_1,h_2\>_{\mathcal H}$ for $h_1,h_2\in \mathcal{H}$. We will make use of a Hilbert space $\mathcal H$ satisfying Assumptions \ref{H1} and \ref{H2} throughout the paper without explicitly referencing them. An example of a Hilbert space with those properties are the forward curve spaces $\mathcal H_w$ introduced in \cite{filipovic_consistency}.
\subsection{Model description}
In the following,  we will work with the zero-coupon \emph{bond discount} curve where the bond discount for maturity $T$ at time $t$ is defined as the difference between the corresponding bond's face value, 1 and its present value at time $t$. Let $P(t,T)$ denote the price at time $t$ of a zero-coupon bond with a maturity date $T$. We denote the corresponding bond discount by
\begin{equation}\label{eq:4_1}
	H_t(T-t)=1-P(t,T).
\end{equation}
For our purposes, we will model $H$ as a diffusion process $H:\R_+\times\Omega\rightarrow\mathcal H$, $H:(t,\omega)\mapsto H_t(\omega)$, that is, $H$ takes values in the Hilbert space $\mathcal H$. Let $W$ be a d-dimensional Brownian motion in  $(\Omega ,\mathcal{F},(\mathcal{F}_t)_{t\geq 0},\Q)$. We assume $H_t$ satisfies
\begin{equation}\label{eq:4_2}
	H_t=\Sg_tH_0+\int _0^t\Sg_{t-s}\alpha _sds+\int _0^t\Sg_{t-s}\Sigma _sdW_s,
\end{equation}
for an appropriate drift coefficient $\alpha :\R_+\times\Omega\rightarrow\mathcal H$ and diffusion coefficient $\Sigma :\R_+\times\Omega\rightarrow L(\R^d,\mathcal H)$. Here, once again $\Sg_h:\mathcal H\rightarrow \mathcal H$, $f\mapsto f(\cdot +h)$ denotes the shift operator of the semigroup of left shifts whose generator will be denoted by $\partial _x$. This implies $H_t$ is the mild solution to the stochastic differential equation (see, e.g., \cite{zabczyk})
\begin{equation}\label{eq:4_sde}
	dH_t=\left(\partial _xH_t+\alpha _t\right)dt+\Sigma _tdW_t.
\end{equation}
\begin{remark}
    Consider now the forward curve spaces $\mathcal H_w$ defined in \cite[Definition 5.1.1]{filipovic_consistency}. Since $\mathcal H_w$ is a normed space, we have by \ref{H1} that the evaluation functional $\delta _x$ is bounded, hence $\mathcal H_w$ is a RKHS. This fact is leveraged in e.g. \cite{filipovic3, filipovic_kr} where the authors derive a reproducing kernel for $\mathcal H_w$ and use its properties for an efficient interpolation scheme of the discount curve.
\end{remark}
\subsection{HJM-drift condition}
 This section includes the results on the sufficient conditions for NAFLVR. The sufficiency conditions were first proven in \cite{filipovic_discount}, where they are formulated in terms of the evolution of a random field. We adopt the setting of the Musiela parametrization (\cite{musiela}) and state the corresponding results here for convenience and completeness. 

Assume the limit $r_t:=\lim _{T\rightarrow t}-\partial _T\log (P(t,T))$ exists. In that case, $r_t$ is the short rate, and it follows immediately from \Cref{eq:4_1} that $r_t=H_t'(0)$. The discounted price of the zero-coupon bond is given by 
\begin{equation}\label{eq:4_3}
	\tilde{P}(t,T)=e^{-\int _0^tr_sds}P(t,T).
\end{equation} 
We now proceed with deriving the HJM-drift condition.
\begin{proposition}\label{prop:4_1}
	Assume that the process $H$ as defined in \eqref{eq:4_2} is additionally a strong solution to the SDE \eqref{eq:4_sde}. Let $\beta _t(x):=\delta _x(\partial _xH_t+\alpha _t)$ denote its drift coefficient then the processes $(\tilde{P}(t,T))_{t\in [0,T]}$ as defined in \Cref{eq:4_3} are local martingales for all $T\in\R_+$ if and only if the drift $\beta _t(x)$ of $H_t(x)$ fulfills for all $x,t>0$, $\Q$-a.s.
	\begin{equation}\label{eq:4_5}
		\beta _t(x)=H'_t(x)-r_t+r_tH_t(x).
	\end{equation}
\end{proposition}
\begin{proof}
	See \Cref{app:b}.
\end{proof}
\subsection{Pricing under the forward measure}

One way to facilitate the methodology developed in the discount setting is to use it to price interest rate derivatives on the market. To do this, one may use \emph{forward pricing measures}, which are important tools for simplifying the pricing of interest rate derivatives, such as caps and floors, swaptions, and bond options, to name a few. Forward measures are closely tied to the concept of numeraires, which are benchmark assets used to express prices in relative terms.

The $T$ forward pricing measure is a probability measure under which the price of a zero-coupon bond maturing at time $T$ is deterministic. Moreover, all discounted asset prices relative to the $T$ bond are (local) martingales under that measure. The measure transformation from the original risk-neutral measure (e.g., the  $\Q$ measure) to the forward measure is achieved via the Radon-Nikodym derivative. In the following, we make this notion precise and provide the form of the density process for the change of measure in terms of the dynamics of the discount process.

Let $B_t:=e^{\int _0^tr_sds}$ denote the risk-free bank account with initial condition $B_0=1$. The forward measure $\mathbb P^T$ is defined as the measure equivalent to the risk-neutral measure $\Q$ with the Radon-Nikodym derivative (cf. \cite[Definition 9.6.2.]{musiela_rutkowski})
\begin{equation*}
	\frac{d\mathbb P^T}{d\Q}=\frac{1}{B_TP(0,T)}.
\end{equation*}
\begin{proposition}
	Let $\Q$ denote the risk-neutral measure and $\mathbb P ^T$ be the forward measure. Then the process
	\begin{equation*}
		\eta _t:=\left.\frac{d\mathbb P ^T}{d\Q}\right\vert _{\mathcal F_t}
	\end{equation*}
	fulfills
	\begin{equation*}
		\eta _t=\mathcal E_t\left(\int _0^{\cdot}\frac{\Sigma _s(T-s)}{1-H_t(T-s)}dW_s\right).
	\end{equation*}
    where $\mathcal E_t(X)$ denotes the stochastic exponential of $X$ (cf. \cite[Section I.4f.]{jacod}).
\end{proposition}
\begin{proof}
	By Girsanov's Theorem, we have $\eta _t=\mathcal E_t(\lambda)$ for some adapted process $\lambda$. We have, by definition of the stochastic exponential,
	\begin{equation*}
		d\eta _t=\eta _td\lambda _t
	\end{equation*}
	and therefore
	\begin{equation*}
		d\lambda _t=\frac{1}{\eta _t}d\eta _t.
	\end{equation*}
	On the other hand, by the definition of the forward measure, we have
	\begin{equation*}
		\eta _t=\E ^{\Q}\left[\left.\frac{1}{B_TP(0,T)}\right\vert\mathcal F_t\right] =\E ^{\Q}\left[\left.\frac{P(T,T)}{B_TP(0,T)}\right\vert\mathcal F_t\right]=\frac{P(t,T)}{B_tP(0,T)}.
	\end{equation*}
	Thus, we obtain
	\begin{equation*}
		\begin{aligned}
                d\lambda _t=&\frac{B_tP(0,T)}{P(t,T)}d\left(\frac{P(t,T)}{B_tP(0,T)}\right) =\frac{1}{P(t,T)}\left( dP(t,T)-r_tP(t,T)dt\right) \\=&\frac{1}{1-H(T-t)}\left( \alpha _t(T-t)dt+\Sigma _t(T_t)dW_t -r_t(1-H_t(T-t))dt\right).
		\end{aligned}
	\end{equation*}
	Since the discounted process $B_t^{-1}P(t,T)$ is a local martingale under $\Q$, we may use the drift condition of \Cref{prop:4_1} to obtain
	\begin{equation*}
		d\lambda _t=\frac{\Sigma _t(T-t)}{1-H_t(T-t)}dW_t
	\end{equation*}
	and the assertion follows from the definition of the stochastic exponential.
\end{proof}



\subsection{Linearity assumption}
This section assumes a more tractable structure for the discount process. In particular, we will require the solutions to lie in a finite-dimensional affine subspace. This will force the curve itself to belong to the exponential-affine family and ensure that the (finite-dimensional) stochastic driving process fulfills a slightly modified quadratic drift condition. We make the linearity assumption precise.
\begin{itemize}
    \item[\textbf{(LA)}] \customlabel{LA}{(LA)} 
	We assume that the discount process $H$ satisfies  $H_t(x)=g_0(x)+\sum _{i=1}^dg_i(x)f_i(Y_t)$, where 
	\begin{enumerate}
		\item $g_0,\dots,g_d\in C^1(\R_+,\R)$ and $f_1,\dots,f_d\in C^2(\R ^k,\R )$, satisfy 
        \begin{equation*}
            \text{aff}(\lbrace\! (g_1(x),\dots,g_d(x))^{\top},\, x \geq 0\rbrace)=\R ^d 
        \end{equation*}
        and
        \begin{equation*}
            \text{aff}(\lbrace f_1(y),\dots,f_d(y), y\in\R ^d\rbrace )=\R ^d.
        \end{equation*}
		\item $Y$ is a $d$-dimensional diffusion process with dynamics 
        \begin{equation*}
            Y_t=Y_0+\int _0^tb_sds+\int _0^t\sigma _sdW_s,
        \end{equation*}
        where $Y_0$ is an $\mathcal{F}_0$-measurable random variable in $\R ^d$, $b:\R_+\times\Omega\rightarrow\R^k$ is a progressively measurable $d$-dimensional process with almost surely integrable paths and $\sigma:\R_+\times\Omega\rightarrow\R^{d\times k}$ is a progressively measurable $d$-dimensional matrix process with almost surely integrable paths. 
	\end{enumerate}
	Henceforth (with a slight abuse of notation), we shall set $g:=(g_0,\dots ,g_d)^{\top}$, as well as $f:=(1,f_1,\dots ,f_d)^{\top}$ and write 
    \begin{equation*}
        H_t(x)=\langle g(x),f(Y_t)\rangle .
    \end{equation*}
\end{itemize}

\begin{example}
	We collect here some of the example models that satisfy \ref{LA}.
	\begin{enumerate}
		\item Linear-rational models (see e.g. \cite{filipovic_lrtsm}): 
        \begin{equation*}
        H_t(x)=\frac{\langle g(x), (1,Y_t)\rangle}{\langle \lambda ,(1,Y_t)\rangle}
        \end{equation*}
        for $\lambda\in\mathbb{R}^{d+1}$ satisfies $H_t(x)=\langle g(x), f(Y_t)\rangle$ with 
        \begin{equation*}
            f(y):=\frac{(1,y)^{\top}}{\langle \lambda ,(1,y)\rangle}.
        \end{equation*}
		\item Polynomial models: 
        \begin{equation*}
            H_t(x)= \phi_0(x)+\sum _{\vert\alpha\vert =1}^{n}\phi _{\alpha}(x)Y_t^{\alpha}
        \end{equation*} satisfies $H_t(x)=\langle g(x),f(Y_t)\rangle$ with 
        \begin{equation*}
            g(x):=(\phi _0(x), \phi _1(x),\dots ,\phi _d(x),\phi _{11}(x),\dots ,\phi _{1d}(x),\dots ,\phi _{dd}(x),\dots )^{\top}
        \end{equation*} 
        and 
        \begin{equation*}
            f(y):=(1,y_1,\dots ,y_d,y_1y_1,\dots ,y_1y_d,\dots ,y_dy_d,\dots )^{\top}.
        \end{equation*}
	\end{enumerate}
\end{example}

In the following, we assume that the process $H$ satisfies \ref{LA}. We will see that under the drift condition, this imposes structure in the form of $g$ and $f(Y)$. 
\begin{proposition}\label{prop:4_3}
	Let $H$ be a discount process satisfying \ref{LA} and $P(t,T)=1-H_t(T-t)$ be the zero-coupon bond model induced by $H$. Then the discounted bond price processes $(\tilde P(t,T))_{0\geq t\geq T}$ are local martingales for all $T>0$ if and only if
	\begin{enumerate}
		\item There exists a matrix $M\in\R^{(d+1)\times (d+1)}$ such that the function $g$ satisfies
			\begin{equation}\label{eq:4_prop23b}
				g(x)=\left(\mathbbm{1}_{d+1}-e^{xM}\right) e_0,
			\end{equation}
			where $e_0=(1,0,\dots ,0)^{\top}\in\R ^{d+1}$ is the first unit basis vector
%			\begin{equation}\label{eq:4_matrix_form}
%				M:=\begin{pmatrix} -g'_0(0) & a_{0,1} & \cdots & a_{0,d} \\
%					\begin{matrix} -g'_1(0) \\
%						\vdots \\
%					-g'_d(0)\end{matrix} & &A-g'_0(0)\mathbbm{1}_d\end{pmatrix}
%			\end{equation}
%			for $a_{0,1},\dots ,a_{0,d}\in\R$ and  $A\in\R ^{d\times d}$. 
		\item The drift and diffusion coefficients $b$, respectively $\sigma$ of the process $Y$ satisfy $\Q$-a.s.
			\begin{equation}\label{eq:4_prop23c}
                    \begin{aligned}
				    &D_yf(Y_t)(0,b_t)^{\top}+\frac12\sum _{k=1}^d\Tr\left( \sigma _t\sigma _t^{\top}D^2_yf_k(Y_t)\right) e_k\\
                    &=(M^{\top}+\langle g'(0),f(Y_t)\rangle\mathbbm{1}_{d+1})f(Y_t).
                    \end{aligned}
			\end{equation}
	\end{enumerate}
\end{proposition}

By assuming $f=(1,id)$, we may also solve for the drift term of the process $Y$ explicitly. Indeed, by redefining $X_t=f(Y_t)$, we can always reduce to the following simplified case.
\begin{corollary}
	In the case $f_i=id$ for $i=1,\dots ,d$, \Cref{eq:4_prop23c} simplifies greatly and we obtain
	\begin{equation}\label{eq:4_remark1}
		(0,b_t)^{\top}=\left( M^{\top}+\langle g'(0),(1,Y_t)\rangle\mathbbm{1}_{d+1}\right) (1,Y_t)^{\top},
	\end{equation}
	that is, we may solve for the drift directly.
\end{corollary}

\begin{remark}
	From the drift condition, it is clear that a discount model fulfilling NAFLVR is induced by specifying the matrix that induces the curve component and the diffusion matrix that induces the stochastic component. Indeed, an arbitrage-free model is fully specified, up to reparametrisation, by the triplet $(M, y_0, \sigma )$, where $Y_0=y_0$ is the starting value of the process $Y$. 
\end{remark}
The following result implies that it is sufficient to consider models in a convenient basis transformation.
\begin{corollary}\label{cor:4_basis_change}
	Let $M\in\R ^{(d+1)\times (d+1)}$ and $\sigma :\R _+\times\Omega\rightarrow\R ^{d\times d}$ be a progressively measurable $d$-dimensional matrix process with a.s. integrable paths and let $H$ be the finite-dimensional affine discount model induced by the triplet $(M, y_0, \sigma)$ which fulfills the no-arbitrage condition in the sense of \Cref{prop:4_1}, then $H$ satisfies
	\begin{equation*}
		H_t(x) = 1-\langle e^{xJ}p,Z_t\rangle,
	\end{equation*}
	where $Z:=P^{\top}(1,Y)^{\top}$, $p=P^{-1}e_0$ and $P,J\in\R^{(d+1)\times (d+1)}$ are such that $M=PJP^{-1}$ is the Jordan decomposition of $M$. Furthermore, $Z$ satisfies the drift condition
	\begin{equation}\label{eq:4_drift_basis_change}
		b^Z_t=\left( J+\langle Jp,Z_t\rangle\mathbbm 1_{d+1}\right) Z_t,
	\end{equation}
	where $b^Z$ is the drift of $Z$.
\end{corollary}
\begin{proof}
	We have by definition
	\begin{equation*}
		H_t(x)=\langle g(x),(1,Y_t)\rangle.
	\end{equation*}
	Since $H$ fulfills the no-arbitrage condition, we obtain
	\begin{equation*}
		\begin{aligned}
			H_t(x)&=\langle g(x), (1,Y_t)\rangle = \langle (\mathbbm 1_{d+1}-e^{xM})e_0, (1,Y_t)\rangle =1-\langle e^{xM}e_0,(1,Y_t)\rangle.
		\end{aligned}
	\end{equation*}
	By the properties of the matrix exponential and the Jordan decomposition, we have
	\begin{equation*}
		H_t(x)=1-\langle Pe^{xJ}P^{-1}e_0, (1,Y_t)\rangle = 1-\langle e^{xJ}p,P^{\top}(1,Y_t)\rangle =1-\langle e^{xJ}p, Z_t\rangle.
	\end{equation*}
	Let $b_t$ denote the drift of the process $Y$. The drift condition \eqref{eq:4_remark1} implies
	\begin{equation*}
		\begin{aligned}
			(0,b_t)^{\top}&=\left( (PJP^{-1})^{\top}+\langle g'(0),(1,Y_t)\rangle\mathbbm 1_{d+1}\right) (1,Y_t)^{\top}\\
			   &= (P^{-1})^{\top}JP^{\top}(1,Y_t)^{\top}+\langle g'(0),(1,Y_t)\rangle (1,Y_t)^{\top}\\
			   &= (P^{-1})^{\top}JZ_t+\langle g'(0), (P^{-1})^{\top}Z_t\rangle (P^{-1})^{\top}Z_t\\
			   &=(P^{-1})^{\top}\left( J+\langle P^{-1}g'(0), Z_t\rangle\right) Z_t\\
			   &=(P^{-1})^{\top}\left( J+\langle P^{-1}Me_0, Z_t\rangle\right) Z_t\\
			   &=(P^{-1})^{\top}\left( J+\langle Jp, Z_t\rangle\right) Z_t.
		\end{aligned}
	\end{equation*}
	Multiplying by $P^{\top}$ on both sides and noting that $P^{\top}(0,b_t)^{\top}$ is the drift of the process $Z_t=P^{\top}(1,Y_t)^{\top}$ completes the proof.

\end{proof}
\begin{corollary}\label{cor:4_diagonalisable_m}
	Given the same assumptions as in \Cref{cor:4_basis_change}, assume additionally that $M$ is diagonalizable over $\R$. Then $H$ satisfies
	\begin{equation}\label{eq:4_diag_m}
		H_t(x)=1-\langle e^{xD}\bm{1}, Z_t\rangle,
	\end{equation}
	where $\bm 1\in\R ^{d+1}$ is the vector of ones, $D=\text{diag}(\lambda )$ is the diagonal matrix generated by the vector $\lambda$ of the eigenvalues $\lbrace\lambda _0,\dots ,\lambda _d\rbrace$ of $M$ and $Z$ is defined as $\text{diag}(p)P^{\top}(1,Y_t)^{\top}$, where $p=P^{-1}e_0$. Furthermore, $Z$ satisfies the drift condition
	\begin{equation}\label{eq:4_drift_cond_diag_m}
		b_t^Z=(D+\langle \lambda,Z_t\rangle \mathbbm 1_{d+1})Z_t,
	\end{equation}
	where $b^Z$ is the drift of $Z$.
\end{corollary}
\begin{proof}
	This follows directly by observing that in the case of a diagonal matrix $D$, we may use coordinate-wise multiplication of $p$.
\end{proof}
\begin{remark}
	It is easy to check that $g'(x)=e^{xM}m$, where $m\in\R^{d+1}$ is the first column vector of $M$, that is,  $m_i=M_{i,0}$ for $i=0,\dots ,d$.
\end{remark}

Thus, given the simplifying Assumption \ref{LA}, we may directly determine the space of admissible curves for a risk-neutral HJM model of discount curves, namely the space of quasi-exponentials. We can also determine conditions on the process $Y$ in this framework. 
\subsection{Time inhomogeneous case}
Certain non-trivial extensions of the affine discount model can be considered for more advanced applications. For completeness, we will provide one simple way of generalizing to the time-inhomogeneous case and prove admissibility conditions. This extended model's theoretical implications and statistical practicality are left for future research.

In the following, we make a slight generalization by letting the function $g$ depend on the time of observation $t$; that is, we set $H_t(x)=\langle g(x,t),f(Y_t)\rangle$. Through the application of It\^o's Lemma, we get that the resulting drift of $H(x)$ is of the form
\begin{equation}\label{eq:4_drift_time_inhom}
	\beta _t(x)=\langle\partial _tg(x,t),f(Y_t)\rangle+\langle g(x,t),D_yf(Y_t)b_t+\frac12\sum _{k=1}^d\Tr\left(\sigma _t\sigma _t^{\top}H_yf_k(Y_t)\right) e_k\rangle.
\end{equation}
To get an analogous result to \Cref{prop:4_3}, we first observe that the drift condition \eqref{eq:4_5} implies the same condition on the drift and diffusion coefficients of $Y_t$ as in \Cref{eq:4_prop23c}. On the other hand, the function $g$ is now obtained by solving a partial differential equation. We summarize the corresponding result in the following.
\begin{proposition}\label{prop:4_time_inhom_case}
	Let $H$ be a discount process satisfying \ref{LA} for a function $g\in C^{1,2}(\R _+\times\R _+,\R ^{d+1})$ and let $P(t,T)=1-H_t(T-t)$ be the zero-coupon bond model induced by $H$. Then the discounted bond price processes $(\tilde{P}(t,T))_{t\in [0,T]}$ are local martingales for all $T>0$ if and only if
	\begin{enumerate}
		\item There exists a matrix function $M:\R_+\rightarrow\R^{(d+1)\times (d+1)}$ such that the function $g$ is the solution to the problem
	\begin{equation}\label{eq:4_prop_time_inhom1}
		\begin{aligned}
			&\partial _xg(x,t)-\partial _tg(x,t) = M(t)g(x,t)+\partial _xg(0,t),\\
			&g(0,t)=0,
		\end{aligned}
	\end{equation}
%	where $M(t)$ is the matrix function defined as
%	\begin{equation}\label{eq:4_prop_time_inhom_mat}	
%		M(t):=\begin{pmatrix} -\partial _xg_0(0,t) & a_{0,1} & \cdots & a_{0,d} \\
%			\begin{matrix} -\partial _xg_1(0,t) \\
%				\vdots \\
%			-\partial _xg_d(0,t)\end{matrix} & &A-\partial _xg_0(0,t)\mathbbm{1}_d\end{pmatrix}
%		\end{equation}
%		for some $A\in\R ^{d\times d}$ and $a_0\in\R ^d$.
	\item The drift and diffusion coefficients $b$, respectively $\sigma$ of $Y$ satisfy
	\begin{equation}\label{eq:4_prop_time_inhom2}
            \begin{aligned}
		      &D_yf(Y_t)(0,b_t)^{\top}+\frac12\sum _{k=1}^d\Tr\left( \sigma _t\sigma _t^{\top}H_yf_k(Y_t)\right) e_k \\
                &=(M(t)^{\top}+\langle \partial _xg(0,t),f(Y_t)\rangle\mathbbm{1}_{d+1})f(Y_t).
            \end{aligned}
	\end{equation}
		\end{enumerate}
\end{proposition}
\begin{proof}
	See \Cref{app:b}.
\end{proof}
Assuming some regularity on the matrix function $M(t)$, we may obtain an explicit solution.
\begin{corollary}\label{cor:4_time_inhom_expl}
	Assume that $M(t_1)M(t_2)=M(t_2)M(t_1)$ for all pairs $(t_1,t_2)\in [0,T]\times[0,T]$. Then, the function $g$ is of the form
	\begin{equation}\label{eq:4_pde_expl_sol}
		g(x,t)=e^{\int _0^xM(T-\xi)d\xi}\int _0^xe^{-\int _0^{\xi}M(T-\zeta )d\zeta}\partial _xg(0,T-\xi )d\xi.
	\end{equation}
\end{corollary}
\begin{proof}
	See \Cref{app:b}.
\end{proof}
\section{Fully consistent kernels and induced RKHS}\label{sec:kernels}
Having derived the HJM-type conditions for the discount such that the induced bond market fulfills the NAFLVR condition, we are interested in finding kernels that generate RKHS rich enough to contain such markets. Indeed, we will verify that suitable kernels can generate models fulfilling the NAFLVR condition. We will make precise the notion of these fully consistent kernels. Before we give an appropriate notion, we begin with a definition for kernels, which hold a special significance for the rest of our considerations.
\begin{definition}\label{def:pol_exp_kernels}
	\begin{enumerate}
		\item Let $p:\R _+\times\R _+\rightarrow\R$ be a symmetric positive semidefinite polynomial in the sense of \Cref{def:4_kernel_function} (for a discussion of the terminology of positive semidefinite functions, see e.g. \cite[Section 2.2]{paulsen_rkhs}). Then $k_p(x,y):=p(x,y)$ is a kernel function, which we will refer to as the \emph{polynomial kernel} with the induced space $\mathcal H(p)$.
		\item Let $k_{\exp}(x,y):=e^{xy}$. We will refer to $k_{\exp}$ as the \emph{exponential kernel} with induced RKHS $\mathcal H(\exp)$.
	\end{enumerate}
\end{definition}
Note that we distinguish between the kernels and the functions themselves to avoid confusion whenever functions are used in a different context. In the definition of the respective RKHS, we, however, omit this distinction to emphasize the nature of the kernel. By a slight abuse of notation, we will use the same notation regardless of the reparametrization of the arguments of the functions and scaling by constant factors; that is, we will still call, e.g., $k(x,y)=ce^{(ax+b)(ay+b)}$ an exponential kernel.

In the next step, we introduce the kernels that generate spaces that are consistent with the admissibility conditions for the discount model. To this extent, we will use the following definition.
%\begin{definition}\label{def:fully consistent_kernel}
%	Let $k$ be a kernel function on $\R _+$ in the sense of Definition \ref{def:kernel_function}. We say $k$ is a \emph{fully consistent kernel} if for any choice of $x_1,\dots ,x_N\in\R _+$, $N\geq 2$, there is an admissible discount model $H$ fulfilling \ref{LA} with values $\mathbb Q$-a.s. in the space
%	\begin{equation*}
%		V:=\emph{span}\lbrace k(y_1,\cdot ),\dots ,k(y_N,\cdot )\rbrace .
%	\end{equation*}
%\end{definition}
%Definition \ref{def:fully consistent_kernel} makes precise the notion of kernels which generate spaces where admissible discount models lie. Using the results on the form of admissible curves, we may thus prove the following
\begin{definition}\label{def:fully consistent_kernel}
	Let $k$ be a kernel function on $\R _+$ in the sense of \Cref{def:4_kernel_function}. We say $k$ is \emph{fully consistent} if for any choice $y_1,\dots,y_N\in\R _+$, $N\in\mathbb N$ there is a finite-dimensional space $V\subseteq C^1(\R _+, \R)$ fulfilling
	\begin{enumerate}
		\item $\partial _x(V)\subseteq V$.\label{def:fully consistent_kernel_1}
		\item $k_{y_1},\dots,k_{y_N}\in V$.\label{def:fully consistent_kernel_2}
	\end{enumerate}
\end{definition}
\begin{remark}
	Condition \ref{def:fully consistent_kernel_1} of \Cref{def:fully consistent_kernel} is motivated by the theory of invariant manifolds (see, e.g., \cite{filipovic_invariant, teichmann1, tappe_invariant}). Indeed, the choice of $V$ as the smallest finite-dimensional derivative invariant space, which contains the span of kernels, is the natural choice of domain for the discount process. In some practical cases, this space coincides with the span of the kernels, e.g., in the case of the exponential kernel. This justifies the use of kernels fulfilling the conditions of \Cref{def:fully consistent_kernel} as a regression basis for the statistical calibration of the model.
\end{remark}
Next, we state a key result that will yield the necessary and sufficient conditions for the full consistency of kernels. This will serve as the basis for deriving kernels, which we will use as a regression basis for the estimation problem of the discount models.
\begin{proposition}\label{prop:4_u_space}
	Let $\mathcal{U}:=\lbrace x\mapsto \varphi\left(\left(\mathbbm{1}_{d+1}-e^{xM}\right) e_0\right): M\in\R ^{(d+1)\times (d+1)}, \varphi\in (\R ^{d+1})^*, d\in\mathbb{N}\rbrace$. A kernel $k$ for some RKHS is fully consistent if and only if the map $k_y:x\mapsto k(y,x)$ is such that $k_y\in\mathcal{U}$ for all $y\in\R _+$.
\end{proposition}
\begin{proof}
	See \Cref{app:b}.
\end{proof}
The space $\mathcal{U}$ can be seen as the space of admissible functions where we only consider a specific coordinate since we can choose $\varphi =\langle\cdot ,e_k\rangle$ for $k=1,\dots ,d$. We additionally state the following Lemma, which asserts a ``nice'' vector space structure on the set $\mathcal U$. In particular, this allows us to combine fully consistent kernels to suit our practical needs.
\begin{lemma}\label{lem:v_space_u}
	$\mathcal{U}$ is a vector space of $C^{\infty}$-functions.
\end{lemma}
\begin{proof}
	See \Cref{app:b}.
\end{proof}
\subsection{RKHS induced by fully consistent kernels}
\Cref{prop:4_u_space} gives a general condition for the full consistency of the kernel functions. We will now consider specific examples of kernels that can be used for the discount model and derive descriptions for the RKHS induced by those kernels. Indeed, we will show that there is a broad class of fully consistent kernels with induced RKHS, which provide a rich modelling basis for the discount model while retaining tractability for the computational task of calibrating to the market data. We will start with a definition.
\begin{definition}\label{def:weighted_norm}
	Let $\ell ^2(\R)$ denote the Hilbert space of square-summable sequences over $\R$ and let $w=(w_k)_{k\geq 0}\subseteq\R _+$ denote a sequence (possibly not in $\ell ^2(\R)$). Define for $f,g\in\ell ^2(\R)$ the weighted product
	\begin{equation}\label{eq:4_weighted_prod}
		\langle f,g\rangle _{\ell _w^2}=\langle w\odot f, g\rangle _{\ell ^2}=\langle f,w\odot g\rangle _{\ell ^2},
	\end{equation}
	where $w\odot f=(w_kf_k)_{k\geq 0}$ denotes the Hadamard product, and the weighted norm
	\begin{equation}\label{eq:4_weighted_norm}
		\Vert f\Vert ^2_{\ell ^2_w}:=\langle f,f\rangle _{\ell ^2_w}.
	\end{equation}
\end{definition}
We can now state a general result that will enable us to characterize fully consistent kernels for our model and obtain the RKHS induced by those kernels.
\begin{lemma}\label{lem:rkhs_general}
	Let $h:\R\rightarrow\R$ be a real-analytic function with $h^{(k)}(0)\geq 0$, where $h^{(k)}$ denotes the $k$-th order derivative of $h$ for $k\in\mathbb{N}$. Define the weight sequence $w=(w_k)_{k\geq 0}$ where $w_k:=\mathbbm{1}_{\lbrace h^{(k)}(0)>0\rbrace}(h^{(k)}(0))^{-1}$. Let $a,c\in\R$, $a\neq 0$ and define $k(x,y):=h((ax-c)(ay-c))$. Then $k$ is the reproducing kernel of the RKHS
	\begin{equation}\label{eq:4_rkhs_general_description}
		% \mathcal{H}(k)=\set[\Bigg]{f:\R\rightarrow\R\given f(x)=\sum _{k=0}^{\infty}\mathbbm{1}_{\lbrace h^{(k)}(0)>0\rbrace}\frac{f^{(k)}(\frac{c}{a})}{k!}\left(x-\frac{c}{a}\right)^k, \left\Vert \left(\frac{f^{(k)}\left(c/a\right)}{k!}\right) _{k\geq 0}\right\Vert _{\ell ^2_w}\!\!<\infty}
        \mathcal{H}(k)=\set[\Bigg]{f:\R\rightarrow\R\given f(x)=\sum _{k=0}^{\infty}\mathbbm{1}_{\lbrace h^{(k)}(0)>0\rbrace}b_k\left(x-\frac{c}{a}\right)^k, \left\Vert (b_k)_{k\geq 0}\right\Vert _{\ell ^2_w}\!\!<\infty},
	\end{equation}
	where $b_k:=f^{(k)}(c/a)/k!$, with inner product $\langle\cdot ,\cdot\rangle _{\mathcal{H}(k)}$ given by
	\begin{equation}\label{eq:4_rkhs_general_inner_prod}
		\langle f,g\rangle _{\mathcal{H}(k)}=\sum _{k=0}^{\infty}\frac{w_k}{a^{2k}k!}f^{(k)}\left(\frac{c}{a}\right) g^{(k)}\left(\frac{c}{a}\right)
	\end{equation}
	and with the induced norm
	\begin{equation}\label{eq:4_rkhs_general_inner_norm}
		\Vert f\Vert ^2_{\mathcal{H}(k)}=\sum _{k=0}^{\infty}\frac{w_k}{a^{2k}k!}\left\vert f^{(k)}\left(\frac{c}{a}\right)\right\vert^2.
	\end{equation}
\end{lemma}
\begin{proof}
	See \Cref{app:b}.
\end{proof}
Given the results of \Cref{prop:4_u_space}, we may choose the rich class of fully consistent kernels from the exponential-affine family of functions, and using the results of \Cref{lem:rkhs_general}, we obtain a precise description of the RKHS induced by those kernels.
\begin{proposition}\label{prop:4_rkhs}
	Let $p(t):=a_dt^d+...+a_1t+a_0$ be a polynomial, such that $a_k\geq 0$ for $k=0,\dots ,d$. Let $h_k:=e^{-\alpha ^2/\beta}\sum _{l=0}^{k\wedge\emph{deg}(p)}\binom{k}{l}l!a_l$ for $k\in\mathbb N_0$ and define the weight sequence $w=(w_k)_{k\geq 0}$, where $w_k:=\mathbbm{1}_{\lbrace h_k>0\rbrace}h_k^{-1}$. Let $\alpha,\beta\in\R$, $\alpha\geq 0,\beta > 0$ and define $k(x,y):=p((\sqrt{\beta}x-\alpha /\sqrt{\beta} )(\sqrt{\beta}y-\alpha /\sqrt{\beta}))e^{\beta xy-\alpha (x+y)}$. Then $k$ is a fully consistent kernel in the sense of \Cref{def:fully consistent_kernel} and is the reproducing kernel of the RKHS
	\begin{equation}\label{eq:4_rkhs_description}
		% \mathcal{H}(k)=\set[\Bigg]{ f:\R _+\rightarrow\R\given f(x)=\sum _{k=0}^{\infty}\mathbbm{1}_{\lbrace h_k>0\rbrace}\frac{f^{(k)}\left(\frac{\alpha}{\beta}\right)}{k!}\left(x-\frac{\alpha}{\beta}\right)^k,\left\Vert \left(\frac{f^{(k)}\left(\alpha /\beta\right)}{k!}\right) _{k\geq 0}\right\Vert _{\ell ^2_w} <\infty }
        \mathcal{H}(k)=\set[\Bigg]{ f:\R _+\rightarrow\R\given f(x)=\sum _{k=0}^{\infty}\mathbbm{1}_{\lbrace h_k>0\rbrace}
        b_k\left(x-\frac{\alpha}{\beta}\right)^k,\left\Vert (b_k)_{k\geq 0}\right\Vert _{\ell ^2_w} <\infty },
	\end{equation}
	where $b_k:=f^{(k)}(\alpha /\beta)/k!$, with inner product $\langle\cdot ,\cdot\rangle _{\mathcal{H}(k)}$ given by
	\begin{equation}\label{eq:4_inner_prod}
		\langle f,g\rangle _{\mathcal{H}(k)}=\sum _{k=0}^{\infty}\frac{w_k}{\beta ^kk!}f^{(k)}\left(\frac{\alpha}{\beta}\right) g^{(k)}\left(\frac{\alpha}{\beta}\right),
	\end{equation}
	and induced norm
	\begin{equation}\label{eq:4_rkhs_norm}
		\Vert f\Vert ^2_{\mathcal{H}(k)}=\sum _{k=0}^{\infty}\frac{w_k}{\beta ^kk!}\left\vert f^{(k)}\left(\frac{\alpha}{\beta}\right)\right\vert ^2.
	\end{equation}
\end{proposition}
\begin{proof}
	See \Cref{app:b}.
\end{proof}
\begin{remark}
	\begin{enumerate}
		\item In the case $\beta =0$, $p\equiv 1$, the function $k(x,y):=e^{-\alpha (x+y)}$ is a fully consistent kernel and induces the reproducing kernel Hilbert space $\mathcal{H}(k)=\lbrace f:\R_+\rightarrow\R\vert f(x)=ce^{-\alpha x}, c\in\R\rbrace$ with inner product $\langle c_1e^{-\alpha\cdot},c_2e^{-\alpha\cdot}\rangle _{\mathcal{H}(k)} = c_1c_2$. This follows from the fact that $k(x,y)=f(x)f(y)$, where $f(t):=e^{-\alpha t}$ and the considerations in \cite[Proposition 2.19]{paulsen_rkhs}.
		\item One may extend the definition of the kernel $k$ to the case $\alpha\in\R$. The shift in the Taylor-series to the negative results in a reproducing kernel Hilbert space $\mathcal{H}(k)$ of real analytic functions $f:\R\rightarrow\R$ which fulfill the same weighted square-summability condition. Since we are only interested in term structure models in positive time, we may consider the restriction $f\big\vert _{\R_+}$ for $f\in\mathcal{H}(k)$.
		\item In the case $p\equiv 1$, the resulting RKHS is a special case of the Segal-Bargmann space of analytic functions (see, for instance, \cite[Subsection 7.3.2]{paulsen_rkhs} and \Cref{prop:4_bargmann_space}).
		\item Let $\varphi :x\mapsto \sqrt{\beta}x-\alpha /\sqrt{\beta}$ and $\Delta :x\mapsto (x,x)$. Define $\tilde{k}(x,y):=xy, k_p:=p\circ\tilde{k}\circ\varphi$ and $k_{\exp}:=\exp\circ\tilde{k}\circ\varphi$ and $k:=e^{-\alpha ^2/\sqrt{\beta}}k_pk_{\exp}$. The space $\mathcal{H}(k)$ can be realized as the pullback along the map $\Delta$ of the tensor Hilbert space $\mathcal{H}(\exp )\otimes\mathcal{H}(p)$. Indeed, $k$ induces the RKHS $\mathcal{H}(k)=\lbrace f:\R _+\rightarrow\R\vert f(x)=g(x)h(x), g\in\mathcal{H}(\exp ), h\in\mathcal{H}(p)\rbrace$ with induced norm $\Vert f\Vert _{\mathcal{H}(k)}=\min\lbrace\Vert g\Vert _{\mathcal{H}(\exp )}\Vert h\Vert _{\mathcal{H}(p)}, f=gh, g\in\mathcal{H}(\exp ), h\in\mathcal{H}(p)\rbrace$. This follows from \Cref{lem:rkhs_general} and \cite[Theorem 5.16]{paulsen_rkhs}.
	\end{enumerate}
\end{remark}
\begin{proposition}\label{prop:4_fully consistent_ker}
	Let $p_i(t)=a_{d,i}t^d+...+a_{1,i}t+a_{0,i}$ with $a_{k,i}\geq 0$ for $k=0,\dots ,d$ and $i=1,\dots ,d+1$ and let $\alpha _i,\beta _i\in\R$, $\alpha _i\geq 0,\beta _i >0$ for $i=1,\dots ,d+1$. Set $k_i(x,y)=p_i((\sqrt{\beta _i}x-\alpha _i/\sqrt{\beta _i})(\sqrt{\beta _i}y-\alpha _i/\sqrt{\beta _i}))e^{\beta _ixy-\alpha _i (x+y)}$ and define $k(x,y)=\sum _{i=1}^{d+1}k_i(x,y)$. Then $k$ is a fully consistent kernel in the sense of \Cref{def:fully consistent_kernel} and gives rise to the RKHS given by the direct sum $\mathcal{H}(k)=\mathcal{H}(k_1)\oplus\dots\oplus\mathcal{H}(k_{d+1})$, with norm
	\begin{equation}\label{eq:4_fully consistent_ker_norm}
		\Vert f\Vert ^2_{\mathcal{H}(k)}=\emph{min}\left\lbrace\sum _{i=1}^{d+1}\Vert f_i\Vert ^2_{\mathcal{H}(k_i)}:f=\sum _{i=1}^{d+1}f_i, f_i\in\mathcal{H}(k_i), i=1,\dots ,d+1\right\rbrace ,
	\end{equation}
	where the spaces $\mathcal{H}(k_1),\dots ,\mathcal{H}(k_{d+1})$ are defined as in \Cref{prop:4_rkhs}.
\end{proposition}
