\section{Reproducing kernel Hilbert spaces}\label{sec:rkhs_theory}
In this section, we provide some of the basic theory of reproducing kernel Hilbert spaces which is used in later parts of the paper. In particular, we provide references for some of the results used throughout the paper. Most of the theory and results contained in this section can be found in \cite{aronszajn} and \cite{paulsen_rkhs}. We begin with the following
\begin{definition}\label{def:4_rkhs}
	Let $\mathcal X$ be a set and $\mathbb F$ denote either $\R$ or $\mathbb C$ and denote by $\mathfrak{F}(\mathcal X,\mathbb F)$ the set of functions $f:\mathcal X\rightarrow\mathbb F$. A subset $\mathcal H\subseteq\mathcal F(\mathcal X,\mathbb F)$ is called a \emph{reproducing kernel Hilbert space} (RKHS) if 
	\begin{enumerate}
		\item $\mathcal H$ is a vector space of $\mathfrak F(\mathcal X,\mathbb F)$.
		\item $\mathcal H$ is a Hilbert space with some inner product $\langle \cdot,\cdot\rangle _{\mathcal H}$.
		\item For every $x\in \mathcal X$, the evaluation functional $\delta _x:\mathcal H\rightarrow\mathbb F$ defined as $\delta _x:f\mapsto f(x)$ is bounded.
	\end{enumerate}
\end{definition}
For the remainder of this section let $\mathcal H\subseteq\mathfrak F(\mathcal X, \mathbb F)$ be an RKHS with inner product $\langle\cdot ,\cdot\rangle _{\mathcal H}$.
In the case of an RKHS, by the Riesz representation theorem and the dual representation of a Hilbert space, there exists a function $k_x\in\mathcal H$, such that
	\begin{equation}\label{eq:4_reproducing}
		f(x)=\langle f,k_x\rangle_{\mathcal H}\quad\text{for any }x\in\mathcal X.
	\end{equation}
\begin{definition}
	The function $k(x,y):=\langle k_x,k_y\rangle _{\mathcal H}$ is called the \emph{reproducing kernel} of $\mathcal H$.
\end{definition}
We also call \Cref{eq:4_reproducing} the \emph{reproducing property} of the reproducing kernel $k$. This property allows us to derive some simple, but powerful results on RKHS, such as denseness of the kernel function (see, e.g.~\cite[Proposition 2.1]{paulsen_rkhs}):
\begin{proposition}\label{prop:4_denseness}
	Let $\mathcal H$ be an RKHS with reproducing kernel $k$ on the set $\mathcal X$. Then the linear span of the set $\{ k_x: x\in \mathcal X\}$ is dense in $\mathcal H$.
\end{proposition}
Once can also derive the following convenient convergence properties, which we will utilise throughout the paper:
\begin{lemma}\label{lem:convergence}
	Let $\mathcal H$ be an RKHS, let $f\in\mathcal H$ and let $(f_n)_{n\geq 0}\subseteq\mathcal H$ be a sequence of functions in $\mathcal H$.
	\begin{enumerate}
		\item If $f_n\rightarrow f$ in norm, then $f_n\rightarrow f$ pointwise.
		\item If $f_n\rightarrow f$ weakly, then $f_n\rightarrow f$ pointwise. If, additionally $\Vert f_n\Vert _{\mathcal H}< \infty$ for all $n\geq 0$, then $f_n\rightarrow f$ pointwise implies $f_n\rightarrow f$ weakly. 
	\end{enumerate}
\end{lemma}
\begin{proof}
    See \Cref{app:b}.
\end{proof}

We provide one of the more important characterisations of functions which are candidates to become reproducing kernels of some RKHS.
\begin{definition}\label{def:4_kernel_function}
	Let $\mathcal X$ be a set and let $f:\mathcal X\times \mathcal X\rightarrow\mathbb F$ be a symmetric function, that is $f(x,y)=f(y,x)$ for all $x,y\in\mathcal X$. $f$ is called \emph{positive semidefinite} if for any $n\in\mathbb N$ and any choice $\{ x_1,\dots ,x_n\}\subseteq \mathcal X$ of distinct $n$ points the matrix $(k(x_i,x_j))_{i,j=1}^n$ is positive semidefinite. In that case, we will also refer to $f$ as a \emph{kernel function}.
\end{definition}
\begin{remark}
	Note that positive semidefiniteness implies that $f(x,y)\geq 0$ for all $x,y\in \mathcal X$ and if $\mathbb F =\mathbb C$, then it also implies that $f$ is symmetric.
\end{remark}
Kernel functions are fundamental in the sense that they correspond to reproducing kernel of some RKHS. Indeed, we have the following two important results:
\begin{proposition}
	Let $\mathcal H$ be an RKHS on the set $\mathcal X$ with reproducing kernel $k$. Then $k$ is a kernel function.
\end{proposition}
\begin{proof}
	We have for any $x,y\in \mathcal X$ that $k(x,y)=\langle k_x,k_y\rangle _{\mathcal H}$. Therefore, symmetry and positive definiteness follows from the properties of the inner product.
\end{proof}
The converse statement is a fundamental result due to Moore (see, e.g. \cite{aronszajn}, \cite[Theorem 2.14.]{paulsen_rkhs}).
\begin{theorem}\label{thm:4_aronszajn_moore}
	Let $\mathcal X$ be a set and let $k:\mathcal X\times \mathcal X\rightarrow\mathbb F$ be a kernel function. Then there exists a unique RKHS $\mathcal H$ such that $k$ is the reproducing kernel for $\mathcal H$.
\end{theorem}

\section{Technical tools}\label{app:b}
\begin{lemma}\label{lem:dx_invariance}
	A finite-dimensional vector space $V\subseteq C^1(\mathbb R_+,\mathbb R)$ is derivative invariant if and only if there is a matrix $A$ such that the coordinate functions of $b(x):=\exp (xA)b_0$ are a basis for $V$ where $b_0:=b(0)$.
\end{lemma}
\begin{proof}
	Let $V\subseteq C^1(\R _+,\R)$ be a finite-dimensional vector space. Assume there are $A\in\R ^{d\times d}$ for some $d\in\mathbb N$ and $b:\R _+\rightarrow\R ^d$ defined as above such that $\{ b(x): x\in\R _+\}$ are a basis for $V$, then we see that for each $k=1,\dots,d$, $b_k' = (Ab)_k = \sum _{l=1}^d A_{kl}b_l \in V$. Thus, the derivatives of the basis functions $b_1,\dots,b_d$ are in $V$ and, hence, $V$ is derivative invariant.
For the converse, assume that $V$ is derivative invariant. Let $b_1,\dots,b_d$ be a basis for $V$. Then $b_k' \in V$ and hence there are coefficients $a_{k,1},\dots,a_{k,d}$ such that $b_k' = \sum_{l=1}^d a_{k,l}$. Define $A:=(a_{k,l})_{kl}$. Observe that $b' = Ab$. We find that $b(x) = \exp (xA) b_0$ where $b_0=b(0)$.
\end{proof}
\begin{corollary}\label{cor:full_consistency_equiv}
	Let $k$ be a kernel function in the sense of \Cref{def:4_kernel_function}. $k$ is fully consistent if and only if for any $y_1,\dots, y_N$ there is a matrix $A_N$ such that $b(x) := (k(y_1,x),\dots,k(y_N,x))$ satisfies $b(x) = \exp( xA )b_0$.
\end{corollary}
\begin{proof}
	This follows immediately from \Cref{def:fully consistent_kernel} and \Cref{lem:dx_invariance} by taking $V=\text{span}\{k_{y_1},\dots ,k_{y_N}\}$.
\end{proof}
\begin{proposition}\label{prop:4_bargmann_space}
	Let $k_{\exp}$ be the exponential kernel on $\mathbb{C}$, that is $k_{\exp}=e^{x\bar y}$ and let $\mathcal H(\exp )$ denote the RKHS induced by $k_{\exp}$. Denote by $\mathcal B$ the Segal-Bargmann space of analytic functions defined as
	\begin{equation*}
		\mathcal B:=\set{ f:\mathbb C\rightarrow \mathbb C\given \Vert f\Vert _{\mathcal B} <\infty },
	\end{equation*}
	where the norm $\Vert\cdot\Vert _{\mathcal B}$ is induced by the inner product
	\begin{equation*}
		\langle f,g\rangle _{\mathcal B}:=\frac{1}{\pi}\int _{\mathbb C}f(z)\overline{g(z)}e^{-\vert z\vert ^2}\frac{i}{2}dz\wedge d\bar z,\qquad f,g\in\mathcal B.
	\end{equation*}
	Then $\mathcal B =\mathcal H(\exp )$.
\end{proposition}
\begin{proof}
	It is sufficient to prove that $\langle f,g\rangle _{\mathcal H(\exp )}=\langle f,g\rangle _{\mathcal B}$ for all $f,g\in\mathcal B$. We first note that the surface $1$-form $dz\wedge d\bar z$ satisfies 
	\begin{equation*}
	    \begin{aligned}	
                dz\wedge d\bar z&=(dx+idy)\wedge (dx-idy)\\
                &=dx\wedge dx+idy\wedge dx-idx\wedge dy-dy\wedge dy=-2idx\wedge dy
            \end{aligned}
	\end{equation*}
	by the skew-symmetry of the wedge product, and therefore we have
	\begin{equation*}
		\begin{aligned}
			\langle f,g\rangle _{\mathcal B}&=\frac{1}{\pi}\int _{\mathbb C}f(z)\overline{g(z)}e^{-\vert z\vert ^2}\frac{i}{2}dz\wedge d\bar z\\
            &=\frac{1}{\pi}\int _0^{\infty}\int _0^{\infty}f(x+iy)\overline{g(x+iy)}e^{-(x^2+y^2)}dxdy.
		\end{aligned}
	\end{equation*}
	Making the coordinate change $x+iy=re^{it}$, we find
	\begin{equation*}
		\begin{aligned}
			\langle f,g\rangle _{\mathcal B}&=\frac{1}{\pi}\int _0^{\infty}\int _0^{2\pi}f(re^{it})\overline{g(re^{it})}re^{-r^2}dtdr\\
							&=\frac{1}{\pi}\int _0^{\infty}\int _0^{2\pi}\sum _{k=0}^{\infty}\sum _{l=0}^{\infty}\frac{f^{(k)}(0)}{k!}\frac{\overline{g^{(l)}(0)}}{l!}\left( re^{it}\right) ^k\left( re^{-it}\right) ^lre^{-r^2}dtdr\\
							&=\frac{1}{\pi}\sum _{k=0}^{\infty}\sum _{l=0}^{\infty}\frac{f^{(k)}(0)}{k!}\frac{\overline{g^{(l)}(0)}}{l!}\int _0^{\infty}r^{2k+1}e^{-r^2}\int _0^{2\pi}e^{it(k-l)}dtdr,
		\end{aligned}
	\end{equation*}
	where we used the analyticity of the functions $f$ and $g$ to write down their Taylor series expansions and interchange summation with integration. Now we note that
	\begin{equation*}
		\begin{aligned}
			\int _0^{2\pi}e^{it(k-l)}dt =\begin{cases}2\pi, &\text{ if }k=l,\\
			0, &\text{ else.}\end{cases}
		\end{aligned}
	\end{equation*}
	We additionally have that
	\begin{equation*}
		\begin{aligned}
			\int _0^{\infty}r^{2k+1}e^{-r^2}dr=\frac{\Gamma (k+1)}{2} = \frac{k!}{2}
		\end{aligned}
	\end{equation*}
	for $k\in\mathbb N$. Therefore, 
	\begin{equation*}
		\langle f,g\rangle _{\mathcal B}=\sum _{k=0}^{\infty}\frac{f^{(k)}(0)\overline{g^{(k)}(0)}}{k!},
	\end{equation*}
	which proves the assertion.

\end{proof}
\begin{lemma}\label{lem:dx_product}
	Let $k_{\exp}$ be the exponential kernel on $\mathbb C$ and $\mathcal H(\exp )$ be the induced RKHS. Then we have
	\begin{equation*}
		\langle\partial _{\lambda } (\cdot ^ke^{\lambda\cdot}),\partial _{\mu}(\cdot ^le^{\mu\cdot})\rangle _{\mathcal H(\exp )}=\partial _{\lambda}\partial _{\mu}\langle e^{\lambda\cdot},e^{\mu\cdot}\rangle _{\mathcal H(\exp )}
	\end{equation*}
\end{lemma}
\begin{proof}
	To simplify the proof, we will use \Cref{prop:4_bargmann_space} and work with the integral representation of the inner product. We have
	\begin{equation*}
		\begin{aligned}
			&\int _0^{\infty}\int _0^{\infty}\partial _{\lambda}\partial _{\mu}\left( (x+iy)^ke^{\lambda (x+iy)}\overline{(x+iy)^le^{\mu (x-iy)}}e^{-(x^2+y^2)}\right) dxdy\\
			&=\int _0^{\infty}\int _0^{\infty}(x+iy)^k(x-iy)^l\partial _{\lambda}\left( e^{\lambda (x+iy)}\right)\partial _{\mu}\left(\overline{e^{\mu (x+iy)}}\right)e^{-(x^2+y^2)}dxdy\\
			&=\int _0^{\infty}\int _0^{\infty} (x+iy)^{k+1}(x-iy)^{l+1}e^{\lambda (x+iy)}e^{\mu (x-iy)}e^{-(x^2+y^2)}dxdy\\
			&=\int _0^{\infty}\int _0^{2\pi}r^{k+1}e^{itk}r^{l+1}e^{-itl}e^{\lambda re^{itk}}e^{\mu re^{-itl}}e^{-r^2}dtdr\\
			&=\int _0^{\infty}\int _0^{2\pi}r^{k+l+2}e^{it(k-l)}e^{r(\lambda e^{itk}+\mu e^{-itl})}e^{-r^2}dtdr\leq 2\pi\int _0^{\infty}r^{k+l+2}e^{r(\mu +\lambda)-r^2}dr.
		\end{aligned}
	\end{equation*}
	For any $\lambda ,\mu\in\R$ we can find a constant $C>0$ such that $e^{r(\lambda +\mu)}<Ce^{r^2/2}$ and thus
	\begin{equation*}
		\begin{aligned}
			&\int _0^{\infty}\int _0^{\infty}\partial _{\lambda}\partial _{\mu}\left( (x+iy)^ke^{\lambda (x+iy)}\overline{(x+iy)^le^{\mu (x-iy)}}e^{-(x^2+y^2)}\right) dxdy\\
			&\leq 2\pi C\int _0^{\infty}r^{k+l+2}e^{-r^2/2}dr<\infty.
		\end{aligned}
	\end{equation*}
	Since we have found an integrable majorant, we may use the Leibniz integral rule (see, e.g. \cite{folland}) to interchange differentiation and integration, yielding the result.

\end{proof}
Before we provide the next result, we first provide a definition of the notiotion of \emph{coercive} functions for the reader's convenience.
\begin{definition}\label{def:coercive}
	Let $E$ be a Banach space. A function $f:E\rightarrow\R$ is called \emph{coercive} if for any sequence $\{x _n\}_{n\in\mathbb N}\subseteq E$ with $\Vert x_n\Vert\rightarrow\infty$ as $n\rightarrow\infty$, it holds that $f(x_n)\rightarrow\infty$ as $n\rightarrow\infty$.
\end{definition}
\begin{lemma}\label{lem:weak_optimisation}
	Let $E$ be a reflexive Banach space and let $q:E\rightarrow\R$ be a continuous, coercive, strictly convex map. Assume $V\subseteq E$ is a non-empty set which is closed in the weak topology $\sigma (E, E^*)$. Then there is $x_0\in V$, such that 
	\begin{equation*}
		q(x_0)=\inf\lbrace q(x): x\in V\rbrace.
	\end{equation*}
\end{lemma}
\begin{proof}
	Since $q$ is coercive, the set $C_a:=\{ x\in E: q(x)\leq a\}$ for $a\in\R$ is bounded. Furthermore, since $C_a$ is closed and convex, there is $a\geq 0$, such that $C_a\cap V\neq\emptyset$. By the Banach-Alaoglu Theorem (cf. \cite[Theorem 3.16]{brezis}), $C_a$ is weakly compact, hence, $C_a\cap V$ is weakly compact by the closedness of $V$. Since $q$ is convex and continuous in the norm topology on $E$, it is lower semicontinuous in the weak topology. Thus, there is $x_0\in C_a\cap V$, such that $q(x_0)=\inf _{x\in C_a\cap V}q(x)=\inf _{x\in V}q(x)$ as required.
\end{proof}

\begin{lemma}\label{lem:q_factorisation}
	Let $p:\R _+\times\R _+\rightarrow\R$ be a symmetric, positive semidefinite polynomial. Assume there is $x_0\geq 0$ such that $p(x_0,x_0)=0$. Then there is a positive semidefinite polynomial $r:\R _+\times\R _+\rightarrow\R$ such that
	\begin{equation}\label{eq:q_factorisation1}
		p(x,y)=(x-x_0)(y-x_0)r(x,y)\qquad\text{for all }x,y\geq 0.
	\end{equation}
\end{lemma}
\begin{proof}
	Define the rational positive semidefinite function
	\begin{equation*}
		r(x,y):=\frac{p(x,y)}{(x-x_0)(y-x_0)}\qquad\text{for all }x,y\in\R _+\setminus\{ x_0\}.
	\end{equation*}
	Let $y\in\R _+\setminus\{ x_0\}$ be fixed. To conclude the proof, we will show that $r$ is a polynomial. Note that $\vert p(x_0,y)\vert <\sqrt{p(x_0,x_0)}\sqrt{p(y,y)}=0$. Thus, $p(\cdot, y)$ is a polynomial with a root in $x_0$, and therefore $r(\cdot ,y)$ is a polynomial. Now, $r$ is a polynomial function in its first argument and, by symmetry, its second argument. This implies it is a polynomial in two variables (see, e.g. \cite{carroll}).
\end{proof}
\begin{lemma}\label{lem:q_factorisation2}
	Let $p:\R _+\times\R _+\rightarrow\R$ be a positive semidefinite polynomial. Then there is a polynomial $q:\R_+\rightarrow\R$ and a positive semidefinite polynomial $r:\R _+\times\R _+\rightarrow\R$ such that
	\begin{enumerate}
		\item $p(x,y)=q(x)q(y)r(x,y)$ for all $x,y\geq 0$,
		\item $r(x,x)>0$ for all $x\geq 0$.
	\end{enumerate}
\end{lemma}
\begin{proof}
	This is a direct consequence of \Cref{lem:q_factorisation} through repeated factorisation.
\end{proof}
\begin{lemma}\label{lem:q_multiplier}
	Let $p:\R _+\times\R _+\rightarrow\R$ be a symmetric, positive semidefinite polynomial. Let $q:\R_+\rightarrow\R$ and $r:\R _+\times\R _+\rightarrow\R$ be as in \Cref{lem:q_factorisation2} and let $\mathcal H(r)$ and $\mathcal H(p)$ be the RKHS induced by $r$ and $p$, respectively. For a function $f:\R_+\rightarrow\mathbb C$ define $M_q(f):=q\cdot f$. Then $M_q:\mathcal H(r)\rightarrow\mathcal H(p)$ is a linear bijective isometry.
\end{lemma}
\begin{proof}
	Let $h\in\mathcal H(r)$. Since $r$ is a polynomial, we have $\text{dim}(\mathcal H(r))=\text{deg}(r)<\infty$. Then, for some $n<\infty$, there are $\lambda _1,\dots ,\lambda _n$, $x_1,\dots ,x_n\geq 0$ with $q(x_i)\neq 0$ for $i=1,\dots ,n$ such that $h=\sum _{i=1}^n\lambda _ir(\cdot ,x_i)$. We have
	\begin{equation*}
		M_q(h)=q\cdot h=\sum _{i=1}^n\lambda _iq\cdot h(\cdot, x_i)=\sum _{i=1}^n\frac{\lambda _i}{q(x_i)}p(\cdot, x_i)\in\mathcal{H}(p).
	\end{equation*}
	Thus, $M_q:\mathcal H(r)\rightarrow\mathcal H(p)$ is linear. Let now $g\in\mathcal H(p)$. Then, for $m<\infty$ there are $\eta _1,\dots ,\eta _m\in\R$ and $x_1,\dots ,x_m\geq 0$ such that $g=\sum _{i=1}^m\eta _ip(\cdot ,x_i)$. We then have
	\begin{equation*}
		\begin{aligned}
			g&=\sum _{i=1}^m\eta _ip(\cdot ,x_i)=\sum _{i=1}^m\eta _iq\cdot q(x_i)r(\cdot ,x_i)\\
			 &=q\cdot\sum _{i=1}^m\left(\eta _iq(x_i)\right) r(\cdot ,x_i)=M_q\underbrace{\left(\sum _{i=1}^m\left(\eta _iq(x_i)\right) r(\cdot ,x_i)\right)}_{\in\mathcal H(r)}.
		\end{aligned}
	\end{equation*}
	Hence, $M_q$ is surjective. It is easy to see that $M_q(f)=0$ if and only if either $f\equiv 0$ or $q\equiv 0$, hence it is injective and therefore bijective.

	For $h\in\mathcal H(r)$ we have 
	\begin{equation*}
		M_q(h)(x)=q(x)h(x)=q(x)\langle h,r(\cdot ,x)\rangle _{\mathcal H(r)}=\langle h,q(x)r(\cdot ,x)\rangle _{\mathcal H(r)}.
	\end{equation*}
	On the other hand,
	\begin{equation*}
		\begin{aligned}
			M_q(h)(x)&=q(x)h(x)=(q\cdot h)(x)=\langle q\cdot h,p(\cdot ,x)\rangle _{\mathcal H(p)}\\
				 &=\langle M_q(h), p(\cdot ,x)\rangle _{\mathcal H(p)}=\langle h,M_q^*(p(\cdot ,x))\rangle _{\mathcal H(r)}.
		\end{aligned}
	\end{equation*}
	Therefore, we have $M_q^*(p(\cdot ,x))=r(\cdot ,x)q(x)=p( \cdot, x)/q$ and hence $M_q^*(g)=g/q$ for all $g\in\mathcal H(p)$. This implies $M_q^*=M_q^{-1}$, whence $M_q$ is an isometry.
\end{proof}
\begin{proposition}\label{prop:4_isometry}
	Let $p:\R _+\times\R _+\rightarrow\R$ be a symmetric, positive semidefinite polynomial. Let $q$ and $r$ be defined as in \Cref{lem:q_factorisation2} and $\mathcal H(p)$ and $\mathcal H(r)$ be the RKHS induced by $p$ and $r$, respectively. Furthermore, let $\mathcal H(\exp)$ be the RKHS induced by the exponential kernel. Then
	\begin{equation*}
		H(p)\otimes\mathcal H(\exp)\cong\mathcal H(r)\otimes\mathcal H(\exp)
	\end{equation*}
	isometrically with isometry 
	\begin{equation*}
		\begin{aligned}
			&M_q:\mathcal H(r)\otimes\mathcal H(\exp )\rightarrow\mathcal H(p)\otimes\mathcal H(\exp)&\\
			&M_q:a\otimes b\mapsto (q\cdot a)\otimes b&\text{for all }a\in\mathcal H(r), b\in\mathcal H(\exp).
		\end{aligned}
	\end{equation*}
\end{proposition}
\begin{proof}
	This is a direct consequence of \Cref{lem:q_multiplier}.
\end{proof}
\begin{corollary}\label{cor:isometry}
	Let $p,q,r$ and $\mathcal H(p),\mathcal H(r),\mathcal H(\exp)$, as well as $M_q$ be defined as in \Cref{prop:4_isometry}. Let $\emph{tr}$ be the map $\Tr: f\otimes g\mapsto f\cdot g$. Then the following diagram commutes
	\begin{equation*}
		\begin{tikzcd}
			\mathcal H(r)\otimes \mathcal H(\exp) \arrow{r}{M_q} \arrow[swap]{d}{\Tr} & \mathcal H(p)\otimes\mathcal H(\exp) \arrow{d}{\Tr} \\
			\mathcal H(r)\mathcal H(\exp) \arrow{r}{M_q}& \mathcal H(p)\mathcal H(\exp)
		\end{tikzcd}
	\end{equation*}
	.
\end{corollary}
\begin{proof}
	This follows directly from \Cref{prop:4_isometry}.
\end{proof}

\section{Technical proofs}\label{app:c}

\begin{proof}[Proof of \Cref{prop:4_1}]
        The dynamics of the discounted price process $\tilde{P}(t,T)$ as defined in \Cref{eq:4_3}, fulfill
	\begin{equation}\label{eq:a1}
                d\tilde{P}(t,T)=-r_te^{-\int _0^tr_sds}P(t,T)dt+e^{-\int _0^tr_sds}dP(t,T).
        \end{equation}
	Since $H_t$ is a mild solution to \Cref{eq:4_sde}, we may use \Cref{eq:4_2} and write
	\begin{equation*}
		H_t(T-t) = H_0(T)+\int _0^t\alpha _s(T-s)ds+\int _0^t\Sigma _s(T-s)dW_s.
	\end{equation*}
	Using the fact that $P(t,T)=1-H_t(T-s)$ and inserting the dynamics into \Cref{eq:a1} yields
	\begin{equation*}
		d\tilde{P}(t,T)=e^{-\int _0^tr_sds}\left( (-\alpha _t(T-t)-r_t(1-H_t(T-t))dt-\Sigma _t(T-t)dW_t\right).
	\end{equation*}
        Now, the process $\tilde{P}(t,T)$ is a local martingale if and only if its drift vanishes. This is equivalent to
	\begin{equation*}
		\alpha _t=r_tH_t-r_t.
	\end{equation*}
	If, in addition, $H_t$ is a strong solution to \eqref{eq:4_sde} and the evaluation functional $\delta _xh:=h(x)$ is continuous, the process $\beta _t(x):=\delta _x\left(\partial _xH_t+\alpha _t\right)$ exists for all $x\in\R_+$ and is the drift of the process $H_t(x)$. Then we obtain the drift condition
	\begin{equation*}
		\beta _t(x)=H_t'(x)-r_t+r_tH_t(x).
	\end{equation*}

\end{proof}
\begin{proof}[Proof of \Cref{prop:4_3}]
	In the case of a $d$-dimensional diffusion $Y$, we find that $\beta _t(x)=\langle g(x),D_yf(Y_t)b_t+\frac12\sum _{k=1}^d\Tr\left( \sigma _t\sigma _t^{\top}H_yf_k(Y_t)\right) e_k\rangle$. The drift condition \eqref{eq:4_5} now reads
        \begin{equation*}
		\langle g(x), D_yf(Y_t)b_t+\frac12\sum _{k=1}^d\Tr\left( \sigma _t\sigma _t^{\top}H_yf_k(Y_t)\right) e_k\rangle = H_t'(x)-r_t+r_tH_t(x).
        \end{equation*}
        Inserting our definitions yields
        \begin{equation*}
                \begin{aligned}
			&\langle g(x),D_yf(Y_t)b_t+\frac12\sum _{k=1}^d\Tr\left( \sigma _t\sigma _t^{\top}H_yf_k(Y_t)\right) e_k\rangle \\ 
			&=\langle g'(x),f(Y_t)\rangle -\langle g'(0),f(Y_t)\rangle +\langle g'(0),f(Y_t)\rangle\langle g(x),f(Y_t)\rangle\\
		\end{aligned}
        \end{equation*}
Grouping terms in a convenient way yields
\begin{equation}\label{eq:4_10}
	\begin{aligned}
		&\langle g(x), D_yf(Y_t)b_t+\frac12\sum _{k=1}^d\Tr\left( \sigma _t\sigma _t^{\top}H_yf_k(Y_t)\right) e_k-\langle g'(0), f(Y_t)\rangle f(Y_t)\rangle \\
		&=\langle g'(x)-g'(0),f(Y_t)\rangle .
	\end{aligned}
\end{equation}
We now observe that since we have an inner product of a function depending only on $x$ and a random process independent of $x$, we may look at the factors separately. That is, there is a vector $a_0\in\R ^d$ and a matrix $A\in\R ^{d\times d}$, such that the following system of equations holds
\begin{equation*}
	\begin{aligned}
		\langle a_0,\tilde{g}(x)\rangle &=g'_0(x)+g'_0(0)g_0(x)-g'_0(0),\\
		A\tilde{g}(x)&=\tilde{g}'(x)+g'(0)g_0(x)+g'_0(0)\tilde{g}(x)-g'(0),
	\end{aligned}
\end{equation*}
where $\tilde{g}:=(g_1,\dots ,g_d)^{\top}$. After reordering terms, We obtain the inhomogeneous linear system of ODEs
\begin{equation}\label{eq:ode_nonmat}
	\begin{aligned}
		g'_0(x)&=\langle a_0,\tilde{g}(x)\rangle -g'_0(0)g_0(x)+g'_0(0),\\
		\tilde{g}'(x)&=-\tilde{g}'(0)g_0(x)+A\tilde{g}(x)+-g'_0(0)\tilde{g}(x)+\tilde{g}'(0).
	\end{aligned}
\end{equation}
Define the matrix
\begin{equation*}
	M:=\begin{pmatrix} -g'_0(0) & a_0^{\top} \\
	-\tilde{g}'(0) & A-g'_0(0)\mathbbm{1}_d \end{pmatrix}.
\end{equation*}
We can therefore write \Cref{eq:ode_nonmat} as
\begin{equation}\label{eq:ode_mat}
	g'(x)=Mg(x)+g'(0)
\end{equation}
If $M$ is non-singular, using the constraint $g(0)=0$, the solution can be written as
\begin{equation*}
	g(x)=M^{-1}(e^{xM}-\mathbbm{1}_{d+1})g'(0).
\end{equation*}
Otherwise, we may formally define the function $\xi(z):=\frac{e^{z}-1}{z}$ and observe that its power series satisfies
\begin{equation*}
        \xi(\lambda z)=\frac{e^{\lambda z}-1}{z}=\sum _{k=0}^{\infty}\frac{\lambda ^kz^k}{(k+1)!}.
\end{equation*}
We may therefore write the solution as
\begin{equation}\label{eq:xi_fun}
        g(x)=x\xi(xM)g'(0).
\end{equation}
Note now, that $g'(0)=-Me_0$, where $e_0\in\R^{d+1}$ denotes the first unit basis vector with the extended vector notation. Therefore 
\begin{equation*}
	g(x)=-x\xi(xM)Me_0=-(e^{xM}-\mathbbm{1}_{d+1})e_0=(\mathbbm{1}_{d+1}-e^{xM})e_0
\end{equation*}
as asserted.
Using the separability argument on \Cref{eq:4_10}, we find, after using the fact that $\langle Mx,y\rangle = \langle x,M^{\top}y\rangle$,
\begin{equation*}
    \begin{aligned}
	D_yf(Y_t)(0,b_t)^{\top}+\frac12\sum _{k=1}^d\Tr\left( \sigma _t\sigma _t^{\top}H_yf_k(Y_t)\right) e_k&\\
    -\langle g'(0),f(Y_t)\rangle f(Y_t)&= M^{\top}f(Y_t)
    \end{aligned}
\end{equation*}
Grouping up terms yields the asserted drift condition. For the converse, assume we are given a process $Z:=(1,f(Y))$ fulfilling the drift condition for some diffusion process $Y$ with dynamics $dY_t=b_tdt+\sigma _tdW_t$ and function $f:\R\rightarrow\R$ and a function $g:\R _+\rightarrow\R ^{d+1}$ satisfying $g(x)=(\mathbbm 1_{d+1}-e^{xM})e_0$ for some matrix $M\in\mathbb R^{(d+1)\times (d+1)}$. It is an easy calculation to verify that the process $H:=\langle g(x),Z_t\rangle$ satisfies the drift condition \eqref{eq:4_5} and thus fulfills the equivalent conditions of \Cref{prop:4_3}. 
\end{proof}

\begin{proof}[Proof of \Cref{prop:4_time_inhom_case}]
	Let $H_t(x)=\langle g(x,t),f(Y_t)\rangle$. Proceeding the same way as in the proof of \Cref{prop:4_3} and using \Cref{eq:4_drift_time_inhom}, we obtain
	\begin{equation*}
		\begin{aligned}
			&\langle g(x,t),D_yf(Y_t)b_t+\frac12\sum _{k=1}^d\Tr\left(\sigma _t\sigma _t^{\top}H_yf(Y_t)\right) e_k-\langle \partial _xg(0,t),f(Y_t)\rangle f(Y_t)\rangle\\
			&= \langle\partial _xg(x,t)-\partial _tg(x,t)-\partial _xg(0,t),f(Y_t)\rangle.
		\end{aligned}
	\end{equation*}
	Using the separability argument, we immediately obtain that \Cref{eq:4_prop_time_inhom2} holds and that the function $g$ satisfies
	\begin{equation}\label{eq:4_time_inhom_pde}
		\partial _xg(x,t)-\partial _tg(x,t)=M(t)g(x,t)+\partial _xg(0,t),
	\end{equation}
	where $M$ is defined as
	\begin{equation*}
		M(t):=\begin{pmatrix} -\partial _xg_0(0,t) & a_0^{\top} \\
		-\partial_x\tilde{g}(0,t) & A-\partial_xg_0(0,t)\mathbbm{1}_d \end{pmatrix}
	\end{equation*}
	for some matrix $A\in\R ^{d\times d}$ and vector $a_0\in\R^d$, and where $\tilde{g}:=(g_1,\dots ,g_d)^{\top}$. Using the terminal condition $H_t(0)=0$, we furthermore note that $g(0,t)=0$ for all $t$, thus proving the assertion.
\end{proof}
\begin{proof}[Proof of \Cref{cor:4_time_inhom_expl}]
	Assume $g$ satisfies \Cref{eq:4_time_inhom_pde}. Differentiating in the variable $x$, and using the fact that $g$ has continuous second derivatives so that $\partial _{xt}g(x,t)=\partial _{tx}g(x,t)$, we may define $u(x,t):=\partial _xg(x,t)$ and obtain the equation
	\begin{equation*}
		\partial _xu(x,t)-\partial _tu(x,t)=M(t)u(x,t).
	\end{equation*}
	Using standard PDE solution theory (e.g. the method of characteristics), and that the matrix $M(t)$ commutes with its integral, we obtain that 
	\begin{equation*}
		u(x,t)=e^{\int _0^xM(x+t-\xi)d\xi}c(x+t)
	\end{equation*}
	for some unspecified function $c:\R_+\rightarrow\R^d$. Since $g$ is the antiderivative of $u$, we may integrate with respect to the variable $x$ and use the terminal condition $g(0,t)=0$, to obtain the solution specified in \Cref{eq:4_pde_expl_sol}. It is now easy to check that $g$ of this form satisfies \Cref{eq:4_time_inhom_pde}.
\end{proof}
\begin{proof}[Proof of \Cref{prop:4_u_space}]
	This is a direct consequence of \Cref{cor:full_consistency_equiv}.
\end{proof}
\begin{proof}[Proof of \Cref{lem:v_space_u}]
	Let $g\in\mathcal{U}$ and $\lambda\in\R$. Recall from \Cref{eq:xi_fun} and \Cref{prop:4_u_space} that $g(x)=\varphi (x\xi (xM)v)$ for some $\varphi\in (\R ^{d+1})^*, M\in\R ^{(d+1)\times (d+1)}, v\in\R ^{d+1}$. We have by linearity of the dual space
		\begin{equation*}
			\lambda g(x)=\lambda\varphi (x\xi (xM)v)=\varphi (x\xi (xM)\lambda v)=\varphi (x\xi (xM)w,
		\end{equation*}
		where $w=\lambda v$. Therefore, $\lambda g\in\mathcal{U}$.
		To prove that $\mathcal{U}$ is closed under summation we consider $f,g\in\mathcal{U}$, where $g=\varphi (x\xi (xM_1)v)$ for some $\varphi\in (\R ^{d_1+1})^*, M_1\in\R ^{(d_1+1)\times (d_1+1)}, v\in\R ^{d_1+1}$ and $f(x)=\psi (x\xi (xM_2)w)$ for some $\psi\in (\R ^{d_2+1})^*, M_2\in\R ^{(d_2+1)\times (d_2+1)}, v\in\R ^{d_2+1}$, as well as the direct sum $\R ^{d_1+1}\oplus\R ^{d_2+1}$ with the canonical isomorphism $s:(v,w)\mapsto v+ w$. By the properties of block-diagonal matrices, we observe that $\xi (x(M_1\oplus M_2))=(\xi (xM_1))\oplus (\xi (xM_2))$ and from this we see that
		\begin{equation*}
                \begin{aligned}
			f(x)+g(x)&=\varphi (x\xi(xM_1)v)+\psi (x\xi(xM_2) w)\\
                        &=s^*\left((\varphi\oplus\psi)(x\xi (x(M_1\oplus M_2))(v\oplus w))\right).
		      \end{aligned}
            \end{equation*}
		Therefore, by the canonical isomorphism, $h:=f+g\in\mathcal{U}$ and $h(x)=\vartheta (x\xi (xM_3)u)$, where $(\R ^{d_1+d_2})^*\ni\vartheta :=s^*\circ(\varphi\oplus\psi)$, $\R ^{(d_1+d_2+2)\times (d_1+d_2+2)}\ni M_3:=M_1\oplus M_2$, and $\R ^{d_1+d_2+2}\ni u:=v\oplus w$. Finally, since the function $g(x):=x\xi (z)v$ is smooth, each element $f\in\mathcal{U}$ is of class $C^{\infty}$.
\end{proof}

\begin{proof}[Proof of \Cref{lem:rkhs_general}]
	We will first show that $k$ as defined in the Lemma is a kernel function. We will rely on some of the basic results presented in \cite{aronszajn} and \cite{paulsen_rkhs} without further explicitly referencing them. 

	We note that $k$ is of the form $k=h\circ\tilde k\circ(\varphi\otimes\varphi)$, where $\varphi: x\mapsto ax-c$ and $\tilde k(x,y):=xy$. Now, since $h$ a real analytic function, its power series expansion has infinite radius of convergence, is unique and is given by its Taylor series $h(x)=\sum _{k=0}^{\infty}h^{(k)}(0)/k!x^k$. By assumption, $h^{(k)}(0)\geq 0$ and therefore, by \cite[Theorem 4.16]{paulsen_rkhs}, the function $\tilde k$ is a kernel defined on $\R$. Thus, by \cite[Proposition 5.6]{paulsen_rkhs}, $k$ is a kernel.

	We obtain a description of the RKHS $\mathcal{H}(k)$ induced by the kernel $k$ by considering again $k=h\circ\varphi$. The RKHS induced by $k_h(x,y):=h(xy)$ may be obtained from the results in \cite[Theorem 7.2]{paulsen_rkhs}. Indeed, a function $f$ belongs to $\mathcal{H}(k_h)$ if and only if it is of the form 
	\begin{equation}\label{eq:segal_bergman_gen}
		f(x)=\left\langle\bigoplus _{k=0}^{\infty}\sqrt{\frac{h^{(k)}(0)}{k!}}x^k, w\right\rangle _{\mathcal F(\R)},
	\end{equation}
	for some $w\in \mathcal F(\R)$. Here, $\mathcal F(\mathcal L)=\R\oplus\mathcal L \oplus\mathcal L^{\otimes 2}\oplus\dots$ denotes the Fock space over a Hilbert space $\mathcal L$ (see, e.g. \cite[Definition 7.1]{paulsen_rkhs}). In our case, since $\mathcal L =\R$, we have $\mathcal{F}(\R )\cong\ell ^2(\R )$. Thus, the description in \Cref{eq:segal_bergman_gen} corresponds to any function which can be written as a convergent power series with infinite convergence radius $f(x)=\sum _{k=0}^{\infty}a_kx^k$ with coefficients $(a_k)_{k\geq 0}$ fulfilling the following conditions
	\begin{enumerate}
		\item $a_k=0$ for all $k\geq 0$ such that $h^{(k)}(0)=0$.
		\item The weighted square sum is finite, i.e.
			\begin{equation*}
				\sum _{k=0}^{\infty}\mathbbm{1}_{\lbrace h^{(k)}(0)>0\rbrace}\frac{k!}{h^{(k)}(0)}\vert a_k\vert ^2 <\infty. 
			\end{equation*}
	\end{enumerate}
	We may furthermore write down the inner product explicitly:
	\begin{equation}
		\langle f,g\rangle _{\mathcal H(k_h)}=\sum _{k=0}^{\infty}\mathbbm{1}_{\lbrace h^{(k)}(0)>0\rbrace}\frac{1}{h^{(k)}(0)}\frac{f^{(k)}(0)}{\sqrt{k!}}\frac{g^{(k)}(0)}{\sqrt{k!}}.
	\end{equation}
	The space $\mathcal{H}(k_h)$ is therefore a subspace of the space of real analytic functions fulfilling a weighted $\ell ^2$ summability condition with weights dictated by the power series of $h$.

	To obtain a description of the RKHS induced by $k=k_h\circ\varphi$, we may use the results of \cite[Theorem 5.7]{paulsen_rkhs} and compute the pullback along $\varphi$ of the space $\mathcal{H}(k_h)$. To do this, let $f_k(x):=\frac{f^{(k)}(0)}{k!}x^k$ for $k\in\mathbb{N}_0$ be the coefficient of the $k$-th term in the Taylor-expansion of a function $f\in\mathcal{H}(k_h)$. Then $(f_k\circ\varphi )(x)=\frac{f^{(k)}(0)}{k!}(ax-c)^k=\frac{f^{(k)}(0)a^k}{k!}(x-c/a)^k$. Therefore, the pullback of the Taylor series induces a shift about the point $c/a$ and a scaling of the weights by a factor $a^k$. Since the Taylor expansion is invariant under the choice of point around which the series is developed, the resulting space $\mathcal{H}(k)$ is given as asserted. Finally, we verify the reproducing property of the kernel with respect to the inner product. Let $f\in\mathcal{H}(k)$. Then $f(x)=\sum _{k=0}^{\infty}\mathbbm{1}_{\lbrace h^{(k)}(0)>0\rbrace}\frac{f^{(k)}(c/a)}{k!}(x-c/a )^k$. The kernel $k(\cdot ,y)$ has the form $k_h(x,y)=\sum _{k=0}^{\infty}\frac{v_k}{k!}(x-c/a )^k$, where $v_k=a^{2k}h^{(k)}(0)(y-c/a)^k$. We therefore obtain
	\begin{equation*}
		\begin{aligned}
			\langle f,k(\cdot, y)\rangle _{\mathcal{H}(k)}&=\sum _{k=0}^{\infty}\mathbbm{1}_{\lbrace h^{(k)}(0)>0\rbrace}\frac{1}{a^{2k}h^{(k)}(0)}\frac{f^{(k)}(\frac{c}{a})}{\sqrt{k!}}\frac{a^{2k}(y-\frac{c}{a})^k}{\sqrt{k!}}\\
								      &=\sum _{k=0}^{\infty}\mathbbm{1}_{\lbrace h^{(k)}(0)>0\rbrace}\frac{f^{(k)}(\frac{a}{c})}{k!}\left( x-\frac{a}{c}\right) ^k=f(y).
		\end{aligned}
	\end{equation*}
To complete the proof, we observe that the norm is precisely the one induced by the inner product.
\end{proof}
\begin{proof}[Proof of \Cref{prop:4_rkhs}]
	Let $h(t):=e^{-\alpha ^2/\beta}p(t)e^{t}$ and define $k$ as in the statement of the Proposition. Then $k(x,y)=h((\sqrt{\beta}x-\alpha /\sqrt{\beta} ) (\sqrt{\beta}y-\alpha /\sqrt{\beta} ))$ and therefore $k$ is of the form specified in \Cref{lem:rkhs_general} with weight sequence $w=(w_k)_{k\geq 0}$ given by $w_k=h^{(k)}(0)$. It is easy to show via iterated use of the product rule that
	\begin{equation}
		h^{(k)}(x)=e^{-\frac{\alpha ^2}{\beta}}(p(\cdot )e^{\cdot})^{(k)}(x)=e^{-\frac{\alpha ^2}{\beta}}\sum _{l=0}^{k\wedge\text{deg}(p)}\binom{k}{l}p^{(l)}(x)e^{x}.
	\end{equation}
	Evaluating at $x=0$ yields the asserted form of the weighs and the assertions on the form of the RKHS induced by $k$ thus follow by \Cref{lem:rkhs_general}. It therefore remains to be shown that $k$ is fully consistent in the sense of \Cref{def:fully consistent_kernel}. For this to hold, we must have that $k(\cdot,y)\in\mathcal{U}$ for all $y\in\R _+$. By the Jordan normal form, any element $g\in\mathcal{U}$ can be written as a sum of products of polynomials with exponentials. Therefore, observe that $k$ must be of the form
	\begin{equation}
		k(x,y)=(q_0(y)+q_1(y)x+...+q_d(y)x^d)e^{\lambda (y)x}.
	\end{equation}
	for some functions $q_0,\dots ,q_d,\lambda :\R _+\rightarrow\R$. Now,
	\begin{equation}
		\begin{aligned}
			&p\left(\left(\sqrt{\beta}x-\frac{\alpha}{\sqrt{\beta}}\right) \left(\sqrt{\beta}y-\frac{\alpha}{\sqrt{\beta}} \right)\right)\\
            &=\sum _{k=0}^da_k\left(\sqrt{\beta}x-\frac{\alpha}{\sqrt{\beta}} \right) ^k\left(\sqrt{\beta}y-\frac{\alpha}{\sqrt{\beta}} \right) ^k\\
																		    &=\sum _{k=0}^da_k\left(\sqrt{\beta}y-\frac{\alpha}{\sqrt{\beta}} \right) ^k\sum _{l=0}^k\binom{k}{l}\sqrt{\beta}^lx^l\left(\frac{\alpha}{\sqrt{\beta}}\right) ^{k-l}\\
																		    &=\sum _{l=0}^dx^l\underbrace{\sum _{k=l}^d\binom{k}{l}\sqrt{\beta}^l\left(\frac{\alpha}{\sqrt{\beta}}\right) ^{k-l}a_k\left(\sqrt{\beta}y-\frac{\alpha}{\sqrt{\beta}} \right) ^k}_{b_l(y)}\\
																		    &=\sum _{l=0}^db_l(y)x^l.
		\end{aligned}
	\end{equation}
	We may set $q_i(y):=e^{-\alpha y}b_i(y)$ and $\lambda (y):=\sqrt{\beta}y-\alpha$ which shows that $k$ is of the desired form and thus indeed fully consistent.
\end{proof}
\begin{proof}[Proof of \Cref{prop:4_fully consistent_ker}]
	Let $k_i$ be defined for $i=1,\dots ,d+1$ as in the Proposition. Then, by the results of \Cref{prop:4_rkhs}, $k_i$ is a fully consistent kernel for $i=1,\dots ,d+1$. Now since $k=k_1+...+k_{d+1}$, we see from \cite{paulsen_rkhs} and \cite{aronszajn} that $k$ is a kernel as it is a sum of kernels. Furthermore, since $\mathcal{U}$ is a vector space and $k_i(\cdot ,y)\in\mathcal{U}$ for $i=1,\dots ,d+1$, $k(\cdot ,y)\in\mathcal{U}$ and therefore $k$ is fully consistent.

	Finally, the rest of the Proposition follows from \cite[Theorem 5.4]{paulsen_rkhs}.
\end{proof}
\begin{proof}[Proof of \Cref{prop:4_existence_min}]
	Let $E^d(k_p\cdot k_{\exp})$ be defined as in the statement of the Theorem. By \Cref{lem:weak_optimisation}, it is sufficient to show that $E^d(k_p\cdot k_{\exp})$ is weakly closed. Without loss of generality, we may assume $\beta = 1,\alpha = 0$ and $d=1$.
	\begin{enumerate}
		\item Let $p(x,x)>0$ for all $x\in\R _+$. This implies $k(x,x)>0$ for all $x\in\R _+$. Let now $g_n:=\eta _nk(\cdot ,y_n)$ with $g_n\rightarrow f$ for some $f\in\mathcal H(k)$. Consider first the case $y_n\rightarrow y_{\infty}$ for some $y_{\infty}\in\R _+$. Then $k(\cdot, y_n)\rightarrow k(\cdot, y_{\infty})$. Since $f\leftarrow g_n=\eta _nk(\cdot ,y_n)$, $\vert\eta _n\vert <\infty$ for all $n$. Therefore, $\eta _n$ has a convergent subsequence. By the uniqueness of the limit, we have 
			\begin{equation}
				f=\lim _{n\rightarrow\infty}g_n=\lim _{n\rightarrow\infty}\eta _nk(\cdot ,y_n)=\eta _{\infty}k(\cdot ,y_{\infty})\in E^1(k).
			\end{equation}
			Assume now $\vert y_n\vert\rightarrow\infty$. Since $g_n\rightarrow f$, we have $\Vert g_n\Vert _{\mathcal H(k)} <C$ for some $C\in\R$. We therefore have
			\begin{equation}
				\Vert g_n\Vert _{\mathcal H(k)}=\Vert\eta _nk_{y_n}\Vert _{\mathcal H(k)}=\vert\eta _n\vert\Vert k_{y_n}\Vert _{\mathcal H(k)}=\vert\eta _n\vert \sqrt{k(y_n,y_n)}<C,
			\end{equation}
			and thus, $\vert\eta _n\vert <\frac{C}{\sqrt{k(y_n,y_n)}}=\frac{Ce^{-y_n^2/2}}{p(y_n,y_n)}$. By \Cref{lem:convergence}, it suffices to consider poitwise convergence. We obtain now, for $n$ large enough
			\begin{equation}
				f(x)\leq 2g_n(x)=2\eta _nk(x,y_n)\leq\frac{Cp(x,y_n)}{p(y_n,y_n)}e^{xy_n-y_n^2/2}\rightarrow 0
			\end{equation}
			and thus $f\equiv 0\in E^1(k)$.
		\item If $p(x,x)=0$ for some $x\in\R _+$, we may use \Cref{lem:q_factorisation2} and obtain polynomials $q:\R _+\rightarrow\R$ and $r:\R _+\times\R _+\rightarrow\R$ with $r(x,x)>0$ for all $x\in\R _+$ and $p(x,y)=q(x)q(y)r(x,y)$ as asserted. By the results of the first statement, we have that $E^1(k_r\cdot k_{\exp})$ is weakly closed. Using \Cref{prop:4_isometry} and \Cref{cor:isometry}, the map $M_q:\mathcal H(r)\cdot\mathcal H(\exp)\rightarrow \mathcal H(p)\cdot\mathcal H(\exp)$ defined as $M_q:f\mapsto qf$ is a bijective isometry and, since bijective isometries map closed sets to closed sets, we have $M_q(E^1(k_p\cdot k_{\exp}))=qE^1(k_p\cdot k_{\exp})\subset\mathcal H(p)\cdot\mathcal H(\exp)$ is weakly closed. This concludes the proof.
	\end{enumerate}
\end{proof}i
