We provide a summary of our proposed dual-INR training procedure in Algorithm 1, which outlines the main steps involved in the optimization pipeline. 

\begin{algorithm}[H]
\SetAlgoLined
\KwIn{Pre-trained \texttt{SpecNeuralRepr}, center points $\mathbf{x}_c$, neighbor points $\mathbf{x}_n$, experimental data $\mathbf{S}_{\text{expt}}^*$, regularization weight $\lambda$, window size of the kernel $r$.}
\KwOut{Total training loss}

\tcc{Forward Pass}
$\boldsymbol{\kappa}_{r,\hat{\phi}} \gets \texttt{KernelNet}(\mathbf{x}_c;r) $ \tcp*{Learned kernel weights at center points}
$\mathbf{S}_{\text{sim}} \gets \texttt{SpecNeuralRepr}(\mathbf{x}_n)$ \tcp*{Simulated signal at neighbor points}
$\hat{\mathbf{S}}_{\text{sig}}^{(1)} \gets \texttt{einsum}(\boldsymbol{\kappa}, \mathbf{S}_{\text{sim}})$ \tcp*{Masked kernel-signal convolution}
$\hat{\mathbf{S}}_{\text{sig}}^{(2)} \gets \texttt{BkgdNet}(\mathbf{x}_c)$ \tcp*{Learned background signal}
$\bar{\mathbf{S}}_{\text{expt}}^{\text{pred}} \gets \hat{\mathbf{S}}_{\text{sig}}^{(1)} + \hat{\mathbf{S}}_{\text{sig}}^{(2)}$ \tcp*{Final reconstruction}

\tcc{Loss Computation}
$\text{loss}_{\text{reconst}} \gets \texttt{MSE}(\bar{\mathbf{S}}_{\text{expt}}^{\text{pred}}, \mathbf{S}_{\text{expt}}^*)$ \tcp*{Reconstruction error}
$\text{loss}_{\text{bkg}} \gets \lambda \cdot \texttt{Mean}\left((\hat{\mathbf{S}}_{\text{sig}}^{(2)})^2\right)$ \tcp*{Background magnitude penalty}
$\text{loss} \gets \text{loss}_{\text{reconst}} + \text{loss}_{\text{bkg}}$ \tcp*{Total training loss}

\Return $\text{loss}$
\caption{Training step for the proposed dual INR for image source separation.}
\end{algorithm}

